            amount = Decimal(s).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
            amount = int(amount * 100)
        else:
            amount = int(s)

        if abs(amount) > 1000000:
            return None
        return amount
    except (ValueError, TypeError, InvalidOperation):
        return None


