    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] == 'unmatched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        amount = Decimal(s.strip())
        # Convert to cents
        amount_cents = int(amount * 100)
        # Check if the amount is within valid range
        if abs(amount_cents) > 1000000:
            return None
        return amount_cents
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.strip().split('|')
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount, currency, timestamp = map(str.strip, fields)

    # Validate TYPE
    record_type = record_type.upper()
    if record_type not in ['ORDER', 'PAYMENT']:
        return None

    # Validate IDs
    if not record_id or not order_id:
        return None

    # Validate AMOUNT
    amount_cents = parse_amount(amount)
    if amount_cents is None:
        return None

    # Validate CURRENCY (assuming it should be a non-empty string)
    if not currency:
        return None

    # Validate TIMESTAMP (assuming it should be a valid datetime string)
    try:
        datetime.strptime(timestamp, '%Y-%m-%d %H:%M:%S')
    except ValueError:
        return None

    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount_cents,
        'currency': currency,
        'timestamp': timestamp
    }


def load_records(text):
    records = []
    for line in text.strip().splitlines():
        record = parse_record(line)
        if record is not None and not any(r['record_id'] == record['record_id'] for r in records):
            records.append(record)
    return records


def match_payments(records):
    matches = []
    order_payments = {}

    for record in records:
        if record['type'] == 'ORDER':
            order_payments[record['order_id']] = {
                'order_id': record['order_id'],
                'timestamp': datetime.strptime(record['timestamp'], '%Y-%m-%d %H:%M:%S'),
                'amount': record['amount']
            }
        elif record['type'] == 'PAYMENT':
            order_id = record['order_id']
            payment_timestamp = datetime.strptime(record['timestamp'], '%Y-%m-%d %H:%M:%S')
            if order_id in order_payments:
                order_info = order_payments[order_id]
                order_time_limit = order_info['timestamp'] + timedelta(hours=72)

                if order_info['timestamp <= payment_timestamp < order_time_limit:
                    matches.append({
                        'order_id': order_id,
                        'status': 'matched',
                        'amount': order_info['amount']
                    })
                    del order_payments[order_id]  # Remove matched order
                else:
                    matches.append({
                        'order_id': order_id,
                        'status': 'unmatched',
                        'amount': 0
                    })
            else:
                matches.append({
                    'order_id': order_id,
                    'status': 'unmatched',
                    'amount': 0
                })

    # Handle unmatched orders that have not been matched with any payments
    for order_id, order_info in order_payments.items():
        matches.append({
            'order_id': order_id,
            'status': 'unmatched',
            'amount': 0
        })

    return matches


def compute_refunds(records):
    refund_total = sum(record['amount'] for record in records if record['type'] == 'PAYMENT' and record['amount'] < 0)
    return max(0, refund_total)


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = max(0, sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total)
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] != 'matched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

