"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        if '.' in s:
            amount = Decimal(s).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
            amount = int(amount * 100)
        else:
            amount = int(s)

        if abs(amount) > 1000000:
            return None
        return amount
    except (ValueError, TypeError, InvalidOperation):
        return None


def parse_record(line):
    fields = line.split('|')
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount, currency, timestamp = fields

    record_type = record_type.upper().strip()
    record_id = record_id.strip()
    order_id = order_id.strip()
    amount = parse_amount(amount.strip())
    currency = currency.strip()
    timestamp = timestamp.strip()

    if record_type not in ['ORDER', 'PAYMENT']:
        return None
    if not record_id or not order_id or currency != 'USD' or amount is None:
        return None
    if record_type == 'ORDER' and amount < 0:
        return None

    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount,
        'currency': currency,
        'timestamp': timestamp
    }


def load_records(text):
    raise NotImplementedError


def match_payments(records):
    results = []
    for record in records:
        if record['TYPE'] == 'PAYMENT':
            # Check if it's a refund
            if record['AMOUNT'] < 0:
                continue

            order_id = record['ORDER_ID']
            timestamp = datetime.strptime(record['TIMESTAMP'], '%Y-%m-%d %H:%M:%S')
            end_time = timestamp + timedelta(hours=72)
            results.append({
                'order_id': order_id,
                'status': 'matched',
                'amount': record['AMOUNT']
            })

    return results


def compute_refunds(records):
    raise NotImplementedError


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total
    unmatched_ids = sorted(set(match['record_id'] for match in matches if match['status'] != 'matched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': max(net_total, 0),
        'unmatched_ids': unmatched_ids
    }

