        return None

    try:
        fields = line.split("|")
        if len(fields) != 6:
            return None

        record_type, record_id, order_id, amount_text, currency, timestamp_text = fields

        record_type = record_type.upper()
        if record_type not in ("ORDER", "PAYMENT"):
            return None

        record_id = record_id.strip()
        order_id = order_id.strip()
        if not record_id or not order_id or not order_id.startswith("ORD-"):
            return None

        if currency != "USD":
            return None

        amount = parse_amount(amount_text)
        if amount is None:
            return None
        if record_type == "ORDER" and amount < 0:
            return None

        if len(timestamp_text) == 16:
            format_string = "%Y-%m-%d %H:%M"
        elif len(timestamp_text) == 19:
            format_string = "%Y-%m-%d %H:%M:%S"
        else:
            return None

        expected_positions = (4, 7, 10, 13, 16)
        for position in expected_positions:
            if timestamp_text[position] != "-":
                return None

        if len(timestamp_text) == 19 and timestamp_text[16] != ":":
            return None

        digit_positions = [
            index for index in range(len(timestamp_text))
            if index not in expected_positions
            and not (len(timestamp_text) == 19 and index == 16)
        ]
        if any(not timestamp_text[index].isascii()
               or not timestamp_text[index].isdigit()
               for index in digit_positions):
            return None

        timestamp = datetime.strptime(timestamp_text, format_string)

        return {
            "type": record_type,
            "record_id": record_id,
            "order_id": order_id,
            "amount": amount,
            "currency": currency,
            "timestamp": timestamp,
        }
    except (TypeError, ValueError, OverflowError):
        return None


def load_records(text):
    if not isinstance(text, str):
        return []

    retained = []
    seen_record_ids = set()

    for line in text.splitlines():
        try:
            record = parse_record(line)
        except Exception:
            record = None

        if record is None:
            continue

        record_id = record["record_id"]
        if record_id in seen_record_ids:
            continue

        seen_record_ids.add(record_id)
        retained.append(record)

    return retained


def match_payments(records):
    """Match each retained order with its earliest qualifying payment."""
    if records is None:
        return []

    try:
        retained_records = list(records)
    except (TypeError, ValueError):
        return []

    payments = []
    for source_index, record in enumerate(retained_records):
        if not isinstance(record, dict):
            continue
        if record.get("type") != "PAYMENT":
            continue

        amount = record.get("amount")
        if not isinstance(amount, int) or amount < 0:
            continue

        order_id = record.get("order_id")
        timestamp = record.get("timestamp")
        if not isinstance(order_id, str) or not isinstance(timestamp, datetime):
            continue

        payments.append((order_id, timestamp, source_index, amount))

    results = []

    for record in retained_records:
        if not isinstance(record, dict) or record.get("type") != "ORDER":
            continue

        order_id = record.get("order_id")
        order_timestamp = record.get("timestamp")
        selected = None

        if isinstance(order_id, str) and isinstance(order_timestamp, datetime):
            end_timestamp = order_timestamp + timedelta(hours=72)

            for payment_order_id, payment_timestamp, source_index, amount in payments:
                if (
                    payment_order_id == order_id
                    and order_timestamp <= payment_timestamp < end_timestamp
                ):
                    candidate = (payment_timestamp, source_index, amount)
                    if selected is None or candidate[:2] < selected[:2]:
                        selected = candidate

        if selected is None:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": selected[2],
            })

    return results


def compute_refunds(records):
    """Return the total qualifying refund amount in integer cents."""
    if records is None:
        return 0

    order_ids = set()

    try:
        for record in records:
            if not isinstance(record, dict):
                continue
            if record.get("type") == "ORDER":
                order_id = record.get("order_id")
                if isinstance(order_id, str):
                    order_ids.add(order_id)

        refund_total = 0
        for record in records:
            if not isinstance(record, dict):
                continue
            if (
                record.get("type") == "PAYMENT"
                and record.get("currency") == "USD"
                and record.get("order_id") in order_ids
            ):
                amount = record.get("amount")
                if isinstance(amount, int) and amount < 0:
                    refund_total += abs(amount)

        return refund_total
    except (TypeError, AttributeError):
        return 0


def build_summary(matches, refund_total):
    total_orders = 0
    matched_count = 0
    matched_total = 0
    unmatched_ids = set()

    try:
        iterator = iter(matches)
    except TypeError:
        iterator = iter(())

    for result in iterator:
        total_orders += 1

        if not isinstance(result, dict):
            continue

        status = result.get("status")

        if status == "matched":
            matched_count += 1
            amount = result.get("amount")
            if isinstance(amount, int) and not isinstance(amount, bool):
                matched_total += amount

        elif status == "unmatched":
            order_id = result.get("order_id")
            if isinstance(order_id, str):
                unmatched_ids.add(order_id)

    if not isinstance(refund_total, int) or isinstance(refund_total, bool):
        refund_total = 0

    net_total = matched_total - refund_total
    if net_total < 0:
        net_total = 0

    return {
        "total_orders": total_orders,
        "matched_count": matched_count,
        "refund_total": refund_total,
        "net_total": net_total,
        "unmatched_ids": sorted(unmatched_ids),
    }

