"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str) or s == "":
        return None
    negative = s.startswith("-")
    body = s[1:] if negative else s
    if body == "" or body.count(".") > 1:
        return None
    parts = body.split(".")
    whole = parts[0]
    fraction = parts[1] if len(parts) == 2 else ""
    if whole == "" or not all("0" <= c <= "9" for c in whole):
        return None
    if len(fraction) > 3 or not all("0" <= c <= "9" for c in fraction):
        return None
    padded = fraction.ljust(3, "0")
    cents = int(whole) * 100 + int(padded[:2])
    if int(padded[2]) >= 5:
        cents += 1
    if cents > 1000000:
        return None
    return -cents if negative else cents


def parse_record(line):
    if not isinstance(line, str):
        return None
    fields = line.split("|")
    if len(fields) != 6:
        return None
    record_type, record_id, order_id, amount_text, currency, timestamp_text = fields
    record_type = record_type.upper()
    record_id = record_id.strip()
    order_id = order_id.strip()
    if record_type not in ("ORDER", "PAYMENT"):
        return None
    if not record_id or not order_id.startswith("ORD-") or currency != "USD":
        return None
    amount = parse_amount(amount_text)
    if amount is None or (record_type == "ORDER" and amount < 0):
        return None
    if len(timestamp_text) == 16:
        fmt = "%Y-%m-%d %H:%M"
    elif len(timestamp_text) == 19:
        fmt = "%Y-%m-%d %H:%M:%S"
    else:
        return None
    try:
        timestamp = datetime.strptime(timestamp_text, fmt)
    except (TypeError, ValueError, OverflowError):
        return None
    if timestamp.strftime(fmt) != timestamp_text:
        return None
    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []
    result = []
    seen = set()
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None and record["record_id"] not in seen:
            seen.add(record["record_id"])
            result.append(record)
    return result


def match_payments(records):
    results = []
    if not isinstance(records, list):
        return results
    for order in records:
        if order.get("type") != "ORDER":
            continue
        start = order["timestamp"]
        end = start + timedelta(hours=72)
        selected = None
        for payment in records:
            if payment.get("type") != "PAYMENT":
                continue
            if payment.get("amount", 0) < 0:
                continue
            if payment.get("order_id") != order.get("order_id"):
                continue
            timestamp = payment["timestamp"]
            if start <= timestamp < end:
                if selected is None or timestamp < selected["timestamp"]:
                    selected = payment
        if selected is None:
            results.append({
                "order_id": order["order_id"],
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order["order_id"],
                "status": "matched",
                "amount": selected["amount"],
            })
    return results


def compute_refunds(records):
    if not isinstance(records, list):
        return 0
    order_ids = set()
    for record in records:
        if isinstance(record, dict) and record.get("type") == "ORDER":
            order_ids.add(record.get("order_id"))
    total = 0
    for record in records:
        if not isinstance(record, dict):
            continue
        if (record.get("type") == "PAYMENT"
                and record.get("currency") == "USD"
                and record.get("order_id") in order_ids
                and isinstance(record.get("amount"), int)
                and record.get("amount") < 0):
            total -= record["amount"]
    return total


def build_summary(matches, refund_total):
    if not isinstance(matches, list):
        matches = []
    total_orders = len(matches)
    matched_count = 0
    matched_total = 0
    unmatched_ids = set()
    for result in matches:
        if not isinstance(result, dict):
            continue
        if result.get("status") == "matched":
            matched_count += 1
            amount = result.get("amount", 0)
            if isinstance(amount, int):
                matched_total += amount
        elif result.get("status") == "unmatched":
            unmatched_ids.add(result.get("order_id"))
    if not isinstance(refund_total, int):
        refund_total = 0
    net_total = matched_total - refund_total
    if net_total < 0:
        net_total = 0
    return {
        "total_orders": total_orders,
        "matched_count": matched_count,
        "refund_total": refund_total,
        "net_total": net_total,
        "unmatched_ids": sorted(unmatched_ids),
    }

