"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str) or not s:
        return None
    body = s[1:] if s.startswith("-") else s
    if not body:
        return None
    parts = body.split(".")
    if len(parts) > 2 or not parts[0].isdigit():
        return None
    if len(parts) == 2 and (
        not parts[1].isdigit() or len(parts[1]) == 0 or len(parts[1]) > 3
    ):
        return None
    try:
        amount = Decimal(s).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        cents = int(amount * 100)
    except (InvalidOperation, ValueError, TypeError):
        return None
    if abs(cents) > 1000000:
        return None
    return cents


def parse_record(line):
    if not isinstance(line, str):
        return None
    try:
        fields = line.split("|")
        if len(fields) != 6:
            return None
        record_type, record_id, order_id, amount_text, currency, timestamp_text = fields
        record_type = record_type.upper()
        if record_type not in ("ORDER", "PAYMENT"):
            return None
        record_id = record_id.strip()
        order_id = order_id.strip()
        if not record_id or not order_id or not order_id.startswith("ORD-"):
            return None
        if currency != "USD":
            return None
        amount = parse_amount(amount_text)
        if amount is None or (record_type == "ORDER" and amount < 0):
            return None
        if len(timestamp_text) == 16:
            if timestamp_text[10] != " " or timestamp_text[13] != ":":
                return None
            timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
        elif len(timestamp_text) == 19:
            if (timestamp_text[10] != " " or timestamp_text[13] != ":" or
                    timestamp_text[16] != ":"):
                return None
            timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M:%S")
        else:
            return None
        return {
            "type": record_type,
            "record_id": record_id,
            "order_id": order_id,
            "amount": amount,
            "currency": currency,
            "timestamp": timestamp,
        }
    except Exception:
        return None


def load_records(text):
    if not isinstance(text, str):
        return []
    result = []
    seen = set()
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None and record["record_id"] not in seen:
            seen.add(record["record_id"])
            result.append(record)
    return result


def match_payments(records):
    try:
        orders = [r for r in records
                  if isinstance(r, dict) and r.get("type") == "ORDER"]
        results = []
        for order in orders:
            selected = None
            for index, payment in enumerate(records):
                if not isinstance(payment, dict):
                    continue
                if payment.get("type") != "PAYMENT":
                    continue
                if payment.get("order_id") != order.get("order_id"):
                    continue
                if not isinstance(payment.get("amount"), int) or payment["amount"] < 0:
                    continue
                start = order.get("timestamp")
                stamp = payment.get("timestamp")
                if not isinstance(start, datetime) or not isinstance(stamp, datetime):
                    continue
                if start <= stamp < start + timedelta(hours=72):
                    candidate = (stamp, index, payment)
                    if selected is None or candidate[:2] < selected[:2]:
                        selected = candidate
            if selected is None:
                results.append({
                    "order_id": order.get("order_id"),
                    "status": "unmatched",
                    "amount": 0,
                })
            else:
                results.append({
                    "order_id": order.get("order_id"),
                    "status": "matched",
                    "amount": selected[2]["amount"],
                })
        return results
    except Exception:
        return []


def compute_refunds(records):
    try:
        order_ids = {
            r.get("order_id") for r in records
            if isinstance(r, dict) and r.get("type") == "ORDER"
        }
        return sum(
            abs(r["amount"]) for r in records
            if isinstance(r, dict)
            and r.get("type") == "PAYMENT"
            and r.get("order_id") in order_ids
            and isinstance(r.get("amount"), int)
            and r["amount"] < 0
        )
    except Exception:
        return 0


def build_summary(matches, refund_total):
    try:
        total_orders = len(matches)
        matched_count = sum(
            1 for item in matches
            if isinstance(item, dict) and item.get("status") == "matched"
        )
        matched_total = sum(
            item.get("amount", 0) for item in matches
            if isinstance(item, dict) and item.get("status") == "matched"
        )
        unmatched_ids = sorted({
            item.get("order_id") for item in matches
            if isinstance(item, dict) and item.get("status") == "unmatched"
        })
        net_total = matched_total - refund_total
        if net_total < 0:
            net_total = 0
        return {
            "total_orders": total_orders,
            "matched_count": matched_count,
            "refund_total": refund_total,
            "net_total": net_total,
            "unmatched_ids": unmatched_ids,
        }
    except Exception:
        return {
            "total_orders": 0,
            "matched_count": 0,
            "refund_total": refund_total,
            "net_total": 0,
            "unmatched_ids": [],
        }

