"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str) or s == "":
        return None

    text = s[1:] if s.startswith("-") else s
    if text == "" or text.count(".") > 1:
        return None

    parts = text.split(".")
    whole = parts[0]
    fraction = parts[1] if len(parts) == 2 else ""

    if whole == "" or not whole.isdigit():
        return None
    if fraction != "" and not fraction.isdigit():
        return None
    if len(fraction) > 3:
        return None

    try:
        value = Decimal(s).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        cents = int(value * 100)
    except (InvalidOperation, ValueError, OverflowError):
        return None

    if abs(cents) > 1000000:
        return None
    return cents


def parse_record(line):
    if not isinstance(line, str):
        return None

    try:
        fields = line.split("|")
        if len(fields) != 6:
            return None

        record_type, record_id, order_id, amount_text, currency, timestamp_text = fields
        record_type = record_type.upper()

        if record_type not in ("ORDER", "PAYMENT"):
            return None

        record_id = record_id.strip()
        order_id = order_id.strip()
        if record_id == "" or order_id == "":
            return None
        if not order_id.startswith("ORD-"):
            return None
        if currency != "USD":
            return None

        amount = parse_amount(amount_text)
        if amount is None:
            return None
        if record_type == "ORDER" and amount < 0:
            return None

        if len(timestamp_text) == 16:
            timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
            if timestamp.strftime("%Y-%m-%d %H:%M") != timestamp_text:
                return None
        elif len(timestamp_text) == 19:
            timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M:%S")
            if timestamp.strftime("%Y-%m-%d %H:%M:%S") != timestamp_text:
                return None
        else:
            return None

        return {
            "type": record_type,
            "record_id": record_id,
            "order_id": order_id,
            "amount": amount,
            "currency": currency,
            "timestamp": timestamp,
        }
    except (ValueError, TypeError, OverflowError):
        return None


def load_records(text):
    if not isinstance(text, str):
        return []

    retained = []
    seen_ids = set()

    for line in text.splitlines():
        record = parse_record(line)
        if record is None:
            continue
        if record["record_id"] in seen_ids:
            continue
        seen_ids.add(record["record_id"])
        retained.append(record)

    return retained


def match_payments(records):
    try:
        rows = list(records)
    except (TypeError, ValueError):
        return []

    results = []

    for order in rows:
        if not isinstance(order, dict):
            continue
        try:
            if order.get("type") != "ORDER":
                continue
            order_id = order["order_id"]
            order_time = order["timestamp"]
            deadline = order_time + timedelta(hours=72)
        except (AttributeError, KeyError, TypeError, OverflowError):
            continue

        selected = None
        selected_time = None

        for payment in rows:
            if not isinstance(payment, dict):
                continue
            try:
                if (
                    payment.get("type") != "PAYMENT"
                    or payment.get("currency") != "USD"
                    or payment.get("order_id") != order_id
                    or payment.get("amount") < 0
                ):
                    continue

                payment_time = payment["timestamp"]
                if payment_time < order_time or payment_time >= deadline:
                    continue

                if selected is None or payment_time < selected_time:
                    selected = payment
                    selected_time = payment_time
            except (AttributeError, KeyError, TypeError):
                continue

        if selected is None:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": selected["amount"],
            })

    return results


def compute_refunds(records):
    try:
        rows = list(records)
    except (TypeError, ValueError):
        return 0

    order_ids = set()
    for record in rows:
        if not isinstance(record, dict):
            continue
        try:
            if (
                record.get("type") == "ORDER"
                and record.get("currency") == "USD"
                and isinstance(record.get("order_id"), str)
            ):
                order_ids.add(record["order_id"])
        except (AttributeError, TypeError, KeyError):
            continue

    total = 0
    for record in rows:
        if not isinstance(record, dict):
            continue
        try:
            if (
                record.get("type") == "PAYMENT"
                and record.get("currency") == "USD"
                and record.get("amount") < 0
                and record.get("order_id") in order_ids
            ):
                total += abs(record["amount"])
        except (AttributeError, TypeError, KeyError):
            continue
    return total


def build_summary(matches, refund_total):
    try:
        rows = list(matches)
    except (TypeError, ValueError):
        rows = []

    matched_count = 0
    matched_total = 0
    unmatched_ids = set()

    for result in rows:
        if not isinstance(result, dict):
            continue

        try:
            status = result.get("status")
            if status == "matched":
                matched_count += 1
                matched_total += result.get("amount", 0)
            elif status == "unmatched":
                unmatched_ids.add(result["order_id"])
        except (AttributeError, KeyError, TypeError):
            continue

    try:
        total_orders = len(rows)
    except TypeError:
        total_orders = 0

    try:
        net_total = matched_total - refund_total
        if net_total < 0:
            net_total = 0
    except (TypeError, ValueError):
        net_total = 0

    return {
        "total_orders": total_orders,
        "matched_count": matched_count,
        "refund_total": refund_total,
        "net_total": net_total,
        "unmatched_ids": sorted(unmatched_ids),
    }

