"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    import re
    if not isinstance(s, str):
        return None
    text = s.strip()
    if not re.fullmatch(r"-?\d+(?:\.\d{0,3})?", text):
        return None
    try:
        value = Decimal(text)
        cents = int((value * Decimal("100")).quantize(
            Decimal("1"), rounding=ROUND_HALF_UP
        ))
    except (InvalidOperation, ValueError, TypeError, ArithmeticError):
        return None
    return cents if abs(cents) <= 1_000_000 else None


def parse_record(line):
    if not isinstance(line, str):
        return None
    fields = line.split("|")
    if len(fields) != 6:
        return None
    kind, record_id, order_id, amount_text, currency, timestamp_text = (
        field.strip() for field in fields
    )
    kind = kind.upper()
    if kind not in ("ORDER", "PAYMENT"):
        return None
    if not record_id or not order_id or not order_id.startswith("ORD-"):
        return None
    if currency != "USD":
        return None
    amount = parse_amount(amount_text)
    if amount is None or (kind == "ORDER" and amount < 0):
        return None
    timestamp = None
    for pattern in ("%Y-%m-%d %H:%M", "%Y-%m-%d %H:%M:%S"):
        try:
            timestamp = datetime.strptime(timestamp_text, pattern)
            break
        except (TypeError, ValueError):
            pass
    if timestamp is None:
        return None
    return {
        "type": kind,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []
    records = []
    seen = set()
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None and record["record_id"] not in seen:
            seen.add(record["record_id"])
            records.append(record)
    return records


def match_payments(records):
    if not isinstance(records, list):
        return []
    orders = []
    order_ids = set()
    for record in records:
        if (
            isinstance(record, dict)
            and record.get("type") == "ORDER"
            and record.get("order_id") not in order_ids
            and isinstance(record.get("timestamp"), datetime)
        ):
            order_ids.add(record["order_id"])
            orders.append(record)

    results = []
    for order in orders:
        best = None
        try:
            deadline = order["timestamp"] + timedelta(hours=72)
        except (TypeError, ValueError, OverflowError):
            deadline = None
        if deadline is not None:
            for index, payment in enumerate(records):
                if not isinstance(payment, dict):
                    continue
                if payment.get("type") != "PAYMENT":
                    continue
                if payment.get("order_id") != order.get("order_id"):
                    continue
                amount = payment.get("amount")
                timestamp = payment.get("timestamp")
                if not isinstance(amount, int) or amount < 0:
                    continue
                if not isinstance(timestamp, datetime):
                    continue
                if not (order["timestamp"] <= timestamp < deadline):
                    continue
                candidate = (timestamp, index, payment)
                if best is None or candidate[:2] < best[:2]:
                    best = candidate
        if best is None:
            results.append({
                "order_id": order["order_id"],
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order["order_id"],
                "status": "matched",
                "amount": best[2]["amount"],
            })
    return results


def compute_refunds(records):
    if not isinstance(records, list):
        return 0
    order_ids = {
        record.get("order_id")
        for record in records
        if isinstance(record, dict) and record.get("type") == "ORDER"
    }
    return sum(
        -record["amount"]
        for record in records
        if (
            isinstance(record, dict)
            and record.get("type") == "PAYMENT"
            and isinstance(record.get("amount"), int)
            and record["amount"] < 0
            and record.get("order_id") in order_ids
        )
    )


def build_summary(matches, refund_total):
    if not isinstance(matches, list):
        matches = []
    if not isinstance(refund_total, int):
        refund_total = 0
    matched = [
        match for match in matches
        if isinstance(match, dict) and match.get("status") == "matched"
    ]
    unmatched_ids = sorted({
        match.get("order_id")
        for match in matches
        if (
            isinstance(match, dict)
            and match.get("status") == "unmatched"
            and isinstance(match.get("order_id"), str)
        )
    })
    paid = sum(
        match.get("amount", match.get("payment_amount", 0))
        for match in matched
        if isinstance(match.get("amount", match.get("payment_amount", 0)), int)
    )
    return {
        "total_orders": len(matches),
        "matched_count": len(matched),
        "refund_total": refund_total,
        "net_total": max(0, paid - refund_total),
        "unmatched_ids": unmatched_ids,
    }

