"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str):
        return None
    value = s.strip()
    if not value:
        return None
    negative = value.startswith("-")
    if negative:
        value = value[1:]
    if not value or value.count(".") > 1:
        return None
    parts = value.split(".")
    if not all(part.isdigit() for part in parts if part):
        return None
    if not any(parts):
        return None
    if len(parts) == 2 and len(parts[1]) > 3:
        return None
    try:
        amount = Decimal(("-" if negative else "") + value)
        cents = int((amount * Decimal("100")).quantize(
            Decimal("1"), rounding=ROUND_HALF_UP
        ))
    except (InvalidOperation, ValueError, OverflowError):
        return None
    if abs(cents) > 1000000:
        return None
    return cents


def parse_record(line):
    if not isinstance(line, str):
        return None
    fields = line.split("|")
    if len(fields) != 6:
        return None
    record_type, record_id, order_id, amount_text, currency, timestamp = fields
    record_type = record_type.strip().upper()
    record_id = record_id.strip()
    order_id = order_id.strip()
    currency = currency.strip()
    timestamp = timestamp.strip()
    if record_type not in ("ORDER", "PAYMENT"):
        return None
    if not record_id or not order_id or not order_id.startswith("ORD-"):
        return None
    if currency != "USD":
        return None
    amount = parse_amount(amount_text)
    if amount is None or (record_type == "ORDER" and amount < 0):
        return None
    parsed_time = None
    for fmt in ("%Y-%m-%d %H:%M", "%Y-%m-%d %H:%M:%S"):
        try:
            parsed_time = datetime.strptime(timestamp, fmt)
            break
        except (TypeError, ValueError):
            pass
    if parsed_time is None:
        return None
    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": parsed_time,
    }


def load_records(text):
    if not isinstance(text, str):
        return []
    records = []
    seen = set()
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None and record["record_id"] not in seen:
            seen.add(record["record_id"])
            records.append(record)
    return records


def match_payments(records):
    if not isinstance(records, list):
        return []
    payments = {}
    orders = []
    order_ids = set()
    for index, record in enumerate(records):
        if not isinstance(record, dict):
            continue
        if record.get("type") == "ORDER":
            order_id = record.get("order_id")
            if order_id not in order_ids:
                order_ids.add(order_id)
                orders.append(record)
        elif record.get("type") == "PAYMENT":
            order_id = record.get("order_id")
            amount = record.get("amount")
            timestamp = record.get("timestamp")
            if (isinstance(amount, int) and amount >= 0
                    and isinstance(timestamp, datetime)):
                payments.setdefault(order_id, []).append(
                    (timestamp, index, amount)
                )
    results = []
    for order in orders:
        order_id = order.get("order_id")
        order_time = order.get("timestamp")
        candidates = []
        if isinstance(order_time, datetime):
            end_time = order_time + timedelta(hours=72)
            for timestamp, index, amount in payments.get(order_id, []):
                if order_time <= timestamp < end_time:
                    candidates.append((timestamp, index, amount))
        if candidates:
            candidates.sort(key=lambda item: (item[0], item[1]))
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": candidates[0][2],
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })
    return results


def compute_refunds(records):
    if not isinstance(records, list):
        return 0
    order_ids = {
        record.get("order_id")
        for record in records
        if isinstance(record, dict) and record.get("type") == "ORDER"
    }
    total = 0
    for record in records:
        if (isinstance(record, dict)
                and record.get("type") == "PAYMENT"
                and record.get("order_id") in order_ids
                and isinstance(record.get("amount"), int)
                and record["amount"] < 0):
            total += -record["amount"]
    return total


def build_summary(matches, refund_total):
    if not isinstance(matches, list):
        matches = []
    if not isinstance(refund_total, int):
        refund_total = 0
    total_orders = 0
    matched_count = 0
    matched_total = 0
    unmatched = []
    for match in matches:
        if not isinstance(match, dict):
            continue
        total_orders += 1
        if match.get("status") == "matched":
            matched_count += 1
            amount = match.get("amount", match.get("payment_amount"))
            if isinstance(amount, int):
                matched_total += amount
        elif match.get("status") == "unmatched":
            order_id = match.get("order_id")
            if isinstance(order_id, str):
                unmatched.append(order_id)
    return {
        "total_orders": total_orders,
        "matched_count": matched_count,
        "refund_total": refund_total,
        "net_total": max(0, matched_total - refund_total),
        "unmatched_ids": sorted(set(unmatched)),
    }

