"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        if not isinstance(s, str):
            return None
        text = s.strip()
        if not text:
            return None
        body = text[1:] if text.startswith("-") else text
        if not body or any(c not in "0123456789." for c in body):
            return None
        if body.count(".") > 1:
            return None
        if "." in body:
            whole, fraction = body.split(".")
            if not whole or not whole.isdigit() or len(fraction) > 3:
                return None
        elif not body.isdigit():
            return None
        cents = int((Decimal(text) * Decimal("100")).quantize(
            Decimal("1"), rounding=ROUND_HALF_UP
        ))
        return None if abs(cents) > 1000000 else cents
    except Exception:
        return None


def parse_record(line):
    if not isinstance(line, str):
        return None
    try:
        parts = line.split("|")
        if len(parts) != 6:
            return None
        kind, record_id, order_id, amount, currency, stamp = (
            part.strip() for part in parts
        )
        kind = kind.upper()
        if kind not in ("ORDER", "PAYMENT"):
            return None
        if not record_id or not order_id or not stamp:
            return None
        if not order_id.startswith("ORD-") or currency != "USD":
            return None
        cents = parse_amount(amount)
        if cents is None or (kind == "ORDER" and cents < 0):
            return None
        parsed = None
        for fmt in ("%Y-%m-%d %H:%M", "%Y-%m-%d %H:%M:%S"):
            try:
                candidate = datetime.strptime(stamp, fmt)
                if candidate.strftime(fmt) == stamp:
                    parsed = candidate
                    break
            except ValueError:
                continue
        if parsed is None:
            return None
        return {
            "type": kind,
            "record_id": record_id,
            "order_id": order_id,
            "amount": cents,
            "currency": currency,
            "timestamp": parsed,
        }
    except Exception:
        return None


def load_records(text):
    if not isinstance(text, str):
        return []
    result = []
    seen = set()
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None and record["record_id"] not in seen:
            seen.add(record["record_id"])
            result.append(record)
    return result


def match_payments(records):
    if not isinstance(records, list):
        return []
    orders = [
        r for r in records
        if isinstance(r, dict)
        and r.get("type") == "ORDER"
        and isinstance(r.get("order_id"), str)
        and isinstance(r.get("timestamp"), datetime)
    ]
    result = []
    for order in orders:
        best = None
        for payment in records:
            if not isinstance(payment, dict):
                continue
            if payment.get("type") != "PAYMENT":
                continue
            if payment.get("order_id") != order["order_id"]:
                continue
            if not isinstance(payment.get("timestamp"), datetime):
                continue
            if not isinstance(payment.get("amount"), int):
                continue
            if payment["amount"] < 0:
                continue
            elapsed = payment["timestamp"] - order["timestamp"]
            if elapsed < timedelta(0) or elapsed >= timedelta(hours=72):
                continue
            if best is None or payment["timestamp"] < best["timestamp"]:
                best = payment
        result.append({
            "order_id": order["order_id"],
            "status": "matched" if best is not None else "unmatched",
            "amount": best["amount"] if best is not None else 0,
        })
    return result


def compute_refunds(records):
    if not isinstance(records, list):
        return 0
    order_ids = {
        r.get("order_id") for r in records
        if isinstance(r, dict) and r.get("type") == "ORDER"
    }
    return sum(
        -r["amount"] for r in records
        if isinstance(r, dict)
        and r.get("type") == "PAYMENT"
        and r.get("order_id") in order_ids
        and isinstance(r.get("amount"), int)
        and r["amount"] < 0
    )


def build_summary(matches, refund_total):
    if not isinstance(matches, list):
        matches = []
    if not isinstance(refund_total, int):
        refund_total = 0
    matched_count = 0
    matched_total = 0
    unmatched = set()
    for item in matches:
        if not isinstance(item, dict):
            continue
        if item.get("status") == "matched":
            matched_count += 1
            if isinstance(item.get("amount"), int):
                matched_total += item["amount"]
        elif isinstance(item.get("order_id"), str):
            unmatched.add(item["order_id"])
    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "refund_total": refund_total,
        "net_total": max(0, matched_total - refund_total),
        "unmatched_ids": sorted(unmatched),
    }

