from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    """Convert a decimal amount to integer cents, or return None if invalid."""
    if isinstance(s, bool) or s is None:
        return None

    text = str(s).strip()
    if not text or not _AMOUNT_PATTERN.fullmatch(text):
        return None

    try:
        with localcontext() as context:
            context.prec = max(
                28,
                len(text.replace("-", "").replace("+", "").replace(".", ""))
                + 10,
            )
            value = Decimal(text)
            cents = (value * Decimal("100")).quantize(
                Decimal("1"),
                rounding=ROUND_HALF_UP,
            )

        cents = int(cents)

        if abs(cents) > 100_000_000:
            return None

        return cents
    except (InvalidOperation, ValueError, TypeError, OverflowError):
        return None


def parse_record(line):
    """Parse one six-field pipe-separated record."""
    if not isinstance(line, str):
        return None

    parts = line.strip().split("|")
    if len(parts) != 6:
        return None

    parts = [part.strip() for part in parts]
    record_type, record_id, order_id, amount_text, currency, timestamp_text = parts

    record_type = record_type.upper()
    if record_type not in {"ORDER", "PAYMENT"}:
        return None

    if not record_id or not order_id:
        return None

    if not _CURRENCY_PATTERN.fullmatch(currency):
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None

    if record_type == "ORDER" and amount < 0:
        return None

    timestamp = _parse_timestamp(timestamp_text)
    if timestamp is None:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    """Parse records, retaining the first valid occurrence of each ID."""
    if not isinstance(text, str):
        return []

    records = []
    seen_ids = set()

    for line in text.splitlines():
        record = parse_record(line)
        if record is None:
            continue

        record_id = record["record_id"]
        if record_id in seen_ids:
            continue

        seen_ids.add(record_id)
        records.append(record)

    return records


def match_payments(records):
    """Return one matching result for each retained order."""
    if not isinstance(records, list):
        return []

    orders = []
    order_ids = set()

    for record in records:
        if not isinstance(record, dict):
            continue
        if record.get("type") != "ORDER":
            continue

        order_id = record.get("order_id")
        if order_id in order_ids:
            continue

        order_ids.add(order_id)
        orders.append(record)

    results = []

    for order in orders:
        best_payment = None
        best_index = None

        for index, payment in enumerate(records):
            if not isinstance(payment, dict):
                continue
            if payment.get("type") != "PAYMENT":
                continue
            if payment.get("order_id") != order.get("order_id"):
                continue

            amount = payment.get("amount")
            if not isinstance(amount, int) or isinstance(amount, bool):
                continue
            if amount < 0:
                continue
            if payment.get("currency") != order.get("currency"):
                continue
            if amount != order.get("amount"):
                continue
            if not _timestamps_in_order(
                order.get("timestamp"),
                payment.get("timestamp"),
            ):
                continue

            if best_payment is None:
                best_payment = payment
                best_index = index
                continue

            payment_timestamp = payment.get("timestamp")
            best_timestamp = best_payment.get("timestamp")

            if payment_timestamp < best_timestamp or (
                payment_timestamp == best_timestamp
                and index < best_index
            ):
                best_payment = payment
                best_index = index

        if best_payment is None:
            results.append(
                {
                    "order_id": order["order_id"],
                    "status": "unmatched",
                    "amount": 0,
                }
            )
        else:
            results.append(
                {
                    "order_id": order["order_id"],
                    "status": "matched",
                    "amount": best_payment["amount"],
                }
            )

    return results


def compute_refunds(records):
    """Return the positive sum of negative payments for existing orders."""
    if not isinstance(records, list):
        return 0

    order_ids = set()

    for record in records:
        if not isinstance(record, dict):
            continue
        if record.get("type") == "ORDER":
            order_ids.add(record.get("order_id"))

    refund_total = 0

    for record in records:
        if not isinstance(record, dict):
            continue
        if record.get("type") != "PAYMENT":
            continue
        if record.get("order_id") not in order_ids:
            continue

        amount = record.get("amount")
        if (
            isinstance(amount, int)
            and not isinstance(amount, bool)
            and amount < 0
        ):
            refund_total += -amount

    return refund_total


def build_summary(matches, refund_total):
    """Build the five-field financial summary."""
    if not isinstance(matches, list):
        matches = []

    total_orders = 0
    matched_count = 0
    matched_total = 0
    unmatched_ids = set()

    for result in matches:
        if not isinstance(result, dict):
            continue

        total_orders += 1

        if result.get("status") == "matched":
            matched_count += 1
            amount = result.get("amount")
            if isinstance(amount, int) and not isinstance(amount, bool):
                matched_total += amount
        else:
            order_id = result.get("order_id")
            if isinstance(order_id, str):
                unmatched_ids.add(order_id)

    if not isinstance(refund_total, int) or isinstance(refund_total, bool):
        refund_total = 0

    return {
        "total_orders": total_orders,
        "matched_count": matched_count,
        "refund_total": refund_total,
        "net_total": max(0, matched_total - refund_total),
        "unmatched_ids": sorted(unmatched_ids),
    }

