"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str) or s == "":
        return None

    negative = s.startswith("-")
    body = s[1:] if negative else s
    if body == "" or body.count(".") > 1:
        return None

    parts = body.split(".")
    whole = parts[0]
    fraction = parts[1] if len(parts) == 2 else ""

    if whole == "" or any(ch not in "0123456789" for ch in whole):
        return None
    if len(fraction) > 3 or any(ch not in "0123456789" for ch in fraction):
        return None

    try:
        value = Decimal(s).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        cents = int(value * 100)
    except (InvalidOperation, ValueError, TypeError):
        return None

    if abs(cents) > 1000000:
        return None
    return cents


def parse_record(line):
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount_text, currency, timestamp_text = fields
    record_type = record_type.upper()
    if record_type not in ("ORDER", "PAYMENT"):
        return None

    record_id = record_id.strip()
    order_id = order_id.strip()
    if not record_id or not order_id or not order_id.startswith("ORD-"):
        return None
    if currency != "USD":
        return None

    amount = parse_amount(amount_text)
    if amount is None or (record_type == "ORDER" and amount < 0):
        return None

    if len(timestamp_text) == 16:
        timestamp_format = "%Y-%m-%d %H:%M"
    elif len(timestamp_text) == 19:
        timestamp_format = "%Y-%m-%d %H:%M:%S"
    else:
        return None

    try:
        timestamp = datetime.strptime(timestamp_text, timestamp_format)
    except (TypeError, ValueError):
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []

    retained = []
    seen_ids = set()

    for line in text.splitlines():
        record = parse_record(line)
        if record is None:
            continue
        if record["record_id"] in seen_ids:
            continue
        seen_ids.add(record["record_id"])
        retained.append(record)

    return retained


def match_payments(records):
    if not isinstance(records, list):
        return []

    results = []
    for order in records:
        if not isinstance(order, dict) or order.get("type") != "ORDER":
            continue

        order_id = order.get("order_id")
        order_time = order.get("timestamp")
        selected = None
        selected_index = None

        if isinstance(order_id, str) and isinstance(order_time, datetime):
            for index, payment in enumerate(records):
                if not isinstance(payment, dict):
                    continue
                if payment.get("type") != "PAYMENT":
                    continue
                if payment.get("order_id") != order_id:
                    continue

                amount = payment.get("amount")
                payment_time = payment.get("timestamp")
                if not isinstance(amount, int) or amount < 0:
                    continue
                if not isinstance(payment_time, datetime):
                    continue
                if payment_time < order_time:
                    continue
                if payment_time >= order_time + timedelta(hours=72):
                    continue

                if (
                    selected is None
                    or payment_time < selected["timestamp"]
                    or (
                        payment_time == selected["timestamp"]
                        and index < selected_index
                    )
                ):
                    selected = payment
                    selected_index = index

        if selected is None:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": selected["amount"],
            })

    return results


def compute_refunds(records):
    if not isinstance(records, list):
        return 0

    order_ids = set()
    for record in records:
        if (
            isinstance(record, dict)
            and record.get("type") == "ORDER"
            and record.get("currency") == "USD"
            and isinstance(record.get("order_id"), str)
        ):
            order_ids.add(record["order_id"])

    total = 0
    for record in records:
        if (
            isinstance(record, dict)
            and record.get("type") == "PAYMENT"
            and record.get("currency") == "USD"
            and isinstance(record.get("order_id"), str)
            and record["order_id"] in order_ids
            and isinstance(record.get("amount"), int)
            and record["amount"] < 0
        ):
            total += abs(record["amount"])

    return total


def build_summary(matches, refund_total):
    if not isinstance(matches, list):
        matches = []

    total_orders = len(matches)
    matched_count = 0
    matched_total = 0
    unmatched_ids = set()

    for result in matches:
        if not isinstance(result, dict):
            continue

        if result.get("status") == "matched":
            matched_count += 1
            amount = result.get("amount")
            if isinstance(amount, int):
                matched_total += amount
        elif result.get("status") == "unmatched":
            order_id = result.get("order_id")
            if isinstance(order_id, str):
                unmatched_ids.add(order_id)

    if not isinstance(refund_total, int):
        refund_total = 0

    net_total = matched_total - refund_total
    if net_total < 0:
        net_total = 0

    return {
        "total_orders": total_orders,
        "matched_count": matched_count,
        "refund_total": refund_total,
        "net_total": net_total,
        "unmatched_ids": sorted(unmatched_ids),
    }

