"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if isinstance(s, bool) or not isinstance(s, (str, int, float, Decimal)):
        return None
    try:
        text = str(s).strip()
        if not text or "e" in text.lower():
            return None
        digits = text[1:] if text.startswith("-") else text
        if not digits or digits.count(".") > 1:
            return None
        pieces = digits.split(".")
        if not pieces[0].isdigit():
            return None
        if len(pieces) == 2 and not pieces[1].isdigit():
            return None
        if len(pieces) == 2 and len(pieces[1]) > 3:
            return None
        value = Decimal(text).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        cents = int(value * 100)
        if abs(cents) > 1000000:
            return None
        return cents
    except (InvalidOperation, ValueError, TypeError, OverflowError):
        return None


def parse_record(line):
    if not isinstance(line, str):
        return None
    parts = line.split("|")
    if len(parts) != 6:
        return None
    values = [part.strip() for part in parts]
    if any(not value for value in values):
        return None
    kind, record_id, order_id, amount_text, currency, timestamp = values
    if kind not in ("ORDER", "PAYMENT"):
        return None
    if not order_id.startswith("ORD-") or currency != "USD":
        return None
    amount = parse_amount(amount_text)
    if amount is None or (kind == "ORDER" and amount < 0):
        return None
    parsed_time = None
    for fmt in ("%Y-%m-%d %H:%M", "%Y-%m-%d %H:%M:%S"):
        try:
            parsed_time = datetime.strptime(timestamp, fmt)
            break
        except (ValueError, TypeError):
            pass
    if parsed_time is None:
        return None
    return {
        "type": kind,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": parsed_time,
    }


def load_records(text):
    if not isinstance(text, str):
        return []
    records = []
    seen = set()
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None and record["record_id"] not in seen:
            seen.add(record["record_id"])
            records.append(record)
    return records


def match_payments(records):
    if not isinstance(records, list):
        return []
    payments = []
    for record in records:
        if not isinstance(record, dict):
            continue
        if record.get("type") != "PAYMENT":
            continue
        amount = record.get("amount")
        timestamp = record.get("timestamp")
        if (
            isinstance(amount, int)
            and not isinstance(amount, bool)
            and amount >= 0
            and isinstance(timestamp, datetime)
        ):
            payments.append(record)

    results = []
    for order in records:
        if not isinstance(order, dict) or order.get("type") != "ORDER":
            continue
        order_id = order.get("order_id")
        order_time = order.get("timestamp")
        chosen = None
        if isinstance(order_time, datetime):
            for payment in payments:
                if payment.get("order_id") != order_id:
                    continue
                payment_time = payment["timestamp"]
                if not (
                    order_time <= payment_time <
                    order_time + timedelta(hours=72)
                ):
                    continue
                if chosen is None or payment_time < chosen["timestamp"]:
                    chosen = payment
        if chosen is None:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": chosen["amount"],
            })
    return results


def compute_refunds(records):
    if not isinstance(records, list):
        return 0
    orders = {
        record.get("order_id")
        for record in records
        if isinstance(record, dict) and record.get("type") == "ORDER"
    }
    total = 0
    for record in records:
        if not isinstance(record, dict):
            continue
        amount = record.get("amount")
        if (
            record.get("type") == "PAYMENT"
            and isinstance(amount, int)
            and not isinstance(amount, bool)
            and amount < 0
            and record.get("order_id") in orders
        ):
            total += -amount
    return total


def build_summary(matches, refund_total):
    if not isinstance(matches, list):
        matches = []
    matched_count = 0
    matched_total = 0
    unmatched = set()
    for result in matches:
        if not isinstance(result, dict):
            continue
        if result.get("status") == "matched":
            matched_count += 1
            amount = result.get("amount", 0)
            if isinstance(amount, (int, Decimal)) and not isinstance(amount, bool):
                matched_total += amount
        else:
            order_id = result.get("order_id")
            if isinstance(order_id, str):
                unmatched.add(order_id)
    if not isinstance(refund_total, (int, Decimal)) or isinstance(refund_total, bool):
        refund_total = 0
    net_total = max(0, matched_total - refund_total)
    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "refund_total": refund_total,
        "net_total": net_total,
        "unmatched_ids": sorted(unmatched),
    }

