"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str) or not s:
        return None
    text = s
    if text.startswith("-"):
        text = text[1:]
    if not text or text.count(".") > 1:
        return None
    if "." in text:
        whole, fraction = text.split(".")
        if not whole or not fraction or len(fraction) > 3:
            return None
    else:
        whole, fraction = text, ""
    if not whole.isdigit() or (fraction and not fraction.isdigit()):
        return None
    try:
        cents = int((Decimal(s) * Decimal("100")).quantize(
            Decimal("1"), rounding=ROUND_HALF_UP
        ))
    except (InvalidOperation, ValueError, OverflowError):
        return None
    if abs(cents) > 1_000_000:
        return None
    return cents


def parse_record(line):
    if not isinstance(line, str):
        return None
    fields = line.split("|")
    if len(fields) != 6:
        return None
    record_type, record_id, order_id, amount_text, currency, timestamp_text = fields
    record_type = record_type.upper()
    if record_type not in ("ORDER", "PAYMENT"):
        return None
    record_id = record_id.strip()
    order_id = order_id.strip()
    if not record_id or not order_id or not order_id.startswith("ORD-"):
        return None
    if currency != "USD":
        return None
    amount = parse_amount(amount_text)
    if amount is None or (record_type == "ORDER" and amount < 0):
        return None
    if len(timestamp_text) not in (16, 19):
        return None
    try:
        timestamp = datetime.strptime(
            timestamp_text,
            "%Y-%m-%d %H:%M:%S" if len(timestamp_text) == 19
            else "%Y-%m-%d %H:%M"
        )
    except (ValueError, TypeError):
        return None
    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []
    retained = []
    seen_ids = set()
    for line in text.splitlines():
        try:
            record = parse_record(line)
        except Exception:
            record = None
        if record is None or record["record_id"] in seen_ids:
            continue
        seen_ids.add(record["record_id"])
        retained.append(record)
    return retained


def match_payments(records):
    if not isinstance(records, (list, tuple)):
        return []
    orders = []
    payments = []
    for record in records:
        if not isinstance(record, dict):
            continue
        try:
            if record["type"] == "ORDER" and record["currency"] == "USD":
                orders.append(record)
            elif record["type"] == "PAYMENT" and record["currency"] == "USD":
                payments.append(record)
        except (KeyError, TypeError):
            continue

    results = []
    for order in orders:
        try:
            start = order["timestamp"]
            end = start + timedelta(hours=72)
            chosen = None
            for payment in payments:
                if payment["order_id"] != order["order_id"]:
                    continue
                if payment["amount"] < 0:
                    continue
                timestamp = payment["timestamp"]
                if start <= timestamp < end:
                    if chosen is None or timestamp < chosen["timestamp"]:
                        chosen = payment
            if chosen is None:
                results.append({
                    "order_id": order["order_id"],
                    "status": "unmatched",
                    "amount": 0,
                })
            else:
                results.append({
                    "order_id": order["order_id"],
                    "status": "matched",
                    "amount": chosen["amount"],
                })
        except (KeyError, TypeError, AttributeError):
            continue
    return results


def compute_refunds(records):
    if not isinstance(records, (list, tuple)):
        return 0
    order_ids = set()
    for record in records:
        if not isinstance(record, dict):
            continue
        try:
            if record["type"] == "ORDER" and record["currency"] == "USD":
                order_ids.add(record["order_id"])
        except (KeyError, TypeError):
            continue
    total = 0
    for record in records:
        if not isinstance(record, dict):
            continue
        try:
            if (record["type"] == "PAYMENT"
                    and record["currency"] == "USD"
                    and record["amount"] < 0
                    and record["order_id"] in order_ids):
                total += abs(record["amount"])
        except (KeyError, TypeError):
            continue
    return total


def build_summary(matches, refund_total):
    if not isinstance(matches, (list, tuple)):
        matches = []

    total_orders = len(matches)
    matched_count = 0
    matched_total = 0
    unmatched = set()

    for result in matches:
        if not isinstance(result, dict):
            continue
        if result.get("status") == "matched":
            matched_count += 1
            try:
                matched_total += result["amount"]
            except (KeyError, TypeError):
                pass
        elif result.get("status") == "unmatched":
            if "order_id" in result:
                unmatched.add(result["order_id"])

    try:
        refund = refund_total
        net_total = matched_total - refund
    except TypeError:
        refund = 0
        net_total = matched_total
    if net_total < 0:
        net_total = 0

    return {
        "total_orders": total_orders,
        "matched_count": matched_count,
        "refund_total": refund,
        "net_total": net_total,
        "unmatched_ids": sorted(unmatched),
    }

