"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str) or not s:
        return None
    start = 1 if s[0] == "-" else 0
    if start == len(s):
        return None
    body = s[start:]
    if body.count(".") > 1:
        return None
    if "." in body:
        whole, fraction = body.split(".")
    else:
        whole, fraction = body, ""
    if not whole or any(ch < "0" or ch > "9" for ch in whole):
        return None
    if any(ch < "0" or ch > "9" for ch in fraction):
        return None
    if len(fraction) > 3:
        return None
    cents = int(whole) * 100
    if len(fraction) >= 1:
        cents += int(fraction[0]) * 10
    if len(fraction) >= 2:
        cents += int(fraction[1])
    if len(fraction) == 3 and int(fraction[2]) >= 5:
        cents += 1
    if s[0] == "-":
        cents = -cents
    if abs(cents) > 1000000:
        return None
    return cents


def parse_record(line):
    try:
        if not isinstance(line, str):
            return None
        fields = line.split("|")
        if len(fields) != 6:
            return None
        record_type, record_id, order_id, amount_text, currency, timestamp_text = fields
        record_type = record_type.upper()
        if record_type not in ("ORDER", "PAYMENT"):
            return None
        record_id = record_id.strip()
        order_id = order_id.strip()
        if not record_id or not order_id or not order_id.startswith("ORD-"):
            return None
        if currency != "USD":
            return None
        amount = parse_amount(amount_text)
        if amount is None:
            return None
        if record_type == "ORDER" and amount < 0:
            return None
        if len(timestamp_text) == 16:
            timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
            if timestamp.strftime("%Y-%m-%d %H:%M") != timestamp_text:
                return None
        elif len(timestamp_text) == 19:
            timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M:%S")
            if timestamp.strftime("%Y-%m-%d %H:%M:%S") != timestamp_text:
                return None
        else:
            return None
        return {
            "type": record_type,
            "record_id": record_id,
            "order_id": order_id,
            "amount": amount,
            "currency": currency,
            "timestamp": timestamp,
        }
    except Exception:
        return None


def load_records(text):
    retained = []
    seen_ids = set()
    if not isinstance(text, str):
        return retained
    for line in text.splitlines():
        record = parse_record(line)
        if record is None:
            continue
        if record["record_id"] in seen_ids:
            continue
        seen_ids.add(record["record_id"])
        retained.append(record)
    return retained


def match_payments(records):
    results = []
    try:
        for order in records:
            if order.get("type") != "ORDER":
                continue
            selected = None
            selected_time = None
            cutoff = order["timestamp"] + timedelta(hours=72)
            for payment in records:
                if payment.get("type") != "PAYMENT":
                    continue
                if payment.get("order_id") != order.get("order_id"):
                    continue
                if payment.get("amount", 0) < 0:
                    continue
                timestamp = payment.get("timestamp")
                if timestamp < order["timestamp"] or timestamp >= cutoff:
                    continue
                if selected is None or timestamp < selected_time:
                    selected = payment
                    selected_time = timestamp
            if selected is None:
                results.append({
                    "order_id": order["order_id"],
                    "status": "unmatched",
                    "amount": 0,
                })
            else:
                results.append({
                    "order_id": order["order_id"],
                    "status": "matched",
                    "amount": selected["amount"],
                })
        return results
    except Exception:
        return results


def compute_refunds(records):
    try:
        order_ids = set()
        for record in records:
            if (
                isinstance(record, dict)
                and record.get("type") == "ORDER"
                and record.get("currency") == "USD"
            ):
                order_ids.add(record.get("order_id"))
        total = 0
        for record in records:
            if (
                isinstance(record, dict)
                and record.get("type") == "PAYMENT"
                and record.get("currency") == "USD"
                and isinstance(record.get("amount"), int)
                and record.get("amount") < 0
                and record.get("order_id") in order_ids
            ):
                total += abs(record["amount"])
        return total
    except Exception:
        return 0


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = 0
    matched_total = 0
    unmatched = set()

    for match in matches:
        if match.get("status") == "matched":
            matched_count += 1
            matched_total += match.get("amount", 0)
        elif match.get("status") == "unmatched":
            unmatched.add(match.get("order_id"))

    net_total = matched_total - refund_total
    if net_total < 0:
        net_total = 0

    return {
        "total_orders": total_orders,
        "matched_count": matched_count,
        "refund_total": refund_total,
        "net_total": net_total,
        "unmatched_ids": sorted(unmatched),
    }

