from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str):
        return None
    try:
        text = s.strip()
        if not text or text.startswith("+"):
            return None
        negative = text.startswith("-")
        body = text[1:] if negative else text
        if not body or body.count(".") > 1:
            return None
        parts = body.split(".")
        if not parts[0].isdigit():
            return None
        if len(parts) == 2:
            if not parts[1] or not parts[1].isdigit():
                return None
            if len(parts[1]) > 3:
                return None
        value = Decimal(text)
        cents = int((value * Decimal("100")).quantize(
            Decimal("1"), rounding=ROUND_HALF_UP
        ))
        if abs(cents) > 1000000:
            return None
        return cents
    except (InvalidOperation, ValueError, TypeError, OverflowError):
        return None


def parse_record(line):
    if not isinstance(line, str):
        return None
    parts = line.split("|")
    if len(parts) != 6:
        return None
    record_type, record_id, order_id, amount_text, currency, timestamp = (
        part.strip() for part in parts
    )
    record_type = record_type.upper()
    if record_type not in ("ORDER", "PAYMENT"):
        return None
    if not record_id or not order_id or not order_id.startswith("ORD-"):
        return None
    if currency != "USD":
        return None
    amount = parse_amount(amount_text)
    if amount is None or (record_type == "ORDER" and amount < 0):
        return None
    parsed_time = None
    for fmt in ("%Y-%m-%d %H:%M", "%Y-%m-%d %H:%M:%S"):
        try:
            parsed_time = datetime.strptime(timestamp, fmt)
            break
        except ValueError:
            continue
    if parsed_time is None:
        return None
    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": parsed_time,
    }


def load_records(text):
    if not isinstance(text, str):
        return []
    records = []
    seen = set()
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None and record["record_id"] not in seen:
            seen.add(record["record_id"])
            records.append(record)
    return records


def match_payments(records):
    if not isinstance(records, list):
        return []
    results = []
    for order in records:
        if not isinstance(order, dict) or order.get("type") != "ORDER":
            continue
        order_id = order.get("order_id")
        order_time = order.get("timestamp")
        chosen = None
        if isinstance(order_time, datetime):
            end_time = order_time + timedelta(hours=72)
            for payment in records:
                if not isinstance(payment, dict):
                    continue
                if payment.get("type") != "PAYMENT":
                    continue
                if payment.get("order_id") != order_id:
                    continue
                amount = payment.get("amount")
                payment_time = payment.get("timestamp")
                if not isinstance(amount, int) or amount < 0:
                    continue
                if not isinstance(payment_time, datetime):
                    continue
                if order_time <= payment_time < end_time:
                    if chosen is None or payment_time < chosen["timestamp"]:
                        chosen = payment
        if chosen is None:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": chosen["amount"],
            })
    return results


def compute_refunds(records):
    if not isinstance(records, list):
        return 0
    order_ids = {
        item.get("order_id") for item in records
        if isinstance(item, dict) and item.get("type") == "ORDER"
    }
    total = 0
    for item in records:
        if not isinstance(item, dict):
            continue
        amount = item.get("amount")
        if (item.get("type") == "PAYMENT"
                and isinstance(amount, int)
                and amount < 0
                and item.get("order_id") in order_ids):
            total += -amount
    return total


def build_summary(matches, refund_total):
    if not isinstance(matches, list):
        matches = []
    if not isinstance(refund_total, int):
        refund_total = 0
    matched = [
        item for item in matches
        if isinstance(item, dict) and item.get("status") == "matched"
    ]
    unmatched_ids = []
    for item in matches:
        if (isinstance(item, dict)
                and item.get("status") != "matched"
                and isinstance(item.get("order_id"), str)
                and item["order_id"] not in unmatched_ids):
            unmatched_ids.append(item["order_id"])
    matched_total = sum(
        item.get("amount", 0) for item in matched
        if isinstance(item.get("amount", 0), int)
    )
    return {
        "total_orders": len(matches),
        "matched_count": len(matched),
        "refund_total": refund_total,
        "net_total": max(0, matched_total - refund_total),
        "unmatched_ids": unmatched_ids,
    }

