    if s.startswith("-"):
        negative = True
        s = s[1:]

    if not s:
        return None

    parts = s.split(".")
    if len(parts) > 2:
        return None

    whole = parts[0]
    fraction = parts[1] if len(parts) == 2 else ""

    if not whole or any(char < "0" or char > "9" for char in whole):
        return None
    if len(fraction) > 3:
        return None
    if fraction and any(char < "0" or char > "9" for char in fraction):
        return None
    if len(parts) == 2 and not fraction:
        return None

    cents = int(whole) * 100
    fraction = fraction.ljust(3, "0")
    cents += int(fraction[:2])

    if fraction[2] >= "5":
        cents += 1

    if cents > 1_000_000:
        return None

    return -cents if negative else cents


def parse_record(line):
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount_text, currency, timestamp_text = fields

    record_type = record_type.upper()
    if record_type not in ("ORDER", "PAYMENT"):
