        amount = parse_amount(amount_text)
    except (ValueError, OverflowError):
        return None

    if amount is None:
        return None
    if record_type == "ORDER" and amount < 0:
        return None

    if len(timestamp_text) == 16:
        format_string = "%Y-%m-%d %H:%M"
        separator_positions = (4, 7, 10, 13)
    elif len(timestamp_text) == 19:
        format_string = "%Y-%m-%d %H:%M:%S"
        separator_positions = (4, 7, 10, 13, 16)
    else:
        return None

    expected_separators = {
        4: "-",
        7: "-",
        10: " ",
        13: ":",
        16: ":",
    }

    for position in separator_positions:
        if timestamp_text[position] != expected_separators[position]:
            return None

    for index, character in enumerate(timestamp_text):
        if index not in expected_separators and character not in "0123456789":
            return None

    try:
        timestamp = datetime.strptime(timestamp_text, format_string)
    except (TypeError, ValueError):
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


