        for source_index, payment in payments:
            if payment["order_id"] != order_id:
                continue
            payment_timestamp = payment["timestamp"]
            if order_timestamp <= payment_timestamp < deadline:
                qualifying.append((payment_timestamp, source_index, payment))

        if qualifying:
            qualifying.sort(key=lambda item: (item[0], item[1]))
            selected_payment = qualifying[0][2]
            matches.append({
