def parse_amount(s):
    """Convert a dollar amount to integer cents, or return None if invalid."""
    if isinstance(s, bool) or s is None:
        return None

    text = str(s).strip()
    if not _AMOUNT_RE.fullmatch(text):
        return None

    try:
        value = Decimal(text)
        if not value.is_finite():
            return None

        cents = int(
            (value * Decimal("100")).quantize(
                Decimal("1"),
                rounding=ROUND_HALF_UP,
            )
        )
    except (InvalidOperation, ValueError, OverflowError):
        return None

    if abs(cents) > 1_000_000:
        return None

    return cents


def parse_record(line):
    """Parse one six-field settlement record."""
    if not isinstance(line, str):
        return None

    line = line.strip()
    if not line or line.startswith("#"):
        return None

    parts = _split_record(line)
    if parts is None or any(part == "" for part in parts):
        return None

    record_type, record_id, order_id, amount_text, currency, timestamp_text = parts
    record_type = record_type.upper()

    if record_type not in {"ORDER", "PAYMENT"}:
        return None

    if not record_id or not order_id:
        return None

    if currency != "USD":
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None

    if record_type == "ORDER" and amount < 0:
        return None

    timestamp = _parse_timestamp(timestamp_text)
    if timestamp is None:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    """Load valid records, retaining only the first valid record ID."""
    if not isinstance(text, str):
        return []

    records = []
    seen_ids = set()

    for line in text.splitlines():
        record = parse_record(line)
        if record is None:
            continue

        record_id = record["record_id"]
        if record_id in seen_ids:
            continue

        seen_ids.add(record_id)
        records.append(record)

    return records


def match_payments(records):
    """Return one result for each order and its earliest qualifying payment."""
    if not isinstance(records, list):
        return []

    orders = []
    payments = []

    for index, record in enumerate(records):
        if not isinstance(record, dict):
            continue

        record_type = str(record.get("type", "")).upper()
        order_id = record.get("order_id")
        amount = record.get("amount")
        timestamp = record.get("timestamp")

        if not isinstance(order_id, str):
            continue
        if not isinstance(amount, int) or isinstance(amount, bool):
            continue
        if not isinstance(timestamp, datetime):
            continue

        if record_type == "ORDER" and amount >= 0:
            orders.append(record)
        elif record_type == "PAYMENT" and amount >= 0:
            payments.append((index, record))

    results = []

    for order in orders:
        qualifying = []

        for source_index, payment in payments:
            if payment["order_id"] != order["order_id"]:
                continue
            if payment["amount"] != order["amount"]:
                continue

            payment_time = payment["timestamp"]
            if (
