                < order["timestamp"] + timedelta(hours=72)
            ):
                qualifying.append((payment_time, source_index))

        if qualifying:
            results.append(
                {
                    "order_id": order["order_id"],
                    "status": "matched",
                    "amount": order["amount"],
                }
            )
        else:
            results.append(
                {
                    "order_id": order["order_id"],
                    "status": "unmatched",
                    "amount": 0,
                }
            )

    return results


def compute_refunds(records):
    """Return the positive total of qualifying negative payments."""
    if not isinstance(records, list):
        return 0

    order_ids = {
        record.get("order_id")
        for record in records
        if isinstance(record, dict)
        and str(record.get("type", "")).upper() == "ORDER"
    }

    total = 0

    for record in records:
        if not isinstance(record, dict):
            continue
        if str(record.get("type", "")).upper() != "PAYMENT":
            continue
        if record.get("order_id") not in order_ids:
            continue

        amount = record.get("amount")
        if isinstance(amount, int) and not isinstance(amount, bool) and amount < 0:
            total += abs(amount)

    return total


