from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str):
        return None

    if re.fullmatch(r"-?[0-9]+(?:\.[0-9]{0,3})?", s) is None:
        return None

    try:
        amount = Decimal(s).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        cents = int(amount * 100)
    except (InvalidOperation, ValueError, TypeError):
        return None

    if abs(cents) > 1_000_000:
        return None

    return cents


def parse_record(line):
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 6:
        return None

    type_value, record_id, order_id, amount_text, currency, timestamp_text = fields

    type_value = type_value.upper()
    if type_value not in ("ORDER", "PAYMENT"):
        return None

    record_id = record_id.strip()
    order_id = order_id.strip()

    if not record_id or not order_id or not order_id.startswith("ORD-"):
        return None

    if currency != "USD":
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None

    if type_value == "ORDER" and amount < 0:
        return None

    if re.fullmatch(
        r"[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}(?::[0-9]{2})?",
        timestamp_text,
    ) is None:
        return None

    try:
        if len(timestamp_text) == 16:
            timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
        else:
            timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M:%S")
    except (TypeError, ValueError):
        return None

    return {
        "type": type_value,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []

    retained = []
    seen_record_ids = set()

    for line in text.splitlines():
        try:
            record = parse_record(line)
        except Exception:
            record = None

        if record is None:
            continue

        record_id = record.get("record_id")
        if record_id in seen_record_ids:
            continue

        seen_record_ids.add(record_id)
        retained.append(record)

    return retained


def match_payments(records):
    if records is None:
        return []

    results = []

    try:
        record_list = list(records)
    except (TypeError, ValueError):
        return results

    payments = []

    for source_index, record in enumerate(record_list):
        if not isinstance(record, dict):
            continue

        if (
            record.get("type") == "PAYMENT"
            and record.get("currency") == "USD"
            and isinstance(record.get("order_id"), str)
            and isinstance(record.get("amount"), int)
            and not isinstance(record.get("amount"), bool)
            and record.get("amount") >= 0
            and isinstance(record.get("timestamp"), datetime)
        ):
            payments.append((source_index, record))

    for record in record_list:
        if not isinstance(record, dict) or record.get("type") != "ORDER":
            continue

        order_id = record.get("order_id")
        order_timestamp = record.get("timestamp")
        selected_payment = None
        selected_key = None

        if isinstance(order_id, str) and isinstance(order_timestamp, datetime):
            end_timestamp = order_timestamp + timedelta(hours=72)

            for source_index, payment in payments:
                if payment["order_id"] != order_id:
                    continue

                payment_timestamp = payment["timestamp"]
                if not (
                    order_timestamp <= payment_timestamp < end_timestamp
                ):
                    continue

                candidate_key = (payment_timestamp, source_index)
                if selected_key is None or candidate_key < selected_key:
                    selected_key = candidate_key
                    selected_payment = payment

        if selected_payment is None:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": selected_payment["amount"],
            })

    return results


def compute_refunds(records):
    if records is None:
        return 0

    try:
        record_list = list(records)
    except (TypeError, ValueError):
        return 0

    order_ids = set()

    for record in record_list:
        if not isinstance(record, dict):
            continue

        if (
            record.get("type") == "ORDER"
            and record.get("currency") == "USD"
            and isinstance(record.get("order_id"), str)
        ):
            order_ids.add(record["order_id"])

    refund_total = 0

    for record in record_list:
        if not isinstance(record, dict):
            continue

        if (
            record.get("type") == "PAYMENT"
            and record.get("currency") == "USD"
            and record.get("order_id") in order_ids
            and isinstance(record.get("amount"), int)
            and not isinstance(record.get("amount"), bool)
            and record["amount"] < 0
        ):
            refund_total += abs(record["amount"])

    return refund_total


def build_summary(matches, refund_total):
    if matches is None:
        result_list = []
    else:
        try:
            result_list = list(matches)
        except (TypeError, ValueError):
            result_list = []

    matched_count = 0
    matched_total = 0
    unmatched_ids = set()

    for result in result_list:
        if not isinstance(result, dict):
            continue

        status = result.get("status")

        if status == "matched":
            matched_count += 1
            amount = result.get("amount")
            if isinstance(amount, int) and not isinstance(amount, bool):
                matched_total += amount

        elif status == "unmatched":
            order_id = result.get("order_id")
            if isinstance(order_id, str):
                unmatched_ids.add(order_id)

    net_total = matched_total - refund_total
    if net_total < 0:
        net_total = 0

    return {
        "total_orders": len(result_list),
        "matched_count": matched_count,
        "refund_total": refund_total,
        "net_total": net_total,
        "unmatched_ids": sorted(unmatched_ids),
    }

"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    """Convert a dollar amount to integer cents, or return None if invalid."""
    if not isinstance(s, str):
        return None

    value = s.strip()
    if not value or not _AMOUNT_RE.fullmatch(value):
        return None

    try:
        number = Decimal(value)
        if not number.is_finite():
            return None

        with localcontext() as context:
            context.prec = max(
                28,
                len(value.replace(".", "").lstrip("+-")) + 10,
            )
            cents_decimal = (number * Decimal("100")).quantize(
                Decimal("1"),
                rounding=ROUND_HALF_UP,
            )
            cents = int(cents_decimal)

        if abs(cents) > 1_000_000:
            return None

        return cents
    except (InvalidOperation, ValueError, OverflowError):
        return None


def parse_record(line):
    """Parse a six-field pipe-separated record."""
    if not isinstance(line, str):
        return None

    parts = line.strip().split("|")
    if len(parts) != 6:
        return None

    (
        record_type,
        record_id,
        order_id,
        amount,
        currency,
        timestamp,
    ) = (part.strip() for part in parts)

    record_type = record_type.upper()
    currency = currency.upper()

    if record_type not in {"ORDER", "PAYMENT"}:
        return None
    if not record_id or not order_id:
        return None
    if not _CURRENCY_RE.fullmatch(currency):
        return None

    parsed_amount = parse_amount(amount)
    if parsed_amount is None:
        return None
    if record_type == "ORDER" and parsed_amount < 0:
        return None

    parsed_timestamp = _parse_timestamp(timestamp)
    if parsed_timestamp is None:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": parsed_amount,
        "currency": currency,
        "timestamp": parsed_timestamp,
    }


def load_records(text):
    """Parse valid records, retaining only the first record for each ID."""
    if not isinstance(text, str):
        return []

    records = []
    seen_ids = set()

    for line in text.splitlines():
        record = parse_record(line)
        if record is None:
            continue

        record_id = record["record_id"]
        if record_id in seen_ids:
            continue

        seen_ids.add(record_id)
        records.append(record)

    return records


def match_payments(records):
    """Return one matching result for each order."""
    if not isinstance(records, list):
        return []

    payments_by_order = {}

    for source_index, record in enumerate(records):
        if not isinstance(record, dict):
            continue
        if record.get("type") != "PAYMENT":
            continue

        order_id = record.get("order_id")
        amount = record.get("amount")
        timestamp = record.get("timestamp")

        if not isinstance(order_id, str):
            continue
        if not isinstance(amount, int) or isinstance(amount, bool):
            continue
        if amount < 0:
            continue
        if not isinstance(timestamp, datetime):
            continue

        payments_by_order.setdefault(order_id, []).append(
            (timestamp, source_index, amount)
        )

    results = []

    for order in records:
        if not isinstance(order, dict):
            continue
        if order.get("type") != "ORDER":
            continue

        order_id = order.get("order_id")
        order_amount = order.get("amount")
        order_timestamp = order.get("timestamp")

        selected = None

        if (
            isinstance(order_id, str)
            and isinstance(order_amount, int)
            and not isinstance(order_amount, bool)
            and isinstance(order_timestamp, datetime)
        ):
            latest_timestamp = order_timestamp + timedelta(hours=72)

            candidates = []
            for payment in payments_by_order.get(order_id, []):
                payment_timestamp, source_index, payment_amount = payment

                try:
                    in_window = (
                        order_timestamp
                        <= payment_timestamp
                        < latest_timestamp
                    )
                except TypeError:
                    in_window = False

                if (
                    payment_amount == order_amount
                    and in_window
                ):
                    candidates.append(payment)

            if candidates:
                selected = min(
                    candidates,
                    key=lambda item: (item[0], item[1]),
                )

        if selected is None:
            results.append(
                {
                    "order_id": order_id,
                    "status": "unmatched",
                    "amount": 0,
                }
            )
        else:
            results.append(
                {
                    "order_id": order_id,
                    "status": "matched",
                    "amount": selected[2],
                }
            )

    return results


def compute_refunds(records):
    """Return the total of refunds belonging to existing orders."""
    if not isinstance(records, list):
        return 0

    order_ids = {
        record.get("order_id")
        for record in records
        if (
            isinstance(record, dict)
            and record.get("type") == "ORDER"
        )
    }

    refund_total = 0

    for record in records:
        if not isinstance(record, dict):
            continue
        if record.get("type") != "PAYMENT":
            continue
        if record.get("order_id") not in order_ids:
            continue

        amount = record.get("amount")
        if (
            isinstance(amount, int)
            and not isinstance(amount, bool)
            and amount < 0
        ):
            refund_total += -amount

    return refund_total


def build_summary(matches, refund_total):
    """Build the reconciliation summary."""
    if not isinstance(matches, list):
        matches = []

    total_orders = 0
    matched_count = 0
    matched_total = 0
    unmatched_ids = set()

    for match in matches:
        if not isinstance(match, dict):
            continue

        total_orders += 1

        if match.get("status") == "matched":
            matched_count += 1
            amount = match.get("amount", 0)
            if isinstance(amount, int) and not isinstance(amount, bool):
                matched_total += amount
        else:
            order_id = match.get("order_id")
            if isinstance(order_id, str):
                unmatched_ids.add(order_id)

    if not isinstance(refund_total, int) or isinstance(refund_total, bool):
        refund_total = 0

    net_total = matched_total - refund_total
    if net_total < 0:
        net_total = 0

    return {
        "total_orders": total_orders,
        "matched_count": matched_count,
        "refund_total": refund_total,
        "net_total": net_total,
        "unmatched_ids": sorted(unmatched_ids),
    }

