"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str) or not s:
        return None

    negative = s.startswith("-")
    value = s[1:] if negative else s
    if not value:
        return None

    parts = value.split(".")
    if len(parts) > 2:
        return None
    if not parts[0] or not all("0" <= ch <= "9" for ch in parts[0]):
        return None

    fractional = parts[1] if len(parts) == 2 else ""
    if len(fractional) == 0 and len(parts) == 2:
        return None
    if len(fractional) > 3 or not all("0" <= ch <= "9" for ch in fractional):
        return None

    try:
        cents = int(
            (Decimal(value) * Decimal("100")).quantize(
                Decimal("1"), rounding=ROUND_HALF_UP
            )
        )
    except (InvalidOperation, ValueError):
        return None

    if negative:
        cents = -cents
    if abs(cents) > 1000000:
        return None
    return cents


def parse_record(line):
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount_text, currency, timestamp_text = fields
    record_type = record_type.upper()
    record_id = record_id.strip()
    order_id = order_id.strip()

    if record_type not in ("ORDER", "PAYMENT"):
        return None
    if not record_id or not order_id or not order_id.startswith("ORD-"):
        return None
    if currency != "USD":
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None
    if record_type == "ORDER" and amount < 0:
        return None

    if len(timestamp_text) not in (16, 19):
        return None
    if timestamp_text[4] != "-" or timestamp_text[7] != "-":
        return None
    if timestamp_text[10] != " " or timestamp_text[13] != ":":
        return None
    if len(timestamp_text) == 19 and timestamp_text[16] != ":":
        return None

    digit_positions = list(range(4)) + list(range(5, 7)) + list(range(8, 10))
    digit_positions += list(range(11, 13)) + list(range(14, 16))
    if len(timestamp_text) == 19:
        digit_positions += list(range(17, 19))
    if not all("0" <= timestamp_text[i] <= "9" for i in digit_positions):
        return None

    try:
        timestamp = datetime.strptime(
            timestamp_text,
            "%Y-%m-%d %H:%M:%S"
            if len(timestamp_text) == 19
            else "%Y-%m-%d %H:%M",
        )
    except (TypeError, ValueError):
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []

    retained = []
    seen_ids = set()

    for line in text.splitlines():
        record = parse_record(line)
        if record is None:
            continue
        record_id = record["record_id"]
        if record_id in seen_ids:
            continue
        seen_ids.add(record_id)
        retained.append(record)

    return retained


def match_payments(records):
    if not isinstance(records, (list, tuple)):
        return []

    results = []
    for order in records:
        if not isinstance(order, dict):
            continue
        if order.get("type") != "ORDER":
            continue

        order_id = order.get("order_id")
        order_time = order.get("timestamp")
        best = None
        best_key = None

        if isinstance(order_id, str) and isinstance(order_time, datetime):
            deadline = order_time + timedelta(hours=72)
            for source_index, payment in enumerate(records):
                if not isinstance(payment, dict):
                    continue
                if payment.get("type") != "PAYMENT":
                    continue
                if payment.get("order_id") != order_id:
                    continue
                amount = payment.get("amount")
                payment_time = payment.get("timestamp")
                if not isinstance(amount, int) or isinstance(amount, bool):
                    continue
                if amount < 0 or not isinstance(payment_time, datetime):
                    continue
                if payment_time < order_time or payment_time >= deadline:
                    continue

                candidate_key = (payment_time, source_index)
                if best_key is None or candidate_key < best_key:
                    best_key = candidate_key
                    best = payment

        if best is None:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": best["amount"],
            })

    return results


def compute_refunds(records):
    if not isinstance(records, (list, tuple)):
        return 0

    order_ids = set()
    for record in records:
        if not isinstance(record, dict):
            continue
        if record.get("type") == "ORDER" and record.get("currency") == "USD":
            order_id = record.get("order_id")
            if isinstance(order_id, str):
                order_ids.add(order_id)

    total = 0
    for record in records:
        if not isinstance(record, dict):
            continue
        if record.get("type") != "PAYMENT":
            continue
        if record.get("currency") != "USD":
            continue
        order_id = record.get("order_id")
        amount = record.get("amount")
        if order_id not in order_ids:
            continue
        if not isinstance(amount, int) or isinstance(amount, bool) or amount >= 0:
            continue
        total += abs(amount)

    return total


def build_summary(matches, refund_total):
    if not isinstance(matches, (list, tuple)):
        matches = []

    matched_count = 0
    matched_total = 0
    unmatched_ids = set()

    for result in matches:
        if not isinstance(result, dict):
            continue

        if result.get("status") == "matched":
            matched_count += 1
            amount = result.get("amount")
            if isinstance(amount, int) and not isinstance(amount, bool):
                matched_total += amount
        elif result.get("status") == "unmatched":
            order_id = result.get("order_id")
            if isinstance(order_id, str):
                unmatched_ids.add(order_id)

    if not isinstance(refund_total, int) or isinstance(refund_total, bool):
        refund_total = 0

    net_total = matched_total - refund_total
    if net_total < 0:
        net_total = 0

    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "refund_total": refund_total,
        "net_total": net_total,
        "unmatched_ids": sorted(unmatched_ids),
    }

