"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str) or not s:
        return None

    negative = s.startswith("-")
    body = s[1:] if negative else s
    if not body or body.count(".") > 1:
        return None

    if "." in body:
        whole, fraction = body.split(".")
        if not whole or not fraction or len(fraction) > 3:
            return None
    else:
        whole, fraction = body, ""

    if not whole.isascii() or not whole.isdigit():
        return None
    if fraction and (not fraction.isascii() or not fraction.isdigit()):
        return None

    try:
        cents = int(whole) * 100
        padded = fraction.ljust(3, "0")
        if padded:
            cents += int(padded[:2])
        if len(fraction) == 3 and int(fraction[2]) >= 5:
            cents += 1
    except (ValueError, OverflowError):
        return None

    if negative:
        cents = -cents
    if abs(cents) > 1_000_000:
        return None
    return cents


def parse_record(line):
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount_text, currency, timestamp_text = fields
    record_type = record_type.upper()
    record_id = record_id.strip()
    order_id = order_id.strip()

    if record_type not in ("ORDER", "PAYMENT"):
        return None
    if not record_id or not order_id or not order_id.startswith("ORD-"):
        return None
    if currency != "USD":
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None
    if record_type == "ORDER" and amount < 0:
        return None

    timestamp = None
    for fmt in ("%Y-%m-%d %H:%M", "%Y-%m-%d %H:%M:%S"):
        try:
            timestamp = datetime.strptime(timestamp_text, fmt)
            break
        except (TypeError, ValueError):
            pass
    if timestamp is None:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []

    retained = []
    seen_ids = set()

    for line in text.splitlines():
        record = parse_record(line)
        if record is None:
            continue
        if record["record_id"] in seen_ids:
            continue
        seen_ids.add(record["record_id"])
        retained.append(record)

    return retained


def match_payments(records):
    if not isinstance(records, list):
        return []

    results = []
    for order in records:
        if not isinstance(order, dict) or order.get("type") != "ORDER":
            continue

        order_id = order.get("order_id")
        order_time = order.get("timestamp")
        selected = None
        selected_time = None

        if isinstance(order_time, datetime):
            deadline = order_time + timedelta(hours=72)
            for payment in records:
                if not isinstance(payment, dict):
                    continue
                if payment.get("type") != "PAYMENT":
                    continue
                if payment.get("order_id") != order_id:
                    continue
                if payment.get("amount", 0) < 0:
                    continue

                payment_time = payment.get("timestamp")
                if not isinstance(payment_time, datetime):
                    continue
                if order_time <= payment_time < deadline:
                    if selected is None or payment_time < selected_time:
                        selected = payment
                        selected_time = payment_time

        if selected is None:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": selected["amount"],
            })

    return results


def compute_refunds(records):
    order_ids = set()
    for record in records:
        if (
            isinstance(record, dict)
            and record.get("type") == "ORDER"
            and record.get("currency") == "USD"
        ):
            order_ids.add(record.get("order_id"))

    total = 0
    for record in records:
        if (
            isinstance(record, dict)
            and record.get("type") == "PAYMENT"
            and record.get("currency") == "USD"
            and isinstance(record.get("amount"), int)
            and record["amount"] < 0
            and record.get("order_id") in order_ids
        ):
            total += abs(record["amount"])
    return total


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = 0
    matched_total = 0
    unmatched_ids = set()

    for result in matches:
        if result.get("status") == "matched":
            matched_count += 1
            matched_total += result.get("amount", 0)
        elif result.get("status") == "unmatched":
            unmatched_ids.add(result.get("order_id"))

    net_total = matched_total - refund_total
    if net_total < 0:
        net_total = 0

    return {
        "total_orders": total_orders,
        "matched_count": matched_count,
        "refund_total": refund_total,
        "net_total": net_total,
        "unmatched_ids": sorted(unmatched_ids),
    }

