from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    """Convert a decimal dollar amount to integer cents, or return None."""
    if not isinstance(s, str):
        return None

    value = s.strip()
    if not value or not _AMOUNT_RE.fullmatch(value):
        return None

    try:
        amount = Decimal(value)
        cents = (amount * Decimal("100")).quantize(
            Decimal("1"), rounding=ROUND_HALF_UP
        )
        cents = int(cents)
    except (InvalidOperation, ValueError, OverflowError):
        return None

    if abs(cents) > 1_000_000:
        return None

    return cents


def parse_record(line):
    """Parse one input line into a record dictionary, or return None."""
    if not isinstance(line, str):
        return None

    parts = line.split("|")
    if len(parts) != 6:
        return None

    (
        record_type,
        record_id,
        order_id,
        amount_text,
        currency,
        timestamp_text,
    ) = (part.strip() for part in parts)

    record_type = record_type.upper()
    if record_type not in {"ORDER", "PAYMENT"}:
        return None

    if not record_id or not order_id:
        return None

    if len(currency) != 3 or not currency.isalpha() or currency != currency.upper():
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None

    if record_type == "ORDER" and amount < 0:
        return None

    try:
        timestamp = datetime.fromisoformat(
            timestamp_text.replace("Z", "+00:00")
        )
    except (TypeError, ValueError):
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    """Parse valid records while keeping the first valid record ID."""
    if not isinstance(text, str):
        return []

    records = []
    seen_ids = set()

    for line in text.splitlines():
        record = parse_record(line)
        if record is None:
            continue

        record_id = record["record_id"]
        if record_id in seen_ids:
            continue

        seen_ids.add(record_id)
        records.append(record)

    return records


def match_payments(records):
    """Return one matching result for each order in retained order."""
    if not isinstance(records, list):
        return []

    orders = []
    payments = []

    for source_index, record in enumerate(records):
        if not isinstance(record, dict):
            continue

        if record.get("type") == "ORDER":
            orders.append(record)
        elif record.get("type") == "PAYMENT":
            amount = record.get("amount")
            if (
                isinstance(amount, int)
                and not isinstance(amount, bool)
                and amount >= 0
            ):
                payments.append((source_index, record))

    used_payment_indexes = set()
    results = []

    for order in orders:
        order_id = order.get("order_id")
        order_amount = order.get("amount")
        order_currency = order.get("currency")
        order_time = order.get("timestamp")
        candidates = []

        if isinstance(order_time, datetime):
            end_time = order_time + timedelta(hours=72)

            for source_index, payment in payments:
                if source_index in used_payment_indexes:
                    continue
                if payment.get("order_id") != order_id:
                    continue
                if payment.get("amount") != order_amount:
                    continue
                if payment.get("currency") != order_currency:
                    continue

                payment_time = payment.get("timestamp")
                if not isinstance(payment_time, datetime):
                    continue

                try:
                    if order_time <= payment_time < end_time:
                        candidates.append((payment_time, source_index))
                except TypeError:
                    continue

        if candidates:
            _, selected_index = min(
                candidates,
                key=lambda item: (item[0], item[1]),
            )
            used_payment_indexes.add(selected_index)
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": order_amount,
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })

    return results


def compute_refunds(records):
    """Return the positive total of qualifying negative payments in cents."""
    if not isinstance(records, list):
        return 0

    order_ids = {
        record.get("order_id")
        for record in records
        if (
            isinstance(record, dict)
            and record.get("type") == "ORDER"
            and isinstance(record.get("order_id"), str)
        )
    }

    total = 0
    for record in records:
        if not isinstance(record, dict):
            continue

        amount = record.get("amount")
        if (
            record.get("type") == "PAYMENT"
            and record.get("order_id") in order_ids
            and isinstance(amount, int)
            and not isinstance(amount, bool)
            and amount < 0
        ):
            total += -amount

    return total


def build_summary(matches, refund_total):
    """Build the reconciliation summary."""
    if not isinstance(matches, list):
        matches = []

    if not isinstance(refund_total, int) or isinstance(refund_total, bool) or refund_total < 0:
        refund_total = 0

    matched_count = 0
    matched_total = 0
    unmatched_ids = set()

    for result in matches:
        if not isinstance(result, dict):
            continue

        if result.get("status") == "matched":
            matched_count += 1
            amount = result.get("amount")
            if isinstance(amount, int) and not isinstance(amount, bool):
                matched_total += amount
        else:
            order_id = result.get("order_id")
            if isinstance(order_id, str):
                unmatched_ids.add(order_id)

    net_total = max(0, matched_total - refund_total)

    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "refund_total": refund_total,
        "net_total": net_total,
        "unmatched_ids": sorted(unmatched_ids),
    }

