"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str) or not s:
        return None
    negative = s.startswith("-")
    value = s[1:] if negative else s
    if not value or value.count(".") > 1:
        return None
    if "." in value:
        whole, fraction = value.split(".")
        if not whole or not fraction or len(fraction) > 3:
            return None
    else:
        whole, fraction = value, ""
    if not whole.isascii() or not whole.isdigit():
        return None
    if fraction and (not fraction.isascii() or not fraction.isdigit()):
        return None
    cents = int(whole) * 100
    if fraction:
        cents += int(fraction[:2].ljust(2, "0"))
        if len(fraction) == 3 and int(fraction[2]) >= 5:
            cents += 1
    if negative:
        cents = -cents
    if abs(cents) > 1000000:
        return None
    return cents


def parse_record(line):
    if not isinstance(line, str):
        return None
    fields = line.split("|")
    if len(fields) != 6:
        return None
