from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str) or not s:
        return None

    if s.startswith("-"):
        number = s[1:]
    else:
        number = s

    if not number:
        return None

    if number.count(".") > 1:
        return None

    if "." in number:
        whole, fraction = number.split(".")
        if not whole or not fraction:
            return None
        if len(fraction) > 3:
            return None
    else:
        whole = number
        fraction = ""

    if not all("0" <= character <= "9" for character in whole):
        return None
    if fraction and not all("0" <= character <= "9" for character in fraction):
        return None

    try:
        amount = Decimal(s).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        cents = int(amount * 100)
    except (InvalidOperation, ValueError, OverflowError):
        return None

    if abs(cents) > 1_000_000:
        return None

    return cents


def parse_record(line):
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount_text, currency, timestamp_text = fields

    record_type = record_type.upper()
    if record_type not in ("ORDER", "PAYMENT"):
        return None

    record_id = record_id.strip()
    order_id = order_id.strip()

    if not record_id or not order_id or not order_id.startswith("ORD-"):
        return None

    if currency != "USD":
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None

    if record_type == "ORDER" and amount < 0:
        return None

    if len(timestamp_text) not in (16, 19):
        return None

    if len(timestamp_text) == 16:
        timestamp_format = "%Y-%m-%d %H:%M"
        expected_positions = (4, 7, 10, 13)
    else:
        timestamp_format = "%Y-%m-%d %H:%M:%S"
        expected_positions = (4, 7, 10, 13, 16)

    separators = {
        4: "-",
        7: "-",
        10: " ",
        13: ":",
    }
    if len(timestamp_text) == 19:
        separators[16] = ":"

    for position, separator in separators.items():
        if timestamp_text[position] != separator:
            return None

    for position, character in enumerate(timestamp_text):
        if position not in separators and not character.isdigit():
            return None

    try:
        timestamp = datetime.strptime(timestamp_text, timestamp_format)
    except (TypeError, ValueError):
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []

    retained = []
    seen_record_ids = set()

    for line in text.splitlines():
        record = parse_record(line)
        if record is None:
            continue

        record_id = record["record_id"]
        if record_id in seen_record_ids:
            continue

        seen_record_ids.add(record_id)
        retained.append(record)

    return retained


def match_payments(records):
    results = []

    if not isinstance(records, (list, tuple)):
        return results

    for order in records:
        if not isinstance(order, dict) or order.get("type") != "ORDER":
            continue

        order_id = order.get("order_id")
        order_timestamp = order.get("timestamp")
        selected_payment = None
        selected_key = None

        if isinstance(order_id, str) and isinstance(order_timestamp, datetime):
            deadline = order_timestamp + timedelta(hours=72)

            for source_index, payment in enumerate(records):
                if not isinstance(payment, dict):
                    continue
                if payment.get("type") != "PAYMENT":
                    continue
                if payment.get("order_id") != order_id:
                    continue

                amount = payment.get("amount")
                payment_timestamp = payment.get("timestamp")

                if not isinstance(amount, int) or amount < 0:
                    continue
                if not isinstance(payment_timestamp, datetime):
                    continue
                if payment_timestamp < order_timestamp or payment_timestamp >= deadline:
                    continue

                candidate_key = (payment_timestamp, source_index)
                if selected_key is None or candidate_key < selected_key:
                    selected_key = candidate_key
                    selected_payment = payment

        if selected_payment is None:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": selected_payment["amount"],
            })

    return results


def compute_refunds(records):
    if not isinstance(records, (list, tuple)):
        return 0

    order_ids = set()
    for record in records:
        if not isinstance(record, dict):
            continue
        if record.get("type") == "ORDER":
            order_id = record.get("order_id")
            if isinstance(order_id, str):
                order_ids.add(order_id)

    refund_total = 0
    for record in records:
        if not isinstance(record, dict):
            continue
        if (
            record.get("type") == "PAYMENT"
            and record.get("currency") == "USD"
            and record.get("order_id") in order_ids
        ):
            amount = record.get("amount")
            if isinstance(amount, int) and amount < 0:
                refund_total += abs(amount)

    return refund_total


