        timestamp_format = "%Y-%m-%d %H:%M"
    else:
        timestamp_format = "%Y-%m-%d %H:%M:%S"

    try:
        timestamp = datetime.strptime(timestamp_text, timestamp_format)
    except (TypeError, ValueError):
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []

    retained = []
    seen_record_ids = set()

    for line in text.splitlines():
        try:
            record = parse_record(line)
        except Exception:
            record = None

        if record is None:
            continue

        record_id = record.get("record_id")
        if record_id in seen_record_ids:
            continue

        seen_record_ids.add(record_id)
        retained.append(record)

    return retained


def match_payments(records):
    items = list(records)
    payments = []

    for source_index, record in enumerate(items):
        if record["type"] == "PAYMENT" and record["amount"] >= 0:
            payments.append((source_index, record))

    matches = []

    for record in items:
        if record["type"] != "ORDER":
            continue

        order_time = record["timestamp"]
        latest_time = order_time + timedelta(hours=72)
        candidates = []

        for source_index, payment in payments:
            if payment["order_id"] != record["order_id"]:
                continue
            if order_time <= payment["timestamp"] < latest_time:
                candidates.append((payment["timestamp"], source_index, payment))

        if candidates:
            _, _, selected = min(candidates, key=lambda item: (item[0], item[1]))
            matches.append({
                "order_id": record["order_id"],
                "status": "matched",
                "amount": selected["amount"],
            })
        else:
            matches.append({
                "order_id": record["order_id"],
                "status": "unmatched",
                "amount": 0,
            })

    return matches


def compute_refunds(records):
    order_ids = set()
    payments = []

    try:
        items = list(records)
    except (TypeError, ValueError):
        return 0

    for record in items:
        if not isinstance(record, dict):
            continue

        record_type = record.get("type")
        order_id = record.get("order_id")

        if record_type == "ORDER":
            try:
                order_ids.add(order_id)
            except TypeError:
                continue
        elif record_type == "PAYMENT":
            payments.append(record)

    refund_total = 0

    for payment in payments:
        if payment.get("currency") != "USD":
            continue

        amount = payment.get("amount")
        order_id = payment.get("order_id")

        try:
            qualifies = amount < 0 and order_id in order_ids
        except (TypeError, ValueError):
            qualifies = False

        if qualifies:
            refund_total += abs(amount)

    return refund_total


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = 0
    matched_total = 0
    unmatched_ids = set()

    for result in matches:
        if result.get("status") == "matched":
            matched_count += 1
            matched_total += result.get("amount", 0)
        elif result.get("status") == "unmatched":
            unmatched_ids.add(result.get("order_id"))

    net_total = matched_total - refund_total
    if net_total < 0:
        net_total = 0

    return {
        "total_orders": total_orders,
        "matched_count": matched_count,
        "refund_total": refund_total,
        "net_total": net_total,
        "unmatched_ids": sorted(unmatched_ids),
    }

