"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        import re
        if not isinstance(s, str):
            return None
        text = s.strip()
        if not re.fullmatch(r"-?\d+(?:\.\d{1,3})?", text):
            return None
        value = Decimal(text)
        cents = int((value * Decimal("100")).quantize(
            Decimal("1"), rounding=ROUND_HALF_UP
        ))
        if abs(cents) > 1000000:
            return None
        return cents
    except (InvalidOperation, ValueError, TypeError, ArithmeticError):
        return None


def parse_record(line):
    try:
        if not isinstance(line, str):
            return None
        fields = line.strip().split("|")
        if len(fields) != 6:
            return None
        record_type, record_id, order_id, amount_text, currency, timestamp = fields
        record_type = record_type.strip().upper()
        record_id = record_id.strip()
        order_id = order_id.strip()
        currency = currency.strip()
        timestamp = timestamp.strip()
        if record_type not in ("ORDER", "PAYMENT"):
            return None
        if not record_id or not order_id.startswith("ORD-"):
            return None
        if currency != "USD":
            return None
        parsed_time = datetime.strptime(timestamp, "%Y-%m-%d %H:%M")
        if parsed_time.strftime("%Y-%m-%d %H:%M") != timestamp:
            return None
        amount = parse_amount(amount_text)
        if amount is None or (record_type == "ORDER" and amount < 0):
            return None
        return {
            "type": record_type,
            "record_id": record_id,
            "order_id": order_id,
            "amount": amount,
            "currency": currency,
            "timestamp": timestamp,
        }
    except Exception:
        return None


def load_records(text):
    if not isinstance(text, str):
        return []
    records = []
    seen = set()
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None and record["record_id"] not in seen:
            seen.add(record["record_id"])
            records.append(record)
    return records


def match_payments(records):
    if not isinstance(records, list):
        return []
    orders = []
    payments = []
    for record in records:
        if not isinstance(record, dict):
            continue
        if record.get("type") == "ORDER":
            orders.append(record)
        elif (record.get("type") == "PAYMENT"
              and isinstance(record.get("amount"), int)
              and record["amount"] >= 0):
            payments.append(record)

    results = []
    used = set()
    for order in orders:
        try:
            order_time = datetime.strptime(order["timestamp"], "%Y-%m-%d %H:%M")
        except Exception:
            order_time = None

        candidates = []
        for index, payment in enumerate(payments):
            if index in used:
                continue
            if payment.get("order_id") != order.get("order_id"):
                continue
            if payment.get("amount") != order.get("amount"):
                continue
            try:
                payment_time = datetime.strptime(
                    payment["timestamp"], "%Y-%m-%d %H:%M"
                )
            except Exception:
                continue
            if order_time is None:
                continue
            if not (order_time <= payment_time <
                    order_time + timedelta(hours=72)):
                continue
            candidates.append((payment_time, index, payment))

        if candidates:
