from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str) or s == "":
        return None

    value = s
    if value.startswith("-"):
        value = value[1:]
        if value == "":
            return None

    if value.count(".") > 1:
        return None

    if "." in value:
        whole, fraction = value.split(".")
        if whole == "" or not whole.isdigit():
            return None
        if fraction != "" and not fraction.isdigit():
            return None
        if len(fraction) > 3:
            return None
    else:
        whole = value
        fraction = ""
        if not whole.isdigit():
            return None

    if any(ch not in "0123456789" for ch in whole + fraction):
        return None

    try:
        amount = Decimal(s).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        cents = int(amount * 100)
    except (InvalidOperation, ValueError, TypeError):
        return None

    if abs(cents) > 1000000:
        return None

    return cents


def parse_record(line):
    if not isinstance(line, str):
        return None

    try:
        fields = line.split("|")
        if len(fields) != 6:
            return None

        record_type, record_id, order_id, amount_text, currency, timestamp_text = fields

        record_type = record_type.upper()
        if record_type not in ("ORDER", "PAYMENT"):
            return None

        record_id = record_id.strip()
        order_id = order_id.strip()
        if record_id == "" or order_id == "":
            return None
        if not order_id.startswith("ORD-"):
            return None

        if currency != "USD":
            return None

        amount = parse_amount(amount_text)
        if amount is None:
            return None
        if record_type == "ORDER" and amount < 0:
            return None

        if len(timestamp_text) not in (16, 19):
            return None
        if timestamp_text[10] != " ":
            return None
        if timestamp_text[4] != "-" or timestamp_text[7] != "-":
            return None
        if timestamp_text[13] != ":":
            return None
        if len(timestamp_text) == 19 and timestamp_text[16] != ":":
            return None

        for index, character in enumerate(timestamp_text):
            if index in (4, 7, 10, 13) or (len(timestamp_text) == 19 and index == 16):
                continue
            if not character.isdigit():
                return None

        timestamp_format = "%Y-%m-%d %H:%M"
        if len(timestamp_text) == 19:
            timestamp_format = "%Y-%m-%d %H:%M:%S"

        timestamp = datetime.strptime(timestamp_text, timestamp_format)

        return {
            "type": record_type,
            "record_id": record_id,
            "order_id": order_id,
            "amount": amount,
            "currency": currency,
            "timestamp": timestamp,
        }
    except Exception:
        return None


def load_records(text):
