    try:
        retained_records = list(records)
    except (TypeError, ValueError):
        return results

    for order in retained_records:
        if not isinstance(order, dict) or order.get("type") != "ORDER":
            continue

        order_id = order.get("order_id")
        order_timestamp = order.get("timestamp")

        try:
            deadline = order_timestamp + timedelta(hours=72)
        except (TypeError, ValueError):
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })
            continue

        selected_payment = None
        selected_key = None

        for source_index, payment in enumerate(retained_records):
            if not isinstance(payment, dict):
                continue
            if payment.get("type") != "PAYMENT":
                continue
            if payment.get("order_id") != order_id:
                continue

            amount = payment.get("amount")
            payment_timestamp = payment.get("timestamp")

            if not isinstance(amount, int) or isinstance(amount, bool):
                continue
            if amount < 0:
                continue

            try:
                if not (order_timestamp <= payment_timestamp < deadline):
                    continue
            except TypeError:
                continue

            candidate_key = (payment_timestamp, source_index)
            if selected_key is None or candidate_key < selected_key:
                selected_key = candidate_key
                selected_payment = payment

        if selected_payment is None:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": selected_payment["amount"],
            })

    return results


def compute_refunds(records):
    order_ids = set()

    try:
        for record in records:
            if (
                isinstance(record, dict)
                and record.get("type") == "ORDER"
                and record.get("currency") == "USD"
            ):
                order_ids.add(record.get("order_id"))
    except (TypeError, AttributeError):
