from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    """Convert a decimal dollar amount to integer cents, or return None."""
    if not isinstance(s, str):
        return None

    value_text = s.strip()
    if not value_text or not _AMOUNT_PATTERN.fullmatch(value_text):
        return None

    try:
        value = Decimal(value_text)
        if not value.is_finite():
            return None

        precision = max(28, len(value.as_tuple().digits) + 10)
        with localcontext() as context:
            context.prec = precision
            cents_value = value.quantize(
                Decimal("0.01"),
                rounding=ROUND_HALF_UP,
            ) * 100
            cents = int(cents_value)

        if abs(cents) > 1_000_000:
            return None
        return cents
    except (InvalidOperation, OverflowError, ValueError):
        return None


def parse_record(line):
    """Parse one six-field order or payment record."""
    if not isinstance(line, str) or not line.strip():
        return None

    fields = line.split("|")
    if len(fields) != 6:
        return None

    (
        record_type,
        record_id,
        order_id,
        amount_text,
        currency,
        timestamp_text,
    ) = (field.strip() for field in fields)

    record_type = record_type.upper()
    if record_type not in {"ORDER", "PAYMENT"}:
        return None

    if not record_id or not order_id:
        return None

    currency = currency.upper()
    if not _CURRENCY_PATTERN.fullmatch(currency):
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None

    if record_type == "ORDER" and amount < 0:
        return None

    timestamp = _parse_timestamp(timestamp_text)
    if timestamp is None:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    """Load valid records, retaining only the first valid record ID."""
    if not isinstance(text, str):
        return []

    records = []
    seen_ids = set()

    for line in text.splitlines():
        record = parse_record(line)
        if record is None:
            continue

        record_id = record["record_id"]
        if record_id in seen_ids:
            continue

        seen_ids.add(record_id)
        records.append(record)

    return records


def match_payments(records):
    """Return one matching result for each retained order."""
    if not isinstance(records, list):
        return []

    orders = []
    payments = []

    for source_index, record in enumerate(records):
        if not isinstance(record, dict):
            continue

        if record.get("type") == "ORDER":
            orders.append((source_index, record))
        elif record.get("type") == "PAYMENT":
            amount = record.get("amount")
            if isinstance(amount, int) and not isinstance(amount, bool):
                if amount >= 0:
                    payments.append((source_index, record))

    used_payment_indexes = set()
    results = []

    for _, order in orders:
        order_id = order.get("order_id")
        order_amount = order.get("amount")
        order_currency = order.get("currency")
        order_time = order.get("timestamp")
        candidates = []

        if isinstance(order_time, datetime) and isinstance(order_amount, int):
            end_time = order_time + timedelta(hours=72)

            for payment_index, payment in payments:
                if payment_index in used_payment_indexes:
                    continue
                if payment.get("order_id") != order_id:
                    continue
                if payment.get("currency") != order_currency:
                    continue
                if payment.get("amount") != order_amount:
                    continue

                payment_time = payment.get("timestamp")
                if not isinstance(payment_time, datetime):
                    continue

                if payment_time < order_time or payment_time >= end_time:
                    continue

                candidates.append((payment_time, payment_index))

        if candidates:
            _, payment_index = min(candidates, key=lambda item: (item[0], item[1]))
            used_payment_indexes.add(payment_index)
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": order_amount,
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })

    return results


def compute_refunds(records):
    """Return the positive total of qualifying negative payments."""
    if not isinstance(records, list):
        return 0

    order_ids = {
        record.get("order_id")
        for record in records
        if isinstance(record, dict) and record.get("type") == "ORDER"
    }

    total = 0
    for record in records:
        if not isinstance(record, dict):
            continue
        if record.get("type") != "PAYMENT":
            continue

        amount = record.get("amount")
        if (
            isinstance(amount, int)
            and not isinstance(amount, bool)
            and amount < 0
            and record.get("order_id") in order_ids
        ):
            total += -amount

    return total


def build_summary(matches, refund_total):
    """Build the reconciliation summary."""
    if not isinstance(matches, list):
        matches = []

    matched_count = 0
    matched_total = 0
    unmatched_ids = set()

    for result in matches:
        if not isinstance(result, dict):
            continue

        if result.get("status") == "matched":
            matched_count += 1
            amount = result.get("amount")
            if isinstance(amount, int) and not isinstance(amount, bool):
                matched_total += amount
        elif result.get("status") == "unmatched":
            order_id = result.get("order_id")
            if isinstance(order_id, str):
                unmatched_ids.add(order_id)

    if not isinstance(refund_total, int) or isinstance(refund_total, bool):
        refund_total = 0

    net_total = max(0, matched_total - refund_total)

    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "refund_total": refund_total,
        "net_total": net_total,
