    digit_parts = [
        timestamp_text[:4],
        timestamp_text[5:7],
        timestamp_text[8:10],
        timestamp_text[11:13],
        timestamp_text[14:16],
    ]
    if len(timestamp_text) == 19:
        digit_parts.append(timestamp_text[17:19])

    if any(not part.isascii() or not part.isdigit() for part in digit_parts):
        return None

    try:
        timestamp = datetime.strptime(
            timestamp_text,
            "%Y-%m-%d %H:%M:%S" if len(timestamp_text) == 19
