"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str):
        return None
    value = s.strip()
    if not value or value.startswith("+"):
        return None
    negative = value.startswith("-")
    digits = value[1:] if negative else value
    if not digits or digits.count(".") > 1:
        return None
    whole, dot, fraction = digits.partition(".")
    if not whole and not fraction:
        return None
    if whole and not whole.isdigit():
        return None
    if fraction and not fraction.isdigit():
        return None
    if len(fraction) > 3:
        return None
    try:
        amount = Decimal(value).quantize(
            Decimal("0.01"), rounding=ROUND_HALF_UP
        )
        cents = int(amount * 100)
    except (InvalidOperation, ValueError, OverflowError):
        return None
    if abs(cents) > 1000000:
        return None
    return cents


def parse_record(line):
    if not isinstance(line, str):
        return None
    parts = line.strip().split("|")
    if len(parts) != 6:
        return None
    parts = [part.strip() for part in parts]
    record_type, record_id, order_id, amount, currency, timestamp = parts
    record_type = record_type.upper()
    if record_type not in ("ORDER", "PAYMENT"):
        return None
    if not record_id or not order_id or not order_id.startswith("ORD-"):
        return None
    if currency != "USD":
        return None
    cents = parse_amount(amount)
    if cents is None or (record_type == "ORDER" and cents < 0):
        return None
    parsed_time = None
    for fmt in ("%Y-%m-%d %H:%M", "%Y-%m-%d %H:%M:%S"):
        try:
            parsed_time = datetime.strptime(timestamp, fmt)
            break
        except (TypeError, ValueError):
            pass
    if parsed_time is None:
        return None
    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": cents,
        "currency": currency,
        "timestamp": parsed_time,
    }


def load_records(text):
    if not isinstance(text, str):
        return []
    records = []
    seen = set()
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None and record["record_id"] not in seen:
            seen.add(record["record_id"])
            records.append(record)
    return records


def match_payments(records):
    if not isinstance(records, list):
        return []
    orders = {}
    for record in records:
        if (isinstance(record, dict)
                and record.get("type") == "ORDER"
                and record.get("order_id") not in orders):
            orders[record.get("order_id")] = record

    results = []
    for order_id, order in orders.items():
        start = order.get("timestamp")
        chosen = None
        if isinstance(start, datetime):
            end = start + timedelta(hours=72)
            for record in records:
                if (isinstance(record, dict)
                        and record.get("type") == "PAYMENT"
                        and record.get("order_id") == order_id
                        and record.get("amount", 0) >= 0
                        and isinstance(record.get("timestamp"), datetime)
                        and start <= record["timestamp"] < end):
                    if chosen is None or record["timestamp"] < chosen["timestamp"]:
                        chosen = record
        if chosen is None:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": chosen["amount"],
            })
    return results


def compute_refunds(records):
    if not isinstance(records, list):
        return 0
    order_ids = {
        record.get("order_id")
        for record in records
        if isinstance(record, dict) and record.get("type") == "ORDER"
    }
    total = 0
    for record in records:
        if (isinstance(record, dict)
                and record.get("type") == "PAYMENT"
                and record.get("order_id") in order_ids
                and isinstance(record.get("amount"), int)
                and record["amount"] < 0):
            total -= record["amount"]
    return total


def build_summary(matches, refund_total):
    if not isinstance(matches, list):
        matches = []
    if not isinstance(refund_total, int):
        refund_total = 0
    order_ids = set()
    unmatched_ids = set()
    matched_count = 0
    matched_total = 0
    for match in matches:
        if not isinstance(match, dict):
            continue
        order_id = match.get("order_id")
        if order_id is not None:
            order_ids.add(order_id)
        if match.get("status") == "matched":
            matched_count += 1
            if isinstance(match.get("amount"), int):
                matched_total += match["amount"]
        elif order_id is not None:
            unmatched_ids.add(order_id)
    return {
        "total_orders": len(order_ids),
        "matched_count": matched_count,
        "refund_total": refund_total,
        "net_total": max(0, matched_total - refund_total),
        "unmatched_ids": sorted(unmatched_ids),
    }

"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str) or not s:
        return None

    if s.startswith("-"):
        digits = s[1:]
    else:
        digits = s

    if not digits:
        return None

    parts = digits.split(".")
    if len(parts) > 2:
        return None

    whole = parts[0]
    if not whole or any(char < "0" or char > "9" for char in whole):
        return None

    if len(parts) == 2:
        fraction = parts[1]
        if not fraction or len(fraction) > 3:
            return None
        if any(char < "0" or char > "9" for char in fraction):
            return None

    try:
        cents = int(
            (Decimal(s) * Decimal("100")).quantize(
                Decimal("1"),
                rounding=ROUND_HALF_UP
            )
        )
    except (InvalidOperation, ValueError, OverflowError):
        return None

    if abs(cents) > 1_000_000:
        return None

    return cents


def parse_record(line):
    try:
        if not isinstance(line, str):
            return None

        fields = line.split("|")
        if len(fields) != 6:
            return None

        record_type, record_id, order_id, amount_text, currency, timestamp_text = fields
        record_type = record_type.upper()

        if record_type not in ("ORDER", "PAYMENT"):
            return None

        record_id = record_id.strip()
        order_id = order_id.strip()

        if not record_id or not order_id or not order_id.startswith("ORD-"):
            return None

        if currency != "USD":
            return None

        amount = parse_amount(amount_text)
        if amount is None:
            return None

        if record_type == "ORDER" and amount < 0:
            return None

        if len(timestamp_text) not in (16, 19):
            return None

        if len(timestamp_text) == 16:
            if timestamp_text[10] != " " or timestamp_text[13] != ":":
                return None
            timestamp_format = "%Y-%m-%d %H:%M"
        else:
            if (
                timestamp_text[10] != " "
                or timestamp_text[13] != ":"
                or timestamp_text[16] != ":"
            ):
                return None
            timestamp_format = "%Y-%m-%d %H:%M:%S"

        for index, character in enumerate(timestamp_text):
            if index in (4, 7, 10, 13) or (
                len(timestamp_text) == 19 and index == 16
            ):
                continue
            if character < "0" or character > "9":
                return None

        timestamp = datetime.strptime(timestamp_text, timestamp_format)

        return {
            "type": record_type,
            "record_id": record_id,
            "order_id": order_id,
            "amount": amount,
            "currency": currency,
            "timestamp": timestamp,
        }
    except (TypeError, ValueError, OverflowError):
        return None


def load_records(text):
    if not isinstance(text, str):
        return []

    retained = []
    seen_record_ids = set()

    for line in text.splitlines():
        try:
            record = parse_record(line)
        except Exception:
            continue

        if not isinstance(record, dict):
            continue

        record_id = record.get("record_id")
        if not isinstance(record_id, str):
            continue

        if record.get("currency") != "USD":
            continue

        amount = record.get("amount")
        if isinstance(amount, bool) or not isinstance(amount, int):
            continue

        if record_id in seen_record_ids:
            continue

        seen_record_ids.add(record_id)
        retained.append(record)

    return retained


def match_payments(records):
    if records is None:
        return []

    try:
        retained = list(records)
    except (TypeError, ValueError):
        return []

    payments = []
    orders = []

    for source_index, record in enumerate(retained):
        if not isinstance(record, dict):
            continue

        if (
            record.get("type") == "PAYMENT"
            and record.get("currency") == "USD"
            and isinstance(record.get("order_id"), str)
            and isinstance(record.get("timestamp"), datetime)
            and isinstance(record.get("amount"), int)
            and not isinstance(record.get("amount"), bool)
            and record.get("amount") >= 0
        ):
            payments.append((source_index, record))

        if (
            record.get("type") == "ORDER"
            and record.get("currency") == "USD"
            and isinstance(record.get("order_id"), str)
            and isinstance(record.get("timestamp"), datetime)
        ):
            orders.append(record)

    results = []

    for order in orders:
        order_id = order["order_id"]
        order_time = order["timestamp"]
        try:
            end_time = order_time + timedelta(hours=72)
        except (TypeError, OverflowError):
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })
            continue

        selected = None
        selected_key = None

        for source_index, payment in payments:
            if payment["order_id"] != order_id:
                continue

            payment_time = payment["timestamp"]
            if order_time <= payment_time < end_time:
                key = (payment_time, source_index)
                if selected_key is None or key < selected_key:
                    selected = payment
                    selected_key = key

        if selected is None:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": selected["amount"],
            })

    return results


def compute_refunds(records):
    """Return the total in cents for refunds tied to existing orders."""
    if records is None:
        return 0

    try:
        existing_orders = set()

        for record in records:
            if not isinstance(record, dict):
                continue
            if (
                record.get("type") == "ORDER"
                and record.get("currency") == "USD"
                and isinstance(record.get("order_id"), str)
            ):
                existing_orders.add(record["order_id"])

        refund_total = 0

        for record in records:
            if not isinstance(record, dict):
                continue

            amount = record.get("amount")
            if (
                record.get("type") == "PAYMENT"
                and record.get("currency") == "USD"
                and isinstance(amount, int)
                and not isinstance(amount, bool)
                and amount < 0
                and record.get("order_id") in existing_orders
            ):
                refund_total += abs(amount)

        return refund_total
    except (TypeError, AttributeError):
        return 0


def build_summary(matches, refund_total):
    try:
        results = list(matches)
    except (TypeError, ValueError):
        results = []

    matched_count = 0
    matched_total = 0
    unmatched_ids = set()

    for result in results:
        if not isinstance(result, dict):
            continue

        status = result.get("status")

        if status == "matched":
            matched_count += 1
            amount = result.get("amount")
            if isinstance(amount, int) and not isinstance(amount, bool):
                matched_total += amount

        elif status == "unmatched":
            order_id = result.get("order_id")
            if isinstance(order_id, str):
                unmatched_ids.add(order_id)

    if not isinstance(refund_total, int) or isinstance(refund_total, bool):
        refund_total = 0

    net_total = matched_total - refund_total
    if net_total < 0:
        net_total = 0

    return {
        "total_orders": len(results),
        "matched_count": matched_count,
        "refund_total": refund_total,
        "net_total": net_total,
        "unmatched_ids": sorted(unmatched_ids),
    }

