"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str) or not s:
        return None
    negative = s.startswith("-")
    body = s[1:] if negative else s
    if not body or body.count(".") > 1:
        return None
    if "." in body:
        whole, fraction = body.split(".")
        if not whole or not fraction:
            return None
    else:
        whole, fraction = body, ""
    if not whole or any(c < "0" or c > "9" for c in whole):
        return None
    if any(c < "0" or c > "9" for c in fraction) or len(fraction) > 3:
        return None
    cents = int(whole) * 100
    if len(fraction) >= 1:
        cents += int(fraction[0]) * 10
    if len(fraction) >= 2:
        cents += int(fraction[1])
    if len(fraction) == 3 and int(fraction[2]) >= 5:
        cents += 1
    if negative:
        cents = -cents
    return cents if abs(cents) <= 1000000 else None


def parse_record(line):
    if not isinstance(line, str):
        return None
    fields = line.split("|")
    if len(fields) != 6:
        return None
    kind, record_id, order_id, amount_text, currency, timestamp_text = fields
    kind = kind.upper()
    record_id = record_id.strip()
    order_id = order_id.strip()
    if kind not in ("ORDER", "PAYMENT") or not record_id:
        return None
    if not order_id or not order_id.startswith("ORD-") or currency != "USD":
        return None
    amount = parse_amount(amount_text)
    if amount is None or (kind == "ORDER" and amount < 0):
        return None
    if len(timestamp_text) not in (16, 19):
        return None
    try:
        timestamp = datetime.strptime(
            timestamp_text,
            "%Y-%m-%d %H:%M:%S" if len(timestamp_text) == 19
            else "%Y-%m-%d %H:%M"
        )
    except (TypeError, ValueError, OverflowError):
        return None
    return {
        "type": kind,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []
    retained = []
    seen = set()
    for line in text.splitlines():
        try:
            record = parse_record(line)
        except Exception:
            record = None
        if record is not None and record["record_id"] not in seen:
            seen.add(record["record_id"])
            retained.append(record)
    return retained


def match_payments(records):
    try:
        results = []
        for order in records:
            if order["type"] != "ORDER":
                continue
            selected = None
            deadline = order["timestamp"] + timedelta(hours=72)
            for payment in records:
                if payment["type"] != "PAYMENT" or payment["amount"] < 0:
                    continue
                if payment["order_id"] != order["order_id"]:
                    continue
                if order["timestamp"] <= payment["timestamp"] < deadline:
                    if selected is None or payment["timestamp"] < selected["timestamp"]:
                        selected = payment
            if selected is None:
                results.append({
                    "order_id": order["order_id"],
                    "status": "unmatched",
                    "amount": 0,
                })
            else:
                results.append({
                    "order_id": order["order_id"],
                    "status": "matched",
                    "amount": selected["amount"],
                })
        return results
    except Exception:
        return []


def compute_refunds(records):
    try:
        order_ids = {
            record["order_id"]
            for record in records
            if record.get("type") == "ORDER"
            and record.get("currency") == "USD"
        }
        total = 0
        for record in records:
            if (
                record.get("type") == "PAYMENT"
                and record.get("currency") == "USD"
                and record.get("amount", 0) < 0
                and record.get("order_id") in order_ids
            ):
                total += abs(record["amount"])
        return total
    except Exception:
        return 0


def build_summary(matches, refund_total):
    try:
        total_orders = len(matches)
        matched_count = 0
        matched_total = 0
        unmatched_ids = set()

        for result in matches:
            if result.get("status") == "matched":
                matched_count += 1
                matched_total += result.get("amount", 0)
            elif result.get("status") == "unmatched":
                unmatched_ids.add(result.get("order_id"))

        net_total = matched_total - refund_total
        if net_total < 0:
            net_total = 0

        return {
            "total_orders": total_orders,
            "matched_count": matched_count,
            "refund_total": refund_total,
            "net_total": net_total,
            "unmatched_ids": sorted(unmatched_ids),
        }
    except Exception:
        return {
            "total_orders": 0,
            "matched_count": 0,
            "refund_total": refund_total,
            "net_total": 0,
            "unmatched_ids": [],
        }

"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        amount = Decimal(s)
        amount_cents = int(amount * 100)
        if abs(amount_cents) > 1000000:
            return None
        return amount_cents
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.strip().split('|')
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount, currency, timestamp = fields
    record_type = record_type.upper()

    # Validate TYPE
    if record_type not in ['ORDER', 'PAYMENT']:
        return None

    # Validate IDs
    if not record_id.strip() or not order_id.strip():
        return None

    # Validate AMOUNT
    amount_cents = parse_amount(amount)
    if amount_cents is None:
        return None

    # Validate CURRENCY
    if currency.strip() == '':
        return None

    # Validate TIMESTAMP
    try:
        datetime.fromisoformat(timestamp)
    except ValueError:
        return None

    return {
        'type': record_type,
        'record_id': record_id.strip(),
        'order_id': order_id.strip(),
        'amount': amount_cents,
        'currency': currency.strip(),
        'timestamp': timestamp.strip(),
    }


def load_records(text):
    records = []
    for line in text.strip().splitlines():
        record = parse_record(line)
        if record and not any(r['record_id'] == record['record_id'] for r in records):
            records.append(record)
    return records


def match_payments(records):
    orders = {}
    payments = []

    # Separate orders and payments
    for record in records:
        if record['type'] == 'ORDER':
            orders[record['order_id']] = record
        elif record['type'] == 'PAYMENT':
            payments.append(record)

    results = []

    for order_id, order in orders.items():
        order_timestamp = datetime.fromisoformat(order['timestamp'])
        order_amount = order['amount']
        matching_payments = []

        # Find payments that qualify for this order
        for payment in payments:
            if payment['order_id'] == order_id:
                payment_timestamp = datetime.fromisoformat(payment['timestamp'])
                if order_timestamp <= payment_timestamp < order_timestamp + timedelta(hours=72):
                    matching_payments.append(payment)

        if matching_payments:
            # Sort by timestamp and then by original order
            matching_payments.sort(key=lambda p: (datetime.fromisoformat(p['timestamp']), payments.index(p)))
            earliest_payment = matching_payments[0]
            results.append({
                'order_id': order_id,
                'status': 'matched',
                'amount': earliest_payment['amount'],
            })
        else:
            results.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': 0,
            })

    return results


def compute_refunds(records):
    refund_total = sum(
        record['amount'] for record in records 
        if record['type'] == 'PAYMENT' and record['amount'] < 0
    )
    return max(refund_total, 0)


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = max(sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total, 0)
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] != 'matched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids,
    }

