"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str):
        return None
    text = s.strip()
    if not text:
        return None
    body = text[1:] if text.startswith("-") else text
    if not body or body.count(".") > 1:
        return None
    parts = body.split(".")
    if not parts[0].isdigit():
        return None
    if len(parts) == 2 and (not parts[1].isdigit() or len(parts[1]) > 3):
        return None
    try:
        value = Decimal(text)
        cents = value.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        result = int(cents * 100)
        if abs(result) > 1000000:
            return None
        return result
    except (InvalidOperation, ValueError, TypeError):
        return None


def parse_record(line):
    if not isinstance(line, str):
        return None
    fields = line.split("|")
    if len(fields) != 6:
        return None
    kind, record_id, order_id, amount_text, currency, timestamp_text = fields
    kind = kind.upper()
    record_id = record_id.strip()
    order_id = order_id.strip()
    if kind not in ("ORDER", "PAYMENT"):
        return None
    if not record_id or not order_id.startswith("ORD-"):
        return None
    if currency != "USD":
        return None
    amount = parse_amount(amount_text)
    if amount is None or (kind == "ORDER" and amount < 0):
        return None
    timestamp = None
    for fmt in ("%Y-%m-%d %H:%M", "%Y-%m-%d %H:%M:%S"):
        try:
            timestamp = datetime.strptime(timestamp_text, fmt)
            break
        except (TypeError, ValueError):
            pass
    if timestamp is None:
        return None
    return {
        "type": kind,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []
    records = []
    seen = set()
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None and record["record_id"] not in seen:
            seen.add(record["record_id"])
            records.append(record)
    return records


def match_payments(records):
    if not isinstance(records, list):
        return []
    results = []
    for order in records:
        if not isinstance(order, dict) or order.get("type") != "ORDER":
            continue
        order_id = order.get("order_id")
        start = order.get("timestamp")
        chosen = None
        chosen_index = None
        if isinstance(order_id, str) and isinstance(start, datetime):
            end = start + timedelta(hours=72)
            for index, payment in enumerate(records):
                if not isinstance(payment, dict):
                    continue
                if payment.get("type") != "PAYMENT":
                    continue
                if payment.get("order_id") != order_id:
                    continue
                amount = payment.get("amount")
                timestamp = payment.get("timestamp")
                if not isinstance(amount, int) or amount < 0:
                    continue
                if not isinstance(timestamp, datetime):
                    continue
                if start <= timestamp < end:
                    if chosen is None or timestamp < chosen["timestamp"]:
                        chosen = payment
                        chosen_index = index
                    elif timestamp == chosen["timestamp"] and index < chosen_index:
                        chosen = payment
                        chosen_index = index
        if chosen is None:
            results.append({"order_id": order_id, "status": "unmatched", "amount": 0})
        else:
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": chosen["amount"],
            })
    return results


def compute_refunds(records):
    if not isinstance(records, list):
        return 0
    order_ids = {
        record.get("order_id")
        for record in records
        if isinstance(record, dict) and record.get("type") == "ORDER"
    }
    total = 0
    for record in records:
        if (
            isinstance(record, dict)
            and record.get("type") == "PAYMENT"
            and record.get("order_id") in order_ids
            and isinstance(record.get("amount"), int)
            and record["amount"] < 0
        ):
            total += -record["amount"]
    return total


def build_summary(matches, refund_total):
    if not isinstance(matches, list):
        matches = []
    matched_count = 0
    payment_total = 0
    unmatched = set()
    for result in matches:
        if not isinstance(result, dict):
            continue
        if result.get("status") == "matched":
            matched_count += 1
            amount = result.get("amount", 0)
            if isinstance(amount, int):
                payment_total += amount
        elif result.get("status") == "unmatched":
            order_id = result.get("order_id")
            if isinstance(order_id, str):
                unmatched.add(order_id)
    if not isinstance(refund_total, int):
        refund_total = 0
    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "refund_total": refund_total,
        "net_total": max(0, payment_total - refund_total),
        "unmatched_ids": sorted(unmatched),
    }

