"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        if not isinstance(s, str):
            return None
        text = s.strip()
        if not text:
            return None
        negative = text.startswith("-")
        body = text[1:] if negative else text
        if not body or body.count(".") > 1:
            return None
        parts = body.split(".")
        if not parts[0] or not all(c in "0123456789" for c in parts[0]):
            return None
        fraction = parts[1] if len(parts) == 2 else ""
        if fraction and not all(c in "0123456789" for c in fraction):
            return None
        if len(fraction) > 3:
            return None
        cents = int(Decimal(text).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP) * 100)
        return None if abs(cents) > 1000000 else cents
    except (InvalidOperation, ValueError, TypeError, ArithmeticError):
        return None


def parse_record(line):
    if not isinstance(line, str):
        return None
    fields = line.split("|")
    if len(fields) != 6:
        return None
    kind, record_id, order_id, amount_text, currency, timestamp_text = fields
    kind, record_id, order_id = kind.strip().upper(), record_id.strip(), order_id.strip()
    currency, timestamp_text = currency.strip(), timestamp_text.strip()
    if kind not in ("ORDER", "PAYMENT") or not record_id or not order_id.startswith("ORD-") or currency != "USD":
        return None
    amount = parse_amount(amount_text)
    if amount is None or (kind == "ORDER" and amount < 0):
        return None
    timestamp = None
    for fmt in ("%Y-%m-%d %H:%M", "%Y-%m-%d %H:%M:%S"):
        try:
            timestamp = datetime.strptime(timestamp_text, fmt)
            break
        except (ValueError, TypeError):
            pass
    if timestamp is None:
        return None
    return {"type": kind, "record_id": record_id, "order_id": order_id, "amount": amount, "currency": currency, "timestamp": timestamp}


def load_records(text):
    if not isinstance(text, str):
        return []
    result, seen = [], set()
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None and record["record_id"] not in seen:
            seen.add(record["record_id"])
            result.append(record)
    return result


def match_payments(records):
    if not isinstance(records, (list, tuple)):
        return []
    orders, order_ids, payments = [], set(), {}
    for record in records:
        if not isinstance(record, dict):
            continue
        oid = record.get("order_id")
        if not isinstance(oid, str):
            continue
        if record.get("type") == "ORDER" and oid not in order_ids:
            order_ids.add(oid)
            orders.append(record)
        elif record.get("type") == "PAYMENT" and isinstance(record.get("amount"), int) and record["amount"] >= 0:
            payments.setdefault(oid, []).append(record)
    results = []
    for order in orders:
        oid, chosen = order["order_id"], None
        start = order.get("timestamp")
        if isinstance(start, datetime):
            end = start + timedelta(hours=72)
            for payment in payments.get(oid, []):
                timestamp = payment.get("timestamp")
                if isinstance(timestamp, datetime) and start <= timestamp < end:
                    if chosen is None or timestamp < chosen["timestamp"]:
                        chosen = payment
        results.append({"order_id": oid, "status": "matched" if chosen else "unmatched", "amount": chosen["amount"] if chosen else 0})
    return results


def compute_refunds(records):
    if not isinstance(records, (list, tuple)):
        return 0
    order_ids = {r.get("order_id") for r in records if isinstance(r, dict) and r.get("type") == "ORDER" and isinstance(r.get("order_id"), str)}
    return sum(-r["amount"] for r in records if isinstance(r, dict) and r.get("type") == "PAYMENT" and r.get("order_id") in order_ids and isinstance(r.get("amount"), int) and r["amount"] < 0)


def build_summary(matches, refund_total):
    if not isinstance(matches, (list, tuple)):
        matches = []
    matched = [r for r in matches if isinstance(r, dict) and r.get("status") == "matched"]
    unmatched = sorted({r.get("order_id") for r in matches if isinstance(r, dict) and r.get("status") == "unmatched" and isinstance(r.get("order_id"), str)})
    refund_total = refund_total if isinstance(refund_total, int) else 0
    paid = sum(r.get("amount", 0) for r in matched if isinstance(r.get("amount"), int))
    return {"total_orders": len(matches), "matched_count": len(matched), "refund_total": refund_total, "net_total": max(0, paid - refund_total), "unmatched_ids": unmatched}

