"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    import re
    try:
        if not isinstance(s, str):
            return None
        text = s.strip()
        if not re.fullmatch(r"-?(?:\d+(?:\.\d*)?|\.\d+)", text):
            return None
        cents = (Decimal(text) * Decimal("100")).quantize(
            Decimal("1"), rounding=ROUND_HALF_UP
        )
        result = int(cents)
        if abs(result) > 1000000:
            return None
        return result
    except (InvalidOperation, ValueError, TypeError, OverflowError):
        return None


def parse_record(line):
    try:
        if not isinstance(line, str):
            return None
        parts = line.split("|")
        if len(parts) != 6:
            return None
        record_type, record_id, order_id, amount_text, currency, timestamp_text = parts
        record_type = record_type.strip().upper()
        record_id = record_id.strip()
        order_id = order_id.strip()
        if record_type not in ("ORDER", "PAYMENT"):
            return None
        if not record_id or not order_id.startswith("ORD-"):
            return None
        if currency != "USD":
            return None
        amount = parse_amount(amount_text)
        if amount is None or (record_type == "ORDER" and amount < 0):
            return None
        if len(timestamp_text) == 16:
            timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
        elif len(timestamp_text) == 19:
            timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M:%S")
        else:
            return None
        return {
            "type": record_type,
            "record_id": record_id,
            "order_id": order_id,
            "amount": amount,
            "currency": currency,
            "timestamp": timestamp,
        }
    except (ValueError, TypeError, OverflowError):
        return None


def load_records(text):
    if not isinstance(text, str):
        return []
    records = []
    seen = set()
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None and record["record_id"] not in seen:
            seen.add(record["record_id"])
            records.append(record)
    return records


def match_payments(records):
    if not isinstance(records, list):
        return []
    payments = []
    for source_index, record in enumerate(records):
        if not isinstance(record, dict) or record.get("type") != "PAYMENT":
            continue
        amount = record.get("amount")
        timestamp = record.get("timestamp")
        if isinstance(amount, int) and amount >= 0 and isinstance(timestamp, datetime):
            payments.append((record, source_index))

    results = []
    for order in records:
        if not isinstance(order, dict) or order.get("type") != "ORDER":
            continue
        order_id = order.get("order_id")
        order_time = order.get("timestamp")
        candidates = []
        if isinstance(order_time, datetime):
            deadline = order_time + timedelta(hours=72)
            for payment, source_index in payments:
                if payment.get("order_id") != order_id:
                    continue
                payment_time = payment.get("timestamp")
                if order_time <= payment_time < deadline:
                    candidates.append((payment_time, source_index, payment))
        if candidates:
            candidates.sort(key=lambda item: (item[0], item[1]))
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": candidates[0][2]["amount"],
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })
    return results


def compute_refunds(records):
    if not isinstance(records, list):
        return 0
    order_ids = {
        record.get("order_id")
        for record in records
        if isinstance(record, dict) and record.get("type") == "ORDER"
    }
    total = 0
    for record in records:
        if not isinstance(record, dict) or record.get("type") != "PAYMENT":
            continue
        amount = record.get("amount")
        if isinstance(amount, int) and amount < 0 and record.get("order_id") in order_ids:
            total += -amount
    return total


def build_summary(matches, refund_total):
    if not isinstance(matches, list):
        matches = []
    matched_count = sum(
        1 for result in matches
        if isinstance(result, dict) and result.get("status") == "matched"
    )
    unmatched = {
        result.get("order_id")
        for result in matches
        if isinstance(result, dict)
        and result.get("status") != "matched"
        and result.get("order_id") is not None
    }
    matched_total = sum(
        result.get("amount", 0)
        for result in matches
        if isinstance(result, dict) and result.get("status") == "matched"
    )
    try:
        refunds = int(refund_total)
    except (TypeError, ValueError, OverflowError):
        refunds = 0
    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "refund_total": refunds,
        "net_total": max(0, matched_total - refunds),
        "unmatched_ids": sorted(unmatched),
    }

