"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str):
        return None
    text = s
    body = text[1:] if text.startswith("-") else text
    if not body or body.count(".") > 1:
        return None
    pieces = body.split(".")
    if not pieces[0].isdigit():
        return None
    if len(pieces) == 2 and (
        not pieces[1] or not pieces[1].isdigit() or len(pieces[1]) > 3
    ):
        return None
    try:
        amount = Decimal(text).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        cents = int(amount * 100)
    except (InvalidOperation, ValueError, TypeError):
        return None
    if abs(cents) > 1000000:
        return None
    return cents


def parse_record(line):
    if not isinstance(line, str):
        return None
    parts = line.split("|")
    if len(parts) != 6:
        return None
    record_type, record_id, order_id, amount_text, currency, timestamp_text = parts
    record_type = record_type.upper()
    record_id = record_id.strip()
    order_id = order_id.strip()
    if record_type not in ("ORDER", "PAYMENT"):
        return None
    if not record_id or not order_id or not order_id.startswith("ORD-"):
        return None
    if currency != "USD":
        return None
    amount = parse_amount(amount_text)
    if amount is None:
        return None
    if record_type == "ORDER" and amount < 0:
        return None
    timestamp = None
    for fmt in ("%Y-%m-%d %H:%M", "%Y-%m-%d %H:%M:%S"):
        try:
            timestamp = datetime.strptime(timestamp_text, fmt)
            break
        except (TypeError, ValueError):
            pass
    if timestamp is None:
        return None
    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []
    retained = []
    seen_ids = set()
    for line in text.splitlines():
        record = parse_record(line)
        if record is None or record["record_id"] in seen_ids:
            continue
        seen_ids.add(record["record_id"])
        retained.append(record)
    return retained


def match_payments(records):
    try:
        items = list(records)
    except (TypeError, ValueError):
        return []
    payments = [
        record for record in items
        if isinstance(record, dict) and record.get("type") == "PAYMENT"
    ]
    results = []
    for order in items:
        if not isinstance(order, dict) or order.get("type") != "ORDER":
            continue
        order_id = order.get("order_id")
        order_time = order.get("timestamp")
        selected = None
        for payment in payments:
            if payment.get("amount", 0) < 0:
                continue
            if payment.get("order_id") != order_id:
                continue
            payment_time = payment.get("timestamp")
            try:
                qualifies = (
                    order_time <= payment_time <
                    order_time + timedelta(hours=72)
                )
            except (TypeError, ValueError):
                qualifies = False
            if not qualifies:
                continue
            if selected is None or payment_time < selected.get("timestamp"):
                selected = payment
        if selected is None:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": selected.get("amount"),
            })
    return results


def compute_refunds(records):
    try:
        items = list(records)
    except (TypeError, ValueError):
        return 0
    order_ids = {
        record.get("order_id")
        for record in items
        if isinstance(record, dict) and record.get("type") == "ORDER"
    }
    total = 0
    for record in items:
        if not isinstance(record, dict):
            continue
        if record.get("type") != "PAYMENT":
            continue
        if record.get("currency") != "USD":
            continue
        amount = record.get("amount")
        if type(amount) is int and amount < 0:
            if record.get("order_id") in order_ids:
                total += -amount
    return total


def build_summary(matches, refund_total):
    try:
        items = list(matches)
    except (TypeError, ValueError):
        items = []
    matched_count = 0
    matched_total = 0
    unmatched = set()
    for result in items:
        if not isinstance(result, dict):
            continue
        status = result.get("status")
        if status == "matched":
            matched_count += 1
            amount = result.get("amount", 0)
            if type(amount) is int:
                matched_total += amount
        elif status == "unmatched":
            unmatched.add(result.get("order_id"))
    net_total = matched_total - refund_total
    if net_total < 0:
        net_total = 0
    return {
        "total_orders": len(items),
        "matched_count": matched_count,
        "refund_total": refund_total,
        "net_total": net_total,
        "unmatched_ids": sorted(unmatched),
    }

