from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str) or s == "":
        return None
    value = s[1:] if s.startswith("-") else s
    if value == "" or value.count(".") > 1:
        return None
    parts = value.split(".")
    whole = parts[0]
    fraction = parts[1] if len(parts) == 2 else ""
    if whole == "" or any(ch < "0" or ch > "9" for ch in whole):
        return None
    if len(fraction) > 3 or any(ch < "0" or ch > "9" for ch in fraction):
        return None
    try:
        amount = Decimal(s).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        cents = int(amount * 100)
    except (InvalidOperation, ValueError, TypeError):
        return None
    if abs(cents) > 1000000:
        return None
    return cents


def parse_record(line):
    if not isinstance(line, str):
        return None
    fields = line.split("|")
    if len(fields) != 6:
        return None
    record_type, record_id, order_id, amount_text, currency, timestamp_text = fields
    record_type = record_type.upper()
    record_id = record_id.strip()
    order_id = order_id.strip()
    if record_type not in ("ORDER", "PAYMENT"):
        return None
    if record_id == "" or order_id == "" or not order_id.startswith("ORD-"):
        return None
    if currency != "USD":
        return None
    amount = parse_amount(amount_text)
    if amount is None or (record_type == "ORDER" and amount < 0):
        return None
    if len(timestamp_text) not in (16, 19):
        return None
    if timestamp_text[10] != " ":
        return None
    if timestamp_text[4] != "-" or timestamp_text[7] != "-":
        return None
    if len(timestamp_text) == 16:
        if timestamp_text[13] != ":":
            return None
        fmt = "%Y-%m-%d %H:%M"
    else:
        if timestamp_text[13] != ":" or timestamp_text[16] != ":":
            return None
        fmt = "%Y-%m-%d %H:%M:%S"
    if any(char not in "0123456789-: " for char in timestamp_text):
        return None
    try:
        timestamp = datetime.strptime(timestamp_text, fmt)
    except (ValueError, TypeError):
        return None
    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []
    retained = []
    seen_ids = set()
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None and record["record_id"] not in seen_ids:
            seen_ids.add(record["record_id"])
            retained.append(record)
    return retained


def match_payments(records):
    results = []
    try:
        for order in records:
            if not isinstance(order, dict) or order.get("type") != "ORDER":
                continue
            order_id = order.get("order_id")
            order_time = order.get("timestamp")
            selected = None
            for payment in records:
                if not isinstance(payment, dict):
                    continue
                if payment.get("type") != "PAYMENT":
                    continue
                if payment.get("order_id") != order_id:
                    continue
                amount = payment.get("amount")
                payment_time = payment.get("timestamp")
                if not isinstance(amount, int) or amount < 0:
                    continue
                if not isinstance(order_time, datetime) or not isinstance(payment_time, datetime):
                    continue
                if not (order_time <= payment_time < order_time + timedelta(hours=72)):
                    continue
                if selected is None or payment_time < selected["timestamp"]:
                    selected = payment
            if selected is None:
                results.append({"order_id": order_id, "status": "unmatched", "amount": 0})
            else:
                results.append({
                    "order_id": order_id,
                    "status": "matched",
                    "amount": selected["amount"],
                })
    except Exception:
        return []
    return results


def compute_refunds(records):
    try:
        order_ids = {
            record["order_id"]
            for record in records
            if isinstance(record, dict) and record.get("type") == "ORDER"
        }
        total = 0
        for record in records:
            if not isinstance(record, dict):
                continue
            if record.get("type") != "PAYMENT" or record.get("currency") != "USD":
                continue
            amount = record.get("amount")
            if isinstance(amount, int) and amount < 0 and record.get("order_id") in order_ids:
                total += abs(amount)
        return total
    except Exception:
        return 0


def build_summary(matches, refund_total):
    try:
        total_orders = len(matches)
        matched_count = 0
        matched_total = 0
        unmatched_ids = set()

        for result in matches:
            if not isinstance(result, dict):
                continue
            status = result.get("status")
            if status == "matched":
                matched_count += 1
                amount = result.get("amount")
                if isinstance(amount, int):
                    matched_total += amount
            elif status == "unmatched":
                unmatched_ids.add(result.get("order_id"))

        net_total = matched_total - refund_total
        if net_total < 0:
            net_total = 0

        return {
            "total_orders": total_orders,
            "matched_count": matched_count,
            "refund_total": refund_total,
            "net_total": net_total,
            "unmatched_ids": sorted(unmatched_ids),
        }
    except Exception:
        return {
            "total_orders": 0,
            "matched_count": 0,
            "refund_total": 0,
            "net_total": 0,
            "unmatched_ids": [],
        }

"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        amount = Decimal(s)
        if abs(amount) > 1000000:
            return None
        return int(amount * 100)  # Convert to cents
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.strip().split('|')
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount, currency, timestamp = fields
    record_type = record_type.upper()

    # Validate TYPE
    if record_type not in ['ORDER', 'PAYMENT']:
        return None

    # Validate IDs
    if not record_id.strip() or not order_id.strip():
        return None

    # Validate AMOUNT
    parsed_amount = parse_amount(amount)
    if parsed_amount is None:
        return None

    # Validate CURRENCY (assuming it should be a non-empty string)
    if not currency.strip():
        return None

    # Validate TIMESTAMP (assuming it should be a valid datetime string)
    try:
        datetime.strptime(timestamp, '%Y-%m-%d %H:%M:%S')
    except ValueError:
        return None

    return {
        'type': record_type,
        'record_id': record_id.strip(),
        'order_id': order_id.strip(),
        'amount': parsed_amount,
        'currency': currency.strip(),
        'timestamp': timestamp.strip(),
    }


def load_records(text):
    records = []
    for line in text.strip().splitlines():
        record = parse_record(line)
        if record is not None:
            # Check for duplicates and keep the first valid one
            if not any(r['record_id'] == record['record_id'] for r in records):
                records.append(record)
    return records


def match_payments(records):
    orders = {}
    payments = []

    for record in records:
        if record['type'] == 'ORDER':
            orders[record['order_id']] = record
        elif record['type'] == 'PAYMENT':
            payments.append(record)

    results = []

    for order_id, order in orders.items():
        order_timestamp = datetime.strptime(order['timestamp'], '%Y-%m-%d %H:%M:%S')
        end_time = order_timestamp + timedelta(hours=72)  # Adjusted to be strictly less than 72 hours

        qualifying_payments = [
            payment for payment in payments
            if payment['order_id'] == order_id and 
            order_timestamp <= datetime.strptime(payment['timestamp'], '%Y-%m-%d %H:%M:%S') < end_time and 
            payment['amount'] > 0  # Exclude refunds
        ]

        if qualifying_payments:
            # Sort by timestamp and then by original order
            qualifying_payments.sort(key=lambda p: (datetime.strptime(p['timestamp'], '%Y-%m-%d %H:%M:%S'), payments.index(p)))
            earliest_payment = qualifying_payments[0]
            results.append({
                'order_id': order_id,
                'status': 'matched',
                'amount': earliest_payment['amount'],
            })
        else:
            results.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': 0,
            })

    return results


def compute_refunds(records):
    refund_total = sum(
        record['amount'] for record in records 
        if record['type'] == 'PAYMENT' and record['amount'] < 0
    )
    return max(0, refund_total)  # Ensure refund total is non-negative


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = max(0, sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total)
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] != 'matched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids,
    }

"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str) or not s.strip():
        return None

    try:
        # Convert to Decimal
        amount = Decimal(s)
    except (InvalidOperation, ValueError):
        return None

    # Check for scientific notation or invalid format
    if 'e' in s.lower() or 'E' in s:
        return None

    # Round to at most 3 decimal places
    amount = amount.quantize(Decimal('0.001'), rounding=ROUND_HALF_UP)

    # Convert to cents
    cents = int(amount * 100)

    # Check for absolute value limit
    if abs(cents) > 1000000:
        return None

    return cents


def parse_record(line):
    fields = line.strip().split('|')

    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount_str, currency, timestamp_str = fields

    # Validate TYPE
    record_type = record_type.strip().upper()
    if record_type not in ['ORDER', 'PAYMENT']:
        return None

    # Validate RECORD_ID and ORDER_ID
    record_id = record_id.strip()
    order_id = order_id.strip()
    if not record_id or not order_id.startswith('ORD-'):
        return None

    # Validate CURRENCY
    if currency.strip() != 'USD':
        return None

    # Parse AMOUNT
    amount = parse_amount(amount_str.strip())
    if amount is None or (record_type == 'ORDER' and amount < 0):
        return None

    # Validate TIMESTAMP
    try:
        if len(timestamp_str) == 16:  # YYYY-MM-DD HH:MM
            timestamp = datetime.strptime(timestamp_str, '%Y-%m-%d %H:%M')
        elif len(timestamp_str) == 19:  # YYYY-MM-DD HH:MM:SS
            timestamp = datetime.strptime(timestamp_str, '%Y-%m-%d %H:%M:%S')
        else:
            return None
    except ValueError:
        return None

    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount,
        'currency': currency.strip(),
        'timestamp': timestamp
    }


def load_records(text):
    records = []
    seen_record_ids = set()

    for line in text.strip().splitlines():
        record = parse_record(line)
        if record and record['record_id'] not in seen_record_ids:
            records.append(record)
            seen_record_ids.add(record['record_id'])

    return records


def match_payments(records):
    orders = [record for record in records if record['type'] == 'ORDER']
    payments = [record for record in records if record['type'] == 'PAYMENT' and record['amount'] >= 0]

    results = []

    for order in orders:
        order_id = order['order_id']
        order_timestamp = order['timestamp']
        cutoff_time = order_timestamp + timedelta(hours=72)

        # Filter payments that match the order_id and are within the time window
        qualifying_payments = [
            payment for payment in payments
            if payment['order_id'] == order_id and order_timestamp <= payment['timestamp'] < cutoff_time
        ]

        if qualifying_payments:
            # Sort by timestamp, then by record_id
            qualifying_payments.sort(key=lambda p: (p['timestamp'], p['record_id']))
            earliest_payment = qualifying_payments[0]
            results.append({
                'order_id': order_id,
                'status': 'matched',
                'amount': earliest_payment['amount']
            })
        else:
            results.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': 0
            })

    return results


def compute_refunds(records):
    refund_total = 0

    # Create a set of valid order_ids from the records
    valid_order_ids = {record['order_id'] for record in records if record['type'] == 'ORDER'}

    # Iterate through records to find qualifying refunds
    for record in records:
        if record['type'] == 'PAYMENT' and record['currency'] == 'USD' and record['amount'] < 0:
            if record['order_id'] in valid_order_ids:
                refund_total += abs(record['amount'])

    return refund_total


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = max(sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total, 0)
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] == 'unmatched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

