"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str) or not s:
        return None

    negative = s.startswith("-")
    value = s[1:] if negative else s

    if not value or value.count(".") > 1:
        return None

    if "." in value:
        whole, fraction = value.split(".")
    else:
        whole, fraction = value, ""

    if not whole.isdigit():
        return None
    if fraction and not fraction.isdigit():
        return None
    if len(fraction) > 3:
        return None

    try:
        cents = int(whole) * 100
        if len(fraction) >= 1:
            cents += int(fraction[0]) * 10
        if len(fraction) >= 2:
            cents += int(fraction[1])
        if len(fraction) == 3 and fraction[2] >= "5":
            cents += 1
    except (TypeError, ValueError, OverflowError):
        return None

    if cents > 1000000:
        return None
    return -cents if negative else cents


def parse_record(line):
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount_text, currency, timestamp_text = fields
    record_type = record_type.upper()
    record_id = record_id.strip()
    order_id = order_id.strip()

    if record_type not in ("ORDER", "PAYMENT"):
        return None
    if not record_id or not order_id.startswith("ORD-"):
        return None
    if currency != "USD":
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None
    if record_type == "ORDER" and amount < 0:
        return None

    timestamp = None
    for fmt in ("%Y-%m-%d %H:%M", "%Y-%m-%d %H:%M:%S"):
        try:
            parsed = datetime.strptime(timestamp_text, fmt)
            if parsed.strftime(fmt) == timestamp_text:
                timestamp = parsed
                break
        except (TypeError, ValueError):
            pass

    if timestamp is None:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []

    retained = []
    seen_ids = set()

    for line in text.splitlines():
        try:
            record = parse_record(line)
        except Exception:
            record = None

        if record is None:
            continue

        record_id = record["record_id"]
        if record_id in seen_ids:
            continue

        seen_ids.add(record_id)
        retained.append(record)

    return retained


def match_payments(records):
    if records is None:
        return []

    results = []
    try:
        for order in records:
            if not isinstance(order, dict) or order.get("type") != "ORDER":
                continue

            best = None
            for payment in records:
                if not isinstance(payment, dict):
                    continue
                if payment.get("type") != "PAYMENT":
                    continue
                if payment.get("order_id") != order.get("order_id"):
                    continue

                amount = payment.get("amount")
                if not isinstance(amount, int) or amount < 0:
                    continue

                payment_time = payment.get("timestamp")
                order_time = order.get("timestamp")
                if not isinstance(payment_time, datetime):
                    continue
                if not isinstance(order_time, datetime):
                    continue
                if payment_time < order_time:
                    continue
                if payment_time >= order_time + timedelta(hours=72):
                    continue

                if best is None or payment_time < best.get("timestamp"):
                    best = payment

            if best is None:
                results.append({
                    "order_id": order.get("order_id"),
                    "status": "unmatched",
                    "amount": 0,
                })
            else:
                results.append({
                    "order_id": order.get("order_id"),
                    "status": "matched",
                    "amount": best.get("amount"),
                })
    except Exception:
        return []

    return results


def compute_refunds(records):
    if records is None:
        return 0

    order_ids = set()
    try:
        for record in records:
            if (isinstance(record, dict)
                    and record.get("type") == "ORDER"
                    and record.get("currency") == "USD"):
                order_ids.add(record.get("order_id"))
    except Exception:
        return 0

    total = 0
    try:
        for record in records:
            if not isinstance(record, dict):
                continue
            if (record.get("type") == "PAYMENT"
                    and record.get("currency") == "USD"
                    and isinstance(record.get("amount"), int)
                    and record.get("amount") < 0
                    and record.get("order_id") in order_ids):
                total += abs(record.get("amount"))
    except Exception:
        return 0

    return total


def build_summary(matches, refund_total):
    try:
        items = list(matches) if matches is not None else []
    except Exception:
        items = []

    matched_count = 0
    matched_total = 0
    unmatched_ids = set()

    for result in items:
        if not isinstance(result, dict):
            continue

        status = result.get("status")
        if status == "matched":
            matched_count += 1
            amount = result.get("amount")
            if isinstance(amount, int):
                matched_total += amount
        elif status == "unmatched":
            order_id = result.get("order_id")
            if isinstance(order_id, str):
                unmatched_ids.add(order_id)

    if not isinstance(refund_total, int):
        refund_total = 0

    net_total = matched_total - refund_total
    if net_total < 0:
        net_total = 0

    return {
        "total_orders": len(items),
        "matched_count": matched_count,
        "refund_total": refund_total,
        "net_total": net_total,
        "unmatched_ids": sorted(unmatched_ids),
    }

"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        amount = Decimal(s)
        # Convert to integer cents
        amount_cents = int(amount * 100)
        # Check for validity
        if abs(amount_cents) > 1000000:
            return None
        return amount_cents
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.strip().split('|')
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount, currency, timestamp = fields

    # Validate TYPE
    record_type = record_type.upper()
    if record_type not in ['ORDER', 'PAYMENT']:
        return None

    # Validate IDs
    if not record_id.strip() or not order_id.strip():
        return None

    # Validate AMOUNT
    amount_cents = parse_amount(amount)
    if amount_cents is None:
        return None

    # Validate CURRENCY (assuming it must be a non-empty string)
    if not currency.strip():
        return None

    # Validate TIMESTAMP (assuming it must be a valid datetime format)
    try:
        datetime.strptime(timestamp, '%Y-%m-%d %H:%M:%S')
    except ValueError:
        return None

    return {
        'type': record_type,
        'record_id': record_id.strip(),
        'order_id': order_id.strip(),
        'amount': amount_cents,
        'currency': currency.strip(),
        'timestamp': timestamp.strip()
    }


def load_records(text):
    records = []
    seen_ids = set()

    for line in text.strip().splitlines():
        record = parse_record(line)
        if record and record['record_id'] not in seen_ids:
            records.append(record)
            seen_ids.add(record['record_id'])

    return records


def match_payments(records):
    orders = {}
    payments = []

    # Separate orders and payments
    for record in records:
        if record['type'] == 'ORDER':
            orders[record['order_id']] = {
                'timestamp': datetime.strptime(record['timestamp'], '%Y-%m-%d %H:%M:%S'),
                'amount': record['amount']
            }
        elif record['type'] == 'PAYMENT':
            payments.append({
                'order_id': record['order_id'],
                'amount': record['amount'],
                'timestamp': datetime.strptime(record['timestamp'], '%Y-%m-%d %H:%M:%S')
            })

    results = []

    for order_id, order in orders.items():
        order_timestamp = order['timestamp']
        order_amount = order['amount']
        matched_payment = None

        for payment in payments:
            if payment['order_id'] == order_id:
                payment_timestamp = payment['timestamp']
                # Check if payment is strictly less than 72 hours after the order
                if order_timestamp <= payment_timestamp < order_timestamp + timedelta(hours=72):
                    if matched_payment is None or payment_timestamp < matched_payment['timestamp']:
                        matched_payment = payment

        if matched_payment:
            results.append({
                'order_id': order_id,
                'status': 'matched',
                'amount': matched_payment['amount']
            })
        else:
            results.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': 0
            })

    return results


def compute_refunds(records):
    refund_total = sum(
        record['amount'] for record in records 
        if record['type'] == 'PAYMENT' and record['amount'] < 0
    )
    return max(refund_total, 0)


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = max(sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total, 0)
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] != 'matched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

