    for record in records:
        if record['type'] == 'ORDER':
            orders[record['order_id']] = record
    results = []
    for record in records:
        if record['type'] == 'PAYMENT':
            order_id = record['order_id']
            if order_id in orders:
                order_timestamp = datetime.strptime(orders[order_id]['timestamp'], '%Y-%m-%d %H:%M:%S')
                payment_timestamp = datetime.strptime(record['timestamp'], '%Y-%m-%d %H:%M:%S')
                if order_timestamp <= payment_timestamp < order_timestamp + timedelta(hours=72):
                    results.append({'order_id': order_id, 'status': 'matched', 'amount': record['amount']})
                else:
                    results.append({'order_id': order_id, 'status': 'unmatched', 'amount': 0})
            else:
                results.append({'order_id': order_id, 'status': 'unmatched', 'amount': 0})
    return results


def compute_refunds(records):
    raise NotImplementedError


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = max(sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total, 0)
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] != 'matched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    """Return an amount in integer cents, or None when it is invalid."""
    if not isinstance(s, str):
        return None

    text = s.strip()
    if not _AMOUNT_RE.fullmatch(text):
        return None

    try:
        with localcontext() as context:
            context.prec = max(28, len(text) + 5)
            value = Decimal(text).quantize(
                Decimal("0.01"),
                rounding=ROUND_HALF_UP,
            )
            cents = int(value * 100)
    except (InvalidOperation, ValueError, TypeError):
        return None

    if abs(cents) > 1_000_000:
        return None

    return cents


def parse_record(line):
    """Parse one pipe-separated record, or return None if it is invalid."""
    if not isinstance(line, str):
        return None

    parts = line.strip().split("|")
    if len(parts) != 6:
        return None

    parts = [part.strip() for part in parts]
    if any(part == "" for part in parts):
        return None

    record_type, record_id, order_id, amount_text, currency, timestamp = parts
    record_type = record_type.upper()

    if record_type not in ("ORDER", "PAYMENT"):
        return None

    if not _CURRENCY_RE.fullmatch(currency):
        return None

    if _parse_timestamp(timestamp) is None:
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None

    if record_type == "ORDER" and amount < 0:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    """Load valid records, retaining the first valid record ID."""
    if not isinstance(text, str):
        return []

    records = []
    seen_ids = set()

    for line in text.splitlines():
        record = parse_record(line)
        if record is None:
            continue

        record_id = record["record_id"]
        if record_id in seen_ids:
            continue

        seen_ids.add(record_id)
        records.append(record)

    return records


def match_payments(records):
    """Return one matching result for each order in retained order."""
    if not isinstance(records, list):
        return []

    orders = [
        record
        for record in records
        if isinstance(record, dict) and record.get("type") == "ORDER"
    ]

    payments = [
        (index, record)
        for index, record in enumerate(records)
        if (
            isinstance(record, dict)
            and record.get("type") == "PAYMENT"
            and isinstance(record.get("amount"), int)
            and not isinstance(record.get("amount"), bool)
            and record.get("amount") >= 0
        )
    ]

    results = []

    for order in orders:
        order_time = _parse_timestamp(order.get("timestamp"))
        candidates = []

        for source_index, payment in payments:
            if payment.get("order_id") != order.get("order_id"):
                continue
            if payment.get("currency") != order.get("currency"):
                continue
            if payment.get("amount") != order.get("amount"):
                continue

            payment_time = _parse_timestamp(payment.get("timestamp"))
            order_cmp, payment_cmp = _timestamps_in_same_style(
                order_time,
                payment_time,
            )
            if order_cmp is None or payment_cmp is None:
                continue

            if (
                order_cmp <= payment_cmp
                and payment_cmp < order_cmp + timedelta(hours=72)
            ):
                candidates.append((payment_cmp, source_index, payment))

        if candidates:
            _, _, payment = min(candidates, key=lambda item: (item[0], item[1]))
            results.append({
                "order_id": order["order_id"],
                "status": "matched",
                "amount": payment["amount"],
            })
        else:
            results.append({
                "order_id": order["order_id"],
                "status": "unmatched",
                "amount": 0,
            })

    return results


def compute_refunds(records):
    """Return the positive total of refunds for existing orders."""
    if not isinstance(records, list):
        return 0

    order_ids = {
        record.get("order_id")
        for record in records
        if isinstance(record, dict) and record.get("type") == "ORDER"
    }

    total = 0

    for record in records:
        if not isinstance(record, dict):
            continue
        if record.get("type") != "PAYMENT":
            continue
        if record.get("order_id") not in order_ids:
            continue

        amount = record.get("amount")
        if (
            isinstance(amount, int)
            and not isinstance(amount, bool)
            and amount < 0
        ):
            total += -amount

    return total


def build_summary(matches, refund_total):
    """Build the reconciliation summary."""
    if not isinstance(matches, list):
        matches = []

    total_orders = 0
    matched_count = 0
    matched_total = 0
    unmatched_ids = set()

    for match in matches:
        if not isinstance(match, dict):
            continue

        total_orders += 1

        if match.get("status") == "matched":
            matched_count += 1
            amount = match.get("amount")
            if isinstance(amount, int) and not isinstance(amount, bool):
                matched_total += amount
        elif match.get("status") == "unmatched":
            order_id = match.get("order_id")
            if isinstance(order_id, str):
                unmatched_ids.add(order_id)

    if not isinstance(refund_total, int) or isinstance(refund_total, bool):
        refund_total = 0
    else:
        refund_total = max(0, refund_total)

    return {
        "total_orders": total_orders,
        "matched_count": matched_count,
        "refund_total": refund_total,
        "net_total": max(0, matched_total - refund_total),
        "unmatched_ids": sorted(unmatched_ids),
    }

"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str) or s == "":
        return None

    value = s
    if value.startswith("-"):
        value = value[1:]

    if value == "" or value.count(".") > 1:
        return None

    if "." in value:
        whole, fraction = value.split(".")
        if whole == "" or fraction == "":
            return None
    else:
        whole = value
        fraction = ""

    if not whole.isascii() or not whole.isdigit():
        return None
    if fraction and (not fraction.isascii() or not fraction.isdigit()):
        return None
    if len(fraction) > 3:
        return None

    try:
        amount = Decimal(s).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        cents = int(amount * 100)
    except (InvalidOperation, ValueError, OverflowError):
        return None

    if abs(cents) > 1_000_000:
        return None

    return cents


def parse_record(line):
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount_text, currency, timestamp_text = fields

    record_type = record_type.upper()
    if record_type not in ("ORDER", "PAYMENT"):
        return None

    record_id = record_id.strip()
    order_id = order_id.strip()

    if record_id == "" or order_id == "":
        return None
    if not order_id.startswith("ORD-"):
        return None
    if currency != "USD":
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None
    if record_type == "ORDER" and amount < 0:
        return None

    if len(timestamp_text) not in (16, 19):
        return None

    if len(timestamp_text) == 16:
        date_format = "%Y-%m-%d %H:%M"
    else:
        date_format = "%Y-%m-%d %H:%M:%S"

    try:
        timestamp = datetime.strptime(timestamp_text, date_format)
    except (TypeError, ValueError):
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []

    retained = []
    seen_record_ids = set()

    for line in text.splitlines():
        try:
            record = parse_record(line)
        except Exception:
            record = None

        if record is None:
            continue

        record_id = record["record_id"]
        if record_id in seen_record_ids:
            continue

        seen_record_ids.add(record_id)
        retained.append(record)

    return retained


def match_payments(records):
    if not isinstance(records, (list, tuple)):
        return []

    results = []

    for order in records:
        if not isinstance(order, dict) or order.get("type") != "ORDER":
            continue

        order_id = order["order_id"]
        order_time = order["timestamp"]
        cutoff = order_time + timedelta(hours=72)

        selected = None
        selected_key = None

        for source_index, payment in enumerate(records):
            if not isinstance(payment, dict):
                continue
            if payment.get("type") != "PAYMENT":
                continue
            if payment.get("order_id") != order_id:
                continue
            if payment.get("amount", 0) < 0:
                continue

            payment_time = payment["timestamp"]
            if payment_time < order_time or payment_time >= cutoff:
                continue

            key = (payment_time, source_index)
            if selected_key is None or key < selected_key:
                selected = payment
                selected_key = key

        if selected is None:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": selected["amount"],
            })

    return results


def compute_refunds(records):
    if not isinstance(records, (list, tuple)):
        return 0

    order_ids = set()

    for record in records:
        if not isinstance(record, dict):
            continue
        if record.get("type") == "ORDER":
            order_ids.add(record.get("order_id"))

    refund_total = 0

    for record in records:
        if not isinstance(record, dict):
            continue
        if record.get("type") != "PAYMENT":
            continue
        if record.get("currency") != "USD":
            continue
        if record.get("order_id") not in order_ids:
            continue

        amount = record.get("amount")
        if isinstance(amount, int) and amount < 0:
            refund_total += abs(amount)

    return refund_total


def build_summary(matches, refund_total):
    if not isinstance(matches, (list, tuple)):
        matches = []

    total_orders = len(matches)
    matched_count = 0
    matched_total = 0
    unmatched_ids = set()

    for result in matches:
        if not isinstance(result, dict):
            continue

        status = result.get("status")

        if status == "matched":
            matched_count += 1
            amount = result.get("amount", 0)
            if isinstance(amount, int):
                matched_total += amount
        elif status == "unmatched":
            order_id = result.get("order_id")
            if isinstance(order_id, str):
                unmatched_ids.add(order_id)

    net_total = matched_total - refund_total
    if net_total < 0:
        net_total = 0

    return {
        "total_orders": total_orders,
        "matched_count": matched_count,
        "refund_total": refund_total,
        "net_total": net_total,
        "unmatched_ids": sorted(unmatched_ids),
    }

