"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str) or s == "":
        return None
    negative = s.startswith("-")
    if negative:
        s = s[1:]
    if s == "" or s.count(".") > 1:
        return None
    parts = s.split(".")
    whole = parts[0]
    fraction = parts[1] if len(parts) == 2 else ""
    if not whole or any(ch not in "0123456789" for ch in whole):
        return None
    if len(fraction) > 3 or any(ch not in "0123456789" for ch in fraction):
        return None
    cents = int(whole) * 100
    fraction = (fraction + "00")[:3]
    cents += int(fraction[:2])
    if len(fraction) == 3 and fraction[2] >= "5":
        cents += 1
    if negative:
        cents = -cents
    if abs(cents) > 1000000:
        return None
    return cents


def parse_record(line):
    if not isinstance(line, str):
        return None
    fields = line.split("|")
    if len(fields) != 6:
        return None
    record_type, record_id, order_id, amount_text, currency, timestamp_text = fields
    record_type = record_type.upper()
    record_id = record_id.strip()
    order_id = order_id.strip()
    if record_type not in ("ORDER", "PAYMENT"):
        return None
    if not record_id or not order_id or not order_id.startswith("ORD-"):
        return None
    if currency != "USD":
        return None
    amount = parse_amount(amount_text)
    if amount is None or (record_type == "ORDER" and amount < 0):
        return None
    timestamp = None
    for fmt, length in (("%Y-%m-%d %H:%M", 16),
                        ("%Y-%m-%d %H:%M:%S", 19)):
        if len(timestamp_text) == length:
            try:
                candidate = datetime.strptime(timestamp_text, fmt)
                if candidate.strftime(fmt) == timestamp_text:
                    timestamp = candidate
                    break
            except (ValueError, TypeError):
                pass
    if timestamp is None:
        return None
    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []
    retained = []
    seen_ids = set()
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None and record["record_id"] not in seen_ids:
            seen_ids.add(record["record_id"])
            retained.append(record)
    return retained


def match_payments(records):
    results = []
    for order in records:
        if order.get("type") != "ORDER":
            continue
        selected = None
        end = order["timestamp"] + timedelta(hours=72)
        for payment in records:
            if payment.get("type") != "PAYMENT":
                continue
            if payment["amount"] < 0:
                continue
            if payment["order_id"] != order["order_id"]:
                continue
            if not order["timestamp"] <= payment["timestamp"] < end:
                continue
            if selected is None or payment["timestamp"] < selected["timestamp"]:
                selected = payment
        if selected is None:
            results.append({
                "order_id": order["order_id"],
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order["order_id"],
                "status": "matched",
                "amount": selected["amount"],
            })
    return results


def compute_refunds(records):
    if not isinstance(records, (list, tuple)):
        return 0
    order_ids = set()
    for record in records:
        if isinstance(record, dict) and record.get("type") == "ORDER":
            order_ids.add(record.get("order_id"))
    total = 0
    for record in records:
        if not isinstance(record, dict):
            continue
        if (record.get("type") == "PAYMENT"
                and record.get("currency") == "USD"
                and record.get("amount", 0) < 0
                and record.get("order_id") in order_ids):
            total += abs(record["amount"])
    return total


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = 0
    matched_total = 0
    unmatched_ids = set()
    for result in matches:
        if result.get("status") == "matched":
            matched_count += 1
            matched_total += result.get("amount", 0)
        elif result.get("status") == "unmatched":
            unmatched_ids.add(result.get("order_id"))
    net_total = matched_total - refund_total
    if net_total < 0:
        net_total = 0
    return {
        "total_orders": total_orders,
        "matched_count": matched_count,
        "refund_total": refund_total,
        "net_total": net_total,
        "unmatched_ids": sorted(unmatched_ids),
    }

