from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    """Convert a monetary value to integer cents, or return None if invalid."""
    if not isinstance(s, str):
        return None

    value = s.strip()
    if not value:
        return None

    if value.startswith("-"):
        digits = value[1:]
    else:
        digits = value

    if not digits:
        return None

    if digits.count(".") > 1:
        return None

    if "." in digits:
        whole, fraction = digits.split(".")
        if not whole or not whole.isdigit():
            return None
        if not fraction or not fraction.isdigit() or len(fraction) > 3:
            return None
    elif not digits.isdigit():
        return None

    try:
        amount = Decimal(value)
        if not amount.is_finite():
            return None

        cents = (amount * Decimal("100")).quantize(
            Decimal("1"), rounding=ROUND_HALF_UP
        )

        cents = int(cents)
        if abs(cents) > 1_000_000:
            return None

        return cents
    except (InvalidOperation, ValueError, OverflowError):
        return None


def parse_record(line):
    """Parse one record line, returning a dictionary or None."""
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 6:
        return None

    (
        record_type,
        record_id,
        order_id,
        amount_text,
        currency,
        timestamp_text,
    ) = (field.strip() for field in fields)

    record_type = record_type.upper()
    if record_type not in ("ORDER", "PAYMENT"):
        return None

    if not record_id or not order_id:
        return None

    if (
        len(currency) != 3
        or not currency.isascii()
        or not currency.isalpha()
        or not currency.isupper()
    ):
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None

    if record_type == "ORDER" and amount < 0:
        return None

    if not timestamp_text:
        return None

    try:
        timestamp_value = timestamp_text
        if timestamp_value.endswith(("Z", "z")):
            timestamp_value = timestamp_value[:-1] + "+00:00"

        timestamp = datetime.fromisoformat(timestamp_value)

        if timestamp.tzinfo is not None:
            timestamp.utcoffset()
    except (TypeError, ValueError, OverflowError):
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    """Parse valid records while keeping the first valid record ID."""
    if not isinstance(text, str):
        return []

    records = []
    seen_ids = set()

    for line in text.splitlines():
        record = parse_record(line)
        if record is None:
            continue

        record_id = record["record_id"]
        if record_id in seen_ids:
            continue

        seen_ids.add(record_id)
        records.append(record)

    return records


def match_payments(records):
    """Match each order with the earliest qualifying payment."""
    if not isinstance(records, list):
        return []

    orders = [
        record
        for record in records
        if isinstance(record, dict) and record.get("type") == "ORDER"
    ]

    payments = [
        (index, record)
        for index, record in enumerate(records)
        if (
            isinstance(record, dict)
            and record.get("type") == "PAYMENT"
            and isinstance(record.get("amount"), int)
            and record.get("amount") >= 0
        )
    ]

    results = []

    for order in orders:
        order_id = order.get("order_id")
        order_amount = order.get("amount")
        order_currency = order.get("currency")
        order_timestamp = order.get("timestamp")

        candidates = []

        if (
            isinstance(order_id, str)
            and isinstance(order_amount, int)
            and isinstance(order_timestamp, datetime)
        ):
            end_timestamp = order_timestamp + timedelta(hours=72)

            for source_index, payment in payments:
                if payment.get("order_id") != order_id:
                    continue
                if payment.get("amount") != order_amount:
                    continue
                if payment.get("currency") != order_currency:
                    continue

                payment_timestamp = payment.get("timestamp")
                if not isinstance(payment_timestamp, datetime):
                    continue

                try:
                    if order_timestamp <= payment_timestamp < end_timestamp:
                        candidates.append(
                            (payment_timestamp, source_index, payment)
                        )
                except TypeError:
                    continue

        if candidates:
            candidates.sort(key=lambda item: (item[0], item[1]))
            matched_payment = candidates[0][2]
            results.append(
                {
                    "order_id": order_id,
                    "status": "matched",
                    "amount": matched_payment["amount"],
                }
            )
        else:
            results.append(
                {
                    "order_id": order_id,
                    "status": "unmatched",
                    "amount": 0,
                }
            )

    return results


def compute_refunds(records):
    """Return the total of refunds belonging to existing orders."""
    if not isinstance(records, list):
        return 0

    order_ids = {
        record.get("order_id")
        for record in records
        if isinstance(record, dict)
        and record.get("type") == "ORDER"
        and isinstance(record.get("order_id"), str)
    }

    refund_total = 0

    for record in records:
        if not isinstance(record, dict):
            continue

        amount = record.get("amount")
        if (
            record.get("type") == "PAYMENT"
            and isinstance(amount, int)
            and amount < 0
            and record.get("order_id") in order_ids
        ):
            refund_total += -amount

    return refund_total


def build_summary(matches, refund_total):
    """Build the reconciliation summary."""
    if not isinstance(matches, list):
        matches = []

    if not isinstance(refund_total, int):
        refund_total = 0

    matched_count = 0
    matched_total = 0
    unmatched_ids = set()

    for result in matches:
        if not isinstance(result, dict):
            continue

        if result.get("status") == "matched":
            matched_count += 1
            amount = result.get("amount")
            if isinstance(amount, int):
                matched_total += amount
        elif result.get("status") == "unmatched":
            order_id = result.get("order_id")
            if isinstance(order_id, str):
                unmatched_ids.add(order_id)

    net_total = matched_total - refund_total
    if net_total < 0:
        net_total = 0

    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "refund_total": refund_total,
        "net_total": net_total,
        "unmatched_ids": sorted(unmatched_ids),
    }

