from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    """Convert an amount to integer cents, or return None if invalid."""
    if isinstance(s, bool) or s is None:
        return None

    text = str(s).strip()
    if not _AMOUNT_PATTERN.fullmatch(text):
        return None

    fractional_part = ""
    if "." in text:
        fractional_part = text.split(".", 1)[1]

    if len(fractional_part) > 3:
        return None

    try:
        with localcontext() as context:
            context.prec = max(
                28,
                len(text.replace("-", "").replace("+", "").replace(".", ""))
                + 10,
            )
            cents = int(
                (Decimal(text) * Decimal("100")).quantize(
                    Decimal("1"),
                    rounding=ROUND_HALF_UP,
                )
            )
    except (InvalidOperation, ValueError, TypeError, OverflowError):
        return None

    if abs(cents) > _AMOUNT_LIMIT_CENTS:
        return None

    return cents


def parse_record(line):
    """Parse a six-field pipe-separated record."""
    if not isinstance(line, str):
        return None

    pieces = line.strip().split("|")
    if len(pieces) != 6:
        return None

    record_type, record_id, order_id, amount, currency, timestamp = (
        piece.strip() for piece in pieces
    )

    record_type = record_type.upper()
    if record_type not in {"ORDER", "PAYMENT"}:
        return None

    if (
        not _ID_PATTERN.fullmatch(record_id)
        or not _ID_PATTERN.fullmatch(order_id)
    ):
        return None

    if not _CURRENCY_PATTERN.fullmatch(currency):
        return None

    if _parse_timestamp(timestamp) is None:
        return None

    amount_cents = parse_amount(amount)
    if amount_cents is None:
        return None

    if record_type == "ORDER" and amount_cents < 0:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount_cents,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    """Parse valid records, retaining only the first occurrence of each ID."""
    if not isinstance(text, str):
        return []

    records = []
    seen_ids = set()

    for line in text.splitlines():
        record = parse_record(line)
        if record is None:
            continue

        record_id = record["record_id"]
        if record_id in seen_ids:
            continue

        seen_ids.add(record_id)
        records.append(record)

    return records


def match_payments(records):
    """Match each order with its earliest qualifying payment."""
    if not isinstance(records, list):
        return []

    orders = [
        record
        for record in records
        if isinstance(record, dict) and record.get("type") == "ORDER"
    ]
    payments = [
        record
        for record in records
        if isinstance(record, dict) and record.get("type") == "PAYMENT"
    ]

    results = []

    for order in orders:
        order_time = _parse_timestamp(order.get("timestamp"))
        order_amount = order.get("amount")
        order_currency = order.get("currency")

        best_payment = None
        best_time = None

        if order_time is not None and isinstance(order_amount, int):
            deadline = order_time + timedelta(hours=72)

            for payment in payments:
                payment_amount = payment.get("amount")

                if not isinstance(payment_amount, int):
                    continue
                if payment_amount < 0:
                    continue
                if payment.get("order_id") != order.get("order_id"):
                    continue
                if payment_amount != order_amount:
                    continue
                if payment.get("currency") != order_currency:
                    continue

                payment_time = _parse_timestamp(payment.get("timestamp"))
                if payment_time is None:
                    continue
                if not _timestamps_comparable(order_time, payment_time):
                    continue

                # The order timestamp is included, but exactly 72 hours is not.
                if payment_time < order_time or payment_time >= deadline:
                    continue

                if best_time is None or payment_time < best_time:
                    best_payment = payment
                    best_time = payment_time

        if best_payment is None:
            results.append(
                {
                    "order_id": order.get("order_id"),
                    "status": "unmatched",
                    "amount": 0,
                }
            )
        else:
            results.append(
                {
                    "order_id": order.get("order_id"),
                    "status": "matched",
                    "amount": best_payment.get("amount"),
                }
            )

    return results


def compute_refunds(records):
    """Return the total of refunds belonging to existing orders."""
    if not isinstance(records, list):
        return 0

    order_ids = {
        record["order_id"]
        for record in records
        if (
            isinstance(record, dict)
            and record.get("type") == "ORDER"
            and isinstance(record.get("order_id"), str)
        )
    }

    refund_total = 0
    for record in records:
        if not isinstance(record, dict):
            continue
        if record.get("type") != "PAYMENT":
            continue
        if record.get("order_id") not in order_ids:
            continue

        amount = record.get("amount")
        if isinstance(amount, int) and not isinstance(amount, bool):
            if amount < 0:
                refund_total += -amount

    return refund_total


def build_summary(matches, refund_total):
    """Build a five-field reconciliation summary."""
    if not isinstance(matches, list):
        matches = []

    if isinstance(refund_total, bool) or not isinstance(refund_total, int):
        refund_total = 0

    matched_count = 0
    matched_total = 0
    unmatched_ids = set()

    for result in matches:
        if not isinstance(result, dict):
            continue

        if result.get("status") == "matched":
            matched_count += 1
            amount = result.get("amount")
            if isinstance(amount, int) and not isinstance(amount, bool):
                matched_total += amount
        else:
            order_id = result.get("order_id")
            if isinstance(order_id, str):
                unmatched_ids.add(order_id)

    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "refund_total": refund_total,
        "net_total": max(0, matched_total - refund_total),
        "unmatched_ids": sorted(unmatched_ids),
    }

