from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        amount = Decimal(s)
        # Convert to integer cents
        amount_cents = int(amount * 100)
        # Validate the amount
        if abs(amount_cents) > 1000000:
            return None
        return amount_cents
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.strip().split('|')
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount, currency, timestamp = map(str.strip, fields)

    # Validate TYPE
    if record_type.upper() not in ['ORDER', 'PAYMENT']:
        return None

    # Validate IDs
    if not record_id or not order_id:
        return None

    # Validate AMOUNT
    amount_cents = parse_amount(amount)
    if amount_cents is None:
        return None

    # Validate CURRENCY
    if not currency.isalpha() or len(currency) != 3:
        return None

    # Validate TIMESTAMP
    try:
        timestamp = datetime.fromisoformat(timestamp)
    except ValueError:
        return None

    return {
        'type': record_type.upper(),
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount_cents,
        'currency': currency,
        'timestamp': timestamp
    }


def load_records(text):
    records = []
    for line in text.strip().splitlines():
        record = parse_record(line)
        if record is not None:
            # Check for duplicates by record_id
            if not any(r['record_id'] == record['record_id'] for r in records):
                records.append(record)
    return records


def match_payments(records):
    orders = {}
    payments = []

    for record in records:
        if record['type'] == 'ORDER':
            orders[record['order_id']] = record
        elif record['type'] == 'PAYMENT':
            payments.append(record)

    results = []

    for order_id, order in orders.items():
        order_timestamp = order['timestamp']
        order_amount = order['amount']
        matching_payments = [
            payment for payment in payments
            if payment['order_id'] == order_id and 
            order_timestamp <= payment['timestamp'] < order_timestamp + timedelta(hours=72) and 
            payment['amount'] > 0
        ]

        if matching_payments:
            # Sort by timestamp and then by original order in the list
            matching_payments.sort(key=lambda p: (p['timestamp'], payments.index(p)))
            earliest_payment = matching_payments[0]
            results.append({
                'order_id': order_id,
                'status': 'matched',
                'amount': earliest_payment['amount']
            })
        else:
            results.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': 0
            })

    return results


def compute_refunds(records):
    refund_total = sum(
        record['amount'] for record in records 
        if record['type'] == 'PAYMENT' and record['amount'] < 0
    )
    return max(0, refund_total)


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = max(0, sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total)
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] != 'matched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

