"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str) or not s:
        return None
    negative = s.startswith("-")
    value = s[1:] if negative else s
    if not value or value.count(".") > 1:
        return None
    parts = value.split(".")
    whole = parts[0]
    fraction = parts[1] if len(parts) == 2 else ""
    if not whole or any(ch not in "0123456789" for ch in whole):
        return None
    if len(fraction) > 3 or any(ch not in "0123456789" for ch in fraction):
        return None
    cents = int(whole) * 100
    fraction = fraction.ljust(3, "0")
    cents += int(fraction[:2])
    if fraction[2] >= "5":
        cents += 1
    if cents > 1_000_000:
        return None
    return -cents if negative else cents


def parse_record(line):
    if not isinstance(line, str):
        return None
    fields = line.split("|")
    if len(fields) != 6:
        return None
    record_type, record_id, order_id, amount_text, currency, timestamp_text = fields
    record_type = record_type.upper()
    record_id = record_id.strip()
    order_id = order_id.strip()
    if record_type not in ("ORDER", "PAYMENT"):
        return None
    if not record_id or not order_id or not order_id.startswith("ORD-"):
        return None
    if currency != "USD":
        return None
    amount = parse_amount(amount_text)
    if amount is None or (record_type == "ORDER" and amount < 0):
        return None
    if len(timestamp_text) not in (16, 19):
        return None
    if (timestamp_text[4] != "-" or timestamp_text[7] != "-" or
            timestamp_text[10] != " " or timestamp_text[13] != ":"):
        return None
    if len(timestamp_text) == 19 and timestamp_text[16] != ":":
        return None
    positions = list(range(0, 4)) + list(range(5, 7)) + list(range(8, 10))
    positions += list(range(11, 13)) + list(range(14, 16))
    if len(timestamp_text) == 19:
        positions += list(range(17, 19))
    if any(timestamp_text[i] not in "0123456789" for i in positions):
        return None
    try:
        timestamp = datetime.strptime(
            timestamp_text,
            "%Y-%m-%d %H:%M:%S" if len(timestamp_text) == 19
            else "%Y-%m-%d %H:%M")
    except (TypeError, ValueError, OverflowError):
        return None
    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []
    retained = []
    seen_ids = set()
    for line in text.splitlines():
        try:
            record = parse_record(line)
        except Exception:
            record = None
        if record is None or record["record_id"] in seen_ids:
            continue
        seen_ids.add(record["record_id"])
        retained.append(record)
    return retained


def match_payments(records):
    results = []
    if not isinstance(records, (list, tuple)):
        return results
    orders = []
    payments = []
    for source_index, record in enumerate(records):
        if not isinstance(record, dict):
            continue
        if record.get("type") == "ORDER":
            orders.append(record)
        elif (record.get("type") == "PAYMENT" and
              isinstance(record.get("amount"), int) and
              record.get("amount") >= 0):
            payments.append((source_index, record))
    for order in orders:
        selected = None
        order_time = order.get("timestamp")
        if order_time is not None:
            deadline = order_time + timedelta(hours=72)
            candidates = []
            for source_index, payment in payments:
                if payment.get("order_id") != order.get("order_id"):
                    continue
                payment_time = payment.get("timestamp")
                if payment_time is not None and order_time <= payment_time < deadline:
                    candidates.append((payment_time, source_index, payment))
            if candidates:
                candidates.sort(key=lambda item: (item[0], item[1]))
                selected = candidates[0][2]
        results.append({
            "order_id": order.get("order_id"),
            "status": "matched" if selected is not None else "unmatched",
            "amount": selected["amount"] if selected is not None else 0,
        })
    return results


def compute_refunds(records):
    if not isinstance(records, (list, tuple)):
        return 0
    order_ids = {
        record.get("order_id") for record in records
        if isinstance(record, dict)
        and record.get("type") == "ORDER"
        and record.get("currency") == "USD"
    }
    total = 0
    for record in records:
        if (isinstance(record, dict) and
                record.get("type") == "PAYMENT" and
                record.get("currency") == "USD" and
                isinstance(record.get("amount"), int) and
                record.get("amount") < 0 and
                record.get("order_id") in order_ids):
            total += -record["amount"]
    return total


def build_summary(matches, refund_total):
    if not isinstance(matches, (list, tuple)):
        matches = []
    total_orders = len(matches)
    matched_count = 0
    matched_total = 0
    unmatched = set()
    for result in matches:
        if not isinstance(result, dict):
            continue
        if result.get("status") == "matched":
            matched_count += 1
            amount = result.get("amount")
            if isinstance(amount, int):
                matched_total += amount
        elif result.get("status") == "unmatched":
            unmatched.add(result.get("order_id"))
    net_total = matched_total - refund_total
    if net_total < 0:
        net_total = 0
    return {
        "total_orders": total_orders,
        "matched_count": matched_count,
        "refund_total": refund_total,
        "net_total": net_total,
        "unmatched_ids": sorted(unmatched),
    }

"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    """Return an amount in integer cents, or None when invalid."""
    if isinstance(s, bool) or s is None:
        return None

    text = str(s).strip()
    if not _AMOUNT_RE.fullmatch(text):
        return None

    if "." in text:
        fractional_digits = text.split(".", 1)[1]
        if len(fractional_digits) > 3:
            return None

    try:
        value = Decimal(text)
        cents = int(
            (value * Decimal("100")).quantize(
                _AMOUNT_QUANTUM,
                rounding=ROUND_HALF_UP,
            )
        )
    except (InvalidOperation, ValueError, TypeError, OverflowError):
        return None

    if abs(cents) > _MAX_CENTS:
        return None

    return cents


def parse_record(line):
    """Parse one settlement record, returning a dictionary or None."""
    if not isinstance(line, str):
        return None

    fields = line.strip().split("|")
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount_text, currency, timestamp = (
        field.strip() for field in fields
    )

    record_type = record_type.upper()
    if record_type not in {"ORDER", "PAYMENT"}:
        return None

    if not record_id or not order_id:
        return None

    if len(currency) != 3 or not currency.isalpha() or currency != currency.upper():
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None

    if record_type == "ORDER" and amount < 0:
        return None

    parsed_timestamp = _parse_timestamp(timestamp)
    if parsed_timestamp is None:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": parsed_timestamp,
    }


def load_records(text):
    """Load valid records, keeping the first valid record ID."""
    if not isinstance(text, str):
        return []

    records = []
    seen_ids = set()

    for line in text.splitlines():
        record = parse_record(line)
        if record is None:
            continue

        record_id = record["record_id"]
        if record_id in seen_ids:
            continue

        seen_ids.add(record_id)
        records.append(record)

    return records


def match_payments(records):
    """Return one matching result for each order."""
    if not isinstance(records, list):
        return []

    orders = [
        record
        for record in records
        if isinstance(record, dict) and record.get("type") == "ORDER"
    ]

    payments = [
        (index, record)
        for index, record in enumerate(records)
        if (
            isinstance(record, dict)
            and record.get("type") == "PAYMENT"
            and isinstance(record.get("amount"), int)
            and not isinstance(record.get("amount"), bool)
            and record.get("amount") >= 0
        )
    ]

    results = []

    for order in orders:
        order_id = order.get("order_id")
        order_amount = order.get("amount")
        order_currency = order.get("currency")
        order_time = order.get("timestamp")

        best_payment = None
        best_key = None

        if (
            isinstance(order_id, str)
            and isinstance(order_amount, int)
            and not isinstance(order_amount, bool)
            and isinstance(order_time, datetime)
        ):
            end_time = order_time + timedelta(hours=72)

            for source_index, payment in payments:
                if payment.get("order_id") != order_id:
                    continue
                if payment.get("amount") != order_amount:
                    continue
                if payment.get("currency") != order_currency:
                    continue

                payment_time = payment.get("timestamp")
                if not isinstance(payment_time, datetime):
                    continue

                try:
                    in_window = order_time <= payment_time < end_time
                except TypeError:
                    in_window = False

                if not in_window:
                    continue

                candidate_key = (payment_time, source_index)
                if best_key is None or candidate_key < best_key:
                    best_key = candidate_key
                    best_payment = payment

        if best_payment is None:
            results.append(
                {
                    "order_id": order_id,
                    "status": "unmatched",
                    "amount": 0,
                }
            )
        else:
            results.append(
                {
                    "order_id": order_id,
                    "status": "matched",
                    "amount": best_payment["amount"],
                }
            )

    return results


def compute_refunds(records):
    """Return the positive total of qualifying negative payments."""
    if not isinstance(records, list):
        return 0

    existing_order_ids = {
        record.get("order_id")
        for record in records
        if isinstance(record, dict) and record.get("type") == "ORDER"
    }

    refund_total = 0

    for record in records:
        if not isinstance(record, dict):
            continue
        if record.get("type") != "PAYMENT":
            continue
        if record.get("order_id") not in existing_order_ids:
            continue

        amount = record.get("amount")
        if (
            isinstance(amount, int)
            and not isinstance(amount, bool)
            and amount < 0
        ):
            refund_total += -amount

    return refund_total


def build_summary(matches, refund_total):
    """Build the final settlement summary."""
    if not isinstance(matches, list):
        matches = []

    total_orders = sum(
        1 for match in matches
        if isinstance(match, dict)
    )

    matched_count = 0
    matched_total = 0
    unmatched_ids = set()

    for match in matches:
        if not isinstance(match, dict):
            continue

        if match.get("status") == "matched":
            matched_count += 1
            amount = match.get("amount")
            if isinstance(amount, int) and not isinstance(amount, bool):
                matched_total += amount
        else:
            order_id = match.get("order_id")
            if isinstance(order_id, str):
                unmatched_ids.add(order_id)

    if not isinstance(refund_total, int) or isinstance(refund_total, bool):
        refund_total = 0

    net_total = max(0, matched_total - refund_total)

    return {
        "total_orders": total_orders,
        "matched_count": matched_count,
        "refund_total": refund_total,
        "net_total": net_total,
        "unmatched_ids": sorted(unmatched_ids),
    }

