"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        if not isinstance(s, str):
            return None
        text = s.strip()
        if not text:
            return None
        negative = text.startswith("-")
        body = text[1:] if negative else text
        if not body or body.count(".") > 1:
            return None
        pieces = body.split(".")
        if not pieces[0].isdigit():
            return None
        if len(pieces) == 2:
            fraction = pieces[1]
            if fraction and not fraction.isdigit():
                return None
            if len(fraction) > 3:
                return None
        value = Decimal(text)
        cents = int((value * Decimal("100")).quantize(
            Decimal("1"), rounding=ROUND_HALF_UP
        ))
        if abs(cents) > 1000000:
            return None
        return cents
    except (InvalidOperation, ValueError, TypeError, OverflowError):
        return None


def parse_record(line):
    if not isinstance(line, str):
        return None
    parts = line.rstrip("\r\n").split("|")
    if len(parts) != 6:
        return None
    type_value, record_id, order_id, amount, currency, timestamp = (
        part.strip() for part in parts
    )
    type_value = type_value.upper()
    if type_value not in ("ORDER", "PAYMENT"):
        return None
    if not record_id or not order_id or currency != "USD":
        return None
    cents = parse_amount(amount)
    if cents is None or (type_value == "ORDER" and cents < 0):
        return None
    parsed_time = None
    for fmt in ("%Y-%m-%d %H:%M", "%Y-%m-%d %H:%M:%S"):
        try:
            parsed_time = datetime.strptime(timestamp, fmt)
            break
        except (ValueError, TypeError):
            pass
    if parsed_time is None:
        return None
    return {
        "type": type_value,
        "record_id": record_id,
        "order_id": order_id,
        "amount": cents,
        "currency": currency,
        "timestamp": parsed_time,
    }


def load_records(text):
    if not isinstance(text, str):
        return []
    records = []
    seen = set()
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None and record["record_id"] not in seen:
            seen.add(record["record_id"])
            records.append(record)
    return records


def match_payments(records):
    if not isinstance(records, list):
        return []
    orders = []
    order_ids = set()
    for record in records:
        if not isinstance(record, dict):
            continue
        kind = record.get("type", record.get("TYPE"))
        order_id = record.get("order_id", record.get("ORDER_ID"))
        if kind == "ORDER" and order_id not in order_ids:
            order_ids.add(order_id)
            orders.append(record)

    results = []
    for order in orders:
        order_id = order.get("order_id", order.get("ORDER_ID"))
        start = order.get("timestamp", order.get("TIMESTAMP"))
        best = None
        end = start + timedelta(hours=72) if isinstance(start, datetime) else None
        for payment in records:
            if not isinstance(payment, dict):
                continue
            if payment.get("type", payment.get("TYPE")) != "PAYMENT":
                continue
            if payment.get("order_id", payment.get("ORDER_ID")) != order_id:
                continue
            amount = payment.get("amount", payment.get("AMOUNT"))
            moment = payment.get("timestamp", payment.get("TIMESTAMP"))
            if (isinstance(amount, int) and amount >= 0
                    and isinstance(moment, datetime)
                    and isinstance(start, datetime)
                    and start <= moment < end
                    and (best is None or moment < best[0])):
                best = (moment, amount)
        if best is None:
            results.append({"order_id": order_id, "status": "unmatched", "amount": 0})
        else:
            results.append({"order_id": order_id, "status": "matched", "amount": best[1]})
    return results


def compute_refunds(records):
    if not isinstance(records, list):
        return 0
    order_ids = set()
    for record in records:
        if isinstance(record, dict):
            if record.get("type", record.get("TYPE")) == "ORDER":
                order_ids.add(record.get("order_id", record.get("ORDER_ID")))
    total = 0
    for record in records:
        if not isinstance(record, dict):
            continue
        if (record.get("type", record.get("TYPE")) == "PAYMENT"
                and record.get("order_id", record.get("ORDER_ID")) in order_ids):
            amount = record.get("amount", record.get("AMOUNT"))
            if isinstance(amount, int) and amount < 0:
                total -= amount
    return total


def build_summary(matches, refund_total):
    items = matches if isinstance(matches, list) else []
    refund = refund_total if isinstance(refund_total, int) else 0
    matched = [
        item for item in items
        if isinstance(item, dict) and item.get("status") == "matched"
    ]
    unmatched = sorted({
        item.get("order_id")
        for item in items
        if isinstance(item, dict) and item.get("status") == "unmatched"
    })
    paid = sum(item.get("amount", 0) for item in matched)
    return {
        "total_orders": len(items),
        "matched_count": len(matched),
        "refund_total": refund,
        "net_total": max(0, paid - refund),
        "unmatched_ids": unmatched,
    }

