"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str) or not s:
        return None
    negative = s.startswith("-")
    value = s[1:] if negative else s
    if not value or value.count(".") > 1:
        return None
    if "." in value:
        whole, fraction = value.split(".")
    else:
        whole, fraction = value, ""
    if not whole or any(ch not in "0123456789" for ch in whole):
        return None
    if len(fraction) > 3 or any(ch not in "0123456789" for ch in fraction):
        return None
    cents = int(whole) * 100
    if fraction:
        cents += int((fraction + "00")[:2])
        if len(fraction) == 3 and fraction[2] >= "5":
            cents += 1
    if cents > 1000000:
        return None
    return -cents if negative else cents


def parse_record(line):
    if not isinstance(line, str):
        return None
    fields = line.split("|")
    if len(fields) != 6:
        return None
    record_type, record_id, order_id, amount_text, currency, timestamp_text = fields
    record_type = record_type.upper()
    if record_type not in ("ORDER", "PAYMENT"):
        return None
    record_id = record_id.strip()
    order_id = order_id.strip()
    if not record_id or not order_id or not order_id.startswith("ORD-"):
        return None
    if currency != "USD":
        return None
    amount = parse_amount(amount_text)
    if amount is None or (record_type == "ORDER" and amount < 0):
        return None
    if len(timestamp_text) not in (16, 19) or timestamp_text[10] != " ":
        return None
    if len(timestamp_text) == 16:
        if timestamp_text[13] != ":":
            return None
        positions = list(range(10)) + [11, 12, 14, 15]
        fmt = "%Y-%m-%d %H:%M"
    else:
        if timestamp_text[13] != ":" or timestamp_text[16] != ":":
            return None
        positions = list(range(10)) + [11, 12, 14, 15, 17, 18]
        fmt = "%Y-%m-%d %H:%M:%S"
    if any(not timestamp_text[i].isdigit() for i in positions):
        return None
    try:
        timestamp = datetime.strptime(timestamp_text, fmt)
    except (TypeError, ValueError):
        return None
    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []
    retained = []
    seen_ids = set()
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None and record["record_id"] not in seen_ids:
            seen_ids.add(record["record_id"])
            retained.append(record)
    return retained


def match_payments(records):
    if not isinstance(records, (list, tuple)):
        return []
    results = []
    for order in records:
        if not isinstance(order, dict) or order.get("type") != "ORDER":
            continue
        order_id = order.get("order_id")
        start = order.get("timestamp")
        best = None
        if isinstance(order_id, str) and isinstance(start, datetime):
            end = start + timedelta(hours=72)
            for payment in records:
                if not isinstance(payment, dict):
                    continue
                if payment.get("type") != "PAYMENT":
                    continue
                if payment.get("order_id") != order_id:
                    continue
                if payment.get("currency") != "USD":
                    continue
                amount = payment.get("amount")
                timestamp = payment.get("timestamp")
                if not isinstance(amount, int) or amount < 0:
                    continue
                if not isinstance(timestamp, datetime):
                    continue
                if start <= timestamp < end:
                    if best is None or timestamp < best["timestamp"]:
                        best = payment
        if best is None:
            results.append({"order_id": order_id, "status": "unmatched", "amount": 0})
        else:
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": best["amount"],
            })
    return results


def compute_refunds(records):
    if not isinstance(records, (list, tuple)):
        return 0
    order_ids = set()
    for record in records:
        if (
            isinstance(record, dict)
            and record.get("type") == "ORDER"
            and record.get("currency") == "USD"
            and isinstance(record.get("order_id"), str)
        ):
            order_ids.add(record["order_id"])
    total = 0
    for record in records:
        if (
            isinstance(record, dict)
            and record.get("type") == "PAYMENT"
            and record.get("currency") == "USD"
            and isinstance(record.get("amount"), int)
            and record["amount"] < 0
            and record.get("order_id") in order_ids
        ):
            total += -record["amount"]
    return total


def build_summary(matches, refund_total):
    if not isinstance(matches, (list, tuple)):
        matches = []
    total_orders = len(matches)
    matched_count = 0
    matched_total = 0
    unmatched = set()
    for result in matches:
        if not isinstance(result, dict):
            continue
        if result.get("status") == "matched":
            matched_count += 1
            amount = result.get("amount")
            if isinstance(amount, int):
                matched_total += amount
        elif result.get("status") == "unmatched":
            order_id = result.get("order_id")
            if isinstance(order_id, str):
                unmatched.add(order_id)
    net_total = matched_total - refund_total
    if net_total < 0:
        net_total = 0
    return {
        "total_orders": total_orders,
        "matched_count": matched_count,
        "refund_total": refund_total,
        "net_total": net_total,
        "unmatched_ids": sorted(unmatched),
