from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    """Convert a monetary value to integer cents, or return None if invalid."""
    if not isinstance(s, str):
        return None

    value = s.strip()
    if not value:
        return None

    if value.startswith("-"):
        digits = value[1:]
    else:
        digits = value

    if not digits or digits.count(".") > 1:
        return None

    if "." in digits:
        whole, fraction = digits.split(".", 1)
    else:
        whole, fraction = digits, ""

    if not whole or not whole.isdigit():
        return None
    if fraction and not fraction.isdigit():
        return None
    if len(fraction) > 3:
        return None

    try:
        amount = Decimal(value)
        cents = int(amount.quantize(_CENT, rounding=ROUND_HALF_UP) * 100)
    except (InvalidOperation, ValueError, OverflowError):
        return None

    if abs(cents) > _MAX_CENTS:
        return None

    return cents


def parse_record(line):
    """Parse one valid six-field record, or return None."""
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 6:
        return None

    (
        record_type,
        record_id,
        order_id,
        amount_text,
        currency,
        timestamp,
    ) = (field.strip() for field in fields)

    record_type = record_type.upper()
    if record_type not in ("ORDER", "PAYMENT"):
        return None

    if not record_id or not order_id:
        return None

    if len(currency) != 3 or not currency.isalpha() or not currency.isupper():
        return None

    if _parse_timestamp(timestamp) is None:
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None

    if record_type == "ORDER" and amount < 0:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    """Parse all valid records, retaining the first valid record ID."""
    if not isinstance(text, str):
        return []

    records = []
    seen_ids = set()

    for line in text.splitlines():
        record = parse_record(line)
        if record is None:
            continue

        record_id = record["record_id"]
        if record_id in seen_ids:
            continue

        seen_ids.add(record_id)
        records.append(record)

    return records


def match_payments(records):
    """Match each order with the earliest qualifying payment."""
    if not isinstance(records, list):
        return []

    orders = []
    payments = []

    for index, record in enumerate(records):
        if not isinstance(record, dict):
            continue

        if record.get("type") == "ORDER":
            orders.append((index, record))
        elif record.get("type") == "PAYMENT":
            payments.append((index, record))

    results = []

    for _, order in orders:
        order_id = order.get("order_id")
        order_amount = order.get("amount")
        order_currency = order.get("currency")
        order_time = _parse_timestamp(order.get("timestamp"))

        best_payment = None
        best_time = None
        best_index = None

        if (
            isinstance(order_id, str)
            and isinstance(order_amount, int)
            and order_time is not None
        ):
            end_time = order_time + timedelta(hours=72)

            for payment_index, payment in payments:
                if payment.get("order_id") != order_id:
                    continue
                if payment.get("currency") != order_currency:
                    continue

                payment_amount = payment.get("amount")
                if not isinstance(payment_amount, int) or payment_amount < 0:
                    continue
                if payment_amount != order_amount:
                    continue

                payment_time = _parse_timestamp(payment.get("timestamp"))
                if payment_time is None:
                    continue

                try:
                    qualifies = order_time <= payment_time < end_time
                except TypeError:
                    qualifies = False

                if not qualifies:
                    continue

                if (
                    best_time is None
                    or payment_time < best_time
                    or (
                        payment_time == best_time
                        and payment_index < best_index
                    )
                ):
                    best_payment = payment
                    best_time = payment_time
                    best_index = payment_index

        if best_payment is None:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": best_payment["amount"],
            })

    return results


def compute_refunds(records):
    """Return the total of valid refunds in cents."""
    if not isinstance(records, list):
        return 0

    order_ids = {
        record.get("order_id")
        for record in records
        if isinstance(record, dict) and record.get("type") == "ORDER"
    }

    refund_total = 0

    for record in records:
        if not isinstance(record, dict):
            continue
        if record.get("type") != "PAYMENT":
            continue
        if record.get("order_id") not in order_ids:
            continue

        amount = record.get("amount")
        if isinstance(amount, int) and amount < 0:
            refund_total += -amount

    return refund_total


def build_summary(matches, refund_total):
    """Build the reconciliation summary."""
    if not isinstance(matches, list):
        matches = []

    if not isinstance(refund_total, int):
        refund_total = 0
    refund_total = max(0, refund_total)

    matched_count = 0
    matched_total = 0
    unmatched_ids = set()

    for result in matches:
        if not isinstance(result, dict):
            continue

        if result.get("status") == "matched":
            matched_count += 1

            amount = result.get("amount")
            if not isinstance(amount, int):
                amount = result.get("payment_amount")
            if not isinstance(amount, int):
                amount = result.get("matched_amount")

            if isinstance(amount, int):
                matched_total += amount
        else:
            order_id = result.get("order_id")
            if isinstance(order_id, str):
                unmatched_ids.add(order_id)

    net_total = max(0, matched_total - refund_total)

    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "refund_total": refund_total,
        "net_total": net_total,
        "unmatched_ids": sorted(unmatched_ids),
    }

