from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str) or s == "":
        return None

    negative = s.startswith("-")
    value = s[1:] if negative else s

    if value == "" or value.count(".") > 1:
        return None

    parts = value.split(".")
    whole = parts[0]
    fraction = parts[1] if len(parts) == 2 else ""

    if not whole or any(char not in "0123456789" for char in whole):
        return None

    if len(fraction) > 3 or any(
        char not in "0123456789" for char in fraction
    ):
        return None

    normalized_whole = whole.lstrip("0") or "0"
    if len(normalized_whole) > 5:
        return None

    normalized = normalized_whole
    if fraction:
        normalized += "." + fraction
    if negative:
        normalized = "-" + normalized

    try:
        amount = Decimal(normalized).quantize(
            Decimal("0.01"),
            rounding=ROUND_HALF_UP,
        )
    except InvalidOperation:
        return None

    cents = int(amount * 100)
    if abs(cents) > 1_000_000:
        return None

    return cents


def parse_record(line):
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount_text, currency, timestamp_text = fields

    record_type = record_type.upper()
    if record_type not in ("ORDER", "PAYMENT"):
        return None

    record_id = record_id.strip()
    order_id = order_id.strip()

    if not record_id or not order_id:
        return None
    if not order_id.startswith("ORD-"):
        return None
    if currency != "USD":
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None
    if record_type == "ORDER" and amount < 0:
        return None

    if len(timestamp_text) == 16:
        timestamp_format = "%Y-%m-%d %H:%M"
    elif len(timestamp_text) == 19:
        timestamp_format = "%Y-%m-%d %H:%M:%S"
    else:
        return None

    expected_separators = (
        timestamp_text[4] == "-"
        and timestamp_text[7] == "-"
        and timestamp_text[10] == " "
        and timestamp_text[13] == ":"
    )
    if len(timestamp_text) == 19:
        expected_separators = (
            expected_separators and timestamp_text[16] == ":"
        )

    if not expected_separators:
        return None

    digit_positions = []
    for index, character in enumerate(timestamp_text):
        if index not in (4, 7, 10, 13) and not (
            len(timestamp_text) == 19 and index == 16
        ):
            digit_positions.append(character)

    if any(not character.isdigit() for character in digit_positions):
        return None

    try:
        timestamp = datetime.strptime(timestamp_text, timestamp_format)
    except (TypeError, ValueError):
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []

    records = []
    seen_record_ids = set()

    for line in text.splitlines():
        record = parse_record(line)
        if record is None:
            continue

        record_id = record["record_id"]
        if record_id in seen_record_ids:
            continue

        seen_record_ids.add(record_id)
        records.append(record)

    return records


def match_payments(records):
    results = []

    for order in records:
        if order["type"] != "ORDER":
            continue

        order_time = order["timestamp"]
        deadline = order_time + timedelta(hours=72)
        selected_payment = None

        for payment in records:
            if payment["type"] != "PAYMENT":
                continue
            if payment["amount"] < 0:
                continue
            if payment["order_id"] != order["order_id"]:
                continue
            if not (order_time <= payment["timestamp"] < deadline):
                continue

            if (
                selected_payment is None
                or payment["timestamp"] < selected_payment["timestamp"]
            ):
                selected_payment = payment

        if selected_payment is None:
            results.append({
                "order_id": order["order_id"],
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order["order_id"],
                "status": "matched",
                "amount": selected_payment["amount"],
            })

    return results


def compute_refunds(records):
    """Return the total in cents for qualifying negative payments."""
    order_ids = set()

    try:
        for record in records:
            if not isinstance(record, dict):
                continue
            if record.get("type") == "ORDER":
                order_id = record.get("order_id")
                if isinstance(order_id, str):
                    order_ids.add(order_id)
    except TypeError:
        return 0

    refund_total = 0

    try:
        for record in records:
            if not isinstance(record, dict):
                continue
            if record.get("type") != "PAYMENT":
                continue
            if record.get("currency") != "USD":
                continue

            order_id = record.get("order_id")
            amount = record.get("amount")

            if order_id not in order_ids:
                continue
            if not isinstance(amount, int) or amount >= 0:
                continue

            refund_total += abs(amount)
    except TypeError:
        return refund_total

    return refund_total


def build_summary(matches, refund_total):
    matched_count = 0
    matched_total = 0
    unmatched_ids = set()

    for result in matches:
        if result["status"] == "matched":
            matched_count += 1
            matched_total += result["amount"]
        elif result["status"] == "unmatched":
            unmatched_ids.add(result["order_id"])

    net_total = matched_total - refund_total
    if net_total < 0:
        net_total = 0

    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "refund_total": refund_total,
        "net_total": net_total,
        "unmatched_ids": sorted(unmatched_ids),
    }

