"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str) or not s:
        return None
    digits = s[1:] if s.startswith("-") else s
    if not digits:
        return None
    parts = digits.split(".")
    if len(parts) > 2 or not parts[0].isdigit():
        return None
    if len(parts) == 2 and (
        not parts[1] or not parts[1].isdigit() or len(parts[1]) > 3
    ):
        return None
    try:
        value = Decimal(s).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
    except (InvalidOperation, ValueError):
        return None
    cents = int(value * 100)
    if abs(cents) > 1000000:
        return None
    return cents


def parse_record(line):
    if not isinstance(line, str):
        return None
    fields = line.split("|")
    if len(fields) != 6:
        return None
    record_type, record_id, order_id, amount_text, currency, timestamp_text = fields
    record_type = record_type.upper()
    record_id = record_id.strip()
    order_id = order_id.strip()
    if record_type not in ("ORDER", "PAYMENT"):
        return None
    if not record_id or not order_id or not order_id.startswith("ORD-"):
        return None
    if currency != "USD":
        return None
    amount = parse_amount(amount_text)
    if amount is None or (record_type == "ORDER" and amount < 0):
        return None
    if len(timestamp_text) not in (16, 19) or timestamp_text[10] != " ":
        return None
    if len(timestamp_text) == 16:
        fmt = "%Y-%m-%d %H:%M"
    else:
        if timestamp_text[16] != ":":
            return None
        fmt = "%Y-%m-%d %H:%M:%S"
    try:
        timestamp = datetime.strptime(timestamp_text, fmt)
    except (TypeError, ValueError):
        return None
    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
