    if not isinstance(records, (list, tuple)):
        return []
    results = []
    for order in records:
        if not isinstance(order, dict) or order.get("type") != "ORDER":
            continue
        order_id = order.get("order_id")
        order_time = order.get("timestamp")
        best = None
        best_time = None
        if isinstance(order_id, str) and isinstance(order_time, datetime):
            cutoff = order_time + timedelta(hours=72)
            for payment in records:
                if not isinstance(payment, dict):
                    continue
                if payment.get("type") != "PAYMENT":
                    continue
                if payment.get("order_id") != order_id:
                    continue
                amount = payment.get("amount")
                payment_time = payment.get("timestamp")
                if not isinstance(amount, int) or amount < 0:
                    continue
                if not isinstance(payment_time, datetime):
                    continue
                if order_time <= payment_time < cutoff:
                    if best is None or payment_time < best_time:
                        best = payment
                        best_time = payment_time
        if best is None:
            results.append({"order_id": order_id, "status": "unmatched", "amount": 0})
        else:
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": best["amount"],
            })
    return results


