    if not isinstance(records, (list, tuple)):
        return 0
    order_ids = set()
    for record in records:
        if not isinstance(record, dict):
            continue
        if record.get("type") == "ORDER" and record.get("currency") == "USD":
            order_id = record.get("order_id")
            if isinstance(order_id, str):
                order_ids.add(order_id)
    total = 0
    for record in records:
        if not isinstance(record, dict):
            continue
        if record.get("type") != "PAYMENT" or record.get("currency") != "USD":
            continue
        amount = record.get("amount")
        if record.get("order_id") in order_ids and isinstance(amount, int) and amount < 0:
            total += -amount
    return total


