from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    """Convert a monetary value to integer cents, or return None if invalid."""
    if isinstance(s, bool) or s is None:
        return None

    text = str(s).strip()
    if not _AMOUNT_PATTERN.fullmatch(text):
        return None

    try:
        value = Decimal(text)
        cents = int(
            (value * Decimal("100")).quantize(
                Decimal("1"),
                rounding=ROUND_HALF_UP,
            )
        )
    except (InvalidOperation, ValueError, TypeError, OverflowError):
        return None

    if abs(cents) > _MAX_CENTS:
        return None

    return cents


def parse_record(line):
    """Parse one pipe-delimited record, or return None if it is invalid."""
    if not isinstance(line, str):
        return None

    parts = [part.strip() for part in line.strip().split("|")]
    if len(parts) != 6:
        return None

    record_type, record_id, order_id, amount, currency, timestamp = parts
    record_type = record_type.upper()

    if record_type not in ("ORDER", "PAYMENT"):
        return None
    if not record_id or not order_id:
        return None
    if not _CURRENCY_PATTERN.fullmatch(currency):
        return None

    amount_value = parse_amount(amount)
    if amount_value is None:
        return None
    if record_type == "ORDER" and amount_value < 0:
        return None
    if _parse_timestamp(timestamp) is None:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount_value,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    """Load valid records while retaining only the first valid record ID."""
    if not isinstance(text, str):
        return []

    records = []
    seen_ids = set()

    for line in text.splitlines():
        record = parse_record(line)
        if record is None:
            continue

        record_id = record["record_id"]
        if record_id in seen_ids:
            continue

        seen_ids.add(record_id)
        records.append(record)

    return records


def match_payments(records):
    """Match each order with the earliest qualifying non-refund payment."""
    if not isinstance(records, (list, tuple)):
        return []

    orders = [
        record
        for record in records
        if isinstance(record, dict) and record.get("type") == "ORDER"
    ]

    payments = [
        (position, record)
        for position, record in enumerate(records)
        if (
            isinstance(record, dict)
            and record.get("type") == "PAYMENT"
            and isinstance(record.get("amount"), int)
            and not isinstance(record.get("amount"), bool)
            and record.get("amount") >= 0
        )
    ]

    results = []

    for order in orders:
        order_time = _parse_timestamp(order.get("timestamp"))
        best_payment = None
        best_time = None
        best_position = None

        if order_time is not None:
            end_time = order_time + timedelta(hours=72)

            for position, payment in payments:
                if payment.get("order_id") != order.get("order_id"):
                    continue

                payment_time = _parse_timestamp(payment.get("timestamp"))
                comparable_order_time, comparable_payment_time = (
                    _timestamps_comparable(order_time, payment_time)
                )
                if comparable_order_time is None:
                    continue

                if not (
                    comparable_order_time
                    <= comparable_payment_time
                    < end_time
                ):
                    continue

                if (
                    best_time is None
                    or comparable_payment_time < best_time
                    or (
                        comparable_payment_time == best_time
                        and position < best_position
                    )
                ):
                    best_payment = payment
                    best_time = comparable_payment_time
                    best_position = position

        if best_payment is None:
            results.append(
                {
                    "order_id": order.get("order_id"),
                    "status": "unmatched",
                    "amount": 0,
                }
            )
        else:
            results.append(
                {
                    "order_id": order.get("order_id"),
                    "status": "matched",
                    "amount": best_payment.get("amount"),
                }
            )

    return results


def compute_refunds(records):
    """Return the positive total of negative payments for existing orders."""
    if not isinstance(records, (list, tuple)):
        return 0

    order_ids = {
        record.get("order_id")
        for record in records
        if isinstance(record, dict) and record.get("type") == "ORDER"
    }

    total = 0
    for record in records:
        if not isinstance(record, dict):
            continue
        if record.get("type") != "PAYMENT":
            continue
        if record.get("order_id") not in order_ids:
            continue

        amount = record.get("amount")
        if (
            isinstance(amount, int)
            and not isinstance(amount, bool)
            and amount < 0
        ):
            total += -amount

    return total


def build_summary(matches, refund_total):
    """Build a five-field reconciliation summary."""
    if not isinstance(matches, list):
        matches = []

    if not isinstance(refund_total, int) or isinstance(refund_total, bool):
        refund_total = 0

    matched_count = 0
    matched_payment_total = 0
    unmatched_ids = set()

    for result in matches:
        if not isinstance(result, dict):
            continue

        if result.get("status") == "matched":
            matched_count += 1
            amount = result.get("amount", 0)
            if isinstance(amount, int) and not isinstance(amount, bool):
                matched_payment_total += amount
        elif result.get("status") == "unmatched":
            order_id = result.get("order_id")
            if isinstance(order_id, str):
                unmatched_ids.add(order_id)

    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "refund_total": refund_total,
        "net_total": max(0, matched_payment_total - refund_total),
        "unmatched_ids": sorted(unmatched_ids),
    }

