"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str) or s == "":
        return None
    negative = s.startswith("-")
    body = s[1:] if negative else s
    if body == "" or body.count(".") > 1:
        return None
    parts = body.split(".")
    if not parts[0].isdigit():
        return None
    if len(parts) == 2:
        if not parts[1].isdigit() or len(parts[1]) > 3:
            return None
        fraction = parts[1]
    else:
        fraction = ""
    normalized = parts[0] + "." + fraction.ljust(2, "0")
    try:
        amount = Decimal(("-" if negative else "") + normalized)
        cents = int(amount.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP) * 100)
    except (InvalidOperation, ValueError, OverflowError):
        return None
    if abs(cents) > 1000000:
        return None
    return cents


def parse_record(line):
    if not isinstance(line, str):
        return None
    fields = line.split("|")
    if len(fields) != 6:
        return None
    record_type, record_id, order_id, amount_text, currency, timestamp_text = fields
    record_type = record_type.upper()
    record_id = record_id.strip()
    order_id = order_id.strip()
    if record_type not in ("ORDER", "PAYMENT"):
        return None
    if not record_id or not order_id.startswith("ORD-") or len(order_id) == 4:
        return None
    if currency != "USD":
        return None
    amount = parse_amount(amount_text)
    if amount is None or (record_type == "ORDER" and amount < 0):
        return None
    if len(timestamp_text) == 16:
        fmt = "%Y-%m-%d %H:%M"
        separators = {4: "-", 7: "-", 10: " ", 13: ":"}
    elif len(timestamp_text) == 19:
        fmt = "%Y-%m-%d %H:%M:%S"
        separators = {4: "-", 7: "-", 10: " ", 13: ":", 16: ":"}
    else:
        return None
    for index, expected in separators.items():
        if timestamp_text[index] != expected:
            return None
    for index, char in enumerate(timestamp_text):
        if index not in separators and not ("0" <= char <= "9"):
            return None
    try:
        timestamp = datetime.strptime(timestamp_text, fmt)
    except (TypeError, ValueError, OverflowError):
        return None
    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []
    retained = []
    seen_ids = set()
    for line in text.splitlines():
        record = parse_record(line)
        if record is None or record["record_id"] in seen_ids:
            continue
        seen_ids.add(record["record_id"])
        retained.append(record)
    return retained


def match_payments(records):
    if records is None:
        return []
    orders = [record for record in records if record.get("type") == "ORDER"]
    payments = [
        (index, record)
        for index, record in enumerate(records)
        if record.get("type") == "PAYMENT" and record.get("amount", 0) >= 0
    ]
    results = []
    for order in orders:
        start = order["timestamp"]
        end = start + timedelta(hours=72)
        candidates = [
            (index, payment)
            for index, payment in payments
            if payment["order_id"] == order["order_id"]
            and start <= payment["timestamp"] < end
        ]
        if candidates:
            _, selected = min(
                candidates,
                key=lambda item: (item[1]["timestamp"], item[0])
            )
            results.append({
                "order_id": order["order_id"],
                "status": "matched",
                "amount": selected["amount"],
            })
        else:
            results.append({
                "order_id": order["order_id"],
                "status": "unmatched",
                "amount": 0,
            })
    return results


def compute_refunds(records):
    if records is None:
        return 0
    order_ids = {
        record["order_id"]
        for record in records
        if record.get("type") == "ORDER"
        and record.get("currency") == "USD"
    }
    return sum(
        -record["amount"]
        for record in records
        if record.get("type") == "PAYMENT"
        and record.get("currency") == "USD"
        and record.get("order_id") in order_ids
        and isinstance(record.get("amount"), int)
        and record["amount"] < 0
    )


def build_summary(matches, refund_total):
    if matches is None:
        matches = []
    matched = [
        result for result in matches
        if result.get("status") == "matched"
    ]
    unmatched_ids = sorted({
        result.get("order_id")
        for result in matches
        if result.get("status") == "unmatched"
    })
    net_total = sum(result.get("amount", 0) for result in matched) - refund_total
    if net_total < 0:
        net_total = 0
    return {
        "total_orders": len(matches),
        "matched_count": len(matched),
        "refund_total": refund_total,
        "net_total": net_total,
        "unmatched_ids": unmatched_ids,
    }

