"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str) or not s:
        return None
    body = s[1:] if s.startswith("-") else s
    if not body or body.count(".") > 1:
        return None
    if "." in body:
        whole, fraction = body.split(".")
        if not whole or not fraction or len(fraction) > 3:
            return None
    else:
        whole, fraction = body, ""
    if not whole.isdigit() or (fraction and not fraction.isdigit()):
        return None
    try:
        value = Decimal(s).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        cents = int(value * 100)
    except (InvalidOperation, ValueError):
        return None
    if abs(cents) > 1000000:
        return None
    return cents


def parse_record(line):
    if not isinstance(line, str):
        return None
    fields = line.split("|")
    if len(fields) != 6:
        return None
    record_type, record_id, order_id, amount_text, currency, timestamp_text = fields
    record_type = record_type.upper()
    if record_type not in ("ORDER", "PAYMENT"):
        return None
    record_id = record_id.strip()
    order_id = order_id.strip()
    if not record_id or not order_id or not order_id.startswith("ORD-"):
        return None
    if currency != "USD":
        return None
    amount = parse_amount(amount_text)
    if amount is None or (record_type == "ORDER" and amount < 0):
        return None
    if len(timestamp_text) not in (16, 19):
        return None
    if timestamp_text[10] != " " or timestamp_text[13] != ":":
        return None
    if len(timestamp_text) == 19:
        if timestamp_text[16] != ":":
            return None
        timestamp_format = "%Y-%m-%d %H:%M:%S"
    else:
        timestamp_format = "%Y-%m-%d %H:%M"
    date_part = timestamp_text[:10]
    time_part = timestamp_text[11:]
    if date_part[4] != "-" or date_part[7] != "-":
        return None
    if not date_part[:4].isdigit() or not date_part[5:7].isdigit() or not date_part[8:].isdigit():
        return None
    if not time_part.replace(":", "").isdigit():
        return None
    try:
        timestamp = datetime.strptime(timestamp_text, timestamp_format)
    except (ValueError, TypeError):
        return None
    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []
    records = []
    seen_ids = set()
    for line in text.splitlines():
        record = parse_record(line)
        if record is None:
            continue
        if record["record_id"] in seen_ids:
            continue
        seen_ids.add(record["record_id"])
        records.append(record)
    return records


def match_payments(records):
    if not isinstance(records, (list, tuple)):
        return []
    orders = [
        record for record in records
        if isinstance(record, dict) and record.get("type") == "ORDER"
    ]
    results = []
    for order in orders:
        selected = None
        order_id = order.get("order_id")
        order_time = order.get("timestamp")
        if isinstance(order_time, datetime):
            limit = order_time + timedelta(hours=72)
            for record in records:
                if not isinstance(record, dict):
                    continue
                if record.get("type") != "PAYMENT":
                    continue
                if record.get("order_id") != order_id:
                    continue
                amount = record.get("amount")
                timestamp = record.get("timestamp")
                if not isinstance(amount, int) or isinstance(amount, bool) or amount < 0:
                    continue
                if not isinstance(timestamp, datetime):
                    continue
                if order_time <= timestamp < limit:
                    if selected is None or timestamp < selected.get("timestamp"):
                        selected = record
        if selected is None:
            results.append({"order_id": order_id, "status": "unmatched", "amount": 0})
        else:
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": selected["amount"],
            })
    return results


def compute_refunds(records):
    if not isinstance(records, (list, tuple)):
        return 0
    order_ids = set()
    for record in records:
        if not isinstance(record, dict):
            continue
        if (
            record.get("type") == "ORDER"
            and record.get("currency") == "USD"
            and isinstance(record.get("order_id"), str)
        ):
            order_ids.add(record["order_id"])
    total = 0
    for record in records:
        if not isinstance(record, dict):
            continue
        if (
            record.get("type") == "PAYMENT"
            and record.get("currency") == "USD"
            and record.get("order_id") in order_ids
        ):
            amount = record.get("amount")
            if isinstance(amount, int) and not isinstance(amount, bool) and amount < 0:
                total += abs(amount)
    return total


def build_summary(matches, refund_total):
    if not isinstance(matches, (list, tuple)):
        matches = []
    total_orders = len(matches)
    matched_count = 0
    matched_total = 0
    unmatched_ids = set()

    for result in matches:
        if not isinstance(result, dict):
            continue
        status = result.get("status")
        if status == "matched":
            matched_count += 1
            amount = result.get("amount")
            if isinstance(amount, int) and not isinstance(amount, bool):
                matched_total += amount
        elif status == "unmatched":
            order_id = result.get("order_id")
            if isinstance(order_id, str):
                unmatched_ids.add(order_id)

    if not isinstance(refund_total, int) or isinstance(refund_total, bool):
        refund_total = 0
    net_total = matched_total - refund_total
    if net_total < 0:
        net_total = 0

    return {
        "total_orders": total_orders,
        "matched_count": matched_count,
        "refund_total": refund_total,
        "net_total": net_total,
        "unmatched_ids": sorted(unmatched_ids),
    }

