from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        if not isinstance(s, str):
            return None
        text = s.strip()
        if not text:
            return None
        body = text[1:] if text.startswith("-") else text
        if not body or any(ch not in "0123456789." for ch in body):
            return None
        if body.count(".") > 1:
            return None
        if "." in body and len(body.split(".", 1)[1]) > 3:
            return None
        if not any(ch.isdigit() for ch in body):
            return None
        value = Decimal(text)
        if not value.is_finite():
            return None
        cents = int((value * Decimal("100")).quantize(
            Decimal("1"), rounding=ROUND_HALF_UP
        ))
        return cents if abs(cents) <= 1000000 else None
    except (InvalidOperation, ValueError, TypeError, OverflowError):
        return None


def parse_record(line):
    if not isinstance(line, str):
        return None
    try:
        fields = line.split("|")
        if len(fields) != 6:
            return None
        kind, record_id, order_id, amount, currency, stamp = fields
        kind = kind.upper()
        record_id = record_id.strip()
        order_id = order_id.strip()
        if kind not in ("ORDER", "PAYMENT"):
            return None
        if not record_id or not order_id.startswith("ORD-"):
            return None
        if currency != "USD":
            return None
        cents = parse_amount(amount)
        if cents is None or (kind == "ORDER" and cents < 0):
            return None
        timestamp = None
        for fmt in ("%Y-%m-%d %H:%M", "%Y-%m-%d %H:%M:%S"):
            try:
                timestamp = datetime.strptime(stamp, fmt)
                break
            except ValueError:
                continue
        if timestamp is None:
            return None
        return {
            "type": kind,
            "record_id": record_id,
            "order_id": order_id,
            "amount": cents,
            "currency": currency,
            "timestamp": timestamp,
        }
    except Exception:
        return None


def load_records(text):
    if not isinstance(text, str):
        return []
    result = []
    seen = set()
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None and record["record_id"] not in seen:
            seen.add(record["record_id"])
            result.append(record)
    return result


def match_payments(records):
    if not isinstance(records, list):
        return []
    results = []
    for order in records:
        if not isinstance(order, dict) or order.get("type") != "ORDER":
            continue
        order_id = order.get("order_id")
        start = order.get("timestamp")
        best_index = None
        best_time = None
        if isinstance(order_id, str) and isinstance(start, datetime):
            end = start + timedelta(hours=72)
            for index, payment in enumerate(records):
                if not isinstance(payment, dict):
                    continue
                if payment.get("type") != "PAYMENT":
                    continue
                if payment.get("order_id") != order_id:
                    continue
                amount = payment.get("amount")
                timestamp = payment.get("timestamp")
                if not isinstance(amount, int) or amount < 0:
                    continue
                if not isinstance(timestamp, datetime):
                    continue
                if timestamp < start or timestamp >= end:
                    continue
                if (best_time is None or timestamp < best_time or
                        (timestamp == best_time and index < best_index)):
                    best_time = timestamp
                    best_index = index
        if best_index is None:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": records[best_index]["amount"],
            })
    return results


def compute_refunds(records):
    if not isinstance(records, list):
        return 0
    order_ids = {
        item.get("order_id")
        for item in records
        if isinstance(item, dict) and item.get("type") == "ORDER"
    }
    total = 0
    for item in records:
        if (isinstance(item, dict)
                and item.get("type") == "PAYMENT"
                and item.get("order_id") in order_ids
                and isinstance(item.get("amount"), int)
                and item["amount"] < 0):
            total += -item["amount"]
    return total


def build_summary(matches, refund_total):
    if not isinstance(matches, list):
        matches = []
    if not isinstance(refund_total, int):
        refund_total = 0
    matched = [
        item for item in matches
        if isinstance(item, dict) and item.get("status") == "matched"
    ]
    paid_total = sum(
        item["amount"] for item in matched
        if isinstance(item.get("amount"), int)
    )
    unmatched_ids = sorted({
        item.get("order_id") for item in matches
        if isinstance(item, dict)
        and item.get("status") != "matched"
        and isinstance(item.get("order_id"), str)
    })
    return {
        "total_orders": len(matches),
        "matched_count": len(matched),
        "refund_total": refund_total,
        "net_total": max(0, paid_total - refund_total),
        "unmatched_ids": unmatched_ids,
    }

