from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str):
        return None

    if not re.fullmatch(r"-?[0-9]+(?:\.[0-9]{1,3})?", s):
        return None

    try:
        amount = Decimal(s).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        cents = int(amount * 100)
    except (InvalidOperation, ValueError, OverflowError):
        return None

    if abs(cents) > 1_000_000:
        return None

    return cents


def parse_record(line):
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount_text, currency, timestamp_text = fields
    record_type = record_type.upper()
    record_id = record_id.strip()
    order_id = order_id.strip()

    if record_type not in ("ORDER", "PAYMENT"):
        return None

    if not record_id or not order_id or not order_id.startswith("ORD-"):
        return None

    if currency != "USD":
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None

    if record_type == "ORDER" and amount < 0:
        return None

    if re.fullmatch(r"[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}", timestamp_text):
        timestamp_format = "%Y-%m-%d %H:%M"
    elif re.fullmatch(
        r"[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}:[0-9]{2}",
        timestamp_text,
    ):
        timestamp_format = "%Y-%m-%d %H:%M:%S"
    else:
        return None

    try:
        timestamp = datetime.strptime(timestamp_text, timestamp_format)
    except ValueError:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []

    retained = []
    seen_record_ids = set()

    for line in text.splitlines():
        try:
            record = parse_record(line)
        except Exception:
            record = None

        if record is None:
            continue

        record_id = record["record_id"]
        if record_id in seen_record_ids:
            continue

        seen_record_ids.add(record_id)
        retained.append(record)

    return retained


def match_payments(records):
    results = []

    for order in records:
        if order["type"] != "ORDER":
            continue

        selected_payment = None
        selected_key = None
        deadline = order["timestamp"] + timedelta(hours=72)

        for source_index, payment in enumerate(records):
            if payment["type"] != "PAYMENT":
                continue
            if payment["amount"] < 0:
                continue
            if payment["order_id"] != order["order_id"]:
                continue
            if payment["timestamp"] < order["timestamp"]:
                continue
            if payment["timestamp"] >= deadline:
                continue

            candidate_key = (payment["timestamp"], source_index)
            if selected_key is None or candidate_key < selected_key:
                selected_payment = payment
                selected_key = candidate_key

        if selected_payment is None:
            results.append({
                "order_id": order["order_id"],
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order["order_id"],
                "status": "matched",
                "amount": selected_payment["amount"],
            })

    return results


def compute_refunds(records):
    try:
        existing_order_ids = {
            record["order_id"]
            for record in records
            if isinstance(record, dict)
            and record.get("type") == "ORDER"
        }
    except (TypeError, AttributeError):
        return 0

    refund_total = 0

    try:
        for record in records:
            if (
                isinstance(record, dict)
                and record.get("type") == "PAYMENT"
                and record.get("currency") == "USD"
                and isinstance(record.get("amount"), int)
                and record["amount"] < 0
                and record.get("order_id") in existing_order_ids
            ):
                refund_total += abs(record["amount"])
    except (TypeError, AttributeError):
        return refund_total

    return refund_total


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = 0
    matched_total = 0
    unmatched_ids = set()

    for result in matches:
        if result.get("status") == "matched":
            matched_count += 1
            matched_total += result.get("amount", 0)
        elif result.get("status") == "unmatched":
            unmatched_ids.add(result.get("order_id"))

    net_total = matched_total - refund_total
    if net_total < 0:
        net_total = 0

    return {
        "total_orders": total_orders,
        "matched_count": matched_count,
        "refund_total": refund_total,
        "net_total": net_total,
        "unmatched_ids": sorted(unmatched_ids),
    }

