from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    """Convert a dollar amount to integer cents, or return None if invalid."""
    if isinstance(s, bool) or s is None:
        return None

    text = str(s).strip()
    if not _AMOUNT_RE.fullmatch(text):
        return None

    try:
        value = Decimal(text)
        with localcontext() as context:
            context.prec = max(
                28,
                len(text.replace("-", "").replace("+", "").replace(".", "")) + 10,
            )
            cents = value.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)

        cents_value = int(cents * 100)

        if abs(cents_value) > 100_000_000:
            return None

        return cents_value
    except (InvalidOperation, ValueError, TypeError, OverflowError):
        return None


def parse_record(line):
    """Parse a six-field pipe-separated record."""
    if not isinstance(line, str):
        return None

    fields = line.strip().split("|")
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount, currency, timestamp = (
        field.strip() for field in fields
    )

    record_type = record_type.upper()
    currency = currency.upper()

    if record_type not in ("ORDER", "PAYMENT"):
        return None
    if not record_id or not order_id:
        return None
    if not _CURRENCY_RE.fullmatch(currency):
        return None

    parsed_amount = parse_amount(amount)
    if parsed_amount is None:
        return None

    if record_type == "ORDER" and parsed_amount < 0:
        return None

    if not _valid_timestamp(timestamp):
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": parsed_amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    """Parse valid records, retaining only the first valid record ID."""
    if not isinstance(text, str):
        return []

    records = []
    seen_ids = set()

    for line in text.splitlines():
        record = parse_record(line)
        if record is None:
            continue

        record_id = record["record_id"]
        if record_id in seen_ids:
            continue

        seen_ids.add(record_id)
        records.append(record)

    return records


def match_payments(records):
    """Match each order with one qualifying payment, if available."""
    if not isinstance(records, list):
        return []

    orders = [
        record
        for record in records
        if isinstance(record, dict) and record.get("type") == "ORDER"
    ]

    used_payment_indices = set()
    results = []

    for order in orders:
        order_id = order.get("order_id")
        order_amount = order.get("amount")
        order_currency = order.get("currency")
        order_time = _timestamp_value(order.get("timestamp"))
        candidates = []

        if (
            order_time is not None
            and isinstance(order_amount, int)
            and not isinstance(order_amount, bool)
            and order_amount >= 0
        ):
            deadline = order_time + timedelta(hours=72)

            for payment_index, payment in enumerate(records):
                if payment_index in used_payment_indices:
                    continue
                if not isinstance(payment, dict):
                    continue
                if payment.get("type") != "PAYMENT":
                    continue
                if payment.get("order_id") != order_id:
                    continue
                if payment.get("amount") != order_amount:
                    continue
                if payment.get("currency") != order_currency:
                    continue

                payment_time = _timestamp_value(payment.get("timestamp"))
                if payment_time is None:
                    continue

                try:
                    qualifies = order_time <= payment_time < deadline
                except TypeError:
                    qualifies = False

                if qualifies:
                    candidates.append((payment_time, payment_index, payment))

        if candidates:
            _, payment_index, payment = min(
                candidates,
                key=lambda candidate: (candidate[0], candidate[1]),
            )
            used_payment_indices.add(payment_index)
            results.append(
                {
                    "order_id": order_id,
                    "status": "matched",
                    "amount": payment["amount"],
                }
            )
        else:
            results.append(
                {
                    "order_id": order_id,
                    "status": "unmatched",
                    "amount": 0,
                }
            )

    return results


def compute_refunds(records):
    """Return the positive total of negative payments for existing orders."""
    if not isinstance(records, list):
        return 0

    order_ids = {
        record.get("order_id")
        for record in records
        if isinstance(record, dict) and record.get("type") == "ORDER"
    }

    total = 0
    for record in records:
        if not isinstance(record, dict):
            continue
        if record.get("type") != "PAYMENT":
            continue

        amount = record.get("amount")
        if (
            isinstance(amount, int)
            and not isinstance(amount, bool)
            and amount < 0
            and record.get("order_id") in order_ids
        ):
            total += -amount

    return total


def build_summary(matches, refund_total):
    """Build the reconciliation summary."""
    if not isinstance(matches, list):
        matches = []

    matched_count = 0
    matched_total = 0
    unmatched_ids = set()

    for result in matches:
        if not isinstance(result, dict):
            continue

        status = result.get("status")
        order_id = result.get("order_id")

        if status == "matched":
            matched_count += 1
            amount = result.get("amount")
            if isinstance(amount, int) and not isinstance(amount, bool):
                matched_total += amount
        elif order_id is not None:
            unmatched_ids.add(str(order_id))

    if not isinstance(refund_total, int) or isinstance(refund_total, bool):
        refund_total = 0

    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "refund_total": refund_total,
        "net_total": max(0, matched_total - refund_total),
        "unmatched_ids": sorted(unmatched_ids),
    }

