from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        amount = Decimal(s)
        if abs(amount) > 1000000:
            return None
        return int(amount * 100)  # Convert to cents
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.strip().split('|')
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount, currency, timestamp = fields
    record_type = record_type.upper()

    # Validate TYPE
    if record_type not in ['ORDER', 'PAYMENT']:
        return None

    # Validate IDs
    if not record_id.strip() or not order_id.strip():
        return None

    # Validate AMOUNT
    parsed_amount = parse_amount(amount)
    if parsed_amount is None:
        return None

    # Validate CURRENCY
    if not currency.strip():  # Assuming currency should not be empty
        return None

    # Validate TIMESTAMP
    try:
        datetime.fromisoformat(timestamp)
    except ValueError:
        return None

    return {
        'type': record_type,
        'record_id': record_id.strip(),
        'order_id': order_id.strip(),
        'amount': parsed_amount,
        'currency': currency.strip(),
        'timestamp': timestamp.strip()
    }


def load_records(text):
    records = []
    for line in text.strip().splitlines():
        record = parse_record(line)
        if record and not any(r['record_id'] == record['record_id'] for r in records):
            records.append(record)
    return records


def match_payments(records):
    orders = {}
    payments = []

    for record in records:
        if record['type'] == 'ORDER':
            orders[record['order_id']] = {
                'timestamp': datetime.fromisoformat(record['timestamp']),
                'amount': record['amount']
            }
        elif record['type'] == 'PAYMENT':
            payments.append({
                'order_id': record['order_id'],
                'amount': record['amount'],
                'timestamp': datetime.fromisoformat(record['timestamp'])
            })

    results = []
    for order_id, order in orders.items():
        order_time = order['timestamp']
        order_amount = order['amount']
        matching_payments = [
            payment for payment in payments
            if payment['order_id'] == order_id and
            order_time <= payment['timestamp'] < order_time + timedelta(hours=72)
        ]

        if matching_payments:
            # Sort by timestamp, then by original order in the records
            matching_payments.sort(key=lambda p: (p['timestamp'], payments.index(p)))
            earliest_payment = matching_payments[0]
            results.append({
                'order_id': order_id,
                'status': 'matched',
                'amount': earliest_payment['amount']
            })
        else:
            results.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': 0
            })

    return results


def compute_refunds(records):
    refund_total = sum(record['amount'] for record in records if record['type'] == 'PAYMENT' and record['amount'] < 0)
    return max(0, refund_total)


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = max(0, sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total)
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] != 'matched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

