from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    """Convert a dollar amount to integer cents, or return None if invalid."""
    if not isinstance(s, str):
        return None

    value = s.strip()
    if not value:
        return None

    if value.startswith("-"):
        number = value[1:]
    else:
        number = value

    if not number:
        return None

    if "." in number:
        if number.count(".") != 1:
            return None
        whole, fraction = number.split(".")
        if not whole or not fraction:
            return None
        if len(fraction) > 3:
            return None
    else:
        whole = number
        fraction = ""

    if not whole.isascii() or not whole.isdigit():
        return None

    if fraction and (
        not fraction.isascii() or not fraction.isdigit()
    ):
        return None

    try:
        dollars = Decimal(value)
        cents_value = (dollars * Decimal("100")).quantize(
            Decimal("1"),
            rounding=ROUND_HALF_UP,
        )
    except (InvalidOperation, ValueError, TypeError):
        return None

    if not cents_value.is_finite():
        return None

    cents = int(cents_value)
    if abs(cents) > 1_000_000:
        return None

    return cents


def parse_record(line):
    """Parse one valid input line into a record dictionary."""
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 6:
        return None

    (
        record_type,
        record_id,
        order_id,
        amount_text,
        currency,
        timestamp_text,
    ) = (field.strip() for field in fields)

    record_type = record_type.upper()
    if record_type not in {"ORDER", "PAYMENT"}:
        return None

    if not record_id or not order_id:
        return None

    if (
        len(currency) != 3
        or not currency.isascii()
        or not currency.isalpha()
        or not currency.isupper()
    ):
        return None

    if not timestamp_text:
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None

    if record_type == "ORDER" and amount < 0:
        return None

    timestamp_value = timestamp_text
    if timestamp_value.endswith("Z"):
        timestamp_value = timestamp_value[:-1] + "+00:00"

    try:
        timestamp = datetime.fromisoformat(timestamp_value)
    except (TypeError, ValueError):
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    """Load valid records while preserving order and first duplicates."""
    if not isinstance(text, str):
        return []

    records = []
    seen_record_ids = set()

    for line in text.splitlines():
        record = parse_record(line)
        if record is None:
            continue

        record_id = record["record_id"]
        if record_id in seen_record_ids:
            continue

        seen_record_ids.add(record_id)
        records.append(record)

    return records


def match_payments(records):
    """Match each order with the earliest qualifying payment."""
    if not isinstance(records, list):
        return []

    def comparable_timestamp(timestamp):
        if not isinstance(timestamp, datetime):
            return None

        try:
            offset = timestamp.utcoffset()
        except (TypeError, ValueError):
            return None

        if offset is not None:
            timestamp = timestamp - offset

        return timestamp.replace(tzinfo=None)

    orders = [
        record
        for record in records
        if isinstance(record, dict)
        and record.get("type") == "ORDER"
    ]

    payments = [
        (index, record)
        for index, record in enumerate(records)
        if (
            isinstance(record, dict)
            and record.get("type") == "PAYMENT"
            and isinstance(record.get("amount"), int)
            and not isinstance(record.get("amount"), bool)
            and record.get("amount") >= 0
        )
    ]

    results = []

    for order in orders:
        order_timestamp = comparable_timestamp(order.get("timestamp"))
        order_amount = order.get("amount")
        order_id = order.get("order_id")
        order_currency = order.get("currency")

        best_payment = None
        best_key = None

        if (
            order_timestamp is not None
            and isinstance(order_amount, int)
            and not isinstance(order_amount, bool)
        ):
            end_timestamp = order_timestamp + timedelta(hours=72)

            for source_index, payment in payments:
                payment_timestamp = comparable_timestamp(
                    payment.get("timestamp")
                )

                if payment_timestamp is None:
                    continue
                if payment.get("order_id") != order_id:
                    continue
                if payment.get("currency") != order_currency:
                    continue
                if payment.get("amount") != order_amount:
                    continue
                if not (
                    order_timestamp
                    <= payment_timestamp
                    < end_timestamp
                ):
                    continue

                key = (payment_timestamp, source_index)
                if best_key is None or key < best_key:
                    best_key = key
                    best_payment = payment

        if best_payment is None:
            results.append(
                {
                    "order_id": order_id,
                    "status": "unmatched",
                    "amount": 0,
                }
            )
        else:
            results.append(
                {
                    "order_id": order_id,
                    "status": "matched",
                    "amount": best_payment["amount"],
                }
            )

    return results


def compute_refunds(records):
    """Return the positive total of qualifying negative payments."""
    if not isinstance(records, list):
        return 0

    existing_order_ids = {
        record.get("order_id")
        for record in records
        if (
            isinstance(record, dict)
            and record.get("type") == "ORDER"
        )
    }

    total = 0

    for record in records:
        if not isinstance(record, dict):
            continue
        if record.get("type") != "PAYMENT":
            continue
        if record.get("order_id") not in existing_order_ids:
            continue

        amount = record.get("amount")
        if (
            isinstance(amount, int)
            and not isinstance(amount, bool)
            and amount < 0
        ):
            total += -amount

    return total


def build_summary(matches, refund_total):
    """Build the five-field reconciliation summary."""
    if not isinstance(matches, list):
        matches = []

    matched_count = 0
    matched_total = 0
    unmatched_ids = set()

    for result in matches:
        if not isinstance(result, dict):
            continue

        status = result.get("status")
        order_id = result.get("order_id")

        if status == "matched":
            matched_count += 1
            amount = result.get("amount", 0)
            if isinstance(amount, int) and not isinstance(amount, bool):
                matched_total += amount
        elif status == "unmatched" and isinstance(order_id, str):
            unmatched_ids.add(order_id)

    if not isinstance(refund_total, int) or isinstance(refund_total, bool):
        refund_total = 0

    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "refund_total": refund_total,
        "net_total": max(0, matched_total - refund_total),
        "unmatched_ids": sorted(unmatched_ids),
    }

