"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        if '.' in s:
            whole, frac = s.split('.')
            if len(frac) > 3:
                return None
            amount = int(Decimal(whole + '.' + frac).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP) * 100)
        else:
            amount = int(s)
        if abs(amount) > 1000000:
            return None
        return amount
    except (ValueError, TypeError, InvalidOperation):
        return None


def parse_record(line):
    fields = line.strip().split('|')
    if len(fields) != 6:
        return None
    record_type, record_id, order_id, amount, currency, timestamp = fields
    record_type = record_type.upper()
    if record_type not in ['ORDER', 'PAYMENT']:
        return None
    record_id = record_id.strip()
    order_id = order_id.strip()
    amount = parse_amount(amount.strip())
    if currency != 'USD' or not record_id or not order_id or amount is None:
        return None
    try:
        timestamp = datetime.strptime(timestamp.strip(), '%Y-%m-%d %H:%M:%S')
    except ValueError:
        try:
            timestamp = datetime.strptime(timestamp.strip(), '%Y-%m-%d %H:%M')
        except ValueError:
            return None
    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount,
        'currency': currency,
        'timestamp': timestamp
    }


def load_records(text):
    raise NotImplementedError


def match_payments(records):
    orders = {}
    results = []
    for record in records:
        if record['type'] == 'ORDER':
            orders[record['order_id']] = record
        elif record['type'] == 'PAYMENT':
            order_id = record['order_id']
            if order_id in orders:
                order_timestamp = orders[order_id]['timestamp']
                payment_timestamp = record['timestamp']
                if order_timestamp <= payment_timestamp < order_timestamp + timedelta(hours=72):
                    results.append({
                        'order_id': order_id,
                        'status': 'matched',
                        'amount': record['amount']
                    })
                    continue
            results.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': 0
            })
    return results


def compute_refunds(records):
    raise NotImplementedError


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = max(sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total, 0)
    unmatched_ids = sorted(set(match['record_id'] for match in matches if match['status'] != 'matched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

