"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str) or not s.strip():
        return None
    try:
        amount = Decimal(s)
        if amount.as_tuple().exponent < -3:
            return None
        amount = amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        cents = int(amount * 100)
        if abs(cents) > 1000000:
            return None
        return cents
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.strip().split('|')
    if len(fields) != 6:
        return None
    record_type = fields[0].strip().upper()
    record_id = fields[1].strip()
    order_id = fields[2].strip()
    amount = parse_amount(fields[3].strip())
    currency = fields[4].strip()
    timestamp_str = fields[5].strip()

    if record_type not in ['ORDER', 'PAYMENT']:
        return None
    if not record_id or not order_id.startswith('ORD-'):
        return None
    if currency != 'USD':
        return None
    if amount is None or amount < 0:
        return None
    try:
        timestamp = datetime.strptime(timestamp_str, '%Y-%m-%d %H:%M:%S')
    except ValueError:
        try:
            timestamp = datetime.strptime(timestamp_str, '%Y-%m-%d %H:%M')
        except ValueError:
            return None

    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount,
        'currency': currency,
        'timestamp': timestamp
    }


def load_records(text):
    records = []
    seen_ids = set()

    for line in text.strip().split('\n'):
        record = parse_record(line)
        if record and record['record_id'] not in seen_ids:
            records.append(record)
            seen_ids.add(record['record_id'])

    return records


def match_payments(records):
    orders = [record for record in records if record['type'] == 'ORDER']
    payments = [record for record in records if record['type'] == 'PAYMENT']
    results = []

    for order in orders:
        matched_payment = None
        for payment in payments:
            if (payment['order_id'] == order['order_id'] and
                order['timestamp'] <= payment['timestamp'] < order['timestamp'] + timedelta(hours=72)):
                if matched_payment is None or payment['timestamp'] < matched_payment['timestamp']:
                    matched_payment = payment

        if matched_payment:
            results.append({
                'order_id': order['order_id'],
                'status': 'matched',
                'amount': abs(matched_payment['amount'])
            })
        else:
            results.append({
                'order_id': order['order_id'],
                'status': 'unmatched',
                'amount': 0
            })

    return results


def compute_refunds(records):
    refund_total = 0
    valid_order_ids = {record['order_id'] for record in records if record['type'] == 'ORDER'}

    for record in records:
        if record['type'] == 'PAYMENT' and record['amount'] < 0 and record['order_id'] in valid_order_ids:
            refund_total += abs(record['amount'])

    return refund_total


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total
    net_total = max(net_total, 0)
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] == 'unmatched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    """Convert a valid amount to integer cents, or return None."""
    if isinstance(s, bool) or s is None:
        return None

    text = str(s).strip()

    if not _AMOUNT_PATTERN.fullmatch(text):
        return None

    try:
        with localcontext() as context:
            context.prec = max(28, len(text) + 10)
            value = Decimal(text)
            cents = value.quantize(
                Decimal("0.01"),
                rounding=ROUND_HALF_UP,
            )
            cents_value = int(cents * 100)

        if abs(cents_value) > _MAX_CENTS:
            return None

        return cents_value
    except (InvalidOperation, ValueError, TypeError, ArithmeticError):
        return None


def parse_record(line):
    """Parse one six-field record, returning None when invalid."""
    if not isinstance(line, str):
        return None

    pieces = line.strip().split("|")

    if len(pieces) != 6:
        return None

    pieces = [piece.strip() for piece in pieces]
    record_type, record_id, order_id, amount_text, currency, timestamp = pieces

    record_type = record_type.upper()

    if record_type not in ("ORDER", "PAYMENT"):
        return None

    if not _ID_PATTERN.fullmatch(record_id):
        return None

    if not _ID_PATTERN.fullmatch(order_id):
        return None

    if not _CURRENCY_PATTERN.fullmatch(currency):
        return None

    if _parse_timestamp(timestamp) is None:
        return None

    amount = parse_amount(amount_text)

    if amount is None:
        return None

    if record_type == "ORDER" and amount < 0:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    """Load valid records while keeping the first valid record ID."""
    if not isinstance(text, str):
        return []

    records = []
    seen_ids = set()

    for line in text.splitlines():
        record = parse_record(line)

        if record is None:
            continue

        record_id = record["record_id"]

        if record_id in seen_ids:
            continue

        seen_ids.add(record_id)
        records.append(record)

    return records


def match_payments(records):
    """Match non-negative payments to orders strictly within 72 hours."""
    if not isinstance(records, (list, tuple)):
        return []

    orders = [
        record
        for record in records
        if isinstance(record, dict) and record.get("type") == "ORDER"
    ]

    payments = [
        (index, record)
        for index, record in enumerate(records)
        if (
            isinstance(record, dict)
            and record.get("type") == "PAYMENT"
            and isinstance(record.get("amount"), int)
            and not isinstance(record.get("amount"), bool)
            and record.get("amount") >= 0
        )
    ]

    used_payment_ids = set()
    results = []

    for order in orders:
        order_id = order.get("order_id")
        order_amount = order.get("amount")
        order_currency = order.get("currency")
        order_time = _parse_timestamp(order.get("timestamp"))
        candidates = []

        if (
            order_time is not None
            and isinstance(order_amount, int)
            and not isinstance(order_amount, bool)
        ):
            end_time = order_time + timedelta(hours=72)

            for source_index, payment in payments:
                payment_id = payment.get("record_id")

                if payment_id in used_payment_ids:
                    continue

                if payment.get("order_id") != order_id:
                    continue

                if payment.get("currency") != order_currency:
                    continue

                if payment.get("amount") != order_amount:
                    continue

                payment_time = _parse_timestamp(payment.get("timestamp"))

                if payment_time is None:
                    continue

                if order_time <= payment_time < end_time:
                    candidates.append((payment_time, source_index, payment))

        if candidates:
            _, _, payment = min(candidates, key=lambda item: (item[0], item[1]))
            used_payment_ids.add(payment.get("record_id"))
            results.append(
                {
                    "order_id": order_id,
                    "status": "matched",
                    "amount": payment["amount"],
                }
            )
        else:
            results.append(
                {
                    "order_id": order_id,
                    "status": "unmatched",
                    "amount": 0,
                }
            )

    return results


def compute_refunds(records):
    """Return the positive total of qualifying negative payments."""
    if not isinstance(records, (list, tuple)):
        return 0

    order_ids = {
        record.get("order_id")
        for record in records
        if (
            isinstance(record, dict)
            and record.get("type") == "ORDER"
            and record.get("order_id")
        )
    }

    refund_total = 0

    for record in records:
        if not isinstance(record, dict):
            continue

        amount = record.get("amount")

        if (
            record.get("type") == "PAYMENT"
            and record.get("order_id") in order_ids
            and isinstance(amount, int)
            and not isinstance(amount, bool)
            and amount < 0
        ):
            refund_total += -amount

    return refund_total


def build_summary(matches, refund_total):
    """Build the reconciliation summary."""
    if not isinstance(matches, (list, tuple)):
        matches = []

    if not isinstance(refund_total, int) or isinstance(refund_total, bool):
        refund_total = 0

    matched_count = 0
    matched_total = 0
    unmatched_ids = set()

    for result in matches:
        if not isinstance(result, dict):
            continue

        if result.get("status") == "matched":
            matched_count += 1
            amount = result.get("amount")

            if isinstance(amount, int) and not isinstance(amount, bool):
                matched_total += amount
        else:
            order_id = result.get("order_id")

            if order_id is not None:
                unmatched_ids.add(str(order_id))

    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "refund_total": refund_total,
        "net_total": max(0, matched_total - refund_total),
        "unmatched_ids": sorted(unmatched_ids),
    }

