"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str) or not s.strip():
        return None
    try:
        amount = Decimal(s)
    except (InvalidOperation, ValueError):
        return None

    if amount.as_tuple().exponent < -3:
        return None

    amount = amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)

    if abs(amount) > Decimal('1000000'):
        return None

    return int(amount * 100)  # Convert to cents


def parse_record(line):
    fields = line.split('|')
    if len(fields) != 6:
        return None

    record_type = fields[0].strip().upper()
    record_id = fields[1].strip()
    order_id = fields[2].strip()
    amount_str = fields[3].strip()
    currency = fields[4].strip()
    timestamp_str = fields[5].strip()

    if record_type not in ['ORDER', 'PAYMENT']:
        return None
    if not record_id or not order_id.startswith('ORD-'):
        return None
    if currency != 'USD':
        return None

    amount = parse_amount(amount_str)
    if amount is None or (record_type == 'ORDER' and amount < 0):
        return None

    try:
        timestamp = datetime.strptime(timestamp_str, '%Y-%m-%d %H:%M:%S')
    except ValueError:
        try:
            timestamp = datetime.strptime(timestamp_str, '%Y-%m-%d %H:%M')
        except ValueError:
            return None

    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount,
        'currency': currency,
        'timestamp': timestamp
    }


def load_records(text):
    records = []
    seen_ids = set()

    for line in text.strip().split('\n'):
        record = parse_record(line)
        if record and record['record_id'] not in seen_ids:
            records.append(record)
            seen_ids.add(record['record_id'])

    return records


def match_payments(records):
    orders = [record for record in records if record['type'] == 'ORDER']
    payments = [record for record in records if record['type'] == 'PAYMENT' and record['amount'] >= 0]
    results = []

    for order in orders:
        order_id = order['order_id']
        order_timestamp = order['timestamp']
        valid_payments = [
            payment for payment in payments
            if payment['order_id'] == order_id and order_timestamp <= payment['timestamp'] < order_timestamp + timedelta(hours=72)
        ]

        if valid_payments:
            earliest_payment = min(valid_payments, key=lambda p: (p['timestamp'], payments.index(p)))
            results.append({
                'order_id': order_id,
                'status': 'matched',
                'amount': earliest_payment['amount']
            })
        else:
            results.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': 0
            })

    return results


def compute_refunds(records):
    refund_total = 0
    valid_order_ids = {record['order_id'] for record in records if record['type'] == 'ORDER'}

    for record in records:
        if record['type'] == 'PAYMENT' and record['amount'] < 0:
            if record['order_id'] in valid_order_ids:
                refund_total += abs(record['amount'])

    return refund_total


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total
    net_total = max(net_total, 0)
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] == 'unmatched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    """Convert a decimal dollar amount to integer cents, or return None."""
    if not isinstance(s, str):
        return None

    value = s.strip()
    if not value or not re.fullmatch(r"-?\d+(?:\.\d*)?", value):
        return None

    fractional = value.partition(".")[2]
    if len(fractional) > 3:
        return None

    try:
        amount = Decimal(value)
        if not amount.is_finite():
            return None

        cents = (amount * Decimal("100")).quantize(
            Decimal("1"),
            rounding=ROUND_HALF_UP,
        )
        cents = int(cents)
    except (InvalidOperation, ValueError, TypeError, OverflowError):
        return None

    if abs(cents) > 1_000_000:
        return None

    return cents


def parse_record(line):
    """Parse one input line into a record dictionary, or return None."""
    if not isinstance(line, str):
        return None

    fields = line.rstrip("\r\n").split("|")
    if len(fields) != 6:
        return None

    (
        record_type,
        record_id,
        order_id,
        amount_text,
        currency,
        timestamp,
    ) = (field.strip() for field in fields)

    record_type = record_type.upper()
    if record_type not in {"ORDER", "PAYMENT"}:
        return None

    if not record_id or not order_id:
        return None

    if not re.fullmatch(r"[A-Za-z]{3}", currency):
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None

    if record_type == "ORDER" and amount < 0:
        return None

    try:
        if timestamp.endswith("Z"):
            timestamp_value = timestamp[:-1] + "+00:00"
        else:
            timestamp_value = timestamp

        parsed_timestamp = datetime.fromisoformat(timestamp_value)
    except (TypeError, ValueError):
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency.upper(),
        "timestamp": parsed_timestamp,
    }


def load_records(text):
    """Load valid records, retaining only the first valid occurrence of an ID."""
    if not isinstance(text, str):
        return []

    records = []
    seen_ids = set()

    for line in text.splitlines():
        record = parse_record(line)
        if record is None:
            continue

        record_id = record["record_id"]
        if record_id in seen_ids:
            continue

        seen_ids.add(record_id)
        records.append(record)

    return records


def match_payments(records):
    """Match each order with the earliest qualifying payment."""
    if not isinstance(records, list):
        return []

    orders = []
    payments = []

    for record in records:
        if not isinstance(record, dict):
            continue

        if record.get("type") == "ORDER":
            orders.append(record)
        elif record.get("type") == "PAYMENT":
            payments.append(record)

    used_payments = set()
    results = []

    for order in orders:
        order_id = order.get("order_id")
        order_amount = order.get("amount")
        order_currency = order.get("currency")
        order_timestamp = order.get("timestamp")

        candidates = []

        for payment_index, payment in enumerate(payments):
            if payment_index in used_payments:
                continue

            if payment.get("amount", 0) < 0:
                continue
            if payment.get("order_id") != order_id:
                continue
            if payment.get("amount") != order_amount:
                continue
            if payment.get("currency") != order_currency:
                continue

            payment_timestamp = payment.get("timestamp")
            if not isinstance(order_timestamp, datetime):
                continue
            if not isinstance(payment_timestamp, datetime):
                continue

            try:
                window_end = order_timestamp + timedelta(hours=72)
                qualifies = (
                    order_timestamp
                    <= payment_timestamp
                    < window_end
                )
            except (TypeError, ValueError, OverflowError):
                continue

            if qualifies:
                candidates.append(
                    (payment_timestamp, payment_index, payment)
                )

        if not candidates:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })
            continue

        try:
            _, payment_index, payment = min(
                candidates,
                key=lambda item: (item[0], item[1]),
            )
        except TypeError:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })
            continue

        used_payments.add(payment_index)
        results.append({
            "order_id": order_id,
            "status": "matched",
            "amount": payment.get("amount"),
        })

    return results


def compute_refunds(records):
    """Return the total value of valid refunds in cents."""
    if not isinstance(records, list):
        return 0

    existing_order_ids = {
        record.get("order_id")
        for record in records
        if (
            isinstance(record, dict)
            and record.get("type") == "ORDER"
        )
    }

    total = 0

    for record in records:
        if not isinstance(record, dict):
            continue

        if (
            record.get("type") == "PAYMENT"
            and record.get("order_id") in existing_order_ids
            and isinstance(record.get("amount"), int)
            and record["amount"] < 0
        ):
            total += -record["amount"]

    return total


def build_summary(matches, refund_total):
    """Build the five required aggregate reconciliation values."""
    if not isinstance(matches, list):
        matches = []

    matched_count = 0
    matched_total = 0
    unmatched_ids = set()

    for match in matches:
        if not isinstance(match, dict):
            continue

        if match.get("status") == "matched":
            matched_count += 1
            amount = match.get("amount")
            if isinstance(amount, int):
                matched_total += amount

        if match.get("status") == "unmatched":
            order_id = match.get("order_id")
            if isinstance(order_id, str):
                unmatched_ids.add(order_id)

    if not isinstance(refund_total, int):
        refund_total = 0

    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "refund_total": refund_total,
        "net_total": max(0, matched_total - refund_total),
        "unmatched_ids": sorted(unmatched_ids),
    }

