"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str) or not s:
        return None
    negative = s.startswith("-")
    value = s[1:] if negative else s
    if not value:
        return None
    parts = value.split(".")
    if len(parts) > 2 or not parts[0]:
        return None
    if any(c not in "0123456789" for c in parts[0]):
        return None
    fraction = parts[1] if len(parts) == 2 else ""
    if len(parts) == 2 and not fraction:
        return None
    if len(fraction) > 3 or any(c not in "0123456789" for c in fraction):
        return None
    try:
        amount = Decimal("-" + value if negative else value)
        cents = int((amount * Decimal("100")).quantize(
            Decimal("1"), rounding=ROUND_HALF_UP
        ))
    except (InvalidOperation, ValueError):
        return None
    if abs(cents) > 1000000:
        return None
    return cents


def parse_record(line):
    if not isinstance(line, str):
        return None
    fields = line.split("|")
    if len(fields) != 6:
        return None
    record_type, record_id, order_id, amount_text, currency, timestamp_text = fields
    record_type = record_type.upper()
    record_id = record_id.strip()
    order_id = order_id.strip()
    if record_type not in ("ORDER", "PAYMENT"):
        return None
    if not record_id or not order_id or not order_id.startswith("ORD-"):
        return None
    if currency != "USD":
        return None
    amount = parse_amount(amount_text)
    if amount is None or (record_type == "ORDER" and amount < 0):
        return None
    if len(timestamp_text) == 16:
        timestamp_format = "%Y-%m-%d %H:%M"
    elif len(timestamp_text) == 19:
        timestamp_format = "%Y-%m-%d %H:%M:%S"
    else:
        return None
    try:
        timestamp = datetime.strptime(timestamp_text, timestamp_format)
    except (TypeError, ValueError):
        return None
    if timestamp.strftime(timestamp_format) != timestamp_text:
        return None
    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []
    retained = []
    seen_ids = set()
    for line in text.splitlines():
        record = parse_record(line)
        if record is None or record["record_id"] in seen_ids:
            continue
        seen_ids.add(record["record_id"])
        retained.append(record)
    return retained


def match_payments(records):
    results = []
    if not isinstance(records, (list, tuple)):
        return results
    for order in records:
        if not isinstance(order, dict) or order.get("type") != "ORDER":
            continue
        order_id = order.get("order_id")
        order_time = order.get("timestamp")
        selected = None
        for payment in records:
            if not isinstance(payment, dict):
                continue
            if payment.get("type") != "PAYMENT":
                continue
            if payment.get("order_id") != order_id:
                continue
            amount = payment.get("amount")
            payment_time = payment.get("timestamp")
            if not isinstance(amount, int) or amount < 0:
                continue
            if not isinstance(payment_time, datetime) or not isinstance(order_time, datetime):
                continue
            if payment_time < order_time:
                continue
            if payment_time >= order_time + timedelta(hours=72):
                continue
            if selected is None or payment_time < selected["timestamp"]:
                selected = payment
        if selected is None:
            results.append({"order_id": order_id, "status": "unmatched", "amount": 0})
        else:
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": selected["amount"],
            })
    return results


def compute_refunds(records):
    if not isinstance(records, (list, tuple)):
        return 0
    order_ids = set()
    for record in records:
        if isinstance(record, dict) and record.get("type") == "ORDER":
            if isinstance(record.get("order_id"), str):
                order_ids.add(record["order_id"])
    total = 0
    for record in records:
        if not isinstance(record, dict):
            continue
        if record.get("type") != "PAYMENT":
            continue
        if record.get("currency") != "USD":
            continue
        if record.get("order_id") not in order_ids:
            continue
        amount = record.get("amount")
        if isinstance(amount, int) and amount < 0:
            total += -amount
    return total


def build_summary(matches, refund_total):
    if not isinstance(matches, (list, tuple)):
        matches = []
    total_orders = len(matches)
    matched_count = 0
    matched_total = 0
    unmatched = set()
    for result in matches:
        if not isinstance(result, dict):
            continue
        if result.get("status") == "matched":
            matched_count += 1
            amount = result.get("amount")
            if isinstance(amount, int):
                matched_total += amount
        elif result.get("status") == "unmatched":
            order_id = result.get("order_id")
            if isinstance(order_id, str):
                unmatched.add(order_id)
    if not isinstance(refund_total, int):
        refund_total = 0
    net_total = matched_total - refund_total
    if net_total < 0:
        net_total = 0
    return {
        "total_orders": total_orders,
        "matched_count": matched_count,
        "refund_total": refund_total,
        "net_total": net_total,
        "unmatched_ids": sorted(unmatched),
    }

