"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        if not isinstance(s, str):
            return None
        text = s.strip()
        if not text or text.startswith("+"):
            return None
        negative = text.startswith("-")
        digits = text[1:] if negative else text
        if not digits or any(not (c.isdigit() or c == ".") for c in digits):
            return None
        if digits.count(".") > 1:
            return None
        if "." in digits:
            whole, fraction = digits.split(".")
            if not whole and not fraction:
                return None
            if len(fraction) > 3:
                return None
        value = Decimal(text)
        if not value.is_finite():
            return None
        cents = int((value * Decimal("100")).quantize(
            Decimal("1"), rounding=ROUND_HALF_UP
        ))
        if abs(cents) > 1000000:
            return None
        return cents
    except (InvalidOperation, ValueError, TypeError, AttributeError):
        return None


def parse_record(line):
    try:
        if not isinstance(line, str):
            return None
        fields = line.split("|")
        if len(fields) != 6:
            return None
        kind, record_id, order_id, amount_text, currency, stamp = fields
        kind = kind.strip().upper()
        record_id = record_id.strip()
        order_id = order_id.strip()
        if kind not in ("ORDER", "PAYMENT"):
            return None
        if not record_id or not order_id.startswith("ORD-"):
            return None
        if currency != "USD":
            return None
        amount = parse_amount(amount_text)
        if amount is None or (kind == "ORDER" and amount < 0):
            return None
        parsed_time = None
        for fmt in ("%Y-%m-%d %H:%M", "%Y-%m-%d %H:%M:%S"):
            try:
                parsed_time = datetime.strptime(stamp, fmt)
                break
            except (TypeError, ValueError):
                pass
        if parsed_time is None:
            return None
        return {
            "type": kind,
            "record_id": record_id,
            "order_id": order_id,
            "amount": amount,
            "currency": currency,
            "timestamp": parsed_time,
        }
    except Exception:
        return None


def load_records(text):
    if not isinstance(text, str):
        return []
    records = []
    seen = set()
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None and record["record_id"] not in seen:
            seen.add(record["record_id"])
            records.append(record)
    return records


def match_payments(records):
    if not isinstance(records, list):
        return []
    orders = [
        record for record in records
        if isinstance(record, dict) and record.get("type") == "ORDER"
    ]
    results = []
    for order in orders:
        start = order.get("timestamp")
        best = None
        if isinstance(start, datetime):
            end = start + timedelta(hours=72)
            for payment in records:
                if not isinstance(payment, dict):
                    continue
                if payment.get("type") != "PAYMENT":
                    continue
                if payment.get("order_id") != order.get("order_id"):
                    continue
                amount = payment.get("amount")
                stamp = payment.get("timestamp")
                if not isinstance(amount, int) or amount < 0:
                    continue
                if not isinstance(stamp, datetime) or stamp < start or stamp >= end:
                    continue
                if best is None or stamp < best.get("timestamp"):
                    best = payment
        if best is None:
            results.append({
                "order_id": order.get("order_id"),
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order.get("order_id"),
                "status": "matched",
                "amount": best["amount"],
            })
    return results


def compute_refunds(records):
    if not isinstance(records, list):
        return 0
    order_ids = set()
    for record in records:
        if isinstance(record, dict) and record.get("type") == "ORDER":
            try:
                order_ids.add(record.get("order_id"))
            except TypeError:
                pass
    total = 0
    for record in records:
        if not isinstance(record, dict) or record.get("type") != "PAYMENT":
            continue
        amount = record.get("amount")
        if not isinstance(amount, int) or amount >= 0:
            continue
        try:
            if record.get("order_id") in order_ids:
                total += -amount
        except TypeError:
            continue
    return total


def build_summary(matches, refund_total):
    if not isinstance(matches, list):
        matches = []
    if not isinstance(refund_total, int):
        refund_total = 0
    matched_count = 0
    matched_total = 0
    unmatched = set()
    for result in matches:
        if not isinstance(result, dict):
            continue
        if result.get("status") == "matched":
            matched_count += 1
            amount = result.get("amount", 0)
            if isinstance(amount, int):
                matched_total += amount
        else:
            order_id = result.get("order_id")
            if isinstance(order_id, str):
                unmatched.add(order_id)
    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "refund_total": refund_total,
        "net_total": max(0, matched_total - refund_total),
        "unmatched_ids": sorted(unmatched),
    }

"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    """Convert a decimal amount to integer cents."""
    if not isinstance(s, str):
        return None

    text = s.strip()
    if not text:
        return None

    negative = text.startswith("-")
    digits = text[1:] if negative else text

    if not digits:
        return None
    if digits.count(".") > 1:
        return None

    if "." in digits:
        whole, fraction = digits.split(".")
        if not whole or not whole.isdigit():
            return None
        if not fraction or not fraction.isdigit():
            return None
        if len(fraction) > 3:
            return None
    else:
        whole = digits
        if not whole.isdigit():
            return None

    try:
        value = Decimal(text)
        cents = int(
            (value * Decimal("100")).quantize(
                Decimal("1"),
                rounding=ROUND_HALF_UP,
            )
        )
    except (InvalidOperation, ValueError, TypeError, OverflowError):
        return None

    if abs(cents) > 100_000_000:
        return None

    return -abs(cents) if negative else cents


def parse_record(line):
    """Parse one six-field record, or return None when it is invalid."""
    if not isinstance(line, str):
        return None

    parts = line.split("|")
    if len(parts) != 6:
        return None

    (
        record_type,
        record_id,
        order_id,
        amount_text,
        currency,
        timestamp_text,
    ) = (part.strip() for part in parts)

    record_type = record_type.upper()
    if record_type not in ("ORDER", "PAYMENT"):
        return None

    if not record_id or not order_id:
        return None

    if (
        len(currency) != 3
        or not currency.isascii()
        or not currency.isalpha()
        or currency != currency.upper()
    ):
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None

    if record_type == "ORDER" and amount < 0:
        return None

    timestamp = _parse_timestamp(timestamp_text)
    if timestamp is None:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    """Load valid records, retaining only the first valid record ID."""
    if not isinstance(text, str):
        return []

    records = []
    seen_ids = set()

    for line in text.splitlines():
        record = parse_record(line)
        if record is None:
            continue

        record_id = record["record_id"]
        if record_id in seen_ids:
            continue

        seen_ids.add(record_id)
        records.append(record)

    return records


def match_payments(records):
    """Return one matching result for each order in retained order."""
    if not isinstance(records, list):
        return []

    orders = []
    payments = []

    for source_index, record in enumerate(records):
        if not isinstance(record, dict):
            continue

        if record.get("type") == "ORDER":
            orders.append(record)
        elif (
            record.get("type") == "PAYMENT"
            and isinstance(record.get("amount"), int)
            and not isinstance(record.get("amount"), bool)
            and record["amount"] >= 0
        ):
            payments.append((source_index, record))

    results = []

    for order in orders:
        order_id = order.get("order_id")
        order_timestamp = order.get("timestamp")
        qualifying = []

        if order_timestamp is not None:
            end_timestamp = order_timestamp + timedelta(hours=72)

            for source_index, payment in payments:
                if payment.get("order_id") != order_id:
                    continue

                payment_timestamp = payment.get("timestamp")
                if payment_timestamp is None:
                    continue

                if order_timestamp <= payment_timestamp < end_timestamp:
                    qualifying.append(
                        (payment_timestamp, source_index, payment)
                    )

        if qualifying:
            _, _, payment = min(
                qualifying,
                key=lambda item: (item[0], item[1]),
            )
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": payment["amount"],
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })

    return results


def compute_refunds(records):
    """Return the positive total of qualifying negative payments."""
    if not isinstance(records, list):
        return 0

    order_ids = {
        record.get("order_id")
        for record in records
        if isinstance(record, dict) and record.get("type") == "ORDER"
    }

    total = 0

    for record in records:
        if not isinstance(record, dict):
            continue

        amount = record.get("amount")
        if (
            record.get("type") == "PAYMENT"
            and record.get("order_id") in order_ids
            and isinstance(amount, int)
            and not isinstance(amount, bool)
            and amount < 0
        ):
            total += -amount

    return total


def build_summary(matches, refund_total):
    """Build the reconciliation summary."""
    if not isinstance(matches, list):
        matches = []

    if not isinstance(refund_total, int) or isinstance(refund_total, bool):
        refund_total = 0

    total_orders = 0
    matched_count = 0
    matched_total = 0
    unmatched_ids = set()

    for result in matches:
        if not isinstance(result, dict):
            continue

        total_orders += 1

        if result.get("status") == "matched":
            matched_count += 1
            amount = result.get("amount")
            if isinstance(amount, int) and not isinstance(amount, bool):
                matched_total += amount
        else:
            order_id = result.get("order_id")
            if isinstance(order_id, str):
                unmatched_ids.add(order_id)

    return {
        "total_orders": total_orders,
        "matched_count": matched_count,
        "refund_total": refund_total,
        "net_total": max(0, matched_total - refund_total),
        "unmatched_ids": sorted(unmatched_ids),
    }

