from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str):
        return None
    value = s.strip()
    if not value or value.startswith("+"):
        return None
    negative = value.startswith("-")
    digits = value[1:] if negative else value
    if not digits or "e" in digits.lower() or digits.count(".") > 1:
        return None
    parts = digits.split(".")
    if not parts[0] and not (len(parts) == 2 and parts[1]):
        return None
    if len(parts) == 2 and len(parts[1]) > 3:
        return None
    if not all(part.isdigit() for part in parts if part):
        return None
    try:
        amount = Decimal(value)
        if not amount.is_finite():
            return None
        cents = int((amount * Decimal("100")).quantize(
            Decimal("1"), rounding=ROUND_HALF_UP
        ))
        if abs(cents) > 1000000:
            return None
        return cents
    except (InvalidOperation, ValueError, TypeError, OverflowError):
        return None


def parse_record(line):
    if not isinstance(line, str):
        return None
    fields = line.split("|")
    if len(fields) != 6:
        return None
    kind, record_id, order_id, amount, currency, timestamp = fields
    kind = kind.strip().upper()
    record_id = record_id.strip()
    order_id = order_id.strip()
    if kind not in ("ORDER", "PAYMENT"):
        return None
    if not record_id or not order_id.startswith("ORD-"):
        return None
    if currency != "USD":
        return None
    cents = parse_amount(amount)
    if cents is None or (kind == "ORDER" and cents < 0):
        return None
    parsed_time = None
    for fmt in ("%Y-%m-%d %H:%M", "%Y-%m-%d %H:%M:%S"):
        try:
            parsed_time = datetime.strptime(timestamp, fmt)
            break
        except (TypeError, ValueError):
            pass
    if parsed_time is None:
        return None
    return {
        "type": kind,
        "record_id": record_id,
        "order_id": order_id,
        "amount": cents,
        "currency": currency,
        "timestamp": parsed_time,
    }


def load_records(text):
    if not isinstance(text, str):
        return []
    records = []
    seen = set()
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None and record["record_id"] not in seen:
            seen.add(record["record_id"])
            records.append(record)
    return records


def match_payments(records):
    if not isinstance(records, list):
        return []
    orders = [
        record for record in records
        if isinstance(record, dict) and record.get("type") == "ORDER"
    ]
    results = []
    for order in orders:
        order_id = order.get("order_id")
        order_time = order.get("timestamp")
        chosen = None
        for payment in records:
            if not isinstance(payment, dict):
                continue
            if payment.get("type") != "PAYMENT":
                continue
            if payment.get("order_id") != order_id:
                continue
            amount = payment.get("amount")
            payment_time = payment.get("timestamp")
            if not isinstance(amount, int) or amount < 0:
                continue
            if (isinstance(order_time, datetime)
                    and isinstance(payment_time, datetime)
                    and order_time <= payment_time
                    < order_time + timedelta(hours=72)):
                if chosen is None or payment_time < chosen.get("timestamp"):
                    chosen = payment
        if chosen is not None and chosen.get("amount") == order.get("amount"):
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": chosen.get("amount"),
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })
    return results


def compute_refunds(records):
    if not isinstance(records, list):
        return 0
    order_ids = {
        record.get("order_id")
        for record in records
        if isinstance(record, dict) and record.get("type") == "ORDER"
    }
    return sum(
        -record["amount"]
        for record in records
        if isinstance(record, dict)
        and record.get("type") == "PAYMENT"
        and record.get("order_id") in order_ids
        and isinstance(record.get("amount"), int)
        and record["amount"] < 0
    )


def build_summary(matches, refund_total):
    if not isinstance(matches, list):
        matches = []
    if not isinstance(refund_total, int):
        refund_total = 0
    matched = [
        item for item in matches
        if isinstance(item, dict) and item.get("status") == "matched"
    ]
    unmatched_ids = sorted({
        item.get("order_id")
        for item in matches
        if isinstance(item, dict)
        and item.get("status") != "matched"
        and isinstance(item.get("order_id"), str)
    })
    paid_total = sum(
        item.get("amount", 0) for item in matched
        if isinstance(item.get("amount"), int)
    )
    return {
        "total_orders": len(matches),
        "matched_count": len(matched),
        "refund_total": refund_total,
        "net_total": max(0, paid_total - refund_total),
        "unmatched_ids": unmatched_ids,
    }

