from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    """Convert a decimal amount to integer cents, or return None."""
    if not isinstance(s, str):
        return None

    text = s.strip()
    if not text or not _AMOUNT_PATTERN.fullmatch(text):
        return None

    try:
        value = Decimal(text)
        with localcontext() as context:
            context.prec = max(50, len(text) + 10)
            rounded = value.quantize(_CENT, rounding=ROUND_HALF_UP)

        cents = int(rounded * 100)
        if abs(cents) > _MAX_CENTS:
            return None
        return cents
    except (InvalidOperation, ValueError, TypeError, OverflowError):
        return None


def parse_record(line):
    """Parse one pipe-separated order or payment record."""
    if not isinstance(line, str):
        return None

    parts = line.strip().split("|")
    if len(parts) != 6:
        return None

    (
        record_type,
        record_id,
        order_id,
        amount_text,
        currency,
        timestamp,
    ) = (part.strip() for part in parts)

    record_type = record_type.upper()
    if record_type not in ("ORDER", "PAYMENT"):
        return None

    if not record_id or not order_id:
        return None

    if any(character.isspace() for character in record_id + order_id):
        return None

    if not _CURRENCY_PATTERN.fullmatch(currency):
        return None

    if _parse_timestamp(timestamp) is None:
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None

    if record_type == "ORDER" and amount < 0:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    """Load valid records, retaining only the first valid record ID."""
    if not isinstance(text, str):
        return []

    records = []
    seen_record_ids = set()

    for line in text.splitlines():
        record = parse_record(line)
        if record is None:
            continue

        record_id = record["record_id"]
        if record_id in seen_record_ids:
            continue

        seen_record_ids.add(record_id)
        records.append(record)

    return records


def match_payments(records):
    """Match each order with the earliest qualifying payment."""
    if not isinstance(records, list):
        return []

    orders = [
        record
        for record in records
        if isinstance(record, dict)
        and record.get("type") == "ORDER"
    ]

    payments = [
        (index, record)
        for index, record in enumerate(records)
        if (
            isinstance(record, dict)
            and record.get("type") == "PAYMENT"
            and isinstance(record.get("amount"), int)
            and not isinstance(record.get("amount"), bool)
            and record.get("amount") >= 0
        )
    ]

    results = []

    for order in orders:
        order_timestamp = _parse_timestamp(order.get("timestamp"))
        candidates = []

        if order_timestamp is not None:
            order_timestamp = _timestamp_for_comparison(order_timestamp)
            end_timestamp = order_timestamp + timedelta(hours=72)

            for source_index, payment in payments:
                if payment.get("order_id") != order.get("order_id"):
                    continue
                if payment.get("amount") != order.get("amount"):
                    continue
                if payment.get("currency") != order.get("currency"):
                    continue

                payment_timestamp = _parse_timestamp(
                    payment.get("timestamp")
                )
                if payment_timestamp is None:
                    continue

                payment_timestamp = _timestamp_for_comparison(
                    payment_timestamp
                )

                try:
                    in_window = (
                        order_timestamp
                        <= payment_timestamp
                        < end_timestamp
                    )
                except TypeError:
                    continue

                if not in_window:
                    continue

                candidates.append(
                    (payment_timestamp, source_index, payment)
                )

        if candidates:
            _, _, payment = min(
                candidates,
                key=lambda item: (item[0], item[1]),
            )
            results.append(
                {
                    "order_id": order.get("order_id"),
                    "status": "matched",
                    "amount": payment.get("amount"),
                }
            )
        else:
            results.append(
                {
                    "order_id": order.get("order_id"),
                    "status": "unmatched",
                    "amount": 0,
                }
            )

    return results


def compute_refunds(records):
    """Return cents refunded by payments belonging to existing orders."""
    if not isinstance(records, list):
        return 0

    order_ids = {
        record.get("order_id")
        for record in records
        if isinstance(record, dict)
        and record.get("type") == "ORDER"
    }

    refund_total = 0

    for record in records:
        if not isinstance(record, dict):
            continue
        if record.get("type") != "PAYMENT":
            continue
        if record.get("order_id") not in order_ids:
            continue

        amount = record.get("amount")
        if (
            isinstance(amount, int)
            and not isinstance(amount, bool)
            and amount < 0
        ):
            refund_total += -amount

    return refund_total


def build_summary(matches, refund_total):
    """Build a five-field reconciliation summary."""
    if not isinstance(matches, list):
        matches = []

    matched_count = 0
    matched_total = 0
    unmatched_ids = set()

    for match in matches:
        if not isinstance(match, dict):
            continue

        if match.get("status") == "matched":
            matched_count += 1
            amount = match.get("amount")
            if isinstance(amount, int) and not isinstance(amount, bool):
                matched_total += amount
        else:
            order_id = match.get("order_id")
            if isinstance(order_id, str):
                unmatched_ids.add(order_id)

    if not isinstance(refund_total, int) or isinstance(refund_total, bool):
        refund_total = 0

    net_total = matched_total - refund_total
    if net_total < 0:
        net_total = 0

    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "refund_total": refund_total,
        "net_total": net_total,
        "unmatched_ids": sorted(unmatched_ids),
    }

