from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str) or s == "":
        return None

    negative = s.startswith("-")
    value = s[1:] if negative else s

    if value == "" or value.count(".") > 1:
        return None

    if "." in value:
        whole_part, fraction_part = value.split(".")
        if whole_part == "" or fraction_part == "":
            return None
    else:
        whole_part = value
        fraction_part = ""

    if not all("0" <= char <= "9" for char in whole_part):
        return None
    if not all("0" <= char <= "9" for char in fraction_part):
        return None
    if len(fraction_part) > 3:
        return None

    try:
        whole_cents = int(whole_part) * 100
    except (TypeError, ValueError, OverflowError):
        return None

    cents = whole_cents + int(fraction_part.ljust(2, "0")[:2])

    if len(fraction_part) == 3 and fraction_part[2] >= "5":
        cents += 1

    if negative:
        cents = -cents

    if abs(cents) > 1_000_000:
        return None

    return cents


def parse_record(line):
    if not isinstance(line, str):
        return None

    try:
        fields = line.split("|")
        if len(fields) != 6:
            return None

        record_type, record_id, order_id, amount_text, currency, timestamp_text = fields

        record_type = record_type.upper()
        if record_type not in ("ORDER", "PAYMENT"):
            return None

        record_id = record_id.strip()
        order_id = order_id.strip()

        if record_id == "" or order_id == "":
            return None
        if not order_id.startswith("ORD-"):
            return None
        if currency != "USD":
            return None

        amount = parse_amount(amount_text)
        if amount is None:
            return None
        if record_type == "ORDER" and amount < 0:
            return None

        if len(timestamp_text) == 16:
            timestamp_format = "%Y-%m-%d %H:%M"
            separators = (4, 7, 10, 13)
        elif len(timestamp_text) == 19:
            timestamp_format = "%Y-%m-%d %H:%M:%S"
            separators = (4, 7, 10, 13, 16)
        else:
            return None

        expected_separators = {
            4: "-",
            7: "-",
            10: " ",
            13: ":",
        }
        if len(timestamp_text) == 19:
            expected_separators[16] = ":"

        for position, separator in expected_separators.items():
            if timestamp_text[position] != separator:
                return None

        for index, character in enumerate(timestamp_text):
            if index not in separators and not character.isdigit():
                return None

        timestamp = datetime.strptime(timestamp_text, timestamp_format)

        return {
            "type": record_type,
            "record_id": record_id,
            "order_id": order_id,
            "amount": amount,
            "currency": currency,
            "timestamp": timestamp,
        }
    except (TypeError, ValueError, OverflowError):
        return None


def load_records(text):
    if not isinstance(text, str):
        return []

    retained = []
    seen_record_ids = set()

    for line in text.splitlines():
        try:
            record = parse_record(line)
        except Exception:
            record = None

        if record is None:
            continue

        record_id = record["record_id"]
        if record_id in seen_record_ids:
            continue

        seen_record_ids.add(record_id)
        retained.append(record)

    return retained


def match_payments(records):
    results = []

    for order in records:
        if order["type"] != "ORDER":
            continue

        order_timestamp = order["timestamp"]
        end_timestamp = order_timestamp + timedelta(hours=72)
        selected_payment = None
        selected_key = None

        for source_index, payment in enumerate(records):
            if payment["type"] != "PAYMENT":
                continue
            if payment["order_id"] != order["order_id"]:
                continue
            if payment["amount"] < 0:
                continue
            if payment["timestamp"] < order_timestamp:
                continue
            if payment["timestamp"] >= end_timestamp:
                continue

            candidate_key = (payment["timestamp"], source_index)
            if selected_key is None or candidate_key < selected_key:
                selected_payment = payment
                selected_key = candidate_key

        if selected_payment is None:
            results.append({
                "order_id": order["order_id"],
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order["order_id"],
                "status": "matched",
                "amount": selected_payment["amount"],
            })

    return results


def compute_refunds(records):
    """Return qualifying refund amounts in integer cents."""
    try:
        existing_order_ids = set()

        for record in records:
            if not isinstance(record, dict):
                continue
            if record.get("type") == "ORDER":
                order_id = record.get("order_id")
                if isinstance(order_id, str):
                    existing_order_ids.add(order_id)

        refund_total = 0

        for record in records:
            if not isinstance(record, dict):
                continue
            if record.get("type") != "PAYMENT":
                continue
            if record.get("currency") != "USD":
                continue

            order_id = record.get("order_id")
            amount = record.get("amount")

            if order_id not in existing_order_ids:
                continue
            if not isinstance(amount, int) or isinstance(amount, bool):
                continue
            if amount < 0:
                refund_total += abs(amount)

        return refund_total
    except Exception:
        return 0


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = 0
    matched_total = 0
    unmatched_ids = set()

    for result in matches:
        if not isinstance(result, dict):
            continue

        status = result.get("status")

        if status == "matched":
            matched_count += 1
            amount = result.get("amount")
            if isinstance(amount, int) and not isinstance(amount, bool):
                matched_total += amount
        elif status == "unmatched":
            order_id = result.get("order_id")
            if isinstance(order_id, str):
                unmatched_ids.add(order_id)

    net_total = matched_total - refund_total
    if net_total < 0:
        net_total = 0

    return {
        "total_orders": total_orders,
        "matched_count": matched_count,
        "refund_total": refund_total,
        "net_total": net_total,
        "unmatched_ids": sorted(unmatched_ids),
    }

