"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str):
        return None
    value = s.strip()
    if not value:
        return None
    body = value[1:] if value.startswith("-") else value
    if not body:
        return None
    if body.count(".") > 1:
        return None
    if "." in body:
        whole, fraction = body.split(".")
        if not whole or not whole.isdigit() or not fraction.isdigit():
            return None
        if len(fraction) > 3:
            return None
    elif not body.isdigit():
        return None
    try:
        cents = (Decimal(value) * Decimal("100")).quantize(
            Decimal("1"), rounding=ROUND_HALF_UP
        )
        result = int(cents)
    except (InvalidOperation, ValueError, TypeError, OverflowError):
        return None
    if abs(result) > 1000000:
        return None
    return result


def parse_record(line):
    if not isinstance(line, str):
        return None
    parts = line.split("|")
    if len(parts) != 6:
        return None
    record_type, record_id, order_id, amount_text, currency, timestamp = (
        part.strip() for part in parts
    )
    record_type = record_type.upper()
    if record_type not in ("ORDER", "PAYMENT"):
        return None
    if not record_id or not order_id or currency != "USD":
        return None
    amount = parse_amount(amount_text)
    if amount is None or (record_type == "ORDER" and amount < 0):
        return None
    parsed = None
    for fmt in ("%Y-%m-%d %H:%M", "%Y-%m-%d %H:%M:%S"):
        try:
            candidate = datetime.strptime(timestamp, fmt)
            if candidate.strftime(fmt) == timestamp:
                parsed = candidate
                break
        except (ValueError, TypeError):
            continue
    if parsed is None:
        return None
    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []
    records = []
    seen = set()
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None and record["record_id"] not in seen:
            seen.add(record["record_id"])
            records.append(record)
    return records


def match_payments(records):
    if not isinstance(records, list):
        return []
    orders = []
    seen_orders = set()
    for record in records:
        if (
            isinstance(record, dict)
            and record.get("type") == "ORDER"
            and record.get("currency") == "USD"
            and isinstance(record.get("order_id"), str)
            and record["order_id"]
            and record["order_id"] not in seen_orders
            and isinstance(record.get("amount"), int)
            and record["amount"] >= 0
            and _record_datetime(record) is not None
        ):
            orders.append(record)
            seen_orders.add(record["order_id"])

    results = []
    for order in orders:
        start = _record_datetime(order)
        end = start + timedelta(hours=72)
        chosen = None
        chosen_time = None
        for payment in records:
            if (
                not isinstance(payment, dict)
                or payment.get("type") != "PAYMENT"
                or payment.get("currency") != "USD"
                or payment.get("order_id") != order["order_id"]
                or payment.get("amount") != order["amount"]
                or not isinstance(payment.get("amount"), int)
                or payment["amount"] < 0
            ):
                continue
            payment_time = _record_datetime(payment)
            if payment_time is None or not (start <= payment_time < end):
                continue
            if chosen_time is None or payment_time < chosen_time:
                chosen = payment
                chosen_time = payment_time
        if chosen is None:
            results.append({
                "order_id": order["order_id"],
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order["order_id"],
                "status": "matched",
                "amount": chosen["amount"],
            })
    return results


def compute_refunds(records):
    if not isinstance(records, list):
        return 0
    order_ids = {
        record.get("order_id")
        for record in records
        if (
            isinstance(record, dict)
            and record.get("type") == "ORDER"
            and record.get("currency") == "USD"
            and isinstance(record.get("order_id"), str)
            and record["order_id"]
        )
    }
    total = 0
    for record in records:
        if (
            isinstance(record, dict)
            and record.get("type") == "PAYMENT"
            and record.get("currency") == "USD"
            and record.get("order_id") in order_ids
            and isinstance(record.get("amount"), int)
            and record["amount"] < 0
        ):
            total -= record["amount"]
    return total


def build_summary(matches, refund_total):
    if not isinstance(matches, list):
        matches = []
    if not isinstance(refund_total, int):
        refund_total = 0
    matched_count = 0
    matched_total = 0
    unmatched_ids = []
    for match in matches:
        if not isinstance(match, dict):
            continue
        if match.get("status") == "matched":
            matched_count += 1
            if isinstance(match.get("amount"), int):
                matched_total += match["amount"]
        elif match.get("status") == "unmatched":
            order_id = match.get("order_id")
            if isinstance(order_id, str) and order_id not in unmatched_ids:
                unmatched_ids.append(order_id)
    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "refund_total": refund_total,
        "net_total": max(0, matched_total - refund_total),
        "unmatched_ids": sorted(unmatched_ids),
    }

"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str) or not s.strip():
        return None

    try:
        # Convert to Decimal
        amount = Decimal(s)
    except (InvalidOperation, ValueError):
        return None

    # Check for scientific notation or malformed input
    if 'e' in s.lower() or 'E' in s:
        return None

    # Round to 3 decimal places
    amount = amount.quantize(Decimal('0.001'), rounding=ROUND_HALF_UP)

    # Convert to cents
    cents = int(amount * 100)

    # Check for negative values and the absolute limit
    if cents < -1000000 or cents > 1000000:
        return None

    return cents


def parse_record(line):
    fields = line.strip().split('|')

    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount_str, currency, timestamp_str = fields

    # Validate TYPE
    record_type = record_type.strip().upper()
    if record_type not in ['ORDER', 'PAYMENT']:
        return None

    # Validate RECORD_ID and ORDER_ID
    record_id = record_id.strip()
    order_id = order_id.strip()
    if not record_id or not order_id.startswith('ORD-'):
        return None

    # Validate CURRENCY
    if currency.strip() != 'USD':
        return None

    # Parse AMOUNT
    amount = parse_amount(amount_str.strip())
    if amount is None or (record_type == 'ORDER' and amount < 0):
        return None

    # Validate TIMESTAMP
    try:
        timestamp = datetime.strptime(timestamp_str.strip(), '%Y-%m-%d %H:%M:%S')
    except ValueError:
        try:
            timestamp = datetime.strptime(timestamp_str.strip(), '%Y-%m-%d %H:%M')
        except ValueError:
            return None

    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount,
        'currency': currency.strip(),
        'timestamp': timestamp
    }


def load_records(text):
    records = []
    seen_record_ids = set()

    for line in text.strip().splitlines():
        record = parse_record(line)
        if record and record['record_id'] not in seen_record_ids:
            records.append(record)
            seen_record_ids.add(record['record_id'])

    return records


def match_payments(records):
    orders = [record for record in records if record['type'] == 'ORDER']
    payments = [record for record in records if record['type'] == 'PAYMENT' and record['amount'] >= 0]

    results = []

    for order in orders:
        order_id = order['order_id']
        order_timestamp = order['timestamp']
        end_time = order_timestamp + timedelta(hours=72)

        # Filter payments that match the order_id and are within the time frame
        qualifying_payments = [
            payment for payment in payments
            if payment['order_id'] == order_id and order_timestamp <= payment['timestamp'] < end_time
        ]

        if qualifying_payments:
            # Sort by timestamp, then by record_id
            qualifying_payments.sort(key=lambda p: (p['timestamp'], p['record_id']))
            selected_payment = qualifying_payments[0]
            results.append({
                'order_id': order_id,
                'status': 'matched',
                'amount': selected_payment['amount']
            })
        else:
            results.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': 0
            })

    return results


def compute_refunds(records):
    refund_total = 0

    # Create a set of valid order_ids from the records
    valid_order_ids = {record['order_id'] for record in records if record['type'] == 'ORDER'}

    # Iterate through records to find qualifying refunds
    for record in records:
        if record['type'] == 'PAYMENT' and record['amount'] < 0 and record['order_id'] in valid_order_ids:
            refund_total += abs(record['amount'])

    return refund_total


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = max(sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total, 0)
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] == 'unmatched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

