"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str) or s == "":
        return None

    negative = s.startswith("-")
    value = s[1:] if negative else s
    if value == "" or value.count(".") > 1:
        return None

    parts = value.split(".")
    whole = parts[0]
    fraction = parts[1] if len(parts) == 2 else ""

    if not whole or any(ch < "0" or ch > "9" for ch in whole):
        return None
    if any(ch < "0" or ch > "9" for ch in fraction):
        return None
    if len(fraction) > 3:
        return None

    try:
        amount = Decimal(s).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
    except (InvalidOperation, ValueError):
        return None

    cents = int(amount * 100)
    if abs(cents) > 1000000:
        return None
    return cents


def parse_record(line):
    if not isinstance(line, str):
        return None
    try:
        fields = line.split("|")
        if len(fields) != 6:
            return None

        type_value, record_id, order_id, amount_text, currency, timestamp_text = fields
        type_value = type_value.upper()
        record_id = record_id.strip()
        order_id = order_id.strip()

        if type_value not in ("ORDER", "PAYMENT"):
            return None
        if not record_id or not order_id.startswith("ORD-"):
            return None
        if currency != "USD":
            return None

        amount = parse_amount(amount_text)
        if amount is None or (type_value == "ORDER" and amount < 0):
            return None

        if len(timestamp_text) == 16:
            timestamp_format = "%Y-%m-%d %H:%M"
        elif len(timestamp_text) == 19:
            timestamp_format = "%Y-%m-%d %H:%M:%S"
        else:
            return None

        timestamp = datetime.strptime(timestamp_text, timestamp_format)
        if timestamp.strftime(timestamp_format) != timestamp_text:
            return None

        return {
            "type": type_value,
            "record_id": record_id,
            "order_id": order_id,
            "amount": amount,
            "currency": currency,
            "timestamp": timestamp,
        }
    except Exception:
        return None


def load_records(text):
    if not isinstance(text, str):
        return []

    retained = []
    seen_ids = set()

    for line in text.splitlines():
        record = parse_record(line)
        if record is None:
            continue
        record_id = record["record_id"]
        if record_id in seen_ids:
            continue
        seen_ids.add(record_id)
        retained.append(record)

    return retained


def match_payments(records):
    if not isinstance(records, list):
        return []

    results = []
    for order in records:
        if not isinstance(order, dict) or order.get("type") != "ORDER":
            continue

        order_id = order.get("order_id")
        order_time = order.get("timestamp")
        selected = None

        for payment in records:
            if not isinstance(payment, dict):
                continue
            if payment.get("type") != "PAYMENT":
                continue
            if payment.get("order_id") != order_id:
                continue
            amount = payment.get("amount")
            payment_time = payment.get("timestamp")
            if not isinstance(amount, int) or amount < 0:
                continue
            if payment_time < order_time:
                continue
            if payment_time >= order_time + timedelta(hours=72):
                continue
            if selected is None or payment_time < selected.get("timestamp"):
                selected = payment

        if selected is None:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": selected["amount"],
            })

    return results


def compute_refunds(records):
    if not isinstance(records, list):
        return 0

    order_ids = set()
    for record in records:
        if not isinstance(record, dict):
            continue
        if (record.get("type") == "ORDER"
                and record.get("currency") == "USD"):
            order_ids.add(record.get("order_id"))

    total = 0
    for record in records:
        if not isinstance(record, dict):
            continue
        if (record.get("type") == "PAYMENT"
                and record.get("currency") == "USD"
                and isinstance(record.get("amount"), int)
                and record.get("amount") < 0
                and record.get("order_id") in order_ids):
            total += abs(record["amount"])

    return total


def build_summary(matches, refund_total):
    if not isinstance(matches, list):
        matches = []

    matched_count = 0
    matched_total = 0
    unmatched_ids = set()

    for result in matches:
        if not isinstance(result, dict):
            continue
        if result.get("status") == "matched":
            matched_count += 1
            amount = result.get("amount")
            if isinstance(amount, int):
                matched_total += amount
        elif result.get("status") == "unmatched":
            unmatched_ids.add(result.get("order_id"))

    net_total = matched_total - refund_total
    if net_total < 0:
        net_total = 0

    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "refund_total": refund_total,
        "net_total": net_total,
        "unmatched_ids": sorted(unmatched_ids),
    }

"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str) or not s.strip():
        return None

    try:
        # Convert to Decimal
        amount = Decimal(s)
    except (InvalidOperation, ValueError):
        return None

    # Check for scientific notation or too many decimal places
    if 'e' in s.lower() or amount.as_tuple().exponent < -3:
        return None

    # Round to cents using round-half-up
    amount = amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)

    # Convert to integer cents
    cents = int(amount * 100)

    # Check for absolute value limit
    if abs(cents) > 1000000:
        return None

    return cents


def parse_record(line):
    fields = line.strip().split('|')

    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount_str, currency, timestamp_str = fields

    # Validate TYPE
    record_type = record_type.strip().upper()
    if record_type not in ['ORDER', 'PAYMENT']:
        return None

    # Validate RECORD_ID and ORDER_ID
    record_id = record_id.strip()
    order_id = order_id.strip()
    if not record_id or not order_id.startswith('ORD-'):
        return None

    # Validate CURRENCY
    if currency.strip() != 'USD':
        return None

    # Parse amount
    amount = parse_amount(amount_str.strip())
    if amount is None or (record_type == 'ORDER' and amount < 0):
        return None

    # Validate TIMESTAMP
    try:
        if len(timestamp_str) == 16:  # YYYY-MM-DD HH:MM
            timestamp = datetime.strptime(timestamp_str, '%Y-%m-%d %H:%M')
        elif len(timestamp_str) == 19:  # YYYY-MM-DD HH:MM:SS
            timestamp = datetime.strptime(timestamp_str, '%Y-%m-%d %H:%M:%S')
        else:
            return None
    except ValueError:
        return None

    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount,
        'currency': currency.strip(),
        'timestamp': timestamp
    }


def load_records(text):
    records = []
    seen_record_ids = set()

    for line in text.strip().splitlines():
        record = parse_record(line)
        if record and record['record_id'] not in seen_record_ids:
            records.append(record)
            seen_record_ids.add(record['record_id'])

    return records


def match_payments(records):
    orders = [record for record in records if record['type'] == 'ORDER']
    payments = [record for record in records if record['type'] == 'PAYMENT' and record['currency'] == 'USD' and record['amount'] >= 0]

    results = []

    for order in orders:
        order_id = order['order_id']
        order_timestamp = order['timestamp']
        valid_payments = [
            payment for payment in payments
            if payment['order_id'] == order_id and order_timestamp <= payment['timestamp'] < order_timestamp + timedelta(hours=72)
        ]

        if valid_payments:
            # Sort by timestamp, then by record_id
            valid_payments.sort(key=lambda p: (p['timestamp'], p['record_id']))
            selected_payment = valid_payments[0]
            results.append({
                'order_id': order_id,
                'status': 'matched',
                'amount': selected_payment['amount']
            })
        else:
            results.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': 0
            })

    return results


def compute_refunds(records):
    order_ids = {record['order_id'] for record in records if record['type'] == 'ORDER'}
    refund_total = 0

    for record in records:
        if record['type'] == 'PAYMENT' and record['currency'] == 'USD' and record['amount'] < 0:
            if record['order_id'] in order_ids:
                refund_total += abs(record['amount'])

    return refund_total


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = max(sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total, 0)
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] == 'unmatched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

