from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str) or s == "":
        return None

    text = s
    if text.startswith("-"):
        text = text[1:]

    if text == "" or text.count(".") > 1:
        return None

    parts = text.split(".")
    whole = parts[0]
    fraction = parts[1] if len(parts) == 2 else ""

    if not whole or any(char not in "0123456789" for char in whole):
        return None
    if len(fraction) > 3:
        return None
    if any(char not in "0123456789" for char in fraction):
        return None

    try:
        amount = Decimal(s).quantize(
            Decimal("0.01"),
            rounding=ROUND_HALF_UP
        )
    except (InvalidOperation, ValueError):
        return None

    cents = int(amount * 100)
    if abs(cents) > 1_000_000:
        return None

    return cents


def parse_record(line):
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount_text, currency, timestamp_text = fields

    record_type = record_type.upper()
    if record_type not in ("ORDER", "PAYMENT"):
        return None

    record_id = record_id.strip()
    order_id = order_id.strip()

    if not record_id or not order_id.startswith("ORD-"):
        return None

    if currency != "USD":
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None

    if record_type == "ORDER" and amount < 0:
        return None

    if len(timestamp_text) == 16:
        if (
            timestamp_text[4] != "-"
            or timestamp_text[7] != "-"
            or timestamp_text[10] != " "
            or timestamp_text[13] != ":"
        ):
            return None
        timestamp_format = "%Y-%m-%d %H:%M"
    elif len(timestamp_text) == 19:
        if (
            timestamp_text[4] != "-"
            or timestamp_text[7] != "-"
            or timestamp_text[10] != " "
            or timestamp_text[13] != ":"
            or timestamp_text[16] != ":"
        ):
            return None
        timestamp_format = "%Y-%m-%d %H:%M:%S"
    else:
        return None

    digit_positions = [
        index
        for index, character in enumerate(timestamp_text)
        if index not in (4, 7, 10, 13, 16)
    ]
    if any(not timestamp_text[index].isdigit() for index in digit_positions):
        return None

    try:
        timestamp = datetime.strptime(timestamp_text, timestamp_format)
    except (TypeError, ValueError):
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []

    records = []
    seen_record_ids = set()

    for line in text.splitlines():
        try:
            record = parse_record(line)
        except Exception:
            record = None

        if record is None:
            continue

        record_id = record["record_id"]
        if record_id in seen_record_ids:
            continue

        seen_record_ids.add(record_id)
        records.append(record)

    return records


def match_payments(records):
    results = []

    for order in records:
        if order.get("type") != "ORDER":
            continue

        order_id = order["order_id"]
        order_time = order["timestamp"]
        end_time = order_time + timedelta(hours=72)
        selected_payment = None
        selected_index = None

        for index, payment in enumerate(records):
            if payment.get("type") != "PAYMENT":
                continue
            if payment.get("order_id") != order_id:
                continue
            if payment.get("amount", 0) < 0:
                continue

            payment_time = payment["timestamp"]
            if payment_time < order_time or payment_time >= end_time:
                continue

            if (
                selected_payment is None
                or payment_time < selected_payment["timestamp"]
                or (
                    payment_time == selected_payment["timestamp"]
                    and index < selected_index
                )
            ):
                selected_payment = payment
                selected_index = index

        if selected_payment is None:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": selected_payment["amount"],
            })

    return results


def compute_refunds(records):
    order_ids = {
        record["order_id"]
        for record in records
        if record.get("type") == "ORDER"
    }

    refund_total = 0
    for record in records:
        if (
            record.get("type") == "PAYMENT"
            and record.get("currency") == "USD"
            and record.get("amount", 0) < 0
            and record.get("order_id") in order_ids
        ):
            refund_total += abs(record["amount"])

    return refund_total


def build_summary(matches, refund_total):
    matched_total = 0
    matched_count = 0
    unmatched_ids = set()

    for result in matches:
        status = result.get("status")

        if status == "matched":
            matched_count += 1
            matched_total += result.get("amount", 0)
        elif status == "unmatched":
            unmatched_ids.add(result.get("order_id"))

    net_total = matched_total - refund_total
    if net_total < 0:
        net_total = 0

    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "refund_total": refund_total,
        "net_total": net_total,
        "unmatched_ids": sorted(unmatched_ids),
    }

