from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str) or not s:
        return None

    text = s
    if text.startswith("-"):
        text = text[1:]

    if not text:
        return None

    if text.count(".") > 1:
        return None

    if "." in text:
        whole, fraction = text.split(".")
        if not whole or not fraction:
            return None
        if len(fraction) > 3:
            return None
    else:
        whole = text
        fraction = ""

    digits = "0123456789"
    if any(character not in digits for character in whole + fraction):
        return None

    try:
        amount = Decimal(s).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        cents = int(amount * 100)
    except (InvalidOperation, ValueError, TypeError):
        return None

    if abs(cents) > 1_000_000:
        return None

    return cents


def parse_record(line):
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount_text, currency, timestamp_text = fields

    record_type = record_type.upper()
    if record_type not in ("ORDER", "PAYMENT"):
        return None

    record_id = record_id.strip()
    order_id = order_id.strip()

    if not record_id or not order_id or not order_id.startswith("ORD-"):
        return None

    if currency != "USD":
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None

    if record_type == "ORDER" and amount < 0:
        return None

    if len(timestamp_text) == 16:
        expected_positions = (4, 7, 10, 13)
        timestamp_format = "%Y-%m-%d %H:%M"
    elif len(timestamp_text) == 19:
        expected_positions = (4, 7, 10, 13, 16)
        timestamp_format = "%Y-%m-%d %H:%M:%S"
    else:
        return None

    separators = {
        4: "-",
        7: "-",
        10: " ",
        13: ":",
    }
    if len(timestamp_text) == 19:
        separators[16] = ":"

    for index, separator in separators.items():
        if timestamp_text[index] != separator:
            return None

    for index, character in enumerate(timestamp_text):
        if index not in expected_positions and not character.isdigit():
            return None

    try:
        timestamp = datetime.strptime(timestamp_text, timestamp_format)
    except (TypeError, ValueError):
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []

    retained = []
    seen_ids = set()

    for line in text.splitlines():
        try:
            record = parse_record(line)
        except Exception:
            record = None

        if record is None:
            continue

        record_id = record["record_id"]
        if record_id in seen_ids:
            continue

        seen_ids.add(record_id)
        retained.append(record)

    return retained


def match_payments(records):
    """Match each retained order with its earliest qualifying payment."""
    if not isinstance(records, (list, tuple)):
        return []

    payments = []

    for source_index, record in enumerate(records):
        if not isinstance(record, dict):
            continue
        if record.get("type") != "PAYMENT":
            continue
        if record.get("amount", -1) < 0:
            continue

        payments.append((source_index, record))

    matches = []

    for order in records:
        if not isinstance(order, dict):
            continue
        if order.get("type") != "ORDER":
            continue

        order_id = order.get("order_id")
        order_timestamp = order.get("timestamp")
        selected = None

        for source_index, payment in payments:
            if payment.get("order_id") != order_id:
                continue

            payment_timestamp = payment.get("timestamp")
            if payment_timestamp < order_timestamp:
                continue
            if payment_timestamp >= order_timestamp + timedelta(hours=72):
                continue

            candidate = (payment_timestamp, source_index, payment)
            if selected is None or candidate[:2] < selected[:2]:
                selected = candidate

        if selected is None:
            matches.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })
        else:
            matches.append({
                "order_id": order_id,
                "status": "matched",
                "amount": selected[2]["amount"],
            })

    return matches


def compute_refunds(records):
    """Return the total, in cents, of qualifying payment refunds."""
    if not isinstance(records, (list, tuple)):
        return 0

    existing_orders = set()

    for record in records:
        if not isinstance(record, dict):
            continue
        if record.get("type") == "ORDER":
            order_id = record.get("order_id")
            if isinstance(order_id, str):
                existing_orders.add(order_id)

    refund_total = 0

    for record in records:
        if not isinstance(record, dict):
            continue
        if record.get("type") != "PAYMENT":
            continue
        if record.get("currency") != "USD":
            continue

        order_id = record.get("order_id")
        amount = record.get("amount")

        if order_id not in existing_orders:
            continue
        if not isinstance(amount, int) or isinstance(amount, bool):
            continue
        if amount < 0:
            refund_total += -amount

    return refund_total


def build_summary(matches, refund_total):
    if not isinstance(matches, (list, tuple)):
        matches = []

    total_orders = len(matches)
    matched_count = 0
    matched_total = 0
    unmatched_ids = set()

    for result in matches:
        if not isinstance(result, dict):
            continue

        status = result.get("status")

        if status == "matched":
            matched_count += 1
            amount = result.get("amount", 0)
            if isinstance(amount, int) and not isinstance(amount, bool):
                matched_total += amount
        elif status == "unmatched":
            order_id = result.get("order_id")
            if isinstance(order_id, str):
                unmatched_ids.add(order_id)

    if not isinstance(refund_total, int) or isinstance(refund_total, bool):
        refund_total = 0

    net_total = matched_total - refund_total
    if net_total < 0:
        net_total = 0

    return {
        "total_orders": total_orders,
        "matched_count": matched_count,
        "refund_total": refund_total,
        "net_total": net_total,
        "unmatched_ids": sorted(unmatched_ids),
    }

"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    """Convert a monetary value to integer cents, or return None if invalid."""
    if not isinstance(s, str):
        return None

    value = s.strip()
    if not value or _AMOUNT_RE.fullmatch(value) is None:
        return None

    try:
        amount = Decimal(value)
        if not amount.is_finite():
            return None

        cents = (amount * Decimal("100")).quantize(
            Decimal("1"),
            rounding=ROUND_HALF_UP,
        )
        cents = int(cents)
    except (InvalidOperation, ValueError, OverflowError):
        return None

    if abs(cents) > 1_000_000:
        return None

    return cents


def parse_record(line):
    """Parse one input line into a record dictionary, or return None."""
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 6:
        return None

    (
        record_type,
        record_id,
        order_id,
        amount_text,
        currency,
        timestamp,
    ) = (field.strip() for field in fields)

    record_type = record_type.upper()

    if record_type not in {"ORDER", "PAYMENT"}:
        return None
    if _ID_RE.fullmatch(record_id) is None:
        return None
    if _ID_RE.fullmatch(order_id) is None:
        return None
    if _CURRENCY_RE.fullmatch(currency) is None:
        return None
    if _parse_timestamp(timestamp) is None:
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None
    if record_type == "ORDER" and amount < 0:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    """Load valid records, retaining only the first occurrence of each ID."""
    if not isinstance(text, str):
        return []

    records = []
    seen_ids = set()

    for line in text.splitlines():
        record = parse_record(line)
        if record is None:
            continue

        if record["record_id"] in seen_ids:
            continue

        seen_ids.add(record["record_id"])
        records.append(record)

    return records


def match_payments(records):
    """Match the earliest qualifying payment to each order."""
    if not isinstance(records, (list, tuple)):
        return []

    payments = []
    for source_index, record in enumerate(records):
        if not isinstance(record, dict):
            continue
        if record.get("type") != "PAYMENT":
            continue

        amount = record.get("amount")
        if type(amount) is not int or amount < 0:
            continue

        payments.append((source_index, record))

    results = []

    for order in records:
        if not isinstance(order, dict):
            continue
        if order.get("type") != "ORDER":
            continue

        order_time = _parse_timestamp(order.get("timestamp"))
        selected_payment = None
        selected_key = None

        if order_time is not None:
            latest_time = order_time + timedelta(hours=72)

            for source_index, payment in payments:
                if payment.get("order_id") != order.get("order_id"):
                    continue
                if payment.get("currency") != order.get("currency"):
                    continue

                payment_time = _parse_timestamp(payment.get("timestamp"))
                if payment_time is None:
                    continue

                try:
                    in_window = order_time <= payment_time < latest_time
                except TypeError:
                    in_window = False

                if not in_window:
                    continue

                candidate_key = (payment_time, source_index)
                if selected_key is None or candidate_key < selected_key:
                    selected_key = candidate_key
                    selected_payment = payment

        if selected_payment is None:
            results.append({
                "order_id": order.get("order_id"),
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order.get("order_id"),
                "status": "matched",
                "amount": selected_payment["amount"],
            })

    return results


def compute_refunds(records):
    """Return the positive total of refunds belonging to existing orders."""
    if not isinstance(records, (list, tuple)):
        return 0

    order_ids = {
        record.get("order_id")
        for record in records
        if isinstance(record, dict) and record.get("type") == "ORDER"
    }

    total = 0

    for record in records:
        if (
            isinstance(record, dict)
            and record.get("type") == "PAYMENT"
            and type(record.get("amount")) is int
            and record["amount"] < 0
            and record.get("order_id") in order_ids
        ):
            total += -record["amount"]

    return total


def build_summary(matches, refund_total):
    """Build the reconciliation summary."""
    if not isinstance(matches, (list, tuple)):
        matches = []

    total_orders = len(matches)
    matched_count = 0
    matched_total = 0
    unmatched_ids = set()

    for result in matches:
        if not isinstance(result, dict):
            continue

        if result.get("status") == "matched":
            matched_count += 1
            amount = result.get("amount", 0)
            if type(amount) is int:
                matched_total += amount
        elif result.get("order_id") is not None:
            unmatched_ids.add(result["order_id"])

    if type(refund_total) is not int:
        refund_total = 0

    net_total = matched_total - refund_total
    if net_total < 0:
        net_total = 0

    return {
        "total_orders": total_orders,
        "matched_count": matched_count,
        "refund_total": refund_total,
        "net_total": net_total,
        "unmatched_ids": sorted(unmatched_ids),
    }

