    raise NotImplementedError


def load_records(text):
    # Placeholder for future implementation
    raise NotImplementedError


def match_payments(records):
    results = []
    orders = [record for record in records if record['type'].upper() == 'ORDER']
    payments = [record for record in records if record['type'].upper() == 'PAYMENT']

    for order in orders:
        order_id = order['order_id']
        order_timestamp = datetime.strptime(order['timestamp'], '%Y-%m-%d %H:%M:%S') if ':' in order['timestamp'] else datetime.strptime(order['timestamp'], '%Y-%m-%d %H:%M')
        matched = False

        for payment in payments:
            if payment['amount'] < 0:  # Skip refunds
                continue

            payment_timestamp = datetime.strptime(payment['timestamp'], '%Y-%m-%d %H:%M:%S') if ':' in payment['timestamp'] else datetime.strptime(payment['timestamp'], '%Y-%m-%d %H:%M')
            if order_timestamp <= payment_timestamp < order_timestamp + timedelta(hours=72):
                results.append({'order_id': order_id, 'status': 'matched', 'amount': payment['amount']})
                matched = True
                break

        if not matched:
            results.append({'order_id': order_id, 'status': 'unmatched', 'amount': 0})

    return results


def compute_refunds(records):
    # Placeholder for future implementation
    raise NotImplementedError


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = matched_count * 100 - refund_total  # Assuming matched payment amounts are 100 each for simplicity
    unmatched_ids = sorted(set(match['record_id'] for match in matches if match['status'] != 'matched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': max(net_total, 0),
        'unmatched_ids': unmatched_ids
    }

