"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    import re
    if not isinstance(s, str):
        return None
    text = s.strip()
    if not re.fullmatch(r"-?\d+(?:\.\d{1,3})?", text):
        return None
    try:
        value = Decimal(text)
        cents = int((value * Decimal("100")).quantize(
            Decimal("1"), rounding=ROUND_HALF_UP
        ))
        if abs(cents) > 1000000:
            return None
        return cents
    except (InvalidOperation, ValueError, TypeError, OverflowError):
        return None


def parse_record(line):
    if not isinstance(line, str):
        return None
    fields = line.split("|")
    if len(fields) != 6:
        return None
    record_type, record_id, order_id, amount, currency, timestamp = fields
    record_type = record_type.strip().upper()
    record_id = record_id.strip()
    order_id = order_id.strip()
    currency = currency.strip()
    timestamp = timestamp.strip()
    if record_type not in ("ORDER", "PAYMENT"):
        return None
    if not record_id or not order_id or not order_id.startswith("ORD-"):
        return None
    if currency != "USD":
        return None
    amount_value = parse_amount(amount)
    if amount_value is None:
        return None
    if record_type == "ORDER" and amount_value < 0:
        return None
    parsed_timestamp = None
    for fmt in ("%Y-%m-%d %H:%M", "%Y-%m-%d %H:%M:%S"):
        try:
            parsed_timestamp = datetime.strptime(timestamp, fmt)
            break
        except (TypeError, ValueError):
            pass
    if parsed_timestamp is None:
        return None
    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount_value,
        "currency": currency,
        "timestamp": parsed_timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []
    records = []
    seen = set()
    for line in text.splitlines():
        record = parse_record(line)
        if record is None or record["record_id"] in seen:
            continue
        seen.add(record["record_id"])
        records.append(record)
    return records


def match_payments(records):
    if not isinstance(records, list):
        return []
    orders = []
    order_ids = set()
    for record in records:
        if not isinstance(record, dict):
            continue
        if record.get("currency") != "USD":
            continue
        order_id = record.get("order_id")
        if (record.get("type") == "ORDER"
                and isinstance(order_id, str)
                and order_id not in order_ids):
            order_ids.add(order_id)
            orders.append(record)

    results = []
    for order in orders:
        order_id = order.get("order_id")
        order_time = order.get("timestamp")
        order_amount = order.get("amount")
        if (not isinstance(order_time, datetime)
                or not isinstance(order_amount, int)
                or isinstance(order_amount, bool)):
            results.append({"order_id": order_id, "status": "unmatched",
                            "amount": 0})
            continue

        end_time = order_time + timedelta(hours=72)
        candidates = []
        for index, record in enumerate(records):
            if not isinstance(record, dict):
                continue
            amount = record.get("amount")
            timestamp = record.get("timestamp")
            if (record.get("currency") == "USD"
                    and record.get("type") == "PAYMENT"
                    and record.get("order_id") == order_id
                    and isinstance(amount, int)
                    and not isinstance(amount, bool)
                    and amount >= 0
                    and isinstance(timestamp, datetime)
                    and order_time <= timestamp < end_time):
                candidates.append((timestamp, index, amount))

        if not candidates:
            results.append({"order_id": order_id, "status": "unmatched",
                            "amount": 0})
            continue
        selected = min(candidates, key=lambda item: (item[0], item[1]))
        amount = selected[2]
        results.append({
            "order_id": order_id,
            "status": "matched" if amount == order_amount else "unmatched",
            "amount": amount if amount == order_amount else 0,
        })
    return results


def compute_refunds(records):
    if not isinstance(records, list):
        return 0
    order_ids = set()
    for record in records:
        if (isinstance(record, dict)
                and record.get("currency") == "USD"
                and record.get("type") == "ORDER"
                and isinstance(record.get("order_id"), str)):
            order_ids.add(record["order_id"])

    total = 0
    for record in records:
        if not isinstance(record, dict):
            continue
        amount = record.get("amount")
        if (record.get("currency") == "USD"
                and record.get("type") == "PAYMENT"
                and isinstance(amount, int)
                and not isinstance(amount, bool)
                and amount < 0
                and record.get("order_id") in order_ids):
            total += -amount
    return total


def build_summary(matches, refund_total):
    if not isinstance(matches, list):
        matches = []
    if not isinstance(refund_total, int) or isinstance(refund_total, bool):
        refund_total = 0

    matched_total = 0
    matched_count = 0
    unmatched_ids = set()
    for item in matches:
        if not isinstance(item, dict):
            continue
        if item.get("status") == "matched":
            matched_count += 1
            amount = item.get("amount")
            if isinstance(amount, int) and not isinstance(amount, bool):
                matched_total += amount
        elif isinstance(item.get("order_id"), str):
            unmatched_ids.add(item["order_id"])

    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "refund_total": refund_total,
        "net_total": max(0, matched_total - refund_total),
        "unmatched_ids": sorted(unmatched_ids),
    }

