from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    """Return an amount in integer cents, or None when the amount is invalid."""
    if isinstance(s, bool) or s is None:
        return None

    text = str(s).strip()
    if not _AMOUNT_PATTERN.fullmatch(text):
        return None

    try:
        value = Decimal(text)
        cents = (value * Decimal("100")).quantize(
            Decimal("1"),
            rounding=ROUND_HALF_UP,
        )
        cents = int(cents)

        if abs(cents) > 1_000_000:
            return None

        return cents
    except (InvalidOperation, ValueError, TypeError, OverflowError):
        return None


def parse_record(line):
    """Parse one six-field record, returning a dictionary or None."""
    if not isinstance(line, str):
        return None

    parts = line.strip().split("|")
    if len(parts) != 6:
        return None

    record_type, record_id, order_id, amount, currency, timestamp = (
        part.strip() for part in parts
    )

    record_type = record_type.upper()
    if record_type not in {"ORDER", "PAYMENT"}:
        return None

    if not _ID_PATTERN.fullmatch(record_id):
        return None

    if not _ID_PATTERN.fullmatch(order_id):
        return None

    if not _CURRENCY_PATTERN.fullmatch(currency):
        return None

    parsed_amount = parse_amount(amount)
    if parsed_amount is None:
        return None

    if record_type == "ORDER" and parsed_amount < 0:
        return None

    parsed_timestamp = _parse_timestamp(timestamp)
    if parsed_timestamp is None:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": parsed_amount,
        "currency": currency,
        "timestamp": parsed_timestamp,
    }


def load_records(text):
    """Parse valid records while retaining only the first record ID."""
    if not isinstance(text, str):
        return []

    records = []
    seen_ids = set()

    for line in text.splitlines():
        record = parse_record(line)
        if record is None:
            continue

        record_id = record["record_id"]
        if record_id in seen_ids:
            continue

        seen_ids.add(record_id)
        records.append(record)

    return records


def match_payments(records):
    """Return one payment-matching result for each retained order."""
    if not isinstance(records, list):
        return []

    orders = [
        record
        for record in records
        if isinstance(record, dict) and record.get("type") == "ORDER"
    ]

    payments = [
        (source_index, record)
        for source_index, record in enumerate(records)
        if (
            isinstance(record, dict)
            and record.get("type") == "PAYMENT"
            and isinstance(record.get("amount"), int)
            and not isinstance(record.get("amount"), bool)
            and record.get("amount") >= 0
        )
    ]

    results = []

    for order in orders:
        order_id = order.get("order_id")
        order_amount = order.get("amount")
        order_currency = order.get("currency")
        order_timestamp = order.get("timestamp")

        candidates = []

        if isinstance(order_timestamp, datetime):
            deadline = order_timestamp + timedelta(hours=72)

            for source_index, payment in payments:
                if payment.get("order_id") != order_id:
                    continue
                if payment.get("amount") != order_amount:
                    continue
                if payment.get("currency") != order_currency:
                    continue

                payment_timestamp = payment.get("timestamp")
                if not isinstance(payment_timestamp, datetime):
                    continue

                try:
                    if order_timestamp <= payment_timestamp < deadline:
                        candidates.append(
                            (payment_timestamp, source_index, payment)
                        )
                except TypeError:
                    continue

        if candidates:
            candidates.sort(key=lambda item: (item[0], item[1]))
            payment = candidates[0][2]
            results.append(
                {
                    "order_id": order_id,
                    "status": "matched",
                    "amount": payment["amount"],
                }
            )
        else:
            results.append(
                {
                    "order_id": order_id,
                    "status": "unmatched",
                    "amount": 0,
                }
            )

    return results


def compute_refunds(records):
    """Return the total of refunds belonging to existing orders."""
    if not isinstance(records, list):
        return 0

    order_ids = {
        record.get("order_id")
        for record in records
        if isinstance(record, dict) and record.get("type") == "ORDER"
    }

    refund_total = 0

    for record in records:
        if not isinstance(record, dict):
            continue

        amount = record.get("amount")
        if (
            record.get("type") == "PAYMENT"
            and isinstance(amount, int)
            and not isinstance(amount, bool)
            and amount < 0
            and record.get("order_id") in order_ids
        ):
            refund_total += -amount

    return refund_total


def build_summary(matches, refund_total):
    """Build a five-field summary of payment matching results."""
    if not isinstance(matches, list):
        matches = []

    matched_count = 0
    matched_total = 0
    unmatched_ids = set()

    for result in matches:
        if not isinstance(result, dict):
            continue

        if result.get("status") == "matched":
            matched_count += 1
            amount = result.get("amount", 0)
            if isinstance(amount, bool):
                amount = 0
            try:
                matched_total += int(amount)
            except (TypeError, ValueError, OverflowError):
                pass
        else:
            order_id = result.get("order_id")
            if isinstance(order_id, str):
                unmatched_ids.add(order_id)

    try:
        refund_value = int(refund_total)
    except (TypeError, ValueError, OverflowError):
        refund_value = 0

    net_total = max(0, matched_total - refund_value)

    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "refund_total": refund_total,
        "net_total": net_total,
        "unmatched_ids": sorted(unmatched_ids),
    }

