from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        amount = int(Decimal(s) * 100)
        if abs(amount) > 1000000:
            return None
        return amount
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.strip().split('|')
    if len(fields) != 6:
        return None
    record_type, record_id, order_id, amount, currency, timestamp = fields
    record_type = record_type.upper().strip()
    record_id = record_id.strip()
    order_id = order_id.strip()
    amount = parse_amount(amount.strip())
    timestamp = datetime.strptime(timestamp.strip(), '%Y-%m-%d %H:%M:%S') if ':' in timestamp else datetime.strptime(timestamp.strip(), '%Y-%m-%d %H:%M')

    if record_type not in ['ORDER', 'PAYMENT']:
        return None
    if not record_id or not order_id.startswith('ORD-') or amount is None or currency != 'USD':
        return None

    return {
        'TYPE': record_type,
        'RECORD_ID': record_id,
        'ORDER_ID': order_id,
        'AMOUNT': amount,
        'CURRENCY': currency,
        'TIMESTAMP': timestamp
    }


def load_records(text):
    lines = text.strip().split('\n')
    records = []
    seen_ids = set()

    for line in lines:
        record = parse_record(line)
        if record and record['RECORD_ID'] not in seen_ids:
            records.append(record)
            seen_ids.add(record['RECORD_ID'])

    return records


def match_payments(records):
    orders = {record['ORDER_ID']: record for record in records if record['TYPE'] == 'ORDER'}
    payments = [record for record in records if record['TYPE'] == 'PAYMENT']
    results = []

    for order_id, order in orders.items():
        order_time = order['TIMESTAMP']
        matching_payments = [payment for payment in payments if payment['ORDER_ID'] == order_id and payment['TIMESTAMP'] < order_time + timedelta(hours=72)]

        if matching_payments:
            earliest_payment = min(matching_payments, key=lambda p: p['TIMESTAMP'])
            results.append({
                'order_id': order_id,
                'status': 'matched',
                'amount': earliest_payment['AMOUNT']
            })
        else:
            results.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': 0
            })

    return results


def compute_refunds(records):
    raise NotImplementedError


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = max(sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total, 0)
    unmatched_ids = sorted(set(match['RECORD_ID'] for match in matches if match['status'] != 'matched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str) or not s:
        return None

    if s.startswith("-"):
        number = s[1:]
    else:
        number = s

    if not number:
        return None

    if number.count(".") > 1:
        return None

    if "." in number:
        whole, fraction = number.split(".")
        if not whole or not fraction or len(fraction) > 3:
            return None
    else:
        whole = number
        fraction = ""

    if not whole.isascii() or not whole.isdigit():
        return None
    if fraction and (not fraction.isascii() or not fraction.isdigit()):
        return None

    try:
        value = Decimal(s).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
    except (InvalidOperation, ValueError):
        return None

    cents = int(value * 100)

    if abs(cents) > 1_000_000:
        return None

    return cents


def parse_record(line):
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount_text, currency, timestamp_text = fields

    record_type = record_type.upper()
    if record_type not in ("ORDER", "PAYMENT"):
        return None

    record_id = record_id.strip()
    order_id = order_id.strip()

    if not record_id or not order_id or not order_id.startswith("ORD-"):
        return None

    if currency != "USD":
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None

    if record_type == "ORDER" and amount < 0:
        return None

    if len(timestamp_text) not in (16, 19):
        return None

    if len(timestamp_text) == 16:
        separators = {4: "-", 7: "-", 10: " ", 13: ":"}
        timestamp_format = "%Y-%m-%d %H:%M"
    else:
        separators = {4: "-", 7: "-", 10: " ", 13: ":", 16: ":"}
        timestamp_format = "%Y-%m-%d %H:%M:%S"

    for index, character in enumerate(timestamp_text):
        if index in separators:
            if character != separators[index]:
                return None
        elif not character.isascii() or not character.isdigit():
            return None

    try:
        timestamp = datetime.strptime(timestamp_text, timestamp_format)
    except (TypeError, ValueError):
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []

    records = []
    seen_ids = set()

    for line in text.splitlines():
        record = parse_record(line)
        if record is None:
            continue

        record_id = record["record_id"]
        if record_id in seen_ids:
            continue

        seen_ids.add(record_id)
        records.append(record)

    return records


def match_payments(records):
    """Match each retained order with its earliest qualifying payment."""
    if not isinstance(records, (list, tuple)):
        return []

    results = []

    for order in records:
        if not isinstance(order, dict) or order.get("type") != "ORDER":
            continue

        order_id = order.get("order_id")
        order_time = order.get("timestamp")
        selected = None
        selected_key = None

        for source_index, payment in enumerate(records):
            if not isinstance(payment, dict):
                continue
            if payment.get("type") != "PAYMENT":
                continue
            if payment.get("order_id") != order_id:
                continue

            amount = payment.get("amount")
            payment_time = payment.get("timestamp")

            if not isinstance(amount, int) or amount < 0:
                continue

            if payment_time < order_time:
                continue
            if payment_time >= order_time + timedelta(hours=72):
                continue

            candidate_key = (payment_time, source_index)
            if selected_key is None or candidate_key < selected_key:
                selected = payment
                selected_key = candidate_key

        if selected is None:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": selected["amount"],
            })

    return results


def compute_refunds(records):
    """Return the total in cents for refunds tied to existing orders."""
    if not isinstance(records, (list, tuple)):
        return 0

    order_ids = set()
    for record in records:
        if not isinstance(record, dict):
            continue
        if record.get("type") == "ORDER" and record.get("currency") == "USD":
            order_id = record.get("order_id")
            if isinstance(order_id, str):
                order_ids.add(order_id)

    refund_total = 0
    for record in records:
        if not isinstance(record, dict):
            continue
        if (
            record.get("type") == "PAYMENT"
            and record.get("currency") == "USD"
            and record.get("order_id") in order_ids
        ):
            amount = record.get("amount")
            if isinstance(amount, int) and amount < 0:
                refund_total += abs(amount)

    return refund_total


def build_summary(matches, refund_total):
    if not isinstance(matches, (list, tuple)):
        matches = []

    total_orders = len(matches)
    matched_count = 0
    matched_total = 0
    unmatched_ids = set()

    for result in matches:
        if not isinstance(result, dict):
            continue

        status = result.get("status")

        if status == "matched":
            matched_count += 1
            amount = result.get("amount")
            if isinstance(amount, int) and not isinstance(amount, bool):
                matched_total += amount
        elif status == "unmatched":
            order_id = result.get("order_id")
            if isinstance(order_id, str):
                unmatched_ids.add(order_id)

    if not isinstance(refund_total, int) or isinstance(refund_total, bool):
        refund_total = 0

    net_total = matched_total - refund_total
    if net_total < 0:
        net_total = 0

    return {
        "total_orders": total_orders,
        "matched_count": matched_count,
        "refund_total": refund_total,
        "net_total": net_total,
        "unmatched_ids": sorted(unmatched_ids),
    }

