"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str) or not s:
        return None
    negative = s.startswith("-")
    if negative:
        s = s[1:]
    if not s or s.count(".") > 1:
        return None
    parts = s.split(".")
    whole = parts[0]
    fraction = parts[1] if len(parts) == 2 else ""
    if not whole or any(ch not in "0123456789" for ch in whole):
        return None
    if len(fraction) > 3 or any(ch not in "0123456789" for ch in fraction):
        return None
    try:
        cents = int(whole) * 100 + int((fraction + "00")[:2])
        if len(fraction) == 3 and fraction[2] >= "5":
            cents += 1
    except (ValueError, OverflowError):
        return None
    if cents > 1000000:
        return None
    return -cents if negative else cents


def parse_record(line):
    if not isinstance(line, str):
        return None
    fields = line.split("|")
    if len(fields) != 6:
        return None
    record_type, record_id, order_id, amount_text, currency, timestamp_text = fields
    record_type = record_type.upper()
    if record_type not in ("ORDER", "PAYMENT"):
        return None
    record_id = record_id.strip()
    order_id = order_id.strip()
    if not record_id or not order_id or not order_id.startswith("ORD-"):
        return None
    if currency != "USD":
        return None
    amount = parse_amount(amount_text)
    if amount is None or (record_type == "ORDER" and amount < 0):
        return None
    timestamp = None
    for fmt in ("%Y-%m-%d %H:%M", "%Y-%m-%d %H:%M:%S"):
        try:
            timestamp = datetime.strptime(timestamp_text, fmt)
            break
        except (ValueError, TypeError):
            pass
    if timestamp is None:
        return None
    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []
    retained = []
    seen_ids = set()
    for line in text.splitlines():
        record = parse_record(line)
        if record is None:
            continue
        if record["record_id"] in seen_ids:
            continue
        seen_ids.add(record["record_id"])
        retained.append(record)
    return retained


def match_payments(records):
    if records is None:
        return []
    try:
        retained = list(records)
    except (TypeError, AttributeError):
        return []
    results = []
    for order in retained:
        if not isinstance(order, dict) or order.get("type") != "ORDER":
            continue
        order_id = order.get("order_id")
        order_time = order.get("timestamp")
        best = None
        for payment in retained:
            if not isinstance(payment, dict):
                continue
            if payment.get("type") != "PAYMENT":
                continue
            if payment.get("order_id") != order_id:
                continue
            amount = payment.get("amount")
            payment_time = payment.get("timestamp")
            if not isinstance(amount, int) or amount < 0:
                continue
            if payment_time < order_time:
                continue
            if payment_time >= order_time + timedelta(hours=72):
                continue
            if best is None or payment_time < best["timestamp"]:
                best = {"timestamp": payment_time, "amount": amount}
        if best is None:
            results.append({"order_id": order_id, "status": "unmatched", "amount": 0})
        else:
            results.append({"order_id": order_id, "status": "matched", "amount": best["amount"]})
    return results


def compute_refunds(records):
    if records is None:
        return 0
    try:
        order_ids = {
            record["order_id"]
            for record in records
            if isinstance(record, dict)
            and record.get("type") == "ORDER"
            and record.get("currency") == "USD"
        }
    except (TypeError, AttributeError):
        return 0
    total = 0
    try:
        for record in records:
            if not isinstance(record, dict):
                continue
            if record.get("type") != "PAYMENT" or record.get("currency") != "USD":
                continue
            amount = record.get("amount")
            if isinstance(amount, int) and amount < 0 and record.get("order_id") in order_ids:
                total += abs(amount)
    except (TypeError, AttributeError):
        return total
    return total


def build_summary(matches, refund_total):
    if matches is None:
        matches = []
    try:
        items = list(matches)
    except (TypeError, AttributeError):
        items = []

    matched_count = 0
    matched_total = 0
    unmatched_ids = set()

    for result in items:
        if not isinstance(result, dict):
            continue
        status = result.get("status")
        if status == "matched":
            matched_count += 1
            amount = result.get("amount")
            if isinstance(amount, int):
                matched_total += amount
        elif status == "unmatched":
            unmatched_ids.add(result.get("order_id"))

    if not isinstance(refund_total, int):
        refund_total = 0
    net_total = matched_total - refund_total
    if net_total < 0:
        net_total = 0

    return {
        "total_orders": len(items),
        "matched_count": matched_count,
        "refund_total": refund_total,
        "net_total": net_total,
        "unmatched_ids": sorted(unmatched_ids),
    }

