    value = s
    if value.startswith("-"):
        value = value[1:]

    if not value or value.count(".") > 1:
        return None

    if "." in value:
        whole, fraction = value.split(".")
        if not whole or not fraction or len(fraction) > 3:
            return None
    else:
        whole = value
        fraction = ""

    if not all("0" <= char <= "9" for char in whole + fraction):
        return None

    try:
        amount = Decimal(s).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        cents = int(amount * 100)
    except (InvalidOperation, ValueError, OverflowError):
        return None

    if abs(cents) > 1_000_000:
        return None

    return cents


def parse_record(line):
