    record_id = record_id.strip()
    order_id = order_id.strip()

    if not record_id or not order_id or not order_id.startswith("ORD-"):
        return None

    if currency != "USD":
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None

    if record_type == "ORDER" and amount < 0:
        return None

    if len(timestamp_text) not in (16, 19):
        return None

    if (
        timestamp_text[4] != "-"
        or timestamp_text[7] != "-"
        or timestamp_text[10] != " "
        or timestamp_text[13] != ":"
    ):
        return None

    if len(timestamp_text) == 19 and timestamp_text[16] != ":":
        return None

    digit_positions = list(range(4)) + list(range(5, 7)) + list(range(8, 10))
    digit_positions += list(range(11, 13)) + list(range(14, 16))

    if len(timestamp_text) == 19:
        digit_positions += list(range(17, 19))

    if not all(timestamp_text[index].isdigit() for index in digit_positions):
        return None

    try:
        if len(timestamp_text) == 16:
            timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
        else:
            timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M:%S")
    except (TypeError, ValueError):
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []

    retained = []
    seen_ids = set()

    for line in text.splitlines():
        try:
            record = parse_record(line)
        except Exception:
            record = None

        if record is None:
            continue

        record_id = record["record_id"]
        if record_id in seen_ids:
            continue

        seen_ids.add(record_id)
        retained.append(record)

    return retained


def match_payments(records):
    results = []

    for order in records:
        if order["type"] != "ORDER":
            continue

        start = order["timestamp"]
        end = start + timedelta(hours=72)
        best_payment = None
        best_key = None

        for source_index, payment in enumerate(records):
            if payment["type"] != "PAYMENT":
                continue
            if payment["amount"] < 0:
                continue
            if payment["order_id"] != order["order_id"]:
                continue
            if payment["timestamp"] < start or payment["timestamp"] >= end:
                continue

            key = (payment["timestamp"], source_index)
            if best_key is None or key < best_key:
                best_key = key
                best_payment = payment

        if best_payment is None:
            results.append({
                "order_id": order["order_id"],
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order["order_id"],
                "status": "matched",
                "amount": best_payment["amount"],
            })

    return results


def compute_refunds(records):
    """Return qualifying refund amounts as positive integer cents."""
    if records is None:
        return 0

    try:
        existing_orders = {
            record.get("order_id")
            for record in records
            if isinstance(record, dict)
            and record.get("type") == "ORDER"
        }
    except (TypeError, AttributeError):
        return 0

    refund_total = 0

    try:
        for record in records:
            if not isinstance(record, dict):
                continue

            if (
                record.get("type") == "PAYMENT"
                and record.get("currency") == "USD"
                and record.get("order_id") in existing_orders
            ):
                amount = record.get("amount")
                if isinstance(amount, int) and amount < 0:
                    refund_total += abs(amount)
    except (TypeError, AttributeError):
        return refund_total

    return refund_total


def build_summary(matches, refund_total):
    if matches is None:
        results = []
    else:
        try:
            results = list(matches)
        except (TypeError, ValueError):
            results = []

    matched_total = 0
    matched_count = 0
    unmatched_ids = set()

    for result in results:
        if not isinstance(result, dict):
            continue

        status = result.get("status")

        if status == "matched":
            matched_count += 1
            amount = result.get("amount", 0)
            if isinstance(amount, int):
                matched_total += amount
        elif status == "unmatched":
            order_id = result.get("order_id")
            if isinstance(order_id, str):
                unmatched_ids.add(order_id)

    try:
        net_total = matched_total - refund_total
    except (TypeError, ValueError):
        net_total = matched_total

    if net_total < 0:
        net_total = 0

    return {
        "total_orders": len(results),
        "matched_count": matched_count,
        "refund_total": refund_total,
        "net_total": net_total,
        "unmatched_ids": sorted(unmatched_ids),
    }

