def parse_amount(s):
    try:
        if '.' in s:
            amount = Decimal(s).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
            amount = int(amount * 100)
        else:
            amount = int(s)

        if abs(amount) > 1000000:
            return None
        return amount
    except (ValueError, TypeError, InvalidOperation):
        return None


def parse_record(line):
    fields = line.strip().split('|')
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount, currency, timestamp = fields
    record_type = record_type.upper().strip()

    if record_type not in ['ORDER', 'PAYMENT']:
        return None

    record_id = record_id.strip()
    order_id = order_id.strip()
    amount = parse_amount(amount.strip())
    currency = currency.strip()
    timestamp = timestamp.strip()

    if not record_id or not order_id or currency != 'USD' or amount is None:
        return None

    if record_type == 'ORDER' and amount < 0:
