"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str) or not s:
        return None

    if s.startswith("-"):
        digits = s[1:]
    else:
        digits = s

    if not digits:
        return None

    if digits.count(".") > 1:
        return None

    if "." in digits:
        whole, fraction = digits.split(".")
        if not whole or len(fraction) > 3:
            return None
    else:
        whole = digits
        fraction = ""

    if not whole.isascii() or not whole.isdigit():
        return None

    if fraction and (not fraction.isascii() or not fraction.isdigit()):
        return None

    try:
        cents = int(
            (Decimal(s) * Decimal("100")).quantize(
                Decimal("1"),
                rounding=ROUND_HALF_UP
            )
        )
    except (InvalidOperation, ValueError, TypeError):
        return None

    if abs(cents) > 1_000_000:
        return None

    return cents


def parse_record(line):
    if not isinstance(line, str):
        return None

    try:
        fields = line.split("|")
        if len(fields) != 6:
            return None

        record_type, record_id, order_id, amount_text, currency, timestamp_text = fields

        record_type = record_type.upper()
        if record_type not in ("ORDER", "PAYMENT"):
            return None

        record_id = record_id.strip()
        order_id = order_id.strip()

        if not record_id or not order_id:
            return None
        if not order_id.startswith("ORD-"):
            return None
        if currency != "USD":
            return None

        amount = parse_amount(amount_text)
        if amount is None:
            return None
        if record_type == "ORDER" and amount < 0:
            return None

        if len(timestamp_text) == 16:
            timestamp_format = "%Y-%m-%d %H:%M"
            digit_positions = (
                list(range(0, 4))
                + list(range(5, 7))
                + list(range(8, 10))
                + list(range(11, 13))
                + list(range(14, 16))
            )
            separators = (4, 7, 10, 13)
        elif len(timestamp_text) == 19:
            timestamp_format = "%Y-%m-%d %H:%M:%S"
            digit_positions = (
                list(range(0, 4))
                + list(range(5, 7))
                + list(range(8, 10))
                + list(range(11, 13))
                + list(range(14, 16))
                + list(range(17, 19))
            )
            separators = (4, 7, 10, 13, 16)
        else:
            return None

        if any(
            not timestamp_text[index].isascii()
            or not timestamp_text[index].isdigit()
            for index in digit_positions
        ):
            return None

        expected_separators = ("-", "-", " ", ":", ":")
        if any(
            timestamp_text[index] != expected
            for index, expected in zip(separators, expected_separators)
        ):
            return None

        timestamp = datetime.strptime(timestamp_text, timestamp_format)

        return {
            "type": record_type,
            "record_id": record_id,
            "order_id": order_id,
            "amount": amount,
            "currency": currency,
            "timestamp": timestamp,
        }
    except (ValueError, TypeError, OverflowError):
        return None


def load_records(text):
    if not isinstance(text, str):
        return []

    retained = []
    seen_ids = set()

    for line in text.splitlines():
        try:
            record = parse_record(line)
        except Exception:
            record = None

        if record is None:
            continue

        record_id = record["record_id"]
        if record_id in seen_ids:
            continue

        seen_ids.add(record_id)
        retained.append(record)

    return retained


def match_payments(records):
    """Match each retained order with its earliest qualifying payment."""
    if records is None:
        return []

    try:
        records = list(records)
    except TypeError:
        return []

    payments = []
    orders = []

    for source_index, record in enumerate(records):
        if not isinstance(record, dict):
            continue

        if record.get("type") == "ORDER":
            orders.append(record)
        elif record.get("type") == "PAYMENT":
            amount = record.get("amount")
            if isinstance(amount, int) and not isinstance(amount, bool) and amount >= 0:
                payments.append((source_index, record))

    results = []

    for order in orders:
        order_id = order["order_id"]
        order_timestamp = order["timestamp"]
        latest_timestamp = order_timestamp + timedelta(hours=72)

        qualifying = []
        for source_index, payment in payments:
            if payment["order_id"] != order_id:
                continue

            payment_timestamp = payment["timestamp"]
            if order_timestamp <= payment_timestamp < latest_timestamp:
                qualifying.append((payment_timestamp, source_index, payment))

        if qualifying:
            _, _, selected_payment = min(qualifying, key=lambda item: (item[0], item[1]))
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": selected_payment["amount"],
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })

    return results


def compute_refunds(records):
    """Return the total qualifying refund amount in integer cents."""
    if records is None:
        return 0

    try:
        order_ids = {
            record.get("order_id")
            for record in records
            if isinstance(record, dict)
            and record.get("type") == "ORDER"
        }
    except (TypeError, AttributeError):
        return 0

    total = 0
    try:
        for record in records:
            if not isinstance(record, dict):
                continue
            if record.get("type") != "PAYMENT":
                continue
            if record.get("currency") != "USD":
                continue

            order_id = record.get("order_id")
            amount = record.get("amount")

            if order_id not in order_ids:
                continue
            if not isinstance(amount, int) or isinstance(amount, bool):
                continue
            if amount < 0:
                total += abs(amount)
    except (TypeError, AttributeError):
        return 0

    return total


def build_summary(matches, refund_total):
    try:
        results = list(matches)
    except (TypeError, ValueError):
        results = []

    matched_count = 0
    matched_total = 0
    unmatched_ids = set()

    for result in results:
        if not isinstance(result, dict):
            continue

        status = result.get("status")

        if status == "matched":
            matched_count += 1
            amount = result.get("amount")
            if isinstance(amount, int) and not isinstance(amount, bool):
                matched_total += amount
        elif status == "unmatched":
            order_id = result.get("order_id")
            if isinstance(order_id, str):
                unmatched_ids.add(order_id)

    if not isinstance(refund_total, int) or isinstance(refund_total, bool):
        refund_total = 0

    net_total = matched_total - refund_total
    if net_total < 0:
        net_total = 0

    return {
        "total_orders": len(results),
        "matched_count": matched_count,
        "refund_total": refund_total,
        "net_total": net_total,
        "unmatched_ids": sorted(unmatched_ids),
    }

