"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    import re
    try:
        if not isinstance(s, str):
            return None
        text = s.strip()
        if not re.fullmatch(r"-?\d+(?:\.\d*)?", text):
            return None
        _, _, fraction = text.partition(".")
        if len(fraction) > 3:
            return None
        cents = (Decimal(text) * Decimal("100")).quantize(
            Decimal("1"), rounding=ROUND_HALF_UP
        )
        result = int(cents)
        if abs(result) > 1000000:
            return None
        return result
    except (InvalidOperation, ValueError, TypeError, ArithmeticError):
        return None


def parse_record(line):
    try:
        if not isinstance(line, str):
            return None
        fields = line.strip().split("|")
        if len(fields) != 6:
            return None
        kind, record_id, order_id, amount_text, currency, timestamp = (
            field.strip() for field in fields
        )
        kind = kind.upper()
        if kind not in ("ORDER", "PAYMENT"):
            return None
        if not record_id or not order_id or not order_id.startswith("ORD-"):
            return None
        if currency != "USD":
            return None
        amount = parse_amount(amount_text)
        if amount is None or (kind == "ORDER" and amount < 0):
            return None
        parsed_time = None
        for pattern in ("%Y-%m-%d %H:%M", "%Y-%m-%d %H:%M:%S"):
            try:
                parsed_time = datetime.strptime(timestamp, pattern)
                break
            except (ValueError, TypeError):
                pass
        if parsed_time is None:
            return None
        return {
            "type": kind.lower(),
            "record_id": record_id,
            "order_id": order_id,
            "amount": amount,
            "currency": currency,
            "timestamp": parsed_time,
        }
    except Exception:
        return None


def load_records(text):
    if not isinstance(text, str):
        return []
    records = []
    seen = set()
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None and record["record_id"] not in seen:
            seen.add(record["record_id"])
            records.append(record)
    return records


def match_payments(records):
    if not isinstance(records, list):
        return []
    results = []
    for order in records:
        if not isinstance(order, dict) or order.get("type") != "order":
            continue
        order_id = order.get("order_id")
        order_time = order.get("timestamp")
        best = None
        if isinstance(order_time, datetime):
            endpoint = order_time + timedelta(hours=72)
            for payment in records:
                if not isinstance(payment, dict):
                    continue
                if payment.get("type") != "payment":
                    continue
                if payment.get("currency", "USD") != "USD":
                    continue
                if payment.get("order_id") != order_id:
                    continue
                amount = payment.get("amount")
                payment_time = payment.get("timestamp")
                if not isinstance(amount, int) or isinstance(amount, bool) or amount < 0:
                    continue
                if not isinstance(payment_time, datetime):
                    continue
                if order_time <= payment_time < endpoint:
                    if best is None or payment_time < best[0]:
                        best = (payment_time, amount)
        results.append({
            "order_id": order_id,
            "status": "matched" if best is not None else "unmatched",
            "amount": best[1] if best is not None else 0,
        })
    return results


def compute_refunds(records):
    if not isinstance(records, list):
        return 0
    order_ids = {
        record.get("order_id")
        for record in records
        if isinstance(record, dict)
        and record.get("type") == "order"
        and record.get("currency", "USD") == "USD"
    }
    total = 0
    for record in records:
        if not isinstance(record, dict):
            continue
        amount = record.get("amount")
        if (
            record.get("type") == "payment"
            and record.get("currency", "USD") == "USD"
            and isinstance(amount, int)
            and not isinstance(amount, bool)
            and amount < 0
            and record.get("order_id") in order_ids
        ):
            total += -amount
    return total


def build_summary(matches, refund_total):
    if not isinstance(matches, list):
        matches = []
    matched_count = 0
    matched_total = 0
    unmatched = set()
    for result in matches:
        if not isinstance(result, dict):
            continue
        if result.get("status") == "matched":
            matched_count += 1
            amount = result.get("amount", 0)
            if isinstance(amount, (int, float)):
                matched_total += amount
        elif result.get("status") == "unmatched":
            order_id = result.get("order_id")
            if isinstance(order_id, str):
                unmatched.add(order_id)
    if not isinstance(refund_total, (int, float)):
        refund_total = 0
    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "refund_total": refund_total,
        "net_total": max(0, matched_total - refund_total),
        "unmatched_ids": sorted(unmatched),
    }

"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        amount = Decimal(s)
        # Convert to integer cents
        amount_cents = int(amount * 100)
        # Check for validity
        if abs(amount_cents) > 1000000:
            return None
        return amount_cents
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.strip().split('|')
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount_str, currency, timestamp_str = fields

    # Validate TYPE
    record_type = record_type.upper()
    if record_type not in ['ORDER', 'PAYMENT']:
        return None

    # Validate IDs
    record_id = record_id.strip()
    order_id = order_id.strip()
    if not record_id or not order_id:
        return None

    # Validate AMOUNT
    amount = parse_amount(amount_str)
    if amount is None:
        return None

    # Validate CURRENCY
    currency = currency.strip()
    if not currency:
        return None

    # Validate TIMESTAMP
    try:
        timestamp = datetime.fromisoformat(timestamp_str)
    except ValueError:
        return None

    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount,
        'currency': currency,
        'timestamp': timestamp
    }


def load_records(text):
    records = []
    for line in text.strip().splitlines():
        record = parse_record(line)
        if record is not None:
            # Check for duplicate record_id
            if not any(r['record_id'] == record['record_id'] for r in records):
                records.append(record)
    return records


def match_payments(records):
    orders = {}
    payments = []

    # Separate orders and payments
    for record in records:
        if record['type'] == 'ORDER':
            orders[record['order_id']] = record
        elif record['type'] == 'PAYMENT':
            payments.append(record)

    results = []

    for order_id, order in orders.items():
        order_timestamp = order['timestamp']
        order_amount = order['amount']
        matching_payments = []

        # Find payments that qualify for this order
        for payment in payments:
            if payment['order_id'] == order_id:
                payment_timestamp = payment['timestamp']
                if order_timestamp <= payment_timestamp < order_timestamp + timedelta(hours=72):
                    matching_payments.append(payment)

        if matching_payments:
            # Sort by timestamp and then by original order
            matching_payments.sort(key=lambda p: (p['timestamp'], payments.index(p)))
            earliest_payment = matching_payments[0]
            results.append({
                'order_id': order_id,
                'status': 'matched',
                'amount': earliest_payment['amount']
            })
        else:
            results.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': 0
            })

    return results


def compute_refunds(records):
    refund_total = sum(record['amount'] for record in records if record['type'] == 'PAYMENT' and record['amount'] < 0)
    return max(refund_total, 0)


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = max(sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total, 0)
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] != 'matched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

