"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        if '.' in s:
            parts = s.split('.')
            if len(parts) > 2 or any(not part.isdigit() for part in parts):
                return None
            whole_part = parts[0]
            fractional_part = parts[1][:3]  # Take at most 3 digits
            amount = int(whole_part + fractional_part.ljust(3, '0'))  # Pad with zeros if needed
        else:
            amount = int(s)

        if abs(amount) > 1000000:
            return None
        return amount
    except (ValueError, TypeError):
        return None


def parse_record(line):
    fields = line.split('|')
    if len(fields) != 6:
        return None
    record_type, record_id, order_id, amount, currency, timestamp = map(str.strip, fields)
    if record_type.upper() not in ['ORDER', 'PAYMENT']:
        return None
    if not record_id or not order_id:
        return None
    parsed_amount = parse_amount(amount)
    if parsed_amount is None or currency != 'USD':
        return None
    # Validate timestamp format
    try:
        datetime.strptime(timestamp, '%Y-%m-%d %H:%M:%S')
    except ValueError:
        try:
            datetime.strptime(timestamp, '%Y-%m-%d %H:%M')
        except ValueError:
            return None
    return {
        'type': record_type.upper(),
        'record_id': record_id,
        'order_id': order_id,
        'amount': parsed_amount,
        'currency': currency,
        'timestamp': timestamp
    }


def load_records(text):
    records = []
    seen_ids = set()
    for line in text.strip().splitlines():
        record = parse_record(line)
        if record and record['record_id'] not in seen_ids:
            records.append(record)
            seen_ids.add(record['record_id'])
    return records


def match_payments(records):
    raise NotImplementedError


def compute_refunds(records):
    raise NotImplementedError


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = matched_count - refund_total
    unmatched_ids = sorted(set(match['RECORD_ID'] for match in matches if match['status'] != 'matched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': max(net_total, 0),
        'unmatched_ids': unmatched_ids
    }

