"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str):
        return None
    text = s.strip()
    if not text:
        return None
    negative = text.startswith("-")
    unsigned = text[1:] if negative else text
    if not unsigned or unsigned.count(".") > 1:
        return None
    parts = unsigned.split(".")
    if not parts[0].isdigit():
        return None
    fraction = parts[1] if len(parts) == 2 else ""
    if fraction and not fraction.isdigit():
        return None
    if len(fraction) > 3:
        return None
    try:
        value = Decimal(text)
        cents = int(
            value.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP) * 100
        )
    except (InvalidOperation, ValueError, TypeError, OverflowError):
        return None
    if abs(cents) > 1000000:
        return None
    return cents


def parse_record(line):
    if not isinstance(line, str):
        return None
    parts = line.strip().split("|")
    if len(parts) != 6:
        return None
    record_type, record_id, order_id, amount_text, currency, timestamp = (
        part.strip() for part in parts
    )
    record_type = record_type.upper()
    if record_type not in ("ORDER", "PAYMENT"):
        return None
    if not record_id or not order_id or currency != "USD":
        return None
    amount = parse_amount(amount_text)
    if amount is None or (record_type == "ORDER" and amount < 0):
        return None
    parsed_timestamp = _valid_timestamp(timestamp)
    if parsed_timestamp is None:
        return None
    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": parsed_timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []
    records = []
    seen = set()
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None and record["record_id"] not in seen:
            seen.add(record["record_id"])
            records.append(record)
    return records


def match_payments(records):
    if not isinstance(records, list):
        return []
    orders = []
    payments = []
    for position, record in enumerate(records):
        if not isinstance(record, dict):
            continue
        if record.get("type") == "ORDER":
            orders.append(record)
        elif (
            record.get("type") == "PAYMENT"
            and isinstance(record.get("amount"), int)
            and record["amount"] >= 0
        ):
            payments.append((position, record))

    results = []
    for order in orders:
        start = order.get("timestamp")
        amount = order.get("amount")
        candidates = []
        if isinstance(start, datetime) and isinstance(amount, int):
            end = start + timedelta(hours=72)
            for position, payment in payments:
                payment_time = payment.get("timestamp")
                if (
                    payment.get("order_id") == order.get("order_id")
                    and payment.get("amount") == amount
                    and isinstance(payment_time, datetime)
                ):
                    try:
                        qualifies = start <= payment_time < end
                    except TypeError:
                        qualifies = False
                    if qualifies:
                        candidates.append((payment_time, position, payment))
        if candidates:
            candidates.sort(key=lambda item: (item[0], item[1]))
            results.append({
                "order_id": order.get("order_id"),
                "status": "matched",
                "amount": candidates[0][2]["amount"],
            })
        else:
            results.append({
                "order_id": order.get("order_id"),
                "status": "unmatched",
                "amount": 0,
            })
    return results


def compute_refunds(records):
    if not isinstance(records, list):
        return 0
    order_ids = {
        record.get("order_id")
        for record in records
        if isinstance(record, dict) and record.get("type") == "ORDER"
    }
    total = 0
    for record in records:
        if (
            isinstance(record, dict)
            and record.get("type") == "PAYMENT"
            and isinstance(record.get("amount"), int)
            and record["amount"] < 0
            and record.get("order_id") in order_ids
        ):
            total += -record["amount"]
    return total


def build_summary(matches, refund_total):
    if not isinstance(matches, list):
        matches = []
    matched = [
        item for item in matches
        if isinstance(item, dict) and item.get("status") == "matched"
    ]
    unmatched = {
        item.get("order_id")
        for item in matches
        if (
            isinstance(item, dict)
            and item.get("status") != "matched"
            and item.get("order_id") is not None
        )
    }
    refunds = refund_total if isinstance(refund_total, int) else 0
    payment_total = sum(
        item.get("amount", 0)
        for item in matched
        if isinstance(item.get("amount", 0), int)
    )
    return {
        "total_orders": len(matches),
        "matched_count": len(matched),
        "refund_total": refunds,
        "net_total": max(0, payment_total - refunds),
        "unmatched_ids": sorted(unmatched),
    }

