"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        if not isinstance(s, str):
            return None
        text = s.strip()
        if not text:
            return None
        negative = text.startswith("-")
        body = text[1:] if negative else text
        if not body or body.count(".") > 1:
            return None
        if any(ch not in "0123456789." for ch in body):
            return None
        whole, dot, fraction = body.partition(".")
        if not whole and not fraction:
            return None
        if not any(ch.isdigit() for ch in body) or len(fraction) > 3:
            return None
        value = Decimal(text)
        cents = value.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        result = int(cents * 100)
        if abs(result) > 1000000:
            return None
        return result
    except (InvalidOperation, ValueError, TypeError, OverflowError):
        return None


def parse_record(line):
    try:
        if not isinstance(line, str):
            return None
        fields = line.split("|")
        if len(fields) != 6:
            return None
        record_type, record_id, order_id, amount, currency, timestamp = fields
        record_type = record_type.strip().upper()
        record_id = record_id.strip()
        order_id = order_id.strip()
        currency = currency.strip()
        if record_type not in ("ORDER", "PAYMENT"):
            return None
        if not record_id or not order_id or not order_id.startswith("ORD-"):
            return None
        if currency != "USD":
            return None
        cents = parse_amount(amount)
        if cents is None or (record_type == "ORDER" and cents < 0):
            return None
        stamp = timestamp.strip()
        parsed_time = None
        for fmt in ("%Y-%m-%d %H:%M", "%Y-%m-%d %H:%M:%S"):
            try:
                parsed_time = datetime.strptime(stamp, fmt)
                break
            except ValueError:
                continue
        if parsed_time is None:
            return None
        return {
            "type": record_type,
            "record_id": record_id,
            "order_id": order_id,
            "amount": cents,
            "currency": currency,
            "timestamp": parsed_time,
        }
    except (TypeError, ValueError, AttributeError):
        return None


def load_records(text):
    if not isinstance(text, str):
        return []
    records = []
    seen = set()
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None and record["record_id"] not in seen:
            seen.add(record["record_id"])
            records.append(record)
    return records


def match_payments(records):
    if not isinstance(records, list):
        return []
    payments = []
    for index, record in enumerate(records):
        if (isinstance(record, dict)
                and record.get("type") == "PAYMENT"
                and isinstance(record.get("amount"), int)
                and not isinstance(record.get("amount"), bool)
                and record["amount"] >= 0
                and isinstance(record.get("timestamp"), datetime)):
            payments.append((index, record))

    results = []
    for order in records:
        if not isinstance(order, dict) or order.get("type") != "ORDER":
            continue
        order_id = order.get("order_id")
        amount = order.get("amount")
        start = order.get("timestamp")
        candidates = []
        if (isinstance(order_id, str)
                and isinstance(amount, int)
                and not isinstance(amount, bool)
                and isinstance(start, datetime)):
            end = start + timedelta(hours=72)
            for index, payment in payments:
                if (payment.get("order_id") == order_id
                        and payment.get("amount") == amount
                        and start <= payment["timestamp"] < end):
                    candidates.append((payment["timestamp"], index, payment))
        if candidates:
            candidates.sort(key=lambda item: (item[0], item[1]))
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": candidates[0][2]["amount"],
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })
    return results


def compute_refunds(records):
    if not isinstance(records, list):
        return 0
    order_ids = {
        record.get("order_id")
        for record in records
        if isinstance(record, dict) and record.get("type") == "ORDER"
    }
    total = 0
    for record in records:
        if (isinstance(record, dict)
                and record.get("type") == "PAYMENT"
                and isinstance(record.get("amount"), int)
                and not isinstance(record.get("amount"), bool)
                and record["amount"] < 0
                and record.get("order_id") in order_ids):
            total += -record["amount"]
    return total


def build_summary(matches, refund_total):
    if not isinstance(matches, list):
        matches = []
    matched_count = 0
    matched_total = 0
    unmatched = set()
    for result in matches:
        if not isinstance(result, dict):
            continue
        if result.get("status") == "matched":
            matched_count += 1
            amount = result.get("amount")
            if isinstance(amount, int) and not isinstance(amount, bool):
                matched_total += amount
        elif isinstance(result.get("order_id"), str):
            unmatched.add(result["order_id"])
    if not isinstance(refund_total, int) or isinstance(refund_total, bool):
        refund_total = 0
    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "refund_total": refund_total,
        "net_total": max(0, matched_total - refund_total),
        "unmatched_ids": sorted(unmatched),
    }

"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str):
        return None

    text = s.strip()
    if not text:
        return None

    if text.startswith("-"):
        digits = text[1:]
    else:
        digits = text

    if not digits:
        return None

    if digits.count(".") > 1:
        return None

    if "." in digits:
        whole, fraction = digits.split(".", 1)
        if not whole or not whole.isdigit():
            return None
        if not fraction or not fraction.isdigit() or len(fraction) > 3:
            return None
    elif not digits.isdigit():
        return None

    try:
        value = Decimal(text)
        if not value.is_finite():
            return None

        rounded = value.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        cents = int(rounded * 100)
    except (InvalidOperation, ValueError, TypeError, OverflowError):
        return None

    if abs(cents) > 1_000_000:
        return None

    return cents


def parse_record(line):
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 6:
        return None

    record_type = fields[0].strip().upper()
    record_id = fields[1].strip()
    order_id = fields[2].strip()
    amount_text = fields[3].strip()
    currency = fields[4].strip()
    timestamp = fields[5].strip()

    if record_type not in ("ORDER", "PAYMENT"):
        return None

    if not record_id or not order_id:
        return None

    if (
        len(currency) != 3
        or any(character < "A" or character > "Z" for character in currency)
    ):
        return None

    if _parse_timestamp(timestamp) is None:
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None

    if record_type == "ORDER" and amount < 0:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []

    records = []
    seen_ids = set()

    for line in text.splitlines():
        record = parse_record(line)
        if record is None:
            continue

        record_id = record["record_id"]
        if record_id in seen_ids:
            continue

        seen_ids.add(record_id)
        records.append(record)

    return records


def match_payments(records):
    if not isinstance(records, list):
        return []

    payments = []

    for source_index, record in enumerate(records):
        if not isinstance(record, dict):
            continue
        if record.get("type") != "PAYMENT":
            continue

        amount = record.get("amount")
        if not isinstance(amount, int) or isinstance(amount, bool) or amount < 0:
            continue

        payment_time = _parse_timestamp(record.get("timestamp"))
        if payment_time is None:
            continue

        payments.append((source_index, record, payment_time))

    results = []

    for record in records:
        if not isinstance(record, dict):
            continue
        if record.get("type") != "ORDER":
            continue

        order_id = record.get("order_id")
        order_time = _parse_timestamp(record.get("timestamp"))
        best_payment = None

        if order_time is not None:
            latest_time = order_time + timedelta(hours=72)

            for source_index, payment, payment_time in payments:
                if payment.get("order_id") != order_id:
                    continue

                if payment_time < order_time or payment_time >= latest_time:
                    continue

                if (
                    best_payment is None
                    or payment_time < best_payment[0]
                    or (
                        payment_time == best_payment[0]
                        and source_index < best_payment[1]
                    )
                ):
                    best_payment = (payment_time, source_index, payment)

        if best_payment is None:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": best_payment[2].get("amount"),
            })

    return results


def compute_refunds(records):
    if not isinstance(records, list):
        return 0

    existing_orders = set()

    for record in records:
        if not isinstance(record, dict):
            continue
        if record.get("type") != "ORDER":
            continue

        order_id = record.get("order_id")
        amount = record.get("amount")

        if order_id and isinstance(amount, int) and not isinstance(amount, bool):
            if amount >= 0:
                existing_orders.add(order_id)

    refund_total = 0

    for record in records:
        if not isinstance(record, dict):
            continue
        if record.get("type") != "PAYMENT":
            continue
        if record.get("order_id") not in existing_orders:
            continue

        amount = record.get("amount")
        if isinstance(amount, int) and not isinstance(amount, bool) and amount < 0:
            refund_total += -amount

    return refund_total


def build_summary(matches, refund_total):
    if not isinstance(matches, list):
        matches = []

    total_orders = len(matches)
    matched_count = 0
    matched_amount = 0
    unmatched_ids = set()

    for result in matches:
        if not isinstance(result, dict):
            continue

        if result.get("status") == "matched":
            matched_count += 1
            amount = result.get("amount", 0)
            if isinstance(amount, (int, float, Decimal)):
                matched_amount += amount
        else:
            order_id = result.get("order_id")
            if order_id is not None:
                unmatched_ids.add(str(order_id))

    if not isinstance(refund_total, (int, float, Decimal)):
        refund_total = 0

    net_total = matched_amount - refund_total
    if net_total < 0:
        net_total = 0

    return {
        "total_orders": total_orders,
        "matched_count": matched_count,
        "refund_total": refund_total,
        "net_total": net_total,
        "unmatched_ids": sorted(unmatched_ids),
    }

