"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str) or s == "":
        return None

    negative = False
    if s.startswith("-"):
        negative = True
        s = s[1:]
    if s == "" or s.count(".") > 1:
        return None

    if "." in s:
        whole, fraction = s.split(".")
    else:
        whole, fraction = s, ""

    if whole == "" or not whole.isdigit():
        return None
    if not fraction.isdigit() or len(fraction) > 3:
        return None

    cents = int(whole) * 100
    if len(fraction) >= 1:
        cents += int(fraction[:2].ljust(2, "0"))
    if len(fraction) == 3 and fraction[2] >= "5":
        cents += 1

    if negative:
        cents = -cents
    if abs(cents) > 1000000:
        return None
    return cents


def parse_record(line):
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount_text, currency, timestamp_text = fields
    record_type = record_type.upper()
    if record_type not in ("ORDER", "PAYMENT"):
        return None

    record_id = record_id.strip()
    order_id = order_id.strip()
    if not record_id or not order_id or not order_id.startswith("ORD-"):
        return None
    if currency != "USD":
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None
    if record_type == "ORDER" and amount < 0:
        return None

    timestamp = None
    for fmt in ("%Y-%m-%d %H:%M", "%Y-%m-%d %H:%M:%S"):
        try:
            timestamp = datetime.strptime(timestamp_text, fmt)
            break
        except (TypeError, ValueError):
            pass
    if timestamp is None:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []

    retained = []
    seen_ids = set()

    for line in text.splitlines():
        try:
            record = parse_record(line)
        except Exception:
            record = None
        if record is None:
            continue

        record_id = record["record_id"]
        if record_id in seen_ids:
            continue
        seen_ids.add(record_id)
        retained.append(record)

    return retained


def match_payments(records):
    results = []
    orders = []
    payments = []

    try:
        for record in records:
            if record.get("type") == "ORDER":
                orders.append(record)
            elif (
                record.get("type") == "PAYMENT"
                and record.get("amount", 0) >= 0
            ):
                payments.append(record)
    except Exception:
        return results

    for order in orders:
        order_id = order["order_id"]
        order_time = order["timestamp"]
        limit = order_time + timedelta(hours=72)
        selected = None

        for payment in payments:
            if payment["order_id"] != order_id:
                continue
            payment_time = payment["timestamp"]
            if order_time <= payment_time < limit:
                if selected is None or payment_time < selected["timestamp"]:
                    selected = payment

        if selected is None:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": selected["amount"],
            })

    return results


def compute_refunds(records):
    try:
        order_ids = {
            record["order_id"]
            for record in records
            if (
                isinstance(record, dict)
                and record.get("type") == "ORDER"
                and record.get("currency") == "USD"
            )
        }
    except Exception:
        return 0

    total = 0
    try:
        for record in records:
            if not isinstance(record, dict):
                continue
            if record.get("type") != "PAYMENT":
                continue
            if record.get("currency") != "USD":
                continue
            amount = record.get("amount")
            if type(amount) is not int or amount >= 0:
                continue
            if record.get("order_id") not in order_ids:
                continue
            total += abs(amount)
    except Exception:
        return total

    return total


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = 0
    matched_total = 0
    unmatched_ids = set()

    for result in matches:
        if result.get("status") == "matched":
            matched_count += 1
            matched_total += result.get("amount", 0)
        elif result.get("status") == "unmatched":
            unmatched_ids.add(result.get("order_id"))

    net_total = matched_total - refund_total
    if net_total < 0:
        net_total = 0

    return {
        "total_orders": total_orders,
        "matched_count": matched_count,
        "refund_total": refund_total,
        "net_total": net_total,
        "unmatched_ids": sorted(unmatched_ids),
    }

