"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str) or not s:
        return None
    negative = s.startswith("-")
    value = s[1:] if negative else s
    if not value or value.count(".") > 1:
        return None
    if "." in value:
        whole, fraction = value.split(".")
    else:
        whole, fraction = value, ""
    if not whole.isdigit() or (fraction and not fraction.isdigit()):
        return None
    if len(fraction) > 3:
        return None
    padded = fraction.ljust(3, "0")
    cents = int(whole) * 100 + int(padded[:2])
    if int(padded[2]) >= 5:
        cents += 1
    if negative:
        cents = -cents
    return cents if abs(cents) <= 1000000 else None


def parse_record(line):
    if not isinstance(line, str):
        return None
    try:
        fields = line.split("|")
        if len(fields) != 6:
            return None
        kind, record_id, order_id, amount_text, currency, time_text = fields
        kind = kind.upper()
        record_id = record_id.strip()
        order_id = order_id.strip()
        if kind not in ("ORDER", "PAYMENT"):
            return None
        if not record_id or not order_id.startswith("ORD-"):
            return None
        if currency != "USD":
            return None
        amount = parse_amount(amount_text)
        if amount is None or (kind == "ORDER" and amount < 0):
            return None
        if len(time_text) == 16:
            fmt = "%Y-%m-%d %H:%M"
        elif len(time_text) == 19:
            fmt = "%Y-%m-%d %H:%M:%S"
        else:
            return None
        timestamp = datetime.strptime(time_text, fmt)
        return {"type": kind, "record_id": record_id, "order_id": order_id,
                "amount": amount, "currency": currency, "timestamp": timestamp}
    except (TypeError, ValueError, OverflowError):
        return None


def load_records(text):
    if not isinstance(text, str):
        return []
    result = []
    seen = set()
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None and record["record_id"] not in seen:
            seen.add(record["record_id"])
            result.append(record)
    return result


def match_payments(records):
    result = []
    try:
        for order in records:
            if not isinstance(order, dict) or order.get("type") != "ORDER":
                continue
            start = order["timestamp"]
            end = start + timedelta(hours=72)
            selected = None
            for payment in records:
                if not isinstance(payment, dict):
                    continue
                if payment.get("type") != "PAYMENT":
                    continue
                if payment.get("order_id") != order.get("order_id"):
                    continue
                if payment.get("currency") != "USD":
                    continue
                if not isinstance(payment.get("amount"), int) or payment["amount"] < 0:
                    continue
                timestamp = payment.get("timestamp")
                if timestamp < start or timestamp >= end:
                    continue
                if selected is None or timestamp < selected["timestamp"]:
                    selected = payment
            if selected is None:
                result.append({"order_id": order["order_id"],
                               "status": "unmatched", "amount": 0})
            else:
                result.append({"order_id": order["order_id"],
                               "status": "matched",
                               "amount": selected["amount"]})
        return result
    except (TypeError, KeyError, AttributeError, OverflowError):
        return []


def compute_refunds(records):
    try:
        order_ids = {r["order_id"] for r in records
                     if isinstance(r, dict) and r.get("type") == "ORDER"}
        total = 0
        for record in records:
            if (isinstance(record, dict)
                    and record.get("type") == "PAYMENT"
                    and record.get("currency") == "USD"
                    and isinstance(record.get("amount"), int)
                    and record["amount"] < 0
                    and record.get("order_id") in order_ids):
                total += -record["amount"]
        return total
    except (TypeError, KeyError):
        return 0


def build_summary(matches, refund_total):
    try:
        total_orders = len(matches)
        matched_count = 0
        matched_total = 0
        unmatched = set()
        for match in matches:
            if not isinstance(match, dict):
                continue
            if match.get("status") == "matched":
                matched_count += 1
                amount = match.get("amount")
                if isinstance(amount, int):
                    matched_total += amount
            elif match.get("status") == "unmatched":
                unmatched.add(match.get("order_id"))
        net_total = matched_total - refund_total
        if net_total < 0:
            net_total = 0
        return {
            "total_orders": total_orders,
            "matched_count": matched_count,
            "refund_total": refund_total,
            "net_total": net_total,
            "unmatched_ids": sorted(unmatched),
        }
    except (TypeError, ValueError):
        return {
            "total_orders": 0,
            "matched_count": 0,
            "refund_total": refund_total,
            "net_total": 0,
            "unmatched_ids": [],
        }

