from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str) or not s:
        return None

    if s.startswith("-"):
        digits = s[1:]
    else:
        digits = s

    if not digits or digits.count(".") > 1:
        return None

    parts = digits.split(".")
    if not parts[0].isdigit():
        return None
    if len(parts) == 2 and (
        not parts[1].isdigit() or len(parts[1]) > 3
    ):
        return None

    try:
        amount = Decimal(s).quantize(
            Decimal("0.01"),
            rounding=ROUND_HALF_UP
        )
        cents = int(amount * 100)
    except (InvalidOperation, ValueError, OverflowError):
        return None

    if abs(cents) > 1_000_000:
        return None

    return cents


def parse_record(line):
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 6:
        return None

    record_type = fields[0].upper()
    if record_type not in ("ORDER", "PAYMENT"):
        return None

    record_id = fields[1].strip()
    order_id = fields[2].strip()

    if not record_id or not order_id:
        return None
    if not order_id.startswith("ORD-"):
        return None
    if fields[4] != "USD":
        return None

    amount = parse_amount(fields[3])
    if amount is None:
        return None
    if record_type == "ORDER" and amount < 0:
        return None

    timestamp_text = fields[5]
    if len(timestamp_text) not in (16, 19):
        return None

    if (
        timestamp_text[4] != "-"
        or timestamp_text[7] != "-"
        or timestamp_text[10] != " "
        or timestamp_text[13] != ":"
    ):
        return None

    if len(timestamp_text) == 19 and timestamp_text[16] != ":":
        return None

    digit_positions = (
        list(range(0, 4))
        + list(range(5, 7))
        + list(range(8, 10))
        + list(range(11, 13))
        + list(range(14, 16))
    )
    if len(timestamp_text) == 19:
        digit_positions += list(range(17, 19))

    if any(
        not ("0" <= timestamp_text[index] <= "9")
        for index in digit_positions
    ):
        return None

    try:
        year = int(timestamp_text[0:4])
        month = int(timestamp_text[5:7])
        day = int(timestamp_text[8:10])
        hour = int(timestamp_text[11:13])
        minute = int(timestamp_text[14:16])
        second = int(timestamp_text[17:19]) if len(timestamp_text) == 19 else 0
        timestamp = datetime(
            year, month, day, hour, minute, second
        )
    except (ValueError, OverflowError):
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": fields[4],
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []

    retained = []
    seen_record_ids = set()

    for line in text.splitlines():
        record = parse_record(line)
        if record is None:
            continue

        record_id = record["record_id"]
        if record_id in seen_record_ids:
            continue

        seen_record_ids.add(record_id)
        retained.append(record)

    return retained


def match_payments(records):
    results = []

    for order in records:
        if order["type"] != "ORDER":
            continue

        order_time = order["timestamp"]
        deadline = order_time + timedelta(hours=72)
        selected = None

        for source_index, payment in enumerate(records):
            if payment["type"] != "PAYMENT":
                continue
            if payment["amount"] < 0:
                continue
            if payment["order_id"] != order["order_id"]:
                continue

            payment_time = payment["timestamp"]
            if not (order_time <= payment_time < deadline):
                continue

            if selected is None:
                selected = (payment_time, source_index, payment)
            elif (payment_time, source_index) < selected[:2]:
                selected = (payment_time, source_index, payment)

        if selected is None:
            results.append({
                "order_id": order["order_id"],
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order["order_id"],
                "status": "matched",
                "amount": selected[2]["amount"],
            })

    return results


def compute_refunds(records):
    if not isinstance(records, (list, tuple)):
        return 0

    order_ids = set()

    for record in records:
        if not isinstance(record, dict):
            continue
        if (
            record.get("type") == "ORDER"
            and record.get("currency") == "USD"
            and isinstance(record.get("order_id"), str)
        ):
            order_ids.add(record["order_id"])

    refund_total = 0

    for record in records:
        if not isinstance(record, dict):
            continue

        if (
            record.get("type") == "PAYMENT"
            and record.get("currency") == "USD"
            and record.get("order_id") in order_ids
        ):
            amount = record.get("amount")
            if isinstance(amount, int) and not isinstance(amount, bool):
                if amount < 0:
                    refund_total += abs(amount)

    return refund_total


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = 0
    matched_total = 0
    unmatched_ids = set()

    for result in matches:
        if result.get("status") == "matched":
            matched_count += 1
            matched_total += result.get("amount", 0)
        elif result.get("status") == "unmatched":
            order_id = result.get("order_id")
            if isinstance(order_id, str):
                unmatched_ids.add(order_id)

    net_total = matched_total - refund_total
    if net_total < 0:
        net_total = 0

    return {
        "total_orders": total_orders,
        "matched_count": matched_count,
        "refund_total": refund_total,
        "net_total": net_total,
        "unmatched_ids": sorted(unmatched_ids),
    }

"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str) or not s.strip():
        return None

    try:
        # Convert to Decimal
        amount = Decimal(s)
    except (InvalidOperation, ValueError):
        return None

    # Check for scientific notation
    if 'e' in s.lower() or 'E' in s:
        return None

    # Round to at most 3 decimal places
    amount = amount.quantize(Decimal('0.001'), rounding=ROUND_HALF_UP)

    # Convert to cents
    amount_in_cents = int(amount * 100)

    # Check for negative values and the absolute limit
    if amount_in_cents < -1000000 or amount_in_cents > 1000000:
        return None

    return amount_in_cents


def parse_record(line):
    fields = line.strip().split('|')

    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount_str, currency, timestamp_str = fields

    # Validate TYPE
    record_type = record_type.strip().upper()
    if record_type not in ['ORDER', 'PAYMENT']:
        return None

    # Validate RECORD_ID and ORDER_ID
    record_id = record_id.strip()
    order_id = order_id.strip()
    if not record_id or not order_id.startswith('ORD-'):
        return None

    # Validate CURRENCY
    currency = currency.strip()
    if currency != 'USD':
        return None

    # Parse AMOUNT
    amount = parse_amount(amount_str.strip())
    if amount is None or (record_type == 'ORDER' and amount < 0):
        return None

    # Validate TIMESTAMP
    try:
        timestamp = datetime.strptime(timestamp_str.strip(), '%Y-%m-%d %H:%M:%S')
    except ValueError:
        try:
            timestamp = datetime.strptime(timestamp_str.strip(), '%Y-%m-%d %H:%M')
        except ValueError:
            return None

    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount,
        'currency': currency,
        'timestamp': timestamp
    }


def load_records(text):
    records = []
    seen_record_ids = set()

    for line in text.strip().splitlines():
        record = parse_record(line)
        if record and record['record_id'] not in seen_record_ids:
            records.append(record)
            seen_record_ids.add(record['record_id'])

    return records


def match_payments(records):
    orders = [record for record in records if record['type'] == 'ORDER']
    payments = [record for record in records if record['type'] == 'PAYMENT' and record['amount'] >= 0]

    results = []

    for order in orders:
        order_id = order['order_id']
        order_timestamp = order['timestamp']
        end_timestamp = order_timestamp + timedelta(hours=72)

        # Find matching payments
        matching_payments = [
            payment for payment in payments
            if payment['order_id'] == order_id and order_timestamp <= payment['timestamp'] < end_timestamp
        ]

        if matching_payments:
            # Sort by timestamp, then by record_id
            matching_payments.sort(key=lambda p: (p['timestamp'], p['record_id']))
            selected_payment = matching_payments[0]
            results.append({
                'order_id': order_id,
                'status': 'matched',
                'amount': selected_payment['amount']
            })
        else:
            results.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': 0
            })

    return results


def compute_refunds(records):
    refund_total = 0

    # Create a set of valid order_ids from the records
    valid_order_ids = {record['order_id'] for record in records if record['type'] == 'ORDER'}

    for record in records:
        # Check for negative payment records with valid order_ids
        if record['type'] == 'PAYMENT' and record['amount'] < 0 and record['order_id'] in valid_order_ids:
            refund_total += abs(record['amount'])

    return refund_total


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = max(sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total, 0)
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] == 'unmatched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

