"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str):
        return None
    value = s.strip()
    if not value:
        return None
    negative = value.startswith("-")
    body = value[1:] if negative else value
    if not body or body.count(".") > 1:
        return None
    whole, dot, fraction = body.partition(".")
    if not whole.isdigit():
        return None
    if dot and fraction and not fraction.isdigit():
        return None
    if len(fraction) > 3:
        return None
    try:
        number = Decimal(value)
        cents = int((number * Decimal("100")).quantize(
            Decimal("1"), rounding=ROUND_HALF_UP))
    except (InvalidOperation, ValueError, OverflowError):
        return None
    if abs(cents) > 1000000:
        return None
    return cents


def parse_record(line):
    if not isinstance(line, str):
        return None
    fields = line.split("|")
    if len(fields) != 6:
        return None
    kind, record_id, order_id, amount_text, currency, timestamp_text = fields
    kind = kind.strip().upper()
    record_id = record_id.strip()
    order_id = order_id.strip()
    currency = currency.strip()
    timestamp_text = timestamp_text.strip()
    if kind not in ("ORDER", "PAYMENT"):
        return None
    if not record_id or not order_id or not order_id.startswith("ORD-"):
        return None
    if currency != "USD":
        return None
    amount = parse_amount(amount_text)
    if amount is None or (kind == "ORDER" and amount < 0):
        return None
    timestamp = None
    for fmt in ("%Y-%m-%d %H:%M", "%Y-%m-%d %H:%M:%S"):
        try:
            timestamp = datetime.strptime(timestamp_text, fmt)
            break
        except (TypeError, ValueError):
            continue
    if timestamp is None:
        return None
    return {
        "type": kind,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []
    records = []
    seen = set()
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None and record["record_id"] not in seen:
            seen.add(record["record_id"])
            records.append(record)
    return records


def match_payments(records):
    if not isinstance(records, list):
        return []
    orders = []
    order_ids = set()
    for record in records:
        if not isinstance(record, dict):
            continue
        if record.get("type") != "ORDER":
            continue
        if record.get("currency", "USD") != "USD":
            continue
        order_id = record.get("order_id")
        if order_id not in order_ids:
            order_ids.add(order_id)
            orders.append(record)

    results = []
    for order in orders:
        start = order.get("timestamp")
        if not isinstance(start, datetime):
            results.append({
                "order_id": order.get("order_id"),
                "status": "unmatched",
                "amount": 0,
            })
            continue
        end = start + timedelta(hours=72)
        best = None
        best_index = None
        for index, payment in enumerate(records):
            if not isinstance(payment, dict):
                continue
            if payment.get("type") != "PAYMENT":
                continue
            if payment.get("currency", "USD") != "USD":
                continue
            if payment.get("order_id") != order.get("order_id"):
                continue
            amount = payment.get("amount")
            timestamp = payment.get("timestamp")
            if not isinstance(amount, int) or amount < 0:
                continue
            if not isinstance(timestamp, datetime) or timestamp < start:
                continue
            if timestamp >= end:
                continue
            if best is None or timestamp < best["timestamp"]:
                best = payment
                best_index = index
            elif timestamp == best["timestamp"] and index < best_index:
                best = payment
                best_index = index
        if best is None:
            results.append({
                "order_id": order.get("order_id"),
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order.get("order_id"),
                "status": "matched",
                "amount": best.get("amount"),
            })
    return results


def compute_refunds(records):
    if not isinstance(records, list):
        return 0
    order_ids = set()
    for record in records:
        if isinstance(record, dict) and record.get("type") == "ORDER":
            if record.get("currency", "USD") == "USD":
                order_ids.add(record.get("order_id"))
    total = 0
    for record in records:
        if not isinstance(record, dict):
            continue
        if record.get("type") != "PAYMENT":
            continue
        if record.get("currency", "USD") != "USD":
            continue
        amount = record.get("amount")
        if isinstance(amount, int) and amount < 0:
            if record.get("order_id") in order_ids:
                total -= amount
    return total


def build_summary(matches, refund_total):
    if not isinstance(matches, list):
        matches = []
    matched_count = 0
    matched_amount = 0
    unmatched_ids = set()
    for item in matches:
        if not isinstance(item, dict):
            continue
        if item.get("status") == "matched":
            matched_count += 1
            matched_amount += item.get("amount", item.get("payment_amount", 0))
        else:
            identifier = item.get("order_id")
            if identifier is not None:
                unmatched_ids.add(identifier)
    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "refund_total": refund_total,
        "net_total": max(0, matched_amount - refund_total),
        "unmatched_ids": sorted(unmatched_ids),
    }

