"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        amount = int(Decimal(s) * 100)
        if abs(amount) > 1000000:
            return None
        return amount
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.strip().split('|')
    if len(fields) != 6:
        return None
    record_type, record_id, order_id, amount, currency, timestamp = fields
    if record_type.upper() != 'ORDER' and record_type.upper() != 'PAYMENT':
        return None
    record_id = record_id.strip()
    order_id = order_id.strip()
    amount = parse_amount(amount.strip())
    if not record_id or not order_id or amount is None or currency != 'USD':
        return None
    try:
        timestamp = datetime.strptime(timestamp.strip(), '%Y-%m-%d %H:%M:%S')
    except ValueError:
        try:
            timestamp = datetime.strptime(timestamp.strip(), '%Y-%m-%d %H:%M')
        except ValueError:
            return None
    return {
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount,
        'currency': currency,
        'timestamp': timestamp
    }


def load_records(text):
    raise NotImplementedError


def match_payments(records):
    raise NotImplementedError


def compute_refunds(records):
    return sum(-record['amount'] for record in records if record['type'] == 'PAYMENT' and record['amount'] < 0)


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = max(0, sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total)
    unmatched_ids = sorted(set(match['record_id'] for match in matches if match['status'] != 'matched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

