"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str):
        return None
    value = s.strip()
    if not value:
        return None
    body = value[1:] if value.startswith("-") else value
    if not body or body.count(".") > 1:
        return None
    parts = body.split(".")
    if not parts[0] and not (len(parts) > 1 and parts[1]):
        return None
    if parts[0] and not parts[0].isdigit():
        return None
    if len(parts) > 1 and parts[1] and not parts[1].isdigit():
        return None
    fraction = parts[1] if len(parts) == 2 else ""
    if len(fraction) > 3:
        return None
    try:
        amount = Decimal(value)
        cents = (amount * Decimal("100")).quantize(
            Decimal("1"), rounding=ROUND_HALF_UP
        )
        result = int(cents)
    except (InvalidOperation, ValueError, OverflowError):
        return None
    if abs(result) > 1000000:
        return None
    return result


def parse_record(line):
    if not isinstance(line, str):
        return None
    fields = line.split("|")
    if len(fields) != 6:
        return None
    kind, record_id, order_id, amount, currency, timestamp = fields
    kind = kind.strip().upper()
    record_id = record_id.strip()
    order_id = order_id.strip()
    currency = currency.strip()
    if kind not in ("ORDER", "PAYMENT"):
        return None
    if not record_id or not order_id or not order_id.startswith("ORD-"):
        return None
    if currency != "USD":
        return None
    cents = parse_amount(amount)
    if cents is None or (kind == "ORDER" and cents < 0):
        return None
    timestamp = timestamp.strip()
    parsed_time = None
    for format_string in ("%Y-%m-%d %H:%M", "%Y-%m-%d %H:%M:%S"):
        try:
            parsed_time = datetime.strptime(timestamp, format_string)
            break
        except (TypeError, ValueError):
            pass
    if parsed_time is None:
        return None
    return {
        "type": kind,
        "record_id": record_id,
        "order_id": order_id,
        "amount": cents,
        "currency": currency,
        "timestamp": parsed_time,
    }


def load_records(text):
    if not isinstance(text, str):
        return []
    records = []
    seen = set()
    for line in text.splitlines():
        try:
            record = parse_record(line)
        except Exception:
            record = None
        if record is not None and record["record_id"] not in seen:
            seen.add(record["record_id"])
            records.append(record)
    return records


def match_payments(records):
    if not isinstance(records, list):
        return []
    orders = [
        record for record in records
        if isinstance(record, dict) and record.get("type") == "ORDER"
    ]
    payments = [
        record for record in records
        if isinstance(record, dict) and record.get("type") == "PAYMENT"
    ]
    results = []
    for order in orders:
        order_id = order.get("order_id")
        start = order.get("timestamp")
        candidates = []
        if isinstance(start, datetime):
            end = start + timedelta(hours=72)
            for index, payment in enumerate(payments):
                if payment.get("amount", 0) < 0:
                    continue
                if payment.get("order_id") != order_id:
                    continue
                timestamp = payment.get("timestamp")
                if isinstance(timestamp, datetime) and start <= timestamp < end:
                    candidates.append((timestamp, index, payment))
        if candidates:
            candidates.sort(key=lambda item: (item[0], item[1]))
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": candidates[0][2].get("amount", 0),
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })
    return results


def compute_refunds(records):
    if not isinstance(records, list):
        return 0
    order_ids = {
        record.get("order_id")
        for record in records
        if isinstance(record, dict) and record.get("type") == "ORDER"
    }
    total = 0
    for record in records:
        if not isinstance(record, dict):
            continue
        if record.get("type") != "PAYMENT":
            continue
        if record.get("order_id") not in order_ids:
            continue
        amount = record.get("amount")
        if isinstance(amount, int) and amount < 0:
            total += -amount
    return total


def build_summary(matches, refund_total):
    if not isinstance(matches, list):
        matches = []
    total_orders = len(matches)
    matched_count = 0
    matched_total = 0
    unmatched = set()
    for result in matches:
        if not isinstance(result, dict):
            continue
        if result.get("status") == "matched":
            matched_count += 1
            amount = result.get("payment_amount", result.get("amount", 0))
            if isinstance(amount, int):
                matched_total += amount
        else:
            order_id = result.get("order_id")
            if isinstance(order_id, str):
                unmatched.add(order_id)
    if not isinstance(refund_total, int):
        refund_total = 0
    net_total = max(0, matched_total - refund_total)
    return {
        "total_orders": total_orders,
        "matched_count": matched_count,
