"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        amount = Decimal(s)
        if abs(amount) > 1000000:
            return None
        return int(amount * 100)  # Convert to cents
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.strip().split('|')
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount, currency, timestamp = map(str.strip, fields)

    # Validate TYPE
    if record_type.upper() not in ['ORDER', 'PAYMENT']:
        return None

    # Validate IDs
    if not record_id or not order_id:
        return None

    # Validate AMOUNT
    parsed_amount = parse_amount(amount)
    if parsed_amount is None:
        return None

    # Validate CURRENCY
    if len(currency) != 3:
        return None

    # Validate TIMESTAMP
    try:
        datetime.fromisoformat(timestamp)
    except ValueError:
        return None

    return {
        'type': record_type.upper(),
        'record_id': record_id,
        'order_id': order_id,
        'amount': parsed_amount,
        'currency': currency,
        'timestamp': timestamp,
    }


def load_records(text):
    records = []
    for line in text.strip().splitlines():
        record = parse_record(line)
        if record is not None:
            if not any(r['record_id'] == record['record_id'] for r in records):
                records.append(record)
    return records


def match_payments(records):
    orders = {}
    payments = []

    for record in records:
        if record['type'] == 'ORDER':
            orders[record['order_id']] = {
                'timestamp': datetime.fromisoformat(record['timestamp']),
                'amount': record['amount'],
                'matched': False
            }
        elif record['type'] == 'PAYMENT':
            payments.append(record)

    results = []

    for payment in payments:
        order_id = payment['order_id']
        if order_id in orders:
            order_info = orders[order_id]
            payment_time = datetime.fromisoformat(payment['timestamp'])
            time_limit = order_info['timestamp'] + timedelta(hours=72)

            if order_info['matched'] is False and order_info['timestamp'] <= payment_time < time_limit:
                results.append({
                    'order_id': order_id,
                    'status': 'matched',
                    'amount': payment['amount']
                })
                order_info['matched'] = True  # Mark order as matched
            else:
                results.append({
                    'order_id': order_id,
                    'status': 'unmatched',
                    'amount': 0
                })
        else:
            results.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': 0
            })

    # Add unmatched orders that have not been matched
    for order_id, order_info in orders.items():
        if not order_info['matched']:
            results.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': 0
            })

    return results


def compute_refunds(records):
    refund_total = sum(record['amount'] for record in records if record['type'] == 'PAYMENT' and record['amount'] < 0)
    return max(0, refund_total)  # Ensure refund total is non-negative


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = max(0, sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total)
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] != 'matched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids,
    }

