from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str) or not s:
        return None

    if s.startswith("-"):
        number = s[1:]
    else:
        number = s

    if not number:
        return None

    parts = number.split(".")
    if len(parts) > 2:
        return None

    whole = parts[0]
    if not whole.isdigit():
        return None

    if len(parts) == 2:
        fraction = parts[1]
        if not fraction or not fraction.isdigit() or len(fraction) > 3:
            return None

    try:
        cents = Decimal(s) * Decimal("100")
        cents = cents.quantize(Decimal("1"), rounding=ROUND_HALF_UP)
        cents = int(cents)
    except (InvalidOperation, ValueError, OverflowError):
        return None

    if abs(cents) > 1000000:
        return None

    return cents


def parse_record(line):
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 6:
        return None

    type_value, record_id, order_id, amount_text, currency, timestamp_text = fields
    type_value = type_value.upper()

    if type_value not in ("ORDER", "PAYMENT"):
        return None

    record_id = record_id.strip()
    order_id = order_id.strip()

    if not record_id or not order_id:
        return None

    if not order_id.startswith("ORD-"):
        return None

    if currency != "USD":
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None

    if type_value == "ORDER" and amount < 0:
        return None

    timestamp = None

    try:
        if len(timestamp_text) == 16:
            timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
            if timestamp.strftime("%Y-%m-%d %H:%M") != timestamp_text:
                return None
        elif len(timestamp_text) == 19:
            timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M:%S")
            if timestamp.strftime("%Y-%m-%d %H:%M:%S") != timestamp_text:
                return None
        else:
            return None
    except (TypeError, ValueError, OverflowError):
        return None

    return {
        "type": type_value,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []

    records = []
    seen_record_ids = set()

    for line in text.splitlines():
        try:
            record = parse_record(line)
        except Exception:
            record = None

        if record is None:
            continue

        record_id = record["record_id"]
        if record_id in seen_record_ids:
            continue

        seen_record_ids.add(record_id)
        records.append(record)

    return records


def match_payments(records):
    try:
        retained_records = list(records)
    except TypeError:
        return []

    payments = []
    orders = []

    for source_index, record in enumerate(retained_records):
        if not isinstance(record, dict):
            continue

        try:
            record_type = record.get("type")
            currency = record.get("currency")
            order_id = record.get("order_id")
            amount = record.get("amount")
            timestamp = record.get("timestamp")
        except Exception:
            continue

        if record_type == "ORDER" and currency == "USD":
            orders.append(record)
        elif (
            record_type == "PAYMENT"
            and currency == "USD"
            and isinstance(order_id, str)
            and isinstance(amount, int)
            and not isinstance(amount, bool)
            and amount >= 0
            and isinstance(timestamp, datetime)
        ):
            payments.append((source_index, record))

    results = []

    for order in orders:
        try:
            order_id = order["order_id"]
            order_timestamp = order["timestamp"]
        except (KeyError, TypeError):
            continue

        selected = None
        selected_key = None

        if isinstance(order_id, str) and isinstance(order_timestamp, datetime):
            limit = order_timestamp + timedelta(hours=72)

            for source_index, payment in payments:
                try:
                    if payment["order_id"] != order_id:
                        continue

                    payment_timestamp = payment["timestamp"]
                    if not (
                        order_timestamp <= payment_timestamp < limit
                    ):
                        continue

                    candidate_key = (payment_timestamp, source_index)
                    if selected_key is None or candidate_key < selected_key:
                        selected = payment
                        selected_key = candidate_key
                except (KeyError, TypeError):
                    continue

        if selected is None:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": selected["amount"],
            })

    return results


def compute_refunds(records):
    order_ids = set()
    negative_payments = []

    try:
        iterator = iter(records)
    except TypeError:
        return 0

    for record in iterator:
        if not isinstance(record, dict):
            continue

        try:
            record_type = record.get("type")
            currency = record.get("currency")
            order_id = record.get("order_id")
            amount = record.get("amount")
        except Exception:
            continue

        if record_type == "ORDER" and currency == "USD":
            if isinstance(order_id, str):
                order_ids.add(order_id)
        elif (
            record_type == "PAYMENT"
            and currency == "USD"
            and isinstance(order_id, str)
            and isinstance(amount, int)
            and not isinstance(amount, bool)
            and amount < 0
        ):
            negative_payments.append((order_id, amount))

    total = 0
    for order_id, amount in negative_payments:
        if order_id in order_ids:
            total += abs(amount)

    return total


def build_summary(matches, refund_total):
