def parse_amount(s):
    """Return a valid monetary amount as integer cents, or None."""
    if not isinstance(s, str):
        return None

    value = s.strip()
    if not value or not _AMOUNT_PATTERN.fullmatch(value):
        return None

    try:
        amount = Decimal(value)
        if not amount.is_finite():
            return None

        cents = (amount * Decimal("100")).quantize(
            Decimal("1"),
            rounding=ROUND_HALF_UP,
        )
        cents = int(cents)
    except (InvalidOperation, ValueError, OverflowError):
        return None

    if abs(cents) > 1_000_000:
        return None

    return cents


def parse_record(line):
    """Parse one input line and return a record dictionary, or None."""
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount, currency, timestamp = (
        field.strip() for field in fields
    )

    record_type = record_type.upper()
    if record_type not in {"ORDER", "PAYMENT"}:
        return None

    if not record_id or not order_id:
        return None

    if not _CURRENCY_PATTERN.fullmatch(currency):
        return None

    timestamp_text = timestamp
    if timestamp_text.endswith("Z"):
        timestamp_text = timestamp_text[:-1] + "+00:00"

    if not timestamp_text:
        return None

    try:
        parsed_timestamp = datetime.fromisoformat(timestamp_text)
    except (TypeError, ValueError):
        return None

    if not isinstance(parsed_timestamp, datetime):
        return None

    parsed_amount = parse_amount(amount)
    if parsed_amount is None:
        return None

    if record_type == "ORDER" and parsed_amount < 0:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": parsed_amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    """Parse valid lines, retaining only the first valid record ID."""
    if not isinstance(text, str):
        return []

    records = []
    seen_ids = set()

    for line in text.splitlines():
        record = parse_record(line)
        if record is None:
            continue

        record_id = record["record_id"]
        if record_id in seen_ids:
            continue

        seen_ids.add(record_id)
        records.append(record)

    return records


def match_payments(records):
    """Return one matching result for each order in retained order."""
    if not isinstance(records, list):
        return []

    def parse_timestamp(value):
        if not isinstance(value, str):
            return None

        text = value.strip()
        if not text:
            return None

        if text.endswith("Z"):
            text = text[:-1] + "+00:00"

        try:
            return datetime.fromisoformat(text)
        except (TypeError, ValueError):
            return None

    orders = []
    payments = []

    for source_index, record in enumerate(records):
        if not isinstance(record, dict):
            continue

        if record.get("type") == "ORDER":
            orders.append((source_index, record))
        elif record.get("type") == "PAYMENT":
            amount = record.get("amount")
            if isinstance(amount, int) and not isinstance(amount, bool):
                if amount >= 0:
                    payments.append((source_index, record))

    results = []
    used_payment_indexes = set()

    for _, order in orders:
        order_id = order.get("order_id")
        order_timestamp = parse_timestamp(order.get("timestamp"))
        candidates = []

        if order_timestamp is not None:
            window_end = order_timestamp + timedelta(hours=72)

            for source_index, payment in payments:
                if source_index in used_payment_indexes:
                    continue
                if payment.get("order_id") != order_id:
                    continue
                if payment.get("currency") != order.get("currency"):
                    continue
                if payment.get("amount") != order.get("amount"):
                    continue

                payment_timestamp = parse_timestamp(payment.get("timestamp"))
                if payment_timestamp is None:
                    continue

                try:
                    in_window = (
                        order_timestamp
                        <= payment_timestamp
                        < window_end
                    )
                except TypeError:
                    continue

                if in_window:
                    candidates.append(
                        (payment_timestamp, source_index, payment)
                    )

        if candidates:
            _, payment_source_index, payment = min(
                candidates,
                key=lambda candidate: (candidate[0], candidate[1]),
            )
            used_payment_indexes.add(payment_source_index)
            results.append(
                {
                    "order_id": order_id,
                    "status": "matched",
                    "amount": payment.get("amount"),
                }
            )
        else:
            results.append(
                {
                    "order_id": order_id,
                    "status": "unmatched",
                    "amount": 0,
                }
            )

    return results


def compute_refunds(records):
    """Return the total value of refunds for existing orders, in cents."""
    if not isinstance(records, list):
        return 0

    order_ids = {
        record.get("order_id")
        for record in records
        if isinstance(record, dict)
        and record.get("type") == "ORDER"
    }

    total = 0
    for record in records:
        if not isinstance(record, dict):
            continue
        if record.get("type") != "PAYMENT":
            continue
        if record.get("order_id") not in order_ids:
