    if not value or value.count(".") > 1:
        return None

    parts = value.split(".")
    whole = parts[0]
    fraction = parts[1] if len(parts) == 2 else ""

    if not whole or any(char not in "0123456789" for char in whole):
        return None
    if len(fraction) > 3:
        return None
    if fraction and any(char not in "0123456789" for char in fraction):
        return None
    if len(parts) == 2 and not fraction:
        return None

    cents_fraction = (fraction + "00")[:2]
    cents = int(whole) * 100 + int(cents_fraction)

    if len(fraction) == 3 and fraction[2] >= "5":
        cents += 1

    if negative:
        cents = -cents

    if abs(cents) > 1000000:
        return None
    return cents


def parse_record(line):
