    except (TypeError, ValueError):
        return None

    if timestamp.strftime(timestamp_format) != timestamp_text:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


