"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        if isinstance(s, bool) or s is None:
            return None
        if isinstance(s, int):
            cents = s * 100
        else:
            text = str(s).strip()
            if not text:
                return None
            if not __import__("re").fullmatch(r"-?\d+(?:\.\d{0,3})?", text):
                return None
            cents = int(
                Decimal(text).quantize(
                    Decimal("0.01"), rounding=ROUND_HALF_UP
                ) * 100
            )
        if abs(cents) > 1_000_000:
            return None
        return cents
    except (InvalidOperation, ValueError, TypeError, ArithmeticError):
        return None


def parse_record(line):
    if not isinstance(line, str):
        return None
    parts = line.strip().split("|")
    if len(parts) != 6:
        return None
    kind, record_id, order_id, amount_text, currency, timestamp = (
        part.strip() for part in parts
    )
    kind = kind.upper()
    if kind not in ("ORDER", "PAYMENT"):
        return None
    if not record_id or not order_id or not order_id.startswith("ORD-"):
        return None
    if currency != "USD":
        return None
    valid_time = False
    for pattern in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%d %H:%M"):
        try:
            datetime.strptime(timestamp, pattern)
            valid_time = True
            break
        except (TypeError, ValueError):
            pass
    if not valid_time:
        return None
    amount = parse_amount(amount_text)
    if amount is None or (kind == "ORDER" and amount < 0):
        return None
    return {
        "type": kind,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []
    records = []
    seen = set()
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None and record["record_id"] not in seen:
            seen.add(record["record_id"])
            records.append(record)
    return records


def match_payments(records):
    if not isinstance(records, list):
        return []
    orders = {}
    for record in records:
        if not isinstance(record, dict):
            continue
        order_id = record.get("order_id")
        if (
            record.get("type") == "ORDER"
            and record.get("currency") == "USD"
            and isinstance(order_id, str)
            and order_id not in orders
        ):
            orders[order_id] = record

    results = []
    for order_id, order in orders.items():
        order_time = None
        for pattern in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%d %H:%M"):
            try:
                order_time = datetime.strptime(order["timestamp"], pattern)
                break
            except (KeyError, TypeError, ValueError):
                pass

        chosen = None
        chosen_time = None
        if order_time is not None:
            deadline = order_time + timedelta(hours=72)
            for record in records:
                if not isinstance(record, dict):
                    continue
                if (
                    record.get("type") != "PAYMENT"
                    or record.get("currency") != "USD"
                    or record.get("order_id") != order_id
                    or not isinstance(record.get("amount"), int)
                    or isinstance(record.get("amount"), bool)
                    or record.get("amount") < 0
                ):
                    continue
                payment_time = None
                for pattern in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%d %H:%M"):
                    try:
                        payment_time = datetime.strptime(record["timestamp"], pattern)
                        break
                    except (KeyError, TypeError, ValueError):
                        pass
                if (
                    payment_time is not None
                    and order_time <= payment_time < deadline
                    and (chosen_time is None or payment_time < chosen_time)
                ):
                    chosen = record
                    chosen_time = payment_time

        if chosen is None:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": chosen["amount"],
            })
    return results


def compute_refunds(records):
    if not isinstance(records, list):
        return 0
    order_ids = {
        record.get("order_id")
        for record in records
        if (
            isinstance(record, dict)
            and record.get("type") == "ORDER"
            and record.get("currency") == "USD"
            and isinstance(record.get("order_id"), str)
        )
    }
    total = 0
    for record in records:
        if (
            isinstance(record, dict)
            and record.get("type") == "PAYMENT"
            and record.get("currency") == "USD"
            and record.get("order_id") in order_ids
            and isinstance(record.get("amount"), int)
            and not isinstance(record.get("amount"), bool)
            and record["amount"] < 0
        ):
            total += -record["amount"]
    return total


def build_summary(matches, refund_total):
    if not isinstance(matches, list):
        matches = []
    valid_matches = [item for item in matches if isinstance(item, dict)]
    matched = [item for item in valid_matches if item.get("status") == "matched"]
    matched_total = sum(
        item.get("amount", 0)
        for item in matched
        if isinstance(item.get("amount", 0), int)
        and not isinstance(item.get("amount", 0), bool)
    )
    refund = (
        refund_total
        if isinstance(refund_total, int) and not isinstance(refund_total, bool)
        else 0
    )
    unmatched_ids = sorted({
        item.get("order_id")
        for item in valid_matches
        if item.get("status") == "unmatched"
        and isinstance(item.get("order_id"), str)
    })
    return {
        "total_orders": len(valid_matches),
        "matched_count": len(matched),
        "refund_total": refund,
        "net_total": max(0, matched_total - refund),
        "unmatched_ids": unmatched_ids,
    }

