from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str) or not s:
        return None

    if s.startswith("-"):
        number = s[1:]
    else:
        number = s

    if not number or number.count(".") > 1:
        return None

    if "." in number:
        whole, fraction = number.split(".")
        if not whole or not fraction:
            return None
    else:
        whole = number
        fraction = ""

    if not whole.isascii() or not whole.isdigit():
        return None
    if fraction and (not fraction.isascii() or not fraction.isdigit()):
        return None
    if len(fraction) > 3:
        return None

    try:
        amount = Decimal(s).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        cents = int(amount * 100)
    except (InvalidOperation, ValueError):
        return None

    if abs(cents) > 1_000_000:
        return None

    return cents


def parse_record(line):
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount_text, currency, timestamp_text = fields

    record_type = record_type.upper()
    if record_type not in ("ORDER", "PAYMENT"):
        return None

    record_id = record_id.strip()
    order_id = order_id.strip()

    if not record_id or not order_id or not order_id.startswith("ORD-"):
        return None

    if currency != "USD":
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None

    if record_type == "ORDER" and amount < 0:
        return None

    if len(timestamp_text) not in (16, 19):
        return None

    if (
        timestamp_text[4] != "-"
        or timestamp_text[7] != "-"
        or timestamp_text[10] != " "
        or timestamp_text[13] != ":"
    ):
        return None

    if len(timestamp_text) == 19 and timestamp_text[16] != ":":
        return None

    digit_positions = (
        list(range(0, 4))
        + list(range(5, 7))
        + list(range(8, 10))
        + list(range(11, 13))
        + list(range(14, 16))
    )
    if len(timestamp_text) == 19:
        digit_positions += list(range(17, 19))

    if any(not timestamp_text[index].isdigit() for index in digit_positions):
        return None

    try:
        if len(timestamp_text) == 16:
            timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
        else:
            timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M:%S")
    except (TypeError, ValueError):
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []

    retained = []
    seen_record_ids = set()

    for line in text.splitlines():
        try:
            record = parse_record(line)
        except Exception:
            record = None

        if record is None:
            continue

        record_id = record["record_id"]
        if record_id in seen_record_ids:
            continue

        seen_record_ids.add(record_id)
        retained.append(record)

    return retained


