    results = []

    for order in records:
        if order["type"] != "ORDER":
            continue

        order_id = order["order_id"]
        order_time = order["timestamp"]
        end_time = order_time + timedelta(hours=72)
        selected = None

        for payment in records:
            if payment["type"] != "PAYMENT":
                continue
            if payment["order_id"] != order_id:
                continue
            if payment["amount"] < 0:
                continue
            if not (order_time <= payment["timestamp"] < end_time):
                continue

            if selected is None or payment["timestamp"] < selected["timestamp"]:
                selected = payment

        if selected is None:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": selected["amount"],
            })

    return results


def compute_refunds(records):
    try:
        items = list(records)
    except Exception:
        return 0

    order_ids = set()
    for record in items:
        if not isinstance(record, dict):
            continue
        try:
            if record.get("type") == "ORDER":
                order_ids.add(record.get("order_id"))
        except Exception:
            continue

    refund_total = 0
    for record in items:
        if not isinstance(record, dict):
