    if not isinstance(line, str):
        return None

    parts = line.split("|")
    if len(parts) != 6:
        return None

    (
        record_type,
        record_id,
        order_id,
        amount_text,
        currency,
        timestamp_text,
    ) = (part.strip() for part in parts)

    record_type = record_type.upper()
    if record_type not in {"ORDER", "PAYMENT"}:
        return None

