    if amount is None:
        return None

    if record_type == "ORDER" and amount < 0:
        return None

    try:
        iso_timestamp = timestamp_text
        if iso_timestamp.endswith("Z"):
            iso_timestamp = iso_timestamp[:-1] + "+00:00"
        timestamp_value = datetime.fromisoformat(iso_timestamp)
    except (TypeError, ValueError):
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
