def match_payments(records):
    """Return one matching result for each order."""
    if not isinstance(records, list):
        return []

    orders = [
        record
        for record in records
        if (
            isinstance(record, dict)
            and record.get("type") == "ORDER"
            and isinstance(record.get("order_id"), str)
        )
    ]

    payments = []
    for source_index, record in enumerate(records):
        if not isinstance(record, dict):
            continue
        if record.get("type") != "PAYMENT":
            continue

        amount = record.get("amount")
        timestamp = record.get("timestamp")

        if not isinstance(amount, int) or isinstance(amount, bool) or amount < 0:
            continue
        if not isinstance(timestamp, datetime):
            continue

        payments.append((source_index, record))

    results = []

    for order in orders:
        order_timestamp = order.get("timestamp")
        order_id = order.get("order_id")
        order_currency = order.get("currency")

        best_payment = None
        best_timestamp = None
        best_source_index = None

        if isinstance(order_timestamp, datetime):
            deadline = order_timestamp + timedelta(hours=72)

            for source_index, payment in payments:
                if payment.get("order_id") != order_id:
                    continue
                if payment.get("currency") != order_currency:
                    continue

                payment_timestamp = payment.get("timestamp")

                try:
                    qualifies = (
                        order_timestamp
                        <= payment_timestamp
                        < deadline
                    )
                except TypeError:
                    qualifies = False

                if not qualifies:
                    continue

                if (
                    best_payment is None
                    or payment_timestamp < best_timestamp
                    or (
                        payment_timestamp == best_timestamp
                        and source_index < best_source_index
                    )
                ):
                    best_payment = payment
                    best_timestamp = payment_timestamp
                    best_source_index = source_index

        if best_payment is None:
            results.append(
                {
                    "order_id": order_id,
                    "status": "unmatched",
                    "amount": 0,
                }
            )
        else:
            results.append(
                {
                    "order_id": order_id,
                    "status": "matched",
                    "amount": best_payment["amount"],
                }
            )

    return results


def compute_refunds(records):
    """Return the total of refunds linked to existing orders, in cents."""
    if not isinstance(records, list):
        return 0

    order_ids = {
        record.get("order_id")
        for record in records
        if (
            isinstance(record, dict)
            and record.get("type") == "ORDER"
            and isinstance(record.get("order_id"), str)
            and record.get("order_id")
        )
    }

    total = 0

    for record in records:
        if not isinstance(record, dict):
            continue
        if record.get("type") != "PAYMENT":
            continue
        if record.get("order_id") not in order_ids:
            continue

        amount = record.get("amount")
        if (
            isinstance(amount, int)
            and not isinstance(amount, bool)
            and amount < 0
        ):
            total += -amount

    return total


