"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str):
        return None
    text = s.strip()
    if not text:
        return None
    digits = text[1:] if text.startswith("-") else text
    if not digits or digits.count(".") > 1:
        return None
    parts = digits.split(".")
    if not parts[0].isdigit():
        return None
    if len(parts) == 2 and parts[1] and not parts[1].isdigit():
        return None
    fraction = parts[1] if len(parts) == 2 else ""
    if len(fraction) > 3:
        return None
    try:
        value = Decimal(text)
        cents = int((value * Decimal("100")).quantize(
            Decimal("1"), rounding=ROUND_HALF_UP
        ))
    except (InvalidOperation, ValueError, OverflowError):
        return None
    if abs(cents) > 1000000:
        return None
    return cents


def parse_record(line):
    if not isinstance(line, str):
        return None
    fields = line.split("|")
    if len(fields) != 6:
        return None
    kind, record_id, order_id, amount, currency, stamp = fields
    kind = kind.strip().upper()
    record_id = record_id.strip()
    order_id = order_id.strip()
    if kind not in ("ORDER", "PAYMENT"):
        return None
    if not record_id or not order_id or not order_id.startswith("ORD-"):
        return None
    if currency.strip() != "USD":
        return None
    value = parse_amount(amount)
    if value is None or (kind == "ORDER" and value < 0):
        return None
    stamp = stamp.strip()
    parsed_time = None
    for fmt in ("%Y-%m-%d %H:%M", "%Y-%m-%d %H:%M:%S"):
        try:
            parsed_time = datetime.strptime(stamp, fmt)
            break
        except (TypeError, ValueError):
            pass
    if parsed_time is None:
        return None
    return {
        "type": kind,
        "record_id": record_id,
        "order_id": order_id,
        "amount": value,
        "currency": "USD",
        "timestamp": parsed_time,
    }


def load_records(text):
    if not isinstance(text, str):
        return []
    records = []
    seen = set()
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None and record["record_id"] not in seen:
            seen.add(record["record_id"])
            records.append(record)
    return records


def match_payments(records):
    if not isinstance(records, list):
        return []
    orders = []
    order_ids = set()
    for record in records:
        if isinstance(record, dict) and record.get("type") == "ORDER":
            order_id = record.get("order_id")
            if order_id not in order_ids:
                order_ids.add(order_id)
                orders.append(record)

    results = []
    for order in orders:
        order_id = order.get("order_id")
        order_amount = order.get("amount")
        order_time = order.get("timestamp")
        candidates = []
        for source_index, payment in enumerate(records):
            if not isinstance(payment, dict):
                continue
            if payment.get("type") != "PAYMENT":
                continue
            if payment.get("order_id") != order_id:
                continue
            amount = payment.get("amount")
            payment_time = payment.get("timestamp")
            if (not isinstance(amount, int) or isinstance(amount, bool)
                    or amount < 0 or not isinstance(order_amount, int)
                    or isinstance(order_amount, bool)
                    or not isinstance(order_time, datetime)
                    or not isinstance(payment_time, datetime)):
                continue
            if amount < order_amount:
                continue
            if not (order_time <= payment_time <
                    order_time + timedelta(hours=72)):
                continue
            candidates.append((payment_time, source_index, payment))
        if candidates:
            selected = min(candidates, key=lambda item: (item[0], item[1]))[2]
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": selected.get("amount"),
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })
    return results


def compute_refunds(records):
    if not isinstance(records, list):
        return 0
    order_ids = {
        record.get("order_id") for record in records
        if isinstance(record, dict) and record.get("type") == "ORDER"
    }
    total = 0
    for record in records:
        if not isinstance(record, dict):
            continue
        amount = record.get("amount")
        if (record.get("type") == "PAYMENT"
                and isinstance(amount, int)
                and not isinstance(amount, bool)
                and amount < 0
                and record.get("order_id") in order_ids):
            total += -amount
    return total


def build_summary(matches, refund_total):
    if not isinstance(matches, list):
        matches = []
    matched = [
        item for item in matches
        if isinstance(item, dict) and item.get("status") == "matched"
    ]
    unmatched = sorted({
        item.get("order_id") for item in matches
        if isinstance(item, dict)
        and item.get("status") == "unmatched"
        and isinstance(item.get("order_id"), str)
    })
    refunds = refund_total if isinstance(refund_total, int) else 0
    matched_total = sum(
        item.get("amount", 0) for item in matched
        if isinstance(item.get("amount", 0), int)
        and not isinstance(item.get("amount", 0), bool)
    )
    return {
        "total_orders": len(matches),
        "matched_count": len(matched),
        "refund_total": refunds,
        "net_total": max(0, matched_total - refunds),
        "unmatched_ids": unmatched,
    }

"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str) or not s:
        return None

    negative = s.startswith("-")
    if negative:
        s = s[1:]

    if not s or s.count(".") > 1:
        return None

    if "." in s:
        whole, fraction = s.split(".")
        if not whole or not fraction:
            return None
    else:
        whole, fraction = s, ""

    if not whole.isascii() or not whole.isdigit():
        return None
    if fraction and (not fraction.isascii() or not fraction.isdigit()):
        return None
    if len(fraction) > 3:
        return None

    significant_whole = whole.lstrip("0")
    if len(significant_whole) > 5:
        return None

    whole_cents = int(whole) * 100

    if len(fraction) == 0:
        fractional_cents = 0
    elif len(fraction) == 1:
        fractional_cents = int(fraction) * 10
    elif len(fraction) == 2:
        fractional_cents = int(fraction)
    else:
        fractional_cents = int(fraction[:2])
        if int(fraction[2]) >= 5:
            fractional_cents += 1

    cents = whole_cents + fractional_cents
    if negative:
        cents = -cents

    if abs(cents) > 1_000_000:
        return None

    return cents


def parse_record(line):
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount_text, currency, timestamp_text = fields
    record_type = record_type.upper()
    record_id = record_id.strip()
    order_id = order_id.strip()

    if record_type not in ("ORDER", "PAYMENT"):
        return None
    if not record_id or not order_id:
        return None
    if not order_id.startswith("ORD-"):
        return None
    if currency != "USD":
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None
    if record_type == "ORDER" and amount < 0:
        return None

    if len(timestamp_text) not in (16, 19):
        return None

    if (
        timestamp_text[4] != "-"
        or timestamp_text[7] != "-"
        or timestamp_text[10] != " "
        or timestamp_text[13] != ":"
    ):
        return None

    if len(timestamp_text) == 19 and timestamp_text[16] != ":":
        return None

    digit_parts = timestamp_text[:4] + timestamp_text[5:7] + timestamp_text[8:10]
    digit_parts += timestamp_text[11:13] + timestamp_text[14:16]
    if len(timestamp_text) == 19:
        digit_parts += timestamp_text[17:19]

    if not digit_parts.isascii() or not digit_parts.isdigit():
        return None

    try:
        if len(timestamp_text) == 16:
            timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
        else:
            timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M:%S")
    except (TypeError, ValueError):
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []

    records = []
    seen_record_ids = set()

    for line in text.splitlines():
        try:
            record = parse_record(line)
        except Exception:
            continue

        if record is None:
            continue

        record_id = record["record_id"]
        if record_id in seen_record_ids:
            continue

        seen_record_ids.add(record_id)
        records.append(record)

    return records


def match_payments(records):
    if records is None:
        return []

    try:
        record_list = list(records)
    except (TypeError, ValueError):
        return []

    orders = []
    payments = []

    for source_index, record in enumerate(record_list):
        if not isinstance(record, dict):
            continue

        if record.get("type") == "ORDER":
            orders.append((source_index, record))
        elif record.get("type") == "PAYMENT":
            amount = record.get("amount")
            if type(amount) is int and amount >= 0:
                payments.append((source_index, record))

    results = []

    for _, order in orders:
        order_id = order.get("order_id")
        order_timestamp = order.get("timestamp")

        best_payment = None
        best_key = None

        if isinstance(order_timestamp, datetime):
            deadline = order_timestamp + timedelta(hours=72)

            for source_index, payment in payments:
                if payment.get("order_id") != order_id:
                    continue

                payment_timestamp = payment.get("timestamp")
                if not isinstance(payment_timestamp, datetime):
                    continue

                if order_timestamp <= payment_timestamp < deadline:
                    key = (payment_timestamp, source_index)
                    if best_key is None or key < best_key:
                        best_key = key
                        best_payment = payment

        if best_payment is None:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": best_payment["amount"],
            })

    return results


def compute_refunds(records):
    """Return qualifying refund amounts as a positive total in cents."""
    if records is None:
        return 0

    try:
        record_list = list(records)
    except (TypeError, ValueError):
        return 0

    order_ids = set()
    for record in record_list:
        if not isinstance(record, dict):
            continue
        if record.get("type") != "ORDER":
            continue
        if record.get("currency") != "USD":
            continue

        order_id = record.get("order_id")
        if isinstance(order_id, str):
            order_ids.add(order_id)

    refund_total = 0
    for record in record_list:
        if not isinstance(record, dict):
            continue
        if record.get("type") != "PAYMENT":
            continue
        if record.get("currency") != "USD":
            continue

        order_id = record.get("order_id")
        amount = record.get("amount")

        if order_id not in order_ids:
            continue
        if type(amount) is not int or amount >= 0:
            continue

        refund_total += abs(amount)

    return refund_total


def build_summary(matches, refund_total):
    try:
        result_list = list(matches)
    except (TypeError, ValueError):
        result_list = []

    matched_count = 0
    matched_total = 0
    unmatched_ids = set()

    for result in result_list:
        if not isinstance(result, dict):
            continue

        status = result.get("status")

        if status == "matched":
            matched_count += 1
            amount = result.get("amount")
            if type(amount) is int:
                matched_total += amount
        elif status == "unmatched":
            order_id = result.get("order_id")
            if isinstance(order_id, str):
                unmatched_ids.add(order_id)

    if type(refund_total) is not int:
        refund_total = 0

    net_total = matched_total - refund_total
    if net_total < 0:
        net_total = 0

    return {
        "total_orders": len(result_list),
        "matched_count": matched_count,
        "refund_total": refund_total,
        "net_total": net_total,
        "unmatched_ids": sorted(unmatched_ids),
    }

