from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        if not isinstance(s, str):
            return None
        text = s.strip()
        if not text:
            return None
        sign = ""
        body = text
        if body.startswith("-"):
            sign, body = "-", body[1:]
        if not body or body.count(".") > 1:
            return None
        parts = body.split(".")
        if not parts[0].isdigit():
            return None
        if len(parts) == 2 and parts[1] and not parts[1].isdigit():
            return None
        fraction = parts[1] if len(parts) == 2 else ""
        if len(fraction) > 3:
            return None
        value = Decimal(sign + body)
        cents = (value * Decimal("100")).quantize(
            Decimal("1"), rounding=ROUND_HALF_UP
        )
        result = int(cents)
        return None if abs(result) > 1000000 else result
    except (InvalidOperation, ValueError, TypeError, OverflowError):
        return None


def parse_record(line):
    try:
        if not isinstance(line, str):
            return None
        fields = line.split("|")
        if len(fields) != 6:
            return None
        kind, record_id, order_id, amount, currency, timestamp = fields
        kind = kind.strip().upper()
        record_id = record_id.strip()
        order_id = order_id.strip()
        currency = currency.strip()
        if kind not in ("ORDER", "PAYMENT"):
            return None
        if not record_id or not order_id or not currency:
            return None
        if not order_id.startswith("ORD-") or currency != "USD":
            return None
        cents = parse_amount(amount)
        if cents is None or (kind == "ORDER" and cents < 0):
            return None
        timestamp = timestamp.strip()
        parsed = None
        for fmt in ("%Y-%m-%d %H:%M", "%Y-%m-%d %H:%M:%S"):
            try:
                parsed = datetime.strptime(timestamp, fmt)
                break
            except (TypeError, ValueError):
                pass
        if parsed is None:
            return None
        return {
            "type": kind,
            "record_id": record_id,
            "order_id": order_id,
            "amount": cents,
            "currency": currency,
            "timestamp": parsed,
        }
    except Exception:
        return None


def load_records(text):
    if not isinstance(text, str):
        return []
    result = []
    seen = set()
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None and record["record_id"] not in seen:
            seen.add(record["record_id"])
            result.append(record)
    return result


def match_payments(records):
    if not isinstance(records, list):
        return []
    orders = {}
    for record in records:
        if isinstance(record, dict) and record.get("type") == "ORDER":
            order_id = record.get("order_id")
            if order_id not in orders:
                orders[order_id] = record

    results = []
    for order_id, order in orders.items():
        start = order.get("timestamp")
        best = None
        if isinstance(start, datetime):
            end = start + timedelta(hours=72)
            for payment in records:
                if not isinstance(payment, dict):
                    continue
                if payment.get("type") != "PAYMENT":
                    continue
                if payment.get("order_id") != order_id:
                    continue
                amount = payment.get("amount")
                timestamp = payment.get("timestamp")
                if (isinstance(amount, int) and amount >= 0 and
                        isinstance(timestamp, datetime) and
                        start <= timestamp < end):
                    if best is None or timestamp < best[0]:
                        best = (timestamp, amount)
        if best is None:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": best[1],
            })
    return results


def compute_refunds(records):
    if not isinstance(records, list):
        return 0
    order_ids = {
        record.get("order_id")
        for record in records
        if isinstance(record, dict) and record.get("type") == "ORDER"
    }
    total = 0
    for record in records:
        if (isinstance(record, dict) and
                record.get("type") == "PAYMENT" and
                record.get("order_id") in order_ids and
                isinstance(record.get("amount"), int) and
                record["amount"] < 0):
            total -= record["amount"]
    return total


def build_summary(matches, refund_total):
    if not isinstance(matches, list):
        matches = []
    if not isinstance(refund_total, int):
        refund_total = 0
    matched_count = 0
    matched_total = 0
    unmatched_ids = set()
    for item in matches:
        if not isinstance(item, dict):
            continue
        if item.get("status") == "matched":
            matched_count += 1
            if isinstance(item.get("amount"), int):
                matched_total += item["amount"]
        elif isinstance(item.get("order_id"), str):
            unmatched_ids.add(item["order_id"])
    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "refund_total": refund_total,
        "net_total": max(0, matched_total - refund_total),
        "unmatched_ids": sorted(unmatched_ids),
    }

