from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    """Convert a decimal dollar amount to integer cents, or return None."""
    if not isinstance(s, str):
        return None

    value = s.strip()
    if not value or not _AMOUNT_PATTERN.fullmatch(value):
        return None

    try:
        with localcontext() as context:
            context.prec = max(
                28,
                len(value.replace("-", "").replace("+", "").replace(".", ""))
                + 10,
            )
            amount = Decimal(value)
            if not amount.is_finite():
                return None

            cents = amount.quantize(
                Decimal("0.01"),
                rounding=ROUND_HALF_UP,
            ) * 100

        cents = int(cents)
        if abs(cents) > 1_000_000:
            return None
        return cents

    except (InvalidOperation, ValueError, OverflowError):
        return None


def parse_record(line):
    """Parse one pipe-separated order or payment record."""
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 6:
        return None

    (
        record_type,
        record_id,
        order_id,
        amount_text,
        currency,
        timestamp,
    ) = (field.strip() for field in fields)

    record_type = record_type.upper()
    if record_type not in {"ORDER", "PAYMENT"}:
        return None

    if not record_id or not order_id:
        return None

    if not _CURRENCY_PATTERN.fullmatch(currency):
        return None

    if _parse_timestamp(timestamp) is None:
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None

    if record_type == "ORDER" and amount < 0:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    """Load valid records, keeping the first valid record ID."""
    if not isinstance(text, str):
        return []

    records = []
    seen_ids = set()

    for line in text.splitlines():
        record = parse_record(line)
        if record is None:
            continue

        record_id = record["record_id"]
        if record_id in seen_ids:
            continue

        seen_ids.add(record_id)
        records.append(record)

    return records


def match_payments(records):
    """Match each retained order with its earliest qualifying payment."""
    if not isinstance(records, list):
        return []

    orders = []
    payments = []

    for source_index, record in enumerate(records):
        if not isinstance(record, dict):
            continue

        if record.get("type") == "ORDER":
            orders.append((source_index, record))
        elif record.get("type") == "PAYMENT":
            payments.append((source_index, record))

    results = []

    for _, order in orders:
        order_id = order.get("order_id")
        order_amount = order.get("amount")
        order_currency = order.get("currency")
        order_time = _parse_timestamp(order.get("timestamp"))

        best_payment = None
        best_key = None

        if (
            isinstance(order_id, str)
            and isinstance(order_amount, int)
            and not isinstance(order_amount, bool)
            and order_time is not None
        ):
            end_time = order_time + timedelta(hours=72)

            for payment_index, payment in payments:
                if payment.get("order_id") != order_id:
                    continue
                if payment.get("currency") != order_currency:
                    continue

                payment_amount = payment.get("amount")
                if (
                    not isinstance(payment_amount, int)
                    or isinstance(payment_amount, bool)
                    or payment_amount < 0
                    or payment_amount != order_amount
                ):
                    continue

                payment_time = _parse_timestamp(payment.get("timestamp"))
                if payment_time is None:
                    continue

                try:
                    qualifies = (
                        order_time <= payment_time < end_time
                    )
                except TypeError:
                    qualifies = False

                if not qualifies:
                    continue

                key = (payment_time, payment_index)
                if best_key is None or key < best_key:
                    best_key = key
                    best_payment = payment

        if best_payment is None:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": best_payment["amount"],
            })

    return results


def compute_refunds(records):
    """Return the positive total of qualifying negative payments."""
    if not isinstance(records, list):
        return 0

    order_ids = {
        record.get("order_id")
        for record in records
        if isinstance(record, dict) and record.get("type") == "ORDER"
    }

    refund_total = 0

    for record in records:
        if not isinstance(record, dict):
            continue
        if record.get("type") != "PAYMENT":
            continue
        if record.get("order_id") not in order_ids:
            continue

        amount = record.get("amount")
        if (
            isinstance(amount, int)
            and not isinstance(amount, bool)
            and amount < 0
        ):
            refund_total += -amount

    return refund_total


def build_summary(matches, refund_total):
    """Build the five-field reconciliation summary."""
    if not isinstance(matches, list):
        matches = []

    if not isinstance(refund_total, int) or isinstance(refund_total, bool):
        refund_total = 0

    matched_total = 0
    unmatched_ids = set()
    matched_count = 0

    for result in matches:
        if not isinstance(result, dict):
            continue

        if result.get("status") == "matched":
            matched_count += 1
            amount = result.get("amount", 0)
            if isinstance(amount, int) and not isinstance(amount, bool):
                matched_total += amount
        else:
            order_id = result.get("order_id")
            if isinstance(order_id, str):
                unmatched_ids.add(order_id)

    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "refund_total": refund_total,
        "net_total": max(0, matched_total - refund_total),
        "unmatched_ids": sorted(unmatched_ids),
    }

