"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str):
        return None
    text = s.strip()
    if not text or text.startswith("+"):
        return None
    negative = text.startswith("-")
    body = text[1:] if negative else text
    if not body or body.count(".") > 1:
        return None
    parts = body.split(".")
    if not parts[0].isdigit():
        return None
    if len(parts) == 2 and parts[1] and not parts[1].isdigit():
        return None
    fraction = parts[1] if len(parts) == 2 else ""
    if len(fraction) > 3:
        return None
    try:
        cents = int((Decimal(text) * Decimal("100")).quantize(
            Decimal("1"), rounding=ROUND_HALF_UP
        ))
    except (InvalidOperation, ValueError, TypeError, OverflowError):
        return None
    return cents if abs(cents) <= 1000000 else None


def parse_record(line):
    if not isinstance(line, str):
        return None
    fields = line.split("|")
    if len(fields) != 6:
        return None
    kind, record_id, order_id, amount, currency, timestamp = fields
    kind = kind.strip().upper()
    record_id = record_id.strip()
    order_id = order_id.strip()
    currency = currency.strip()
    timestamp = timestamp.strip()
    if kind not in ("ORDER", "PAYMENT"):
        return None
    if not record_id or not order_id or not order_id.startswith("ORD-"):
        return None
    if currency != "USD":
        return None
    value = parse_amount(amount)
    if value is None or (kind == "ORDER" and value < 0):
        return None
    parsed_time = None
    for fmt in ("%Y-%m-%d %H:%M", "%Y-%m-%d %H:%M:%S"):
        try:
            parsed_time = datetime.strptime(timestamp, fmt)
            break
        except (TypeError, ValueError):
            continue
    if parsed_time is None:
        return None
    return {
        "type": kind,
        "record_id": record_id,
        "order_id": order_id,
        "amount": value,
        "currency": currency,
        "timestamp": parsed_time,
    }


def load_records(text):
    if not isinstance(text, str):
        return []
    result = []
    seen = set()
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None and record["record_id"] not in seen:
            seen.add(record["record_id"])
            result.append(record)
    return result


def match_payments(records):
    if not isinstance(records, list):
        return []
    orders = []
    order_ids = set()
    for record in records:
        if (isinstance(record, dict)
                and record.get("type") == "ORDER"
                and record.get("currency") == "USD"
                and record.get("order_id") not in order_ids):
            orders.append(record)
            order_ids.add(record.get("order_id"))

    results = []
    for order in orders:
        order_id = order.get("order_id")
        start = order.get("timestamp")
        chosen = None
        chosen_index = None
        if isinstance(start, datetime):
            end = start + timedelta(hours=72)
            for index, payment in enumerate(records):
                if not isinstance(payment, dict):
                    continue
                if (payment.get("type") != "PAYMENT"
                        or payment.get("currency") != "USD"
                        or payment.get("order_id") != order_id):
                    continue
                amount = payment.get("amount")
                timestamp = payment.get("timestamp")
                if (not isinstance(timestamp, datetime)
                        or not isinstance(amount, int)
                        or isinstance(amount, bool)
                        or amount < 0
                        or timestamp < start
                        or timestamp >= end):
                    continue
                if (chosen is None
                        or timestamp < chosen.get("timestamp")
                        or (timestamp == chosen.get("timestamp")
                            and index < chosen_index)):
                    chosen = payment
                    chosen_index = index
        if chosen is None:
            results.append({"order_id": order_id, "status": "unmatched",
                            "amount": 0})
        else:
            results.append({"order_id": order_id, "status": "matched",
                            "amount": chosen["amount"]})
    return results


def compute_refunds(records):
    if not isinstance(records, list):
        return 0
    order_ids = {
        record.get("order_id")
        for record in records
        if (isinstance(record, dict)
            and record.get("type") == "ORDER"
            and record.get("currency") == "USD")
    }
    total = 0
    for record in records:
        if not isinstance(record, dict):
            continue
        amount = record.get("amount")
        if (record.get("type") == "PAYMENT"
                and record.get("currency") == "USD"
                and record.get("order_id") in order_ids
                and isinstance(amount, int)
                and not isinstance(amount, bool)
                and amount < 0):
            total += -amount
    return total


def build_summary(matches, refund_total):
    if not isinstance(matches, list):
        matches = []
    if not isinstance(refund_total, int) or isinstance(refund_total, bool):
        refund_total = 0
    matched = [
        item for item in matches
        if isinstance(item, dict) and item.get("status") == "matched"
    ]
    unmatched_ids = sorted({
        item.get("order_id") for item in matches
        if (isinstance(item, dict)
            and item.get("status") == "unmatched"
            and item.get("order_id") is not None)
    })
    matched_amount = sum(
        item.get("amount", 0) for item in matched
        if isinstance(item.get("amount", 0), int)
    )
    return {
        "total_orders": len(matches),
        "matched_count": len(matched),
        "refund_total": refund_total,
        "net_total": max(0, matched_amount - refund_total),
        "unmatched_ids": unmatched_ids,
    }

