"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        if '.' in s:
            parts = s.split('.')
            if len(parts) > 2 or any(not part.isdigit() for part in parts):
                return None
            amount = Decimal(s).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
            amount = int(amount * 100)
        else:
            amount = int(s)

        if abs(amount) > 1000000:
            return None
        return amount
    except (ValueError, TypeError, InvalidOperation):
        return None


def parse_record(line):
    fields = line.strip().split('|')
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount, currency, timestamp = fields
    record_type = record_type.upper().strip()

    if record_type not in ['ORDER', 'PAYMENT']:
        return None

    record_id = record_id.strip()
    order_id = order_id.strip()
    amount = parse_amount(amount.strip())
    currency = currency.strip()
    timestamp = timestamp.strip()

    if not (record_id and order_id and amount is not None and currency == 'USD'):
        return None

    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount,
        'currency': currency,
        'timestamp': timestamp
    }


def load_records(text):
    raise NotImplementedError


def match_payments(records):
    orders = {}
    payments = []

    for record in records:
        if record['type'] == 'ORDER':
            orders[record['order_id']] = record
        elif record['type'] == 'PAYMENT':
            payments.append(record)

    results = []

    for order_id, order in orders.items():
        matched_payment = None
        order_time = order['timestamp']
        for payment in payments:
            if payment['order_id'] == order_id and payment['amount'] >= 0:
                payment_time = payment['timestamp']
                if order_time <= payment_time < order_time + timedelta(hours=72):
                    if matched_payment is None or payment_time < matched_payment['timestamp']:
                        matched_payment = payment

        if matched_payment:
            results.append({
                'order_id': order_id,
                'status': 'matched',
                'amount': matched_payment['amount']
            })
        else:
            results.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': 0
            })

    return results


def compute_refunds(records):
    positive_sum = sum(-record['amount'] for record in records if record['type'] == 'PAYMENT' and record['amount'] < 0)
    return positive_sum


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = max(0, sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total)
    unmatched_ids = sorted(set(match['record_id'] for match in matches if match['status'] != 'matched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    """Convert a monetary string to integer cents, or return None."""
    if not isinstance(s, str):
        return None

    text = s.strip()
    if not _AMOUNT_RE.fullmatch(text):
        return None

    try:
        value = Decimal(text)
        cents = (value * Decimal("100")).quantize(
            Decimal("1"), rounding=ROUND_HALF_UP
        )
    except (InvalidOperation, ValueError, OverflowError):
        return None

    cents = int(cents)

    if abs(cents) > 1_000_000:
        return None

    return cents


def parse_record(line):
    """Parse one pipe-separated settlement record."""
    if not isinstance(line, str):
        return None

    parts = line.strip().split("|")
    if len(parts) != 6:
        return None

    parts = [part.strip() for part in parts]
    record_type, record_id, order_id, amount_text, currency, timestamp_text = parts

    record_type = record_type.upper()
    if record_type not in ("ORDER", "PAYMENT"):
        return None

    if not record_id or not order_id:
        return None

    if len(currency) != 3 or not currency.isalpha() or currency != currency.upper():
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None

    if record_type == "ORDER" and amount < 0:
        return None

    timestamp = _parse_timestamp(timestamp_text)
    if timestamp is None:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "currency": currency,
        "timestamp": timestamp,
    }


def load_records(text):
    """Parse valid records, retaining only the first occurrence of each ID."""
    if not isinstance(text, str):
        return []

    records = []
    seen_ids = set()

    for line in text.splitlines():
        record = parse_record(line)
        if record is None:
            continue

        record_id = record["record_id"]
        if record_id in seen_ids:
            continue

        seen_ids.add(record_id)
        records.append(record)

    return records


def match_payments(records):
    """Match each order with the earliest qualifying payment."""
    if not isinstance(records, (list, tuple)):
        return []

    orders = [
        record
        for record in records
        if isinstance(record, dict) and record.get("type") == "ORDER"
    ]

    payments = [
        record
        for record in records
        if (
            isinstance(record, dict)
            and record.get("type") == "PAYMENT"
            and isinstance(record.get("amount"), int)
            and not isinstance(record.get("amount"), bool)
            and record.get("amount") >= 0
        )
    ]

    results = []

    for order in orders:
        order_id = order.get("order_id")
        order_amount = order.get("amount")
        order_currency = order.get("currency")
        order_time = order.get("timestamp")

        best_payment = None

        if isinstance(order_time, datetime):
            deadline = order_time + timedelta(hours=72)

            for payment in payments:
                if payment.get("order_id") != order_id:
                    continue
                if payment.get("amount") != order_amount:
                    continue
                if payment.get("currency") != order_currency:
                    continue

                payment_time = payment.get("timestamp")
                if not isinstance(payment_time, datetime):
                    continue

                try:
                    if payment_time < order_time or payment_time >= deadline:
                        continue
                except TypeError:
                    continue

                if (
                    best_payment is None
                    or payment_time < best_payment.get("timestamp")
                ):
                    best_payment = payment

        if best_payment is None:
            results.append(
                {
                    "order_id": order_id,
                    "status": "unmatched",
                    "amount": 0,
                }
            )
        else:
            results.append(
                {
                    "order_id": order_id,
                    "status": "matched",
                    "amount": best_payment["amount"],
                }
            )

    return results


def compute_refunds(records):
    """Return the positive total of valid negative payments."""
    if not isinstance(records, (list, tuple)):
        return 0

    order_ids = {
        record.get("order_id")
        for record in records
        if isinstance(record, dict) and record.get("type") == "ORDER"
    }

    total = 0
    for record in records:
        if not isinstance(record, dict):
            continue
        if record.get("type") != "PAYMENT":
            continue
        if record.get("order_id") not in order_ids:
            continue

        amount = record.get("amount")
        if isinstance(amount, int) and not isinstance(amount, bool) and amount < 0:
            total += -amount

    return total


def build_summary(matches, refund_total):
    valid_matches = matches if isinstance(matches, list) else []

    matched_count = 0
    matched_total = 0
    unmatched_ids = set()

    for result in valid_matches:
        if not isinstance(result, dict):
            continue

        status = result.get("status")
        if status == "matched":
            matched_count += 1

            amount = result.get("payment_amount")
            if amount is None:
                amount = result.get("amount")

            if (
                isinstance(amount, int)
                and not isinstance(amount, bool)
                and amount > 0
            ):
                matched_total += amount

        elif status == "unmatched":
            order_id = result.get("order_id")
            if isinstance(order_id, str):
                unmatched_ids.add(order_id)

    if (
        not isinstance(refund_total, int)
        or isinstance(refund_total, bool)
        or refund_total < 0
    ):
        refund_total = 0

    net_total = max(0, matched_total - refund_total)

    return {
        "total_orders": len(valid_matches),
        "matched_count": matched_count,
        "refund_total": refund_total,
        "net_total": net_total,
        "unmatched_ids": sorted(unmatched_ids),
    }
